INSERT INTO `article` (`article_id`,`title`,`author`,`dynasty`,`content`,`translate`,`appreciate`,`notes`,`genre`,`source`) VALUES
('rd3_2_0','送客归湘楚','许浑','唐','无辞一杯酒，
昔日与君深。
秋色换归鬓，
曙光生别心。
桂花山庙冷，
枫树水楼阴。
此路千馀里，
应劳楚客吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1','送客江行','许浑','唐','萧萧芦荻花，
郢客独辞家。
远棹依山响，
危樯转浦斜。
水寒澄浅石，
潮落涨虚沙。
莫与征徒望，
乡园去渐赊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_2','送客自两河归江南','许浑','唐','两河庶事已堪伤，
南客秋归路更长。
台畔古松悲魏帝，
苑边脩竹吊梁王。
山行露变茱萸色，
水宿风披菡萏香。
遥羡落帆逢旧友，
绿蛾青鬓醉横塘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_3','送客南归有怀','许浑','唐','绿水暖青蘋，
湘潭万里春。
瓦尊迎海客，
铜鼓赛江神。
避雨松枫岸，
看云杨柳津。
长安一杯酒，
座上有归人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_4','送段觉之西蜀结婚','许浑','唐','词赋名高身不闲，
䌽衣如锦度函关。
镜中鸾影胡威去，
剑外花归卫玠还。
秋浪远侵黄鹤岭，
暮云遥断碧鸡山。
时人若问西游客，
心在重霄鬓欲斑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_5','送段觉归东阳兼寄窦使君','许浑','唐','山水引归路，
陆郎从此谙。
秋茶垂露细，
寒菊带霜甘。
台倚乌龙岭，
楼侵白雁潭。
沈公如借问，
心在浙河南。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_6','送段觉归杜曲闲居','许浑','唐','书剑南归去，
山扉别几年。
苔侵岩下路，
果落洞中泉。
红叶高斋雨，
青萝曲槛烟。
宁知远游客，
羸马太行前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_7','送郭秀才游天台','许浑','唐','云埋阴壑雪凝峰，
半壁天台已万重。
人度碧溪疑辍棹，
僧归苍岭似闻钟。
暖眠鸂鶒晴滩草，
高挂猕猴暮涧松。
曾约共游今独去，
赤城西面水溶溶。',NULL,'','{"preface": "余尝与郭秀才同玩朱审画天台山图，秀才因游是山，题诗赠别。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_8','送惟素上人归新安','许浑','唐','山空叶复落，
一径下新安。
风急渡溪晚，
雪晴归寺寒。
寻云策藤杖，
向日倚蒲团。
宁忆西游客，
劳劳歌路难。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_9','送萧处士归缑岭别业','许浑','唐','醉斜乌帽发如丝，
曾看仙人一局棋。
宾馆有鱼为客久，
乡书无雁到家迟。
缑山住近吹笙庙，
湘水行逢鼓瑟祠。
今夜月明何处宿，
九疑云尽碧参差。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_10','送黄隐居归南海','许浑','唐','瘴雾南边久寄家，
海中来往信流槎。
林藏狒狒多残笋，
树过猩猩少落花。
深洞有云龙蜕骨，
半岩无草象生牙。
知君爱宿层峰顶，
坐到三更见日华。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_11','送韩校书','许浑','唐','恨与前欢隔，
愁因此会同。
迹高芸阁吏，
名散雪楼翁。
城闭三秋雨，
帆飞一夜风。
酒醒鲈鲙美，
应在竟陵东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_12','送楼烦李别驾','许浑','唐','琴清诗思劳，
更欲学龙韬。
王粲暂停笔，
吕虔初佩刀。
夜吟关月静，
秋望塞云高。
去去从军乐，
雕飞代马豪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_13','送僧归金山寺','许浑','唐','老归江上寺，
不忘旧师恩。
驻锡逢山色，
停杯见浪痕。
秋涛吞楚驿，
晓月上荆门。
为访题诗处，
莓苔几字存。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_14','送僧归敬亭山寺','许浑','唐','十年剑中路，
传尽本师经。
晓月下黔峡，
秋风归敬亭。
开门新树绿，
登阁旧山青。
遥想论禅处，
松阴水一瓶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_15','送薛秀才南游','许浑','唐','姑苏城外柳初凋，
同上江楼更寂寥。
绕壁旧诗尘漠漠，
对窗寒竹雨潇潇。
怜君别路随秋雁，
尽我离觞任晚潮。
从此草玄应有处，
白云青嶂一相招。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_16','郡斋夜坐寄旧乡二侄','许浑','唐','千官奉职衮龙垂，
旅卧淮阳鬓日衰。
三月已乖棠树政，
二年空负竹林期。
楼侵白浪风来远，
城抱丹岩日到迟。
长欲挂帆君莫笑，
越禽花晚梦南枝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_17','重伤杨攀处士二首','许浑','唐','绿云多学术，
黄发竟无成。
酒纵山中性，
诗留海上名。
读书新树老，
垂钓旧矶平。
今日悲前事，
西风闻哭声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_18','重伤杨攀处士二首','许浑','唐','从官任直道，
几处脱长裾。
殁后儿犹小，
葬来人渐疏。
新邻占池馆，
长史觅图书。
身贱难相报，
平生恨有馀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_19','重经姑苏怀古二首','许浑','唐','越兵驱绮罗，
越女唱吴歌。
宫尽燕声少，
台荒麋迹多。
茱萸垂晓露，
菡萏落秋波。
无复君王醉，
满城颦翠蛾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_20','重经姑苏怀古二首','许浑','唐','香径绕吴宫，
千帆落照中。
鹳鸣山欲雨，
鱼跃水多风。
城带晚莎绿，
池连秋蓼红。
当年国门外，
谁识伍员忠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_21','重游飞泉观题故梁道士宿龙池','许浑','唐','西岩泉落水容宽，
灵物蜿蜒黑处蟠。
松叶正秋琴韵响，
菱花初晓镜光寒。
云开星月浮山殿，
雨过风雷绕石坛。
仙客不归龙亦去，
稻畦长满此池乾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_22','重游郁林寺道玄上人院','许浑','唐','藤杖叩松关，
春溪斸药还。
雨晴巢燕急，
波暖浴鸥闲。
倚槛花临水，
回舟月照山。
忆归师莫笑，
书剑在人间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_23','重游綀湖怀旧','许浑','唐','西风渺渺月连天，
同醉兰舟未十年。
鵩鸟赋成人已没，
嘉鱼诗在世空传。
荣枯尽寄浮云外，
哀乐犹惊逝水前。
日暮长堤更回首，
一声邻笛旧山川。',NULL,'','{"preface": "余尝与故宋补阙次都秋夕游永泰寺后湖亭（余尝与故宋补阙次都秋夕游练湖亭），今复登赏，怆然有感，因赋是诗。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_24','重赋鹭鸶','许浑','唐','何年去此地，
南浦满凫雏。
云汉知心远，
林塘觉思孤。
低飞下晚树，
独睡映新蒲。
为尔多归兴，
前年在五湖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_25','闻州中有宴寄崔大夫兼简邢群评事','许浑','唐','箫管筵间列翠蛾，
玉杯金液耀金波。
池边雨过飘帷幕，
海上风来动绮罗。
颜子巷深青草遍，
庾君楼迥碧山多。
甘心不及同年友，
卧听行云一曲歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_26','闻两河用兵因贻友人','许浑','唐','故人日已远，
身事与谁论。
性拙难趋世，
心孤易感恩。
秋悲怜宋玉，
夜舞笑刘琨。
徒有干时策，
青山尚掩门。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_27','闻范秀才自蜀游江湖','许浑','唐','蜀道下湘渚，
客帆应不迷。
江分三峡响，
山并九华齐。
秋泊雁初宿，
夜吟猿乍啼。
归时慎行李，
莫到石城西。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_28','闻释子栖玄欲奉道因寄','许浑','唐','欲求真诀恋禅扃，
羽帔方袍尽有情。
仙骨本微灵鹤远，
法心潜动毒龙惊。
三山未有偷桃计，
四海初传问菊名。
今日劝师师莫惑，
长生难学證无生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_29','闻韶州李相公移拜郴州因寄','许浑','唐','诏移丞相木兰舟，
桂水潺湲岭北流。
青汉梦归双阙曙，
白云吟过五湖秋。
恩回玉扆人先喜，
道在金縢世不忧。
闻说公卿尽南望，
甘棠花暖凤池头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_30','闻薛先辈陪大夫看早梅因寄','许浑','唐','涧梅寒正发，
莫信笛中吹。
素艳雪凝树，
清香风满枝。
折惊山鸟散，
携任野蜂随。
今日从公醉，
何人倒接䍦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_31','乘月棹舟送大历寺灵聪上人不及','许浑','唐','万峰秋尽百泉清，
旧锁禅扉在赤城。
枫浦客来烟未散，
竹窗僧去月犹明。
杯浮野渡鱼龙远，
锡响空山虎豹惊。
一字不留何足讶，
白云无路水无情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_32','凌歊台','许浑','唐','宋祖凌高乐未回，
三千歌舞宿层台。
湘潭云尽暮山出，
巴蜀雪消春水来。
行殿有基荒荠合，
寝园无主野棠开。
百年便作万年计，
岩畔古碑空绿苔。',NULL,'[{"Book": "《瀛奎律髓》", "Section": null, "Content": "刘裕起于布衣，作俭之主，“三千歌舞”之句不近诬否？第四句最玄，上一句似牵强。至如“有基”、“无主”一联近于熟套而格卑。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓》"}, {"Book": "《麓堂诗话》", "Section": null, "Content": "律诗对偶最难，如贾浪仙“独行潭底影，数息树边身”，至有“两句三年得”之句。许用晦“湘潭云尽暮山出，巴蜀雪消春水来”，皆有感而后得者也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《麓堂诗话》"}, {"Book": "《升庵诗话》", "Section": null, "Content": "许浑《凌歊台》诗“宋祖凌歊乐未同，三千歌舞宿层台。”此宋祖乃刘裕也。《南史》称宋祖清简寡欲，俭于布素，缤御至少……浑非有意于诬前代，何胸中无学，目不观书，徒弄声律以侥幸一第。机关用之既熟，不觉于怀古之作亦发之。而后之浅学如杨仲弘、高柄、郝天挺之徒，选以为警策，而村学究又诵以教蒙童，是以流传至此不废耳。又：许浑诗，刘巨济泾曾得其手书“湘潭云尽暮烟出”，“烟”字极妙，兼是许之手笔无疑也。后人改“烟”作“山”，无味。大抵湘中烟色与他方异。张泌诗“中流欲暮见湘烟”……颇中湘中晚景。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《升庵诗话》"}, {"Book": "《艺苑卮言》", "Section": null, "Content": "“湘潭云尽暮烟出，巴蜀雪消春水来”，大是妙境。然读之，便知作长庆以前语。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《艺苑卮言》"}, {"Book": "《唐诗选脉会通评林》", "Section": null, "Content": "周弼列为四实体，顾璘曰：此篇中联虽急，而赋景切实，有可取者。却作一结，如此粗浊，缘兴意已竭，勉作拦截耳。胡应麟曰：佳句如次二语，虽晚唐格调，而清新自得。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选脉会通评林》"}, {"Book": "《姜斋诗话》", "Section": null, "Content": "诗文俱有主宾。无主之宾、谓之乌合……“湘潭云尽暮烟出，巴蜀雪消春水来”，于许浑奚涉？皆乌合也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《姜斋诗话》"}, {"Book": "《东岩草堂评订唐诗鼓吹》", "Section": null, "Content": "朱东岩曰：“乐未回”三字是一篇主意。言宋祖长夏畏暑，筑台纳凉，当夫暑去凉生，自应还朝听政，乃三千歌舞，流荡忘返，荒游极矣。三四即咏“乐未回”也。“云尽山出”，言夏徂秋尽，犹在台端也；“雪消水来”，言腊尽春初，犹在台端也。人知此二句，是写登台远望景色，亦知唐人写景，必有所指乎？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《东岩草堂评订唐诗鼓吹》"}, {"Book": "《贯华堂选批唐才子诗》", "Section": null, "Content": "歊，暑气也。凌，高出层表以破除之也。乐，暑去凉生则心乐也。通解写宋祖纵心肆志，只一“未”字已尽。言祖初因长夏畏暑，故筑层台纳凉。然则暑去凉生，自应还朝听政，乃因三千歌舞，乐此不欲复去，于是更月改岁，遥遥只住台端。三、四，正极写之也。云尽烟出，言天下已见夏徂秋尽也；雪消水来，言天下又见腊尽春回也。若问行在何在，则还在凌歊台上避暑未归，是可发一大笑也（前四句下）。夫宋祖代晋，初有天下，其百凡创业垂统，岂不自谓我为始皇帝哉！他日子孙代立，而自一世、二世至于千世、万世，人有同情，畏暑唯均，则于此处能无行殿！此固其岩畔丰碑，自叙斯志，其文现在可扪而读者也。其又乌料身死之后，不唯后人不成坐殿，连自家亦已无主。嗟乎，嗟乎！荒荠野棠，一春事毕；豪人远计，万载无休！人不云乎：后之视今，犹今视昔。登斯台者，夫亦可以少悟矣（后四句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《贯华堂选批唐才子诗》"}, {"Book": "《五朝诗善鸣集》", "Section": null, "Content": "学盛唐人格律者好作远大之句，往往入于痴肥。此诗三四一联，远矣不觉其远，大矣不见其大，另开生面，正是善变化盛唐处。不唯善变，只是写实景真确耳。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《五朝诗善鸣集》"}, {"Book": "《唐三体诗评》", "Section": null, "Content": "二联写台之高固妙，尤觉三联叹古今之变好。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐三体诗评》"}, {"Book": "《瀛奎律髓汇评》", "Section": null, "Content": "冯舒：第三不可谓之牵强。五六熟矣，亦未必不合。冯班：方君极诋丁卯为格卑，为俗套，不知用晦诗极工细，与“江西”格正相反，宜方君之不喜也。何义门：“三千歌舞”，不觉嚣烦，唯其旷绝，如次联所云也。第二变化曲折，有此句方顶接得首句气脉足，五六亦有照应。“高高”含“层”字，“乐未回”反呼后四句。查慎行：除却“宋祖凌歒”四字，以后无一语切题者，且三四于起句神气不浃。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓汇评》"}, {"Book": "《五七言今体诗钞》", "Section": null, "Content": "鼐按：用晦此诗，大为杨升庵诋斥，赖遁叟升其屈。然“湘潭”一联与上二句如何接下？要不免有句无章之病。“寝园”二字，亦凑用不的当。此等诗姑以句取可耳。“百年”句无著。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《五七言今体诗钞》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_33','凌歊台送韦秀才','许浑','唐','云起高台日未沈，
数村残照半岩阴。
野蚕成茧桑柘尽，
溪鸟引雏蒲稗深。
帆势依依投极浦，
钟声杳杳隔前林。
故山迢遰故人去，
一夜月明千里心。',NULL,'[{"Book": "《贯华堂选批唐才子诗》", "Section": null, "Content": "五犹银见帆，六乃何闻钟矣，妙妙！故山迢递，故人独去，一夜月明，思人乎，抑自思乎（末四句下）？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《贯华堂选批唐才子诗》"}, {"Book": "《五朝诗善鸣集》", "Section": null, "Content": "每一句中有几层情景，看得进，说得出，隽水无穷，吾为沉吟终日。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《五朝诗善鸣集》"}, {"Book": "《唐诗鼓吹评注》", "Section": null, "Content": "第七将一事剔多层意，收尽前后瞻望弗及神理。此诗前四句即目前景以起送别之意，后四句言别后相思之情。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗鼓吹评注》"}, {"Book": "《桐城吴先生评点唐诗鼓吹》", "Section": null, "Content": "此忧乱之诗，前六句皆兼比兴。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《桐城吴先生评点唐诗鼓吹》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_34','哭杨攀处士','许浑','唐','先生忧道乐清贫，
白发终为不仕身。
嵇阮没来无酒客，
应刘亡后少诗人。
山前月照荒坟晓，
溪上花开旧宅春。
昨夜回舟更惆怅，
至今钟磬满南邻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_35','夏日戏题郭别驾东堂','许浑','唐','微风起画鸾，
金翠暗珊珊。
晚树垂朱实，
春篁露粉竿。
散香蕲簟滑，
沈水越瓶寒。
犹恐何郎热，
冰生白玉盘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_36','宴饯李员外','许浑','唐','病守江城眼暂开，
昔年吴越共衔杯。
膺舟出镇虚陈榻，
郑履还京下隗台。
云叶渐低朱阁掩，
浪花初起画樯回。
心期解印同君醉，
九曲池西望月来。',NULL,'','{"preface": "李群之员外从事荆南尚书阳公，诏徵赴阙，俄为淮南相国杜公辟命，自汉上舟行至此郡，于云楼宴罢解缆，阻风却回，因赠。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_37','恩德寺','许浑','唐','楼台横复重，
犹有半岩空。
萝洞浅深水，
竹廊高下风。
晴山疏雨后，
秋树断云中。
未尽平生意，
孤帆又向东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_38','旅中别侄炜','许浑','唐','相见又南北，
中宵泪满襟。
旅游知世薄，
贫别觉情深。
歌管一尊酒，
山川万里心。
此身多在路，
休诵异乡吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_39','旅怀','许浑','唐','征车何轧轧，
南北极天涯。
孤枕易为客，
远书难到家。
乡连云外树，
城闭月中花。
犹有扁舟思，
前年别若耶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_40','旅怀作','许浑','唐','促促因吟昼短诗，
朝惊秾色暮空枝。
无情春色不长久，
有限年光多盛衰。
往事只应随梦里，
劳生何处是闲时。
眼前扰扰日一日，
暗送白头人不知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_41','旅夜怀远客','许浑','唐','异乡多远情，
梦断落江城。
病起惭书癖，
贫家负酒名。
过春花自落，
竟晓月空明。
独此一长啸，
故人天际行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_42','晓发天井关寄李师晦','许浑','唐','山在水滔滔，
流年欲二毛。
湘潭归梦远，
燕赵客程劳。
露晓红兰重，
云晴碧树高。
逢秋正多感，
万里别同袍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_43','晓发鄞江北渡寄崔韩二先辈','许浑','唐','南北信多岐，
生涯半别离。
地穷山尽处，
江泛水寒时。
露晓蒹葭重，
霜晴橘柚垂。
无劳促回楫，
千里有心期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_44','晓过郁林寺戏呈李明府','许浑','唐','身闲白日长，
何处不寻芳？
山崦登楼寺，
溪湾泊晚樯。
洞花蜂聚蜜，
岩柏麝留香。
若指求仙路，
刘郎学阮郎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_45','朗上人院晨坐','许浑','唐','簟凉襟袖清，
月没尚残星。
山果落秋院，
水花开晓庭。
疏藤风袅袅，
圆桂露冥冥。
正忆江南寺，
岩斋闻诵经。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_46','留别赵端公','许浑','唐','海门征棹赴龙泷，
暂寄华筵倒玉缸。
箫鼓散时逢夜雨，
绮罗分处下秋江。
孤帆已过滕王阁，
高榻留眠谢守窗。
却愿烟波阻风雪，
待君同拜碧油幢。',NULL,'','{"preface": "余行次钟陵，府中诸公宴饯赵端公，晓赴郡斋，一约余来，且整棹，因留别。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_47','留题李侍御书斋','许浑','唐','昔话平生志，
高斋曾见留。
道孤心易感，
恩重力难酬。
独立千峰晓，
频来一叶秋。
鸡鸣应有处，
不觉泪空流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_48','留赠偃师主人','许浑','唐','孤城漏未残，
徒侣拂征鞍。
洛北去游远，
淮南归梦阑。
晓灯回壁暗，
晴雪卷帘寒。
强尽主人酒，
出门行路难。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_49','疾后与郡中群公宴李秀才','许浑','唐','强留佳客宴王孙，
岩上馀花落酒樽。
书院欲开虫网户，
讼庭犹掩雀罗门。
耳虚尽日疑琴癖，
眼暗经秋觉镜昏。
莫引刘安倚西槛，
夜来红叶下江村。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_50','病中二首','许浑','唐','三年婴酒渴，
高卧似袁安。
秋色鬓应改，
夜凉心已宽。
风衣藤簟滑，
露井竹床寒。
卧忆郊扉月，
恩深未挂冠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_51','病中二首','许浑','唐','私归人暂适，
扶杖绕西林。
风急柳溪响，
露寒莎径深。
一身仍白发，
万虑只丹心。
此意无言处，
高窗托素琴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_52','病间寄郡中文士','许浑','唐','卢橘含花处处香，
老人依旧卧清漳。
心同客舍惊秋早，
迹似僧斋厌夜长。
风捲翠帘琴自响，
露凝朱阁簟先凉。
明朝欲醉文中彦，
犹觉吟声带越乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_53','破北虏太和公主归宫阙','许浑','唐','毳幕承秋极断蓬，
飘飖一剑黑山空。
匈奴北走荒秦垒，
贵主西还盛汉宫。
定是庙谟倾种落，
必知边寇畏骁雄。
恩沾残类从归去，
莫使华人杂犬戎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_54','途中逢故人话西山读书早曾游览','许浑','唐','西岩曾到读书堂，
穿竹行沙十里强。
湖上梦馀波滟滟，
岭头愁断路茫茫。
经过事寄烟霞远，
名利尘随日月长。
莫道少年头不白，
君看潘岳几茎霜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_55','途中寒食','许浑','唐','处处哭声悲，
行人马亦迟。
店闲无火日，
村暖斫桑时。
泣路同杨子，
烧山忆介推。
清明明日是，
甘负故园期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_56','途经李翰林墓','许浑','唐','气逸何人识，
才高举世疑。
祢生狂善赋，
陶令醉能诗。
碧水鲈鱼思，
青山鵩鸟悲。
至今孤冢在，
荆棘楚江湄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_57','途经敷水','许浑','唐','脩蛾颦翠倚柔桑，
遥谢春风白面郎。
五夜有情随暮雨，
百年无节待秋霜。
重寻绣带朱藤合，
更认罗裙碧草长。
何处野花何处水，
下峰流出一渠香。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_58','陪王尚书泛舟莲池','许浑','唐','莲塘移画舸，
泛泛日华清。
水暖鱼频跃，
烟秋雁早鸣。
舞疑回雪态，
歌转遏云声。
客散山公醉，
风高月满城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_59','陪郑史君泛舟晚归','许浑','唐','南郭望归处，
郡楼高卷帘。
平桥低皂盖，
曲岸转彤襜。
江晚笙歌促，
山晴鼓角严。
羊公莫先醉，
清晓月纤纤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_60','陪宣城大夫崔公泛后池兼北楼宴二首','许浑','唐','陪汎芳池醉北楼，
水花繁艳照膺舟。
亭台阴合树初昼，
弦管韵高山欲秋。
皆贺虢岩终选傅，
自伤燕谷未逢邹。
昔时恩遇今能否，
一尉沧洲已白头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_61','陪宣城大夫崔公泛后池兼北楼宴二首','许浑','唐','江上西来共鸟飞，
剪荷浮汎似轻肥。
王珣作簿公曾喜，
刘表为邦客尽依。
云外轩窗通早景，
风前箫鼓送残晖。
宛陵行乐金陵住，
遥对家山未忆归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_62','陪越中使院诸公镜波馆饯明台裴郑二使君','许浑','唐','倾幕来华馆，
淹留二使君。
舞移清夜月，
歌断碧空云。
海郡楼台接，
江船剑戟分。
明时自骞翥，
无复叹离群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_63','陵阳春日寄汝洛旧游','许浑','唐','百年身世似飘蓬，
泽国移家叠嶂中。
万里绿波鱼恋钓，
九重青汉鹤愁笼。
西池水冷春岩雪，
南浦花香晓树风。
纵倒芳尊心不醉，
故人多在洛城东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_64','骊山','许浑','唐','闻说先皇醉碧桃，
日华浮动郁金袍。
风随玉辇笙歌迥，
云捲珠帘剑佩高。
凤驾北归山寂寂，
龙旟西幸水滔滔。
贵妃没后巡游少，
瓦落宫墙见野蒿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_65','鸳鸯','许浑','唐','两两戏沙汀，
长疑画不成。
锦机争织样，
歌曲爱呼名。
好□顾栖息，
堪怜泛浅情。
凫鸥皆尔类，
唯羡独含情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_66','宿开元寺楼','许浑','唐','谁家歌袅袅，
孤枕在西楼。
竹色寒清簟，
松香染翠帱。
月移珠殿晓，
风遰玉筝秋。
日出应移棹，
三湘万里愁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_67','宿松江驿却寄苏州一二同志','许浑','唐','候馆人稀夜自长，
姑苏台远树苍苍。
江湖潮落高楼迥，
河汉秋归广簟凉。
月转碧梧移鹊影，
露低红叶湿萤光。
西园诗侣应多思，
莫醉笙歌掩画堂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_68','寄天乡寺仲仪上人富春孙处士','许浑','唐','诗僧与钓翁，
千里两情通。
云带雁门雪，
水连渔浦风。
心期荣辱外，
名挂是非中。
岁晚亦归去，
田园清洛东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_69','寄当涂李远','许浑','唐','赋拟相如诗似陶，
云阳烟月又同袍。
车前骥病驽骀逸，
架上鹰闲鸟雀高。
旧日乐贫能饮水，
他时随俗愿餔糟。
不须倚向青山住，
咏雪题诗用意劳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_70','寄阳陵处士','许浑','唐','旧隐青山紫桂阴，
一书迢遰寄归心。
谢公楼上晚花盛，
杨子宅前春草深。
吴岫雨来溪鸟浴，
楚江云暗岭猿吟。
野人宁忆沧洲畔，
会待吹嘘定至音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_71','寄远','许浑','唐','两叶愁眉愁不开，
独含惆怅上层台。
碧云空断雁行处，
红叶已凋人未来。
塞外音书无信息，
道傍车马起尘埃。
功名待寄凌烟阁，
力尽辽城不肯回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_72','寄房千里博士','许浑','唐','春风白马紫丝缰，
正值蚕眠未采桑。
五夜有心随暮雨，
百年无节待秋霜。
重寻绣带朱藤合，
更认罗裙碧草长。
为报西游减离恨，
阮郎才去嫁刘郎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_73','寄契盈上人','许浑','唐','何处是西林，
疏钟复远砧。
雁来秋水阔，
鸦尽夕阳沈。
婚嫁乖前志，
功名异夙心。
汤师不可问，
江上碧云深。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_74','寄殷尧藩','许浑','唐','直道知难用，
经年向水滨。
宅从栽竹贵，
家为买书贫。
就学多新客，
登朝尽故人。
蓬莱自有路，
莫羡武陵春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_75','寄殷尧藩先辈','许浑','唐','十载功名翰墨林，
为从知己信浮沈。
青山有雪谙松性，
碧落无云称鹤心。
带月独归萧寺远，
玩花频醉庾楼深。
思君一见如琼树，
空把新诗尽日吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_76','寄袁校书','许浑','唐','扰扰换时节，
旧山琪树阴。
犹乖清汉志，
空负白云心。
广陌埃尘远，
重门管吹深。
劳歌极西望，
芸省有知音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_77','寄献三川守刘公','许浑','唐','三川歌颂彻咸秦，
十二楼前侍从臣。
休闭玉笼留鸑鷟，
早开金埒纵麒麟。
花深稚榻迎何客，
月在膺舟醉几人。
自笑东风过寒食，
茂陵寥落未知春。',NULL,'','{"preface": "余奉陪三川守刘公宴言，尝蒙询访行止，因话一麾之任，翼成三径之谋，特蒙府鉴丹诚，寻许慰荐，属移履道，卧疾弥旬，辄抒二章寄献。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_78','寄献三川守刘公','许浑','唐','半年三度转蓬居，
锦帐心阑羡隼旟。
老去自惊秦塞雁，
病来先忆楚江鱼。
长闻季氏千金诺，
更望刘公一纸书。
春雪未晴春酒贵，
莫教愁杀马相如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_79','寄题华严韦秀才院','许浑','唐','三面楼台百丈峰，
西岩高枕树重重。
晴攀翠竹题诗滑，
秋摘黄花酿酒浓。
山殿日斜喧鸟雀，
石潭波动戏鱼龙。
今来故国遥相忆，
月照千山半夜钟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_80','寄题南山王隐居','许浑','唐','近逢商洛客，
知尔住南塘。
草阁平春水，
柴门掩夕阳。
随蜂收野蜜，
寻麝采生香。
更忆前年醉，
松花满石床。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_81','崇圣寺别杨至之','许浑','唐','萧寺暂相逢，
离忧满病容。
寒斋秋少燕，
阴壁夜多蛩。
树暗水千里，
山深云万重。
怀君在书信，
莫过雁回峰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_82','晚自东郭回留一二游侣','许浑','唐','乡心迢遰宦情微，
吏散寻幽竟落晖。
林下草腥巢鹭宿，
洞前云湿雨龙归。
钟随野艇回孤棹，
鼓绝山城掩半扉。
今夜西斋好风月，
一瓢春酒莫相违。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_83','晚自朝台津至韦隐居郊园','许浑','唐','秋来凫雁下方塘，
系马朝台步夕阳。
村径绕山松叶暗，
野门临水稻花香。
云连海气琴书润，
风带潮声枕簟凉。
西下磻溪犹万里，
可能垂白待文王。',NULL,'[{"Book": "《归田诗话》", "Section": null, "Content": "（郁鲁珍）见予诵许仲晦诗“村径绕山松叶滑，柴门临水稻花香”、“牛羊晚食铺平地，鹳鹤晴飞磨远天”、“日落远波惊宿雁，风吹轻浪起眠鸥”等句，谓写村居之景，曲尽其妙，令不复见矣。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《归田诗话》"}, {"Book": "《东岩草堂评订唐诗鼓吹》", "Section": null, "Content": "朱东岩曰：海气潮声，郊园之景；琴书枕箪，郊园之物。人皆谓以海气潮声写“琴书润”、“枕簟凉”耳，不知郊园之中，琴书、枕簟有何异处？睹其柴门流水，一望汪洋，水天一色，觉琴声枕簟、顿然改观；直以“琴书润”写海气，“沈簟凉”写潮声也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《东岩草堂评订唐诗鼓吹》"}, {"Book": "《山满楼笺注唐诗七言律》", "Section": null, "Content": "起手先着一笔布置，次句落题，唐人手法往往如此。此诗须要看其次序：一专写秋；二带写晚；三写路上，以绕山，故多松叶；四写门前，既临水，又有稻花：幽之至也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《山满楼笺注唐诗七言律》"}, {"Book": "《诗境浅说》", "Section": null, "Content": "许有《朝台韦氏郊园》诗云：“云连海气琴书润，风带潮声枕簟冷。”亦善写海南情状。《郊园》诗第三句“柴门临水稻花香”，为时人传诵，但此景在江乡皆有之，不独粤东耳。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《诗境浅说》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_84','晚泊七里滩','许浑','唐','天晚日沈沈，
归舟系柳阴。
江村平见寺，
山郭远闻砧。
树密猿声响，
波澄雁影深。
荣华暂时事，
谁识子陵心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_85','晚登龙门驿楼','许浑','唐','鱼龙多处凿门开，
万古人知夏禹材。
青嶂远分从地断，
洪流高泻自天来。
风云有路皆烧尾，
波浪无程尽曝腮。
心感膺门身过此，
晚山秋树独徘徊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_86','晨至南亭呈裴明府','许浑','唐','南斋梦钓竿，
晨起月犹残。
露重萤依草，
风高蝶委兰。
池光秋镜澈，
山色晓屏寒。
更恋陶彭泽，
无心议去官。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_87','晨别翛然上人','许浑','唐','吴僧诵经罢，
败衲倚蒲团。
钟韵花犹敛，
楼阴月向残。
晴山开殿响，
秋水捲帘寒。
独恨孤舟去，
千滩复万滩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_88','晨起二首','许浑','唐','桂树绿层层，
风微烟露凝。
檐楹衔落月，
帏幌映残灯。
蕲簟曙香冷，
越瓶秋水澄。
心闲即无事，
何异住山僧。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_89','晨起二首','许浑','唐','残月皓烟露，
掩门深竹斋。
水虫鸣曲槛，
山鸟下空阶。
清镜晓看发，
素琴秋寄怀。
因知北窗客，
日与世情乖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_90','晨起白云楼寄龙兴江准上人兼呈窦秀才','许浑','唐','兹楼今是望乡台，
乡信全稀晓雁哀。
山翠万重当槛出，
水华千里抱城来。
东岩月在僧初定，
南浦花残客未回。
欲吊灵均能赋否，
秋风还有木兰开。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_91','晨装','许浑','唐','带月饭行侣，
西游关塞长。
晨鸡鸣远戍，
宿雁起寒塘。
云卷四山雪，
风凝千树霜。
谁家游侠子，
沈醉卧兰堂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_92','淮阴阻风寄呈楚州韦中丞','许浑','唐','垂钓京江欲白头，
江鱼堪钓却西游。
刘伶台下稻花晚，
韩信庙前枫叶秋。
淮月未明先倚槛，
海云初起更维舟。
河桥有酒无人醉，
独上高城望庾楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_93','深春','许浑','唐','故里千帆外，
深春一雁飞。
干名频恸哭，
将老欲何归。
未谷抛还忆，
交亲晚更稀。
空持望乡泪，
沾洒寄来衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_94','移摄太平寄前李明府','许浑','唐','病移岩邑称闲身，
何处风光贳酒频。
溪柳绕门彭泽令，
野花连洞武陵人。
娇歌自驻壶中景，
艳舞长留海上春。
早晚高台更同醉，
绿萝如帐草如茵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_95','喜李诩秀才见访因赠','许浑','唐','浙南分首日，
谁谓别经时。
路远遥相访，
家贫喜见知。
不须辞小酌，
更请续新诗。
但得心中剑，
酬恩会有期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_96','喜远书','许浑','唐','端居换时节，
离恨隔龙泷。
苔色上春阁，
柳阴移晚窗。
寄怀因桂水，
流泪极枫江。
此日南来使，
金盘鱼一双。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_97','寓怀','许浑','唐','南国浣纱伴，
盈盈天下姝。
盘金明绣带，
动佩响罗襦。
素手怨瑶瑟，
清心悲玉壶。
春华坐销落，
未忍泣蘼芜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_98','寓居开元精舍酬薛秀才见贻','许浑','唐','知己萧条信陆沈，
茂陵扶疾卧西林。
芰荷风起客堂静，
松桂月高僧院深。
清露下时伤旅鬓，
白云归处寄乡心。
怜君诗句犹相忆，
题在空斋夜夜吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_99','寓崇圣寺怀李校书','许浑','唐','几日卧南亭，
卷帘秋月清。
河关初罢梦，
池阁更含情。
寒露润金井，
高风飘玉筝。
前年共游客，
刀笔事戎旌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_100','朝台送客有怀','许浑','唐','赵佗西拜已登坛，
马援南征土宇宽。
越国旧无唐印绶，
蛮乡今有汉衣冠。
江云带日秋偏热，
海雨随风夏亦寒。
岭北归人莫回首，
蓼花枫叶万重滩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_101','游果昼二僧院','许浑','唐','何必老林泉，
冥心便是禅。
讲时开院去，
斋后下帘眠。
镜朗灯分焰，
香销印绝烟。
真乘不可到，
云尽月明天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_102','游钱塘青山李隐居西斋','许浑','唐','小隐西亭为客开，
翠萝深处遍苍苔。
林间扫石安棋局，
岩下分泉递酒杯。
兰叶露光秋月上，
芦花风起夜潮来。
云山绕屋犹嫌浅，
欲棹渔舟近钓台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_103','游维山新兴寺宿石屏村谢叟家','许浑','唐','晚过石屏村，
村长日渐曛。
僧归下岭见，
人语隔溪闻。
谷响寒耕雪，
山明夜烧云。
家家扣铜鼓，
欲赛鲁将军。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_104','湖州韦长史山居','许浑','唐','一官唯买昼公堂，
但得身闲日自长。
琴曲少声重勘谱，
药丸多忌更寻方。
溪浮箬叶添醅绿，
泉绕松根助茗香。
明日鳜鱼何处钓，
门前春水似沧浪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_105','湖南徐明府余之南邻久不还家因题林馆','许浑','唐','湘南官罢不归来，
高阁经年掩绿苔。
鱼溢池塘秋雨过，
鸟还洲岛暮潮回。
阶前石稳棋终局，
窗外山寒酒满杯。
借问先生独何处，
一篱疏菊又花开。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_106','登尉佗楼','许浑','唐','刘项持兵鹿未穷，
自乘黄屋岛夷中。
南来作尉任嚣力，
北向称臣陆贾功。
箫鼓尚陈今世庙，
旌旗犹镇昔时宫。
越人未必知虞舜，
一奏薰弦万古风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_107','紫藤','许浑','唐','绿萝萦数匝，
本在草堂间。
秋色寄高树，
昼阴笼远山。
移花疏处种，
斸药困时攀。
日暮微风起，
难寻旧径还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_108','谢人赠鞭','许浑','唐','蜀国名鞭见惠稀，
驽骀从此长光辉。
独根拥肿来云岫，
紫陌提携在绣衣。
几度拂花香里过，
也曾敲𩍐月中归。
莫言三尺长无用，
百万军中要指挥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_109','趋慈和寺移宴','许浑','唐','高寺移清宴，
渔舟系绿萝。
潮平秋水阔，
云敛暮山多。
广槛停箫鼓，
繁弦散绮罗。
西楼半床月，
莫问夜如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_110','颍州从事西湖亭宴饯','许浑','唐','西湖清宴不知回，
一曲离歌酒一杯。
城带夕阳闻鼓角，
寺临秋水见楼台。
兰堂客散蝉犹噪，
桂楫人稀鸟自来。
独想征车过巩洛，
此中霜菊绕潭开。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_111','新卜原上居寄袁校书','许浑','唐','贫居乐游此，
江海思迢迢。
雪夜书千卷，
花时酒一瓢。
独愁秦树老，
孤梦楚山遥。
有路应相念，
风尘满黑貂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_112','新兴道中','许浑','唐','芙蓉村步失官金，
折狱无功不可寻。
初挂海帆逢岁暮，
却开山馆值春深。
波浑未辨鱼龙迹，
雾暗宁知蚌鹬心。
夜榜归舟望渔火，
一溪风雨两岩阴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_113','新柳','许浑','唐','无力摇风晓色新，
细腰争妒看来频。
绿阴未覆长堤水，
金穗先迎上苑春。
几处伤心怀远路，
一枝和日送行尘。
东□门外多离别，
愁杀朝朝暮暮人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_114','溪亭二首','许浑','唐','溪亭四面山，
横柳半溪湾。
蝉响螳螂急，
鱼深翡翠闲。
水寒留客醉，
月上与僧还。
犹恋萧萧竹，
西斋未掩关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_115','溪亭二首','许浑','唐','暖枕眠溪柳，
僧斋昨夜期。
茶香秋梦后，
松韵晚吟时。
共戏鱼翻藻，
争栖鸟坠枝。
重阳应一醉，
栽菊助东篱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_116','献白尹','许浑','唐','醉舞任生涯，
褐宽乌帽斜。
庾公先在郡，
疏傅早还家。
林晚鸟争树，
园春蜂护花。
高吟应更逸，
嵩洛旧烟霞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_117','献鄜坊丘常侍','许浑','唐','诏选将军护北戎，
身骑白马臂彤弓。
柳营远识金貂贵，
榆塞遥知玉帐雄。
秋槛鼓鼙惊朔雪，
晓阶旗纛起边风。
蓬莱每望平安火，
应奏班超定远功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_118','献韶阳相国崔公','许浑','唐','一匮为功极九层，
康庄犹自剑棱棱。
舟回北渚经年泊，
门接东山尽日登。
万国已闻传玉玺，
百官犹望启金縢。
贤臣会致唐虞世，
独倚江楼笑范增。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_119','蒙河南刘大夫见示与吏部张公喜雪酬唱辄敢攀和','许浑','唐','风度龙山暗，
云凝象阙阴。
瑞花琼树合，
仙草玉苗深。
欲醉梁王酒，
先调楚客琴。
即应携手去，
将此助商霖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_120','詶殷尧藩','许浑','唐','相如愧许询，
寥落向溪滨。
竹马儿犹小，
荆钗妇惯贫。
独愁忧过日，
多病不如人。
莫怪青袍选，
长安隐旧春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_121','詶钱汝州','许浑','唐','白雪多随汉水流，
谩劳旌旆晚悠悠。
笙歌暗写终年恨，
台榭潜消尽日忧。
鸟散落花人自醉，
马嘶芳草客先愁。
怪来雅韵清无敌，
三十六峰当庾楼。',NULL,'','{"preface": "汝州钱中丞以浑赴郢城（汝州钱中丞以浑赴郢几），见寄佳什，恩怜过等，宠饰逾深，虽吟咏忘疲，实楷模不及，辄率荒浅，依韵献酬。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_122','酬邢杜二员外','许浑','唐','雪带东风洗画屏，
客星悬处聚文星。
未归嵩岭暮云碧，
久别杜陵春草青。
熊轼并驱因雀噪，
隼旟齐驻是鸿冥。
岂知京洛旧亲友，
梦绕潺湲江上亭。',NULL,'','{"preface": "新安刑员外怀洛下旧游（新安刑员外怀洛下旧居），新定杜员外思关中故里，各蒙缄示，因寄一诗以酬。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_123','酬报先上人登楼见寄','许浑','唐','丹叶下西楼，
知君万里愁。
钟非黔峡寺，
帆是敬亭舟。
山色和云暮，
湖光共月秋。
天台多道侣，
何惜更南游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_124','酬杜补阙初春雨中舟次横江喜裴郎中相迎见寄','许浑','唐','江馆维舟为庾公，
暖波微渌雨濛濛。
红桥迤逦春岩下，
朱旆联翩晓树中。
柳滴圆波生细浪，
梅含香艳吐轻风。
郢歌莫问青山吏，
鱼在深池鸟在笼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_125','酬和杜侍御','许浑','唐','花时曾省杜陵游，
闻下书帷不举头。
因过石城先访戴，
欲朝金阙暂依刘。
征帆夜转鸬鹚穴，
骋骑春辞鹳雀楼。
正把新诗望南浦，
棹歌应是木兰舟。',NULL,'','{"preface": "河中杜侍御，祗命本府，自钟陵舟抵汉上，道出兹郡，以某专使迎接，先蒙雅什见贻，窃慕清才，辄酬和。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_126','酬河中杜侍御重寄','许浑','唐','五色如丝下碧空，
片帆还绕楚王宫。
文章已变南山雾，
羽翼应抟北海风。
春雪预呈霜简白，
晓霞先染绣衣红。
十千沽酒留君醉，
莫道归心似转蓬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_127','酬郭少府先奉使巡涝见寄兼呈裴明府','许浑','唐','载书携榼别池龙，
十幅轻帆处处通。
谢朓宅荒山翠里，
王敦城古月明中。
江村夜涨浮天水，
泽国秋生动地风。
饱食鲙鱼榜归楫，
待君琴酒醉陶公。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_128','酬副使郑端公见寄','许浑','唐','一日高名遍九州，
玄珠仍向道中求。
郢中白雪惭新唱，
涂上青山忆旧游。
笙磬有文终易别，
珠玑无价竟难酬。
柳营迢遰江风阔，
夜夜孤吟月下楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_129','酬绵州于中丞使君见寄','许浑','唐','故人书信越褒斜，
新意虽多旧约赊。
皆就一麾先去国，
共谋三径未还家。
荆巫夜隔巴西月，
鄢郢春连汉上花。
半月离居犹怅望，
可堪垂白各天涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_130','暝投灵智寺渡溪不得却取沿江路往','许浑','唐','双岩泻一川，
回马断桥前。
古庙阴风地，
寒钟暮雨天。
沙虚留虎迹，
水滑带龙涎。
却下临江路，
潮深无渡船。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_131','韶州送窦司直北归','许浑','唐','江曲山如画，
贪程亦驻舟。
果随岩狖落，
槎带水禽流。
客散他乡夜，
人归故国秋。
樽前挂帆去，
风雨下西楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_132','韶州韶阳楼夜宴','许浑','唐','待月西楼捲翠罗，
玉杯瑶瑟近星河。
帘前碧树穷秋密，
窗外青山薄暮多。
鸲鹆未知狂客醉，
鹧鸪先让美人歌。
使君莫惜通宵饮，
刀笔初从马伏波。',NULL,'[{"Book": "《唐贤小三昧集续集》", "Section": null, "Content": "三四佳句，开放翁一派。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐贤小三昧集续集》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_133','潼关兰若','许浑','唐','来往几经过，
前轩枕大河。
远帆春水阔，
高寺夕阳多。
蝶影下红药，
鸟声喧绿萝。
故山归未得，
徒咏采芝歌。',NULL,'[{"Book": "《重订中晚唐诗主客图》", "Section": null, "Content": "名句（“远帆”二句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《重订中晚唐诗主客图》"}, {"Book": "《石园诗话》", "Section": null, "Content": "韦庄读浑诗云：“江南才子许浑诗，字字清新句句奇。十斛真珠量不尽，惠休空作碧云词。”《丁卯集》中“孤枕易为客，远书难到家”、“林繁树势直，溪转水纹斜”、“远帆春水阔，高寺夕阳多”……“两岸晓烟千银草，半帆斜日一江风”、“溪云初起日沉阁，山雨欲来风满楼”之句，《寄房千里》、《金陵怀古》、《凌歊台》、《骊山》、《四皓庙》诸诗，字字清新，果不愧乎为“江南才子”也！", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《石园诗话》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_134','霅上宴别','许浑','唐','山断水茫茫，
洛人西路长。
笙歌留远棹，
风雨寄华堂。
红壁耿秋烛，
翠帘凝晓香。
谁堪从此去，
云树满陵阳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_135','题义女亭','许浑','唐','身没兰闺道日明，
郭南寻得旧池亭。
诗人愁立暮山碧，
贾客怨离秋草青。
四望月沈疑掩镜，
两檐花动认收屏。
至今乡里风犹在，
借问谁传义女铭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_136','题卫将军庙','许浑','唐','武牢关下护龙旗，
挟槊弯弧马上飞。
汉业未兴王霸在，
秦军才散鲁连归。
坟穿大泽埋金剑，
庙枕长溪挂铁衣。
欲奠忠魂何处问，
苇花枫叶雨霏霏。',NULL,'[{"Book": "《对床夜语》", "Section": null, "Content": "用物而不为物所赘，写情而不为情所牵，李杜之后，当学者许浑而已。周伯弼以唐诗自鸣，亦唯以许集谆淳诲人。今摭拔警句可以为法者书于后，云：“风传鼓角箱侵戟，云卷笙歌月上楼”、“山殿日斜喧鸟雀，石潭波动戏鱼龙”……《卫将军庙》云：“汉业未兴王霸在，秦军才散鲁连归”，皆妙。其起结尤非中唐人可及。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《对床夜语》"}, {"Book": "《诗源辨体》", "Section": null, "Content": "（许浑）七言律如“坟穿大泽埋金剑，庙枕长溪托铁衣”、“对雪夜穷黄石略，望云秋计黑山程”、“旧精鸟篆谙书体，新授龙韬识禅机”三联，巧晚唐俊调。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《诗源辨体》"}, {"Book": "《东岩草觉评订唐诗鼓吹》", "Section": null, "Content": "朱东岩曰：“护龙旗”、“马上飞”，写将军神勇如画。三写其功也，四写其功成身退也。以将军如此之功而能急流勇退，此所以成其大勇也。后四句虽寓感慨之意，然“穿大泽”、“枕长流”、“埋金剑”、“挂铁衣”，如此写将军庙貌，赫赫然有生气。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《东岩草觉评订唐诗鼓吹》"}, {"Book": "《围炉诗话》", "Section": null, "Content": "首联言战功，次联言高蹈，三联言坟庙，国联以情景结之，题中之意自足，措词无一虚壳。但许海俱无远神，故当时不重之耳。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《围炉诗话》"}, {"Book": "《山满楼笺注唐诗七言律》", "Section": null, "Content": "此卫将军生平大节，无过“护龙旗”一事，故首举之，而“挟槊弯弧”七字，写将军勇略盖世，觉千载下犹奕奕有生气。三承上，以王霸之辅光武称之；四侧下，以平原之不能留鲁仲连惜之：可谓重之至矣。三承上：将言“庙挂铁衣”，六先用“坟埋金剑”作陪笔，得宾主法。七一顿，八一缴；“何处问”之为言，无处问也，非欲问之细雨之中、苇花枫叶之间。可知脉络井然，其气格一何高爽！", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《山满楼笺注唐诗七言律》"}]','{"preface": "将军名逖，阳羡人，少习诗书，学弓剑，有武略，二十七游并汾间，遇神尧皇帝始建义旗，逖以勇艺进，备行列。洎擒宝建德，逖时挟鎗剑，前突后翼，太宗顾而奇之，天下既定，录其功，拜将军宿卫。以母老且病，乞归侍残年，辞旨哀激，诏许之，既而以孝敬睦闺门。以然信居乡里，及卒，邑人怀其贤，庙于荆溪之湄，以平生弓甲，县东西庑下，岁时祠祭，颇福其土焉。文士王敖撰碑，辞实详备，惜乎国史阙书其人，因题是诗于庙壁。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_137','题韦隐居西斋','许浑','唐','斸药去还归，
家人半掩扉。
山风藤子落，
溪雨豆花肥。
寺远僧来少，
桥危客到稀。
不闻砧杵动，
应解制荷衣。',NULL,'[{"Book": "《唐诗近体》", "Section": null, "Content": "韦处士起（首句下）。所居（“家人”句下）。幽绝（“山风”二句下）。斸药制衣，皆隐居事，一实一虚（末二句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗近体》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_138','题四皓庙','许浑','唐','桂香松暖庙门开，
独泻椒浆奠一杯。
秦法欲兴鸿已去，
汉储将废凤还来。
紫芝翳翳多青草，
白石苍苍半绿苔。
山下驿尘南窜路，
不知冠盖几人回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_139','题冲沼上人院','许浑','唐','斸石种松子，
数根侵杳冥。
天寒犹讲律，
雨暗尚寻经。
小殿灯千盏，
深炉水一瓶。
碧云多别思，
休到望溪亭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_140','题杜居士','许浑','唐','松偃石床平，
何人识姓名。
溪冰寒棹响，
岩雪夜窗明。
机尽心猿伏，
神闲意马行。
应知此来客，
身世两无情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_141','题灵山寺行坚师院','许浑','唐','西岩一径不通樵，
八十持杯未觉遥。
龙在石潭闻夜雨，
雁移沙渚见秋潮。
经函露湿文多暗，
香印风吹字半销。
应笑东归又南去，
越山无路水迢迢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_142','题苏州虎丘寺僧院','许浑','唐','暂引寒泉濯远尘，
此生多是异乡人。
荆溪夜雨花开疾，
吴苑秋风月满频。
万里高低门外路，
百年荣辱梦中身。
世间谁似西林客，
一卧烟霞四十春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_143','题邹处士隐居','许浑','唐','桑柘满江村，
西斋接海门。
浪冲高岸响，
潮入小池浑。
岩树阴棋局，
山花落酒樽。
相逢亦留宿，
还似识王孙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_144','题陆侍御林亭','许浑','唐','野水通池石叠台，
五营无事隐雄才。
松斋下马书千卷，
兰舫逢人酒一杯。
寒树雪晴红艳吐，
远山云晓翠光来。
定知别后无多日，
海柳江花次第开。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_145','题官舍','许浑','唐','燕雁水乡飞，
京华信自稀。
箪瓢贫守道，
书剑病忘机。
叠鼓吏初散，
繁钟鸟独归。
高梧与疏柳，
风雨似郊扉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_146','题岫上人院','许浑','唐','病客与僧闲，
频来不掩关。
高窗云外树，
疏磬雨中山。
离索秋虫响，
登临夕鸟还。
心知落帆处，
明日浙河湾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_147','题青山馆','许浑','唐','昔人诗酒地，
芳草思王孙。
白水半塘岸，
青山横郭门。
悬岩碑已折，
盘石井犹存。
无处继行乐，
野花空一尊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_148','题宣州元处士幽居','许浑','唐','潺湲绕门水，
未省濯缨尘。
鸟散千岩曙，
蜂来一径春。
杉松还待客，
芝朮不求人。
宁学磻溪叟，
逢时罢隐沦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_149','题故李秀才居','许浑','唐','曾醉笙歌日正迟，
醉中相送易前期。
橘花满地人亡后，
菰叶连天雁过时。
琴倚旧窗尘漠漠，
剑埋新冢草离离。
河桥酒熟平生事，
更向东流奠一卮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_150','题倪处士旧居','许浑','唐','儒翁九十馀，
旧向此山居。
生寄一壶酒，
死留千卷书。
槛摧新竹少，
池浅故莲疏。
但有子孙在，
带经还荷锄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_151','题崇圣寺','许浑','唐','西林本行殿，
池榭日坡陁。
雨过水初涨，
云开山渐多。
晓街垂御柳，
秋院闭宫莎。
借问龙归处，
鼎湖空碧波。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_152','题崔处士山居','许浑','唐','坐穷今古掩书堂，
二顷湖田一半荒。
荆树有花兄弟乐，
橘林无实子孙忙。
龙归晓洞云犹湿，
麝过春山草自香。
向夜欲归心万里，
故园松月更苍苍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_153','题舒女庙','许浑','唐','山乐来迎去不言，
庙前高柳水禽喧。
绮罗无色雨侵帐，
珠翠有声风绕幡。
妆镜尚疑山月满，
寝屏犹认野花繁。
孤舟梦断行云散，
何限离心寄晓猿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_154','题勤尊师历阳山居','许浑','唐','二十知兵在羽林，
中年潜识子房心。
苍鹰出塞胡尘灭，
白鹤还乡楚水深。
春坼酒瓶浮药气，
晚携棋局带松阴。
鸡笼山上云多处，
自斸黄精不可寻。',NULL,'','{"preface": "师即思齐之孙，顷为故相国萧公录用。相国致政，尊师亦自边将入道，因赠是诗。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_155','题愁','许浑','唐','聚散竟无形，
回肠百结成。
古今销不得，
离别觉潜生。
降虏将军思，
穷秋远客情。
何人更憔悴，
落第泣秦京。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_156','题灞西骆隐士','许浑','唐','磻溪连灞水，
商岭接秦山。
青汉不回驾，
白云长掩关。
雀喧知鹤静，
凫戏识鸥闲。
却笑南昌尉，
悠悠城市间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_157','题灞西骆隐居','许浑','唐','志凌三蜀客，
心爱五湖人。
𢬵死酒中老，
谋生书外贫。
扫花眠石榻，
捣药转溪轮。
往往乘黄牸，
鹿裘乌角巾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_158','鹤林寺中秋夜玩月','许浑','唐','待月东林月正圆，
广庭无树草无烟。
中秋云尽出沧海，
半夜露寒当碧天。
轮彩渐移金殿外，
镜光犹挂玉楼前。
莫辞达曙殷勤望，
一堕西岩又隔年。',NULL,'[{"Book": "《贯华堂选批唐才子诗》", "Section": null, "Content": "前后二解，皆写当天宝月。然前解是写“待”，后解是写“惜”，待在未当天前，惜在正当天后，此理本自面前，而并无一人猛省，偶因读此，不胜太息。二句七字，写尽“待月中庭”四字神理。三四十四字，写尽“月正圆”三字神理。唐人每用先唱七字，而后以三句了之，此其法也（首四句下）。“端挂”前，遽写渐移，使人心惊。“渐移”下，仍写“端挂”，使人心慰。若在俗笔，必将换转，写“端挂”在前，“渐移”在后，便是满纸衰飒，灭尽无限神理。一将“渐移”字换转“端挂”字下，便心笔都竭矣。偏将“端挂”字转换“渐移”字下，而反觉心头眼底有事忽忽，恐失信知；“一堕西岩”，正是天生妙结（末四句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《贯华堂选批唐才子诗》"}, {"Book": "《东岩草堂评订唐诗鼓吹》", "Section": null, "Content": "朱东岩曰：题是《中秋玩月》，通首只写“月正圆”三字。……五六须看托换笔之妙，如先写“犹挂”，后写“渐移”，顺笔也；先写“渐移”，后写“犹桂”，倒笔也；一经转换，便觉生气灵动，意味无穷，于此可分雅俗之别。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《东岩草堂评订唐诗鼓吹》"}, {"Book": "《诗学纂闻》", "Section": null, "Content": "（彭茶江）先生曰：此诗意境似平，格律实细。首云“待月东林月正圆”，月从东出，“待”在来出之时；既出，则“月正圆”也。次曰“广庭无树草无烟”，写月之明，一句尽矣。三曰“中秋云净出沧海”，此特补点中秋，以别于他月之望。四云“午夜露凉当碧天”，半夜月正当头也。五云“轮影渐移金殿外”，月昃时西移矣。六云“镜光犹挂玉楼前”，将落而犹未落也。结云“不辞达旦殷勤望，一堕西岩又隔年”，隔年又以醒“中秋”之意。八句次第写尽达旦之景，此唐律所以胜于后人，不然，轮影镜光玉楼金殿，抑何尘容俗状欤？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《诗学纂闻》"}, {"Book": "《山满楼笺注唐诗七言律》", "Section": null, "Content": "题是玩月，诗却从月未出以前写起，故先著一“待”字。既言“东林”，又补出东林之“广庭”，言此寺中最好玩月也。三，月初出；四，月已中：此二句只写中秋夜月。以下方是写“玩”。五，影渐移，惜之；六，光端挂，幸之。一捺一抬，恰好翻起。七之“莫辞”，八之“一堕”，回翔婉转，最为有情存趣之笔也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《山满楼笺注唐诗七言律》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_159','赠王山人','许浑','唐','贳酒携琴访我频，
始知城市有闲人。
君臣药在宁忧病，
子母钱成岂患贫。
年长每劳推甲子，
夜寒初共守庚申。
近来闻说烧丹处，
玉洞桃花万树春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_160','赠王处士','许浑','唐','归卧养天真，
鹿裘乌角巾。
茂陵闲久病，
彭泽醉长贫。
冠盖西园夜，
笙歌北里春。
谁怜清渭曲，
又老钓鱼人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_161','赠迁客','许浑','唐','无机还得罪，
直道不伤情。
微雨昏山色，
疏笼闭鹤声。
闲居多野客，
高枕见江城。
门外长溪水，
怜君又濯缨。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_162','赠别','许浑','唐','眼前迎送不曾休，
相续轮蹄似水流。
门外若无南北路，
人间应免别离愁。
苏秦六印归何日，
潘岳双毛去值秋。
莫怪分襟衔泪语，
十年耕钓忆沧洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_163','赠李伊阙','许浑','唐','桐履如飞不可寻，
一壶双笈峄阳琴。
舟横野度寒风急，
门掩荒山夜雪深。
贫笑白驹无去意，
病惭黄鹄有归心。
云间二室劳君画，
水墨苍苍半壁阴。',NULL,'','{"preface": "前伊阙李师晦侍御辞秩归山，过余所止，醉图二室于屋壁，亦招隐之旨也，因而有赠焉。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_164','赠闲师','许浑','唐','近日高僧更有谁，
宛陵山下遇闲师。
东林共许三乘学，
南国争传五字诗。
初到庾楼红叶坠，
夜投萧寺碧云随。
秋江莫惜题佳句，
正是磷磷见底时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_165','赠所知','许浑','唐','因钓鲈鱼住浙河，
挂帆千里亦相过。
茅檐夜醉平阶月，
兰棹春归拍岸波。
湖日似阴鼍鼓响，
海云才起蜃楼多。
明时又作闲居赋，
谁荐东门策四科。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_166','赠河东虞押衙二首','许浑','唐','长剑高歌换素衣，
君恩未报不言归。
旧精鸟篆谙书体，
新授龙韬识战机。
万里往来征马瘦，
十年离别故人稀。
生平志气何人见，
空上西楼望落晖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_167','赠河东虞押衙二首','许浑','唐','吴门风水各萍流，
月满花开懒独游。
万里山川分晓梦，
四邻歌管送春愁。
昔年顾我长青眼，
今日逢君尽白头。
莫向尊前更惆怅，
古来投笔尽封侯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_168','赠茅山高拾遗','许浑','唐','谏猎归来绮季歌，
大茅峰影满秋波。
山斋留客扫红叶，
野艇送僧披绿莎。
长覆旧图棋势尽，
遍添新品药名多。
云中黄鹄日千里，
自宿自飞无网罗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_169','赠郑处士','许浑','唐','道傍年少莫矜誇，
心在重霄鬓未华。
杨子可曾过北里，
鲁人何必敬东家。
寒云晓散千峰雪，
暖雨晴开一径花。
且卖湖田酿春酒，
与君书剑是生涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_170','赠柳璟冯陶二校书','许浑','唐','霄汉两飞鸣，
喧喧动禁城。
桂堂同日盛，
芸阁间年荣。
香掩蕙兰气，
韵高鸾鹤声。
应怜茂陵客，
未有子虚名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_171','赠桐庐房明府先辈','许浑','唐','帝城春榜谪灵仙，
四海声华二十年。
阙下书功无后辈，
卷中文字掩前贤。
官闲每喜江山静，
道在宁忧雨露偏。
自笑小儒非一鹗，
亦趋门屏冀相怜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_172','赠高处士','许浑','唐','宅前云水满，
高兴一书生。
垂钓有深意，
望山多远情。
夜棋留客宿，
春酒劝僧倾。
未作干时计，
何人问姓名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_173','赠梁将军','许浑','唐','曾经黑山虏，
一剑出重围。
年长穷书意，
时清隐钓矶。
高斋云外住，
瘦马月中归。
唯说乡心苦，
春风雁北飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_174','赠萧兵曹先辈','许浑','唐','广陵堤上昔离居，
帆转潇湘万里馀。
楚客病时无鵩鸟，
越乡归处有鲈鱼。
潮生水郭蒹葭响，
雨过山城橘柚疏。
闻说携琴兼载酒，
邑人争识马相如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_175','赠隐者','许浑','唐','回报隐居士，
莫愁山兴阑。
求人颜色尽，
知道性情宽。
信谱弹琴误，
缘崖斸药难。
东皋亦自给，
殊愧远相安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_176','赠裴处士','许浑','唐','为儒白发生，
乡里早闻名。
煖酒雪初下，
读书山欲明。
字形翻鸟迹，
诗调合猿声。
门外沧浪水，
知君欲濯缨。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_177','懿安皇太后挽歌词','许浑','唐','陵前春不尽，
陵下夜何穷。
未信金蚕老，
先惊玉燕空。
挽移兰殿月，
笳引柏城风。
自此随龙驭，
桥山翠霭中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_178','灞上逢元九处士东归','许浑','唐','瘦马频嘶灞水寒，
灞南高处望长安。
何人更结王生袜，
此客虚弹贡氏冠。
江上蟹螯沙渺渺，
坞中蜗壳雪漫漫。
旧交已变新知少，
却伴渔郎把钓竿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_179','灞东题司马郊园','许浑','唐','楚翁秦塞住，
昔事李轻车。
白社贫思橘，
青门老仰瓜。
读书三径草，
沽酒一篱花。
更欲寻芝朮，
商山便寄家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_180','鸂鶒','许浑','唐','池寒柳复凋，
独宿夜迢迢。
雨顶冠应冷，
风毛剑欲飘。
故巢迷碧水，
旧侣越丹霄。
不是无归处，
心高多寂寥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_181','岁暮自广江至新兴往复中题峡山寺四首','许浑','唐','夜醉晨方醒，
孤吟恐失群。
海䲡潮上见，
江鹄雾中闻。
未腊梅先实，
经冬草自薰。
树随山崦合，
泉到石棱分。
虎迹空林雨，
猿声绝岭云。
萧萧异乡鬓，
明日共丝棼。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_182','岁暮自广江至新兴往复中题峡山寺四首','许浑','唐','薄暮缘西峡，
停桡一访僧。
鹭巢横卧柳，
猿饮倒垂藤。
水曲岩千叠，
云重树百层。
山风寒殿磬，
溪雨夜船灯。
滩涨危槎没，
泉冲怪石崩。
中台一襟泪，
岁杪别良朋。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_183','岁暮自广江至新兴往复中题峡山寺四首','许浑','唐','密树分苍壁，
长溪抱碧岑。
海风闻鹤远，
潭日见鱼深。
松盖环清韵，
榕根架绿阴。
洞丁多斲石，
蛮女半淘金。
南浦惊春至，
西楼送月沈。
江流不过岭，
何处寄归心。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_184','岁暮自广江至新兴往复中题峡山寺四首','许浑','唐','月在行人起，
千峰复万峰。
海虚争翡翠，
溪逻斗芙蓉。
古木高生槲，
阴池满种松。
火探深洞燕，
香送远潭龙。
蓝坞寒先烧，
禾堂晚并舂。
更投何处宿，
西峡隔云钟。',NULL,'[{"Book": "《瀛奎律髓》", "Section": null, "Content": "许丁卯此四首诗题峡山寺，其实广东风土也。诗句句工，但太工则形胜于神耳。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓》"}, {"Book": "《瀛奎律髓汇评》", "Section": null, "Content": "冯班：丁卯诗句句清新，大略少萧散之致。纪昀：此乃纪程之诗，题之峡山寺中耳，非题峡山寺也。虚谷……云形胜于神，则诚为确论。李光垣：四首中凡用云、月、风、雨、树、石、山、溪等字，俱复。\\n无名氏（甲）：此诗言广东风土甚备，可存典故。至于铺陈排比，未能血脉贯串，眼目玲珑，自工部而外，希风者鲜，未可独苛丁卯也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓汇评》"}]','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_185','泛五云溪','许浑','唐','此溪何处路，
遥问白髯翁。
佛庙千岩里，
人家一岛中。
鱼倾荷叶露，
蝉噪柳林风。
急濑鸣车轴，
微波漾钓筒。
石苔萦棹绿，
山果拂舟红。
更就千村宿，
溪桥与剡通。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_186','和李相国','许浑','唐','巨实珍吴果，
驯雏重越禽。
摘来渔浦上，
携在兔园阴。
霜合凝丹颊，
风披敛素襟。
刀分琼液散，
笼簌雪华深。
虎帐斋中设，
龙楼洛下吟。
含消兼受彩，
应贵冢卿心。',NULL,'','{"preface": "蒙宾客相国李公见示和宣武卢仆射以吏部高尚书自江南赴阙贶大梨白鹇，因赠五言六韵攀和。", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_187','和宾客相国咏雪','许浑','唐','近腊千岩白，
迎春四气催。
云阴连海起，
风急度山来。
尽日隋堤絮，
经冬越岭梅。
艳疑歌处散，
轻似舞时回。
道蕴诗传丽，
相如赋骋才。
霁添松筱媚，
寒积蕙兰猜。
暗涨宫池水，
平封辇路埃。
烛龙初照耀，
巢鹤乍裴回。
檐日琼先挂，
墙风粉旋摧。
五门环玉垒，
双阙对瑶台。
绮席陵寒坐，
珠帘远曙开。
灵芝霜下秀，
仙桂月中栽。
卷幌书千帙，
援琴酒百杯。
垂休编太史，
呈瑞表中台。
皓夜迷三径，
浮光彻九垓。
兹辰是丰岁，
歌咏属良哉。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_188','奉命和后池十韵','许浑','唐','叠石通溪水，
量波失旧规。
芳洲还屈曲，
朱阁更逶迤。
浴鸟翻荷叶，
惊蝉出柳丝。
翠烟秋桧耸，
红露晓莲披。
攀槛登楼近，
停桡待客迟。
野桥从浪没，
轻舸信风移。
竹韵迁棋局，
松阴递酒卮。
性闲鸥自识，
心远鹤先知。
应想秦人会，
休怀越相祠。
当期穆天子，
箫鼓宴瑶池。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_189','奉和卢大夫新立假山','许浑','唐','岩谷留心赏，
为山极自然。
孤峰空迸笋，
攒萼旋开莲。
黛色朱楼下，
云形绣户前。
砌尘凝积霭，
檐溜挂飞泉。
树暗壶中月，
花香洞里天。
何如谢康乐，
海峤独题篇。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_190','金陵阻风登延祚阁','许浑','唐','极目皆陈迹，
披图问远公。
戈鋋三国后，
冠盖六朝中。
葛蔓交残垒，
芒花没后宫。
水流箫鼓绝，
山在绮罗空。
极浦千艘聚，
高台一径通。
云移吴岫雨，
潮转楚江风。
登阁惭漂梗，
停舟忆断蓬。
归期与归路，
杉桂海门东。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_191','南海使院对菊怀丁卯别墅','许浑','唐','何处曾移菊，
溪桥鹤岭东。
篱疏还有艳，
园小亦无丛。
日晚秋烟里，
星繁晓露中。
影摇金涧水，
香染玉潭风。
罢酒惭陶令，
题诗答谢公。
朝来数花发，
身在尉佗宫。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_192','秋夕宴李侍御宅','许浑','唐','公子徵词客，
秋堂递玉杯。
月高罗幕卷，
风度锦屏开。
凤管添簧品，
鹍弦促柱哀。
转喉云旋合，
垂手露徐来。
烛换三条烬，
香销十炷灰。
蛩声闻鼓歇，
萤燄触帘回。
广槛烟分柳，
空庭露积苔。
解酲须满酌，
应为拨新醅。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_193','送从兄别驾归蜀','许浑','唐','闻与湘南令，
童年侍玉墀。
家留秦塞曲，
官谪瘴溪湄。
道直奸臣屏，
冤深圣主知。
逝川东去疾，
霈泽北来迟。
青汉龙髯绝，
苍岑马鬣移。
风凄闻笛处，
月惨罢琴时。
客路黄公庙，
乡关白帝祠。
已称鹦鹉赋，
宁诵鹡鸰诗。
远道书难达，
长亭酒莫持。
当凭蜀江水，
万里寄相思。',NULL,'','{"preface": "从兄彦昭与桂阳令韦伯达，贞元中，俱为千牛，伯达官至王府长史。长庆中，非罪受谴。前年，会赦，复故秩，诏未及而已殁。从兄自蜀而南，发旅榇，归葬涂上，既而西旋，因成十韵赠别。", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_194','送林处士自闽中道越由霅抵两川','许浑','唐','书剑少青眼，
烟波初白头。
乡关背梨岭，
客路转蘋洲。
处困道难固，
乘时恩易酬。
镜中非访戴，
剑外欲依刘。
高枕海天暝，
落帆江雨秋。
鼍声应远鼓，
蜃气学危楼。
智士役千虑，
达人经百忧。
唯闻陶靖节，
多在醉乡游。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_195','陪少师李相国崔宾客宴居守狄仆射池亭','许浑','唐','池色似潇湘，
仙舟正日长。
燕飞惊蛱蝶，
鱼跃动鸳鸯。
云聚歌初转，
风回舞欲翔。
暖醅松叶嫩，
寒粥杏花香。
罗绮留春色，
笙竽送晚光。
何须明月夜，
红烛在华堂。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_196','寄郴州李相公','许浑','唐','高楼王与谢，
逸韵比南金。
不遇销忧日，
埃尘谁复寻。
旷怀澹得丧，
失意纵登临。
彩槛浮云迥，
绮窗明月深。
虬龙压沧海，
鸳鸯思邓林。
青云伤国器，
白发轸乡心。
功高恩自洽，
道直谤徒侵。
应笑灵均恨，
江畔独行吟。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_197','晨自竹径至龙兴寺崇隐上人院','许浑','唐','佛寺通南径，
僧堂倚北坡。
藤阴迷晚竹，
苔滑仰晴莎。
病忆春前别，
闲宜雨后过。
石横闻水远，
林缺见山多。
欲结三天社，
初降十地魔。
毒龙来有窟，
灵鹤去无窠。
客路随萍梗，
乡园失薜萝。
禅心如可学，
不藉鲁阳戈。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_198','维舟秦淮过温州李给事宅','许浑','唐','给事为郎日，
青溪醉隐衔。
冰池通极浦，
雪径绕高岩。
珠玉砂同弃，
松筠草共芟。
帝图忧一失，
臣节耻三缄。
代有王陵戆，
时无靳尚谗。
定应标直笔，
宁为发空函。
雾黑连云栈，
风狂截海帆。
石梯迎雨润，
沙井待潮咸。
蜡屐青筇杖，
蓝舆白罽衫。
应劳北归梦，
山路正巉巉。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_199','登蒜山观发军','许浑','唐','羽檄徵兵急，
辕门选将雄。
犬羊忧破竹，
貔虎极飞蓬。
定系猖狂虏，
何烦矍铄翁。
更探黄石略，
重振黑山功。
别马嘶营柳，
惊乌散井桐。
低星连宝剑，
残月让雕弓。
浪晓戈鋋里，
山晴鼓角中。
甲开鱼照水，
旗飏虎拿风。
去想金河远，
行知玉塞空。
汉庭应有问，
师律在元戎。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_200','赠萧鍊师','许浑','唐','曾试昭阳曲，
瑶斋帝自临。
红珠络绣帽，
翠钿束罗襟。
双阙胡尘起，
千门宿露阴。
出宫迷国步，
回驾轸皇心。
桂殿春空晚，
椒房夜自深。
急宣求故剑，
冥契得遗簪。
暗记神仙传，
潜封女史箴。
壶中知日永，
掌上畏年侵。
莫比班家扇，
宁同卓氏琴。
云车辞凤辇，
羽帔别鸳衾。
网断鱼游藻，
笼开鹤戏林。
洛烟浮碧汉，
嵩月上丹岑。
露草争三秀，
风篁共八音。
吹笙延鹤舞，
敲磬引龙吟。
旄节纤腰举，
霞杯皓腕斟。
还磨照宝镜，
犹插辟寒金。
东海人情变，
南山圣寿沈。
朱颜常似渥，
绿发已如寻。
养气齐生死，
留形尽古今。
更求应不见，
鸡犬日骎骎。',NULL,'','{"preface": "鍊师，贞元初自梨园选为内妓，善舞柘枝，宫中莫有伦比者，宠锡甚厚，及驾幸奉天，以病不获随辇，遂失所止。洎复宫阙，上颇怀其艺，求之浃日，得于人间，后闻神仙之事，谓长生可致，乞奉黄老，上许之，诏居嵩南洞清观，迨今八十馀矣。雪肤花颜，与昔无异，则知龟鹤之寿，安得不由所尚哉，因赋是诗，题于院壁。", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_201','冬日宣城开元寺赠元孚上人','许浑','唐','一钵事南宗，
僧仪称病容。
曹溪花里别，
萧寺竹前逢。
烛影深寒殿，
经声彻曙钟。
欲斋檐睡鸽，
初定壁吟蛩。
诗继休遗韵，
书传永逸踪。
艺多人誉洽，
机绝道情浓。
汲涧瓶沈藻，
眠阶锡挂松。
云鸣新放鹤，
池卧旧降龙。
露茗山厨焙，
霜粳野碓舂。
梵文明处译，
禅衲暖时缝。
层塔题应遍，
飞轩步不慵。
绣梁交薜荔，
画井倒芙蓉。
翠户垂旗网，
朱窗列剑锋。
寒风金磬远，
晴雪玉楼重。
妙理三乘达，
清才万象供。
山高横睥睨，
滩浅聚艨艟。
微雾苍平楚，
残晖淡远峰。
林疏霜摵摵，
波静月溶溶。
剑出因雷焕，
琴全遇蔡邕。
西方知有社，
支许合相从。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_202','洛阳道中','许浑','唐','洛阳多旧迹，
一日几堪愁。
风起林花晚，
月明陵树秋。
兴亡不可问，
自古水东流。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_203','闻边将刘皋无辜受戮','许浑','唐','外监多假帝王尊，
威胁偏裨势不存。
才许誓心安玉垒，
已伤传首动金门。
三千客里宁无义，
五百人中必有恩。
却赖汉庭多烈士，
至今犹自伏蒲轮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_204','游江令旧宅','许浑','唐','身没南朝宅已荒，
邑人犹赏旧风光。
芹根生叶石池浅，
桐树落花金井香。
带暖山蜂巢画阁，
欲阴溪燕集书堂。
闲愁此地更西望，
潮浸台城春草长。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_205','酬康州韦侍御同年','许浑','唐','桂楫美人歌木兰，
西风袅袅露漙漙。
夜长曲尽意不尽，
月在清湘洲渚寒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_206','句','许浑','唐','蒹葭水暗萤知夜，
杨柳风高雁送秋。
露滴晓花疑锦绣，
风吹寒竹认笙簧。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_207','咏牛应制','许圉师','初唐','逸足还同骥，
奇毛自偶麟。
欲知花迹远，
云影入天津。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_208','日暮碧云合','许康佐','中唐','日际愁阴生，
天涯暮云碧。
重重不辨盖，
沈沈乍如积。
林色黯疑暝，
隙光俄已夕。
出岫且从龙，
萦空宁触石。
馀辉澹瑶草，
浮影凝绮席。
时景讵能留，
几思轻尺璧。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_209','北游夜怀','许彬','唐末','苦心终是否，
舍此复无营。
已致归成晚，
非缘去有程。
馆空吟向月，
霜曙坐闻更。
住久谁相问，
驰羸又独行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_210','归山夜发湖中','许彬','唐末','广泽去无边，
夜程风信偏。
疏星遥抵浪，
远烧似迎船。
响岳猿相次，
翻空雁接连。
北归家业就，
深处更踰年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_211','寻白石山人涧','许彬','唐末','路穷川岛上，
果值古仙家。
阴洞长鸣磬，
石泉寒泛花。
莓苔深峭壁，
烟霭积层崖。
难见囊中术，
人间有岁华。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_212','经李翰林庐山屏风叠所居','许彬','唐末','放逐非多罪，
江湖偶不回。
深居应有谓，
济代岂无才。
叠巘晴舒障，
寒川暗动雷。
谁能续高兴，
醉死一千杯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_213','送李处士归山','许彬','唐末','旧山来复去，
不与世人论。
得道书留箧，
忘机酒满尊。
溪轩松偃坐，
石室水临门。
应有频相访，
相看坐到昏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_214','重经汉南','许彬','唐末','分散多如此，
人情岂自由。
重来看月夕，
不似去年秋。
息虑虽孤寝，
论空未识愁。
须同醉乡者，
万事付江流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_215','湘江','许彬','唐末','孤舟方此去，
嘉景称于闻。
烟尽九峰雪，
雨生诸派云。
沙寒鸿鹄聚，
底极龟鱼分。
异日谁为侣，
逍遥耕钓群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_216','酬简寂熊尊师以赵员外庐山草堂见借','许彬','唐末','岂易投居止，
庐山得此峰。
主人曾已许，
仙客偶相逢。
顾己恩难答，
穷经业未慵。
还能励僮仆，
稍更补杉松。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_217','黔中书事','许彬','唐末','巴蜀水南偏，
山穷塞垒宽。
岁时将近腊，
草树未知寒。
独狖啼朝雨，
群牛向暮滩。
更闻蛮俗近，
烽火不艰难。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_218','府试莱城晴日望三山','许彬','唐末','不易识蓬瀛，
凭高望有程。
盘根出巨浸，
远色到孤城。
隐隐排云峻，
层层就日明。
净收残霭尽，
浮动嫩岚轻。
纵目徒多暇，
驰心累发诚。
从容更何往，
此路彻三清。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_219','题故李宾客庐山草堂','许彬','唐末','难穷林下趣，
坐使致君恩。
术业行当代，
封章动谏垣。
已明邪佞迹，
几雪薜萝冤。
报主深知此，
忧民讵可论。
名将山共古，
迹与道俱存。
为谢重来者，
何人更及门。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_220','拟江令于长安归扬州九日赋','许敬宗','隋末唐初','本逐征鸿去，
还随落叶来。
菊花应未满，
请待诗人开。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_221','拟江令于长安归扬州九日赋','许敬宗','隋末唐初','游人倦蓬转，
乡思逐雁来。
偏想临潭菊，
芳蕊对谁开。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_222','冬日宴于庶子宅各赋一字得归','许敬宗','隋末唐初','倦游嗟落拓，
短翮慕追飞。
周醪忽同醉，
牙弦乃共挥。
油云澹寒色，
落景霭霜霏。
累日方投分，
兹夕谅无归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_223','奉和七夕宴悬圃应制二首','许敬宗','隋末唐初','牛闺临浅汉，
鸾驷涉秋河。
两怀萦别绪，
一宿庆停梭。
星模铅里靥，
月写黛中蛾。
奈许今宵度，
长婴离恨多。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_224','奉和七夕宴悬圃应制二首','许敬宗','隋末唐初','婺闺期今夕，
娥轮泛浅潢。
迎秋伴暮雨，
待暝合神光。
荐寝低云鬓，
呈态解霓裳。
喜中愁漏促，
别后怨天长。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_225','奉和仪鸾殿早秋应制','许敬宗','隋末唐初','睿想追嘉豫，
临轩御早秋。
斜晖丽粉壁，
清吹肃朱楼。
高殿凝阴满，
雕窗艳曲流。
小臣参广宴，
大造谅难酬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_226','奉和过慈恩寺应制','许敬宗','隋末唐初','凤阙邻金地，
龙旂拂宝台。
云楣将叶并，
风牖送花来。
月宫清晚桂，
虹梁绚早梅。
梵境留宸瞩，
掞发丽天才。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_227','奉和咏雨应诏','许敬宗','隋末唐初','舞商初赴节，
湘燕远迎秋。
飘丝交殿网，
乱滴起池沤。
激溜分龙阙，
斜飞洒凤楼。
崇朝方浃宇，
宸盼俯凝旒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_228','送刘散员同赋得陈思王诗山树郁苍苍','许敬宗','隋末唐初','乔木托危岫，
积翠绕连冈。
叶疏犹漏影，
花少未流芳。
风来闻肃肃，
雾罢见苍苍。
此中饯行迈，
不异上河梁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_229','安德山池宴集','许敬宗','隋末唐初','戚里欢娱地，
园林瞩望新。
山庭带芳杜，
歌吹叶阳春。
台榭疑巫峡，
荷蕖似洛滨。
风花萦少女，
虹梁聚美人。
宴游穷至乐，
谈笑毕良辰。
独叹高阳晚，
归路不知津。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_230','侍宴莎册宫应制得情字','许敬宗','隋末唐初','三星希曙景，
万骑翊天行。
葆羽翻风队，
腾吹掩山楹。
暖日晨光浅，
飞烟旦彩轻。
塞寒桃变色，
冰断箭流声。
渐奏长安道，
神皋动睿情。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_231','奉和九月九日应制','许敬宗','隋末唐初','爽气申时豫，
临秋肆武功。
太液荣光发，
曾城佳气融。
紫霄寒暑丽，
黄山极望通。
讲艺遵先轨，
睹德畅宸衷。
鹫岭飞夏服，
娥魄乱雕弓。
汗浃镳流赭，
尘生埒散红。
饮羽惊开石，
中叶遽凋丛。
雁殚云路静，
乌坠日轮空。
九流参广宴，
万宇抃恩隆。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_232','奉和元日应制','许敬宗','隋末唐初','天正开初节，
日观上重轮。
百灵滋景祚，
万玉庆惟新。
待旦敷玄造，
韬旒御紫宸。
武帐临光宅，
文卫象钩陈。
广庭扬九奏，
大帛丽三辰。
发生同化育，
播物体陶钧。
霜空澄晓气，
霞景莹芳春。
德辉覃率土，
相贺奉还淳。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_233','奉和圣制登三台言志应制','许敬宗','隋末唐初','中天表云榭，
载极耸昆楼。
圣作规玄造，
轩阿复聿修。
高门符令节，
形胜总神州。
企翼抟禽萃，
飞甍燕雀游。
缀星罗百拱，
缘汉转三休。
旦云生玉舄，
初月上银钩。
妙管含秦凤，
仙姿丽斗牛。
形言防处逸，
粹藻发嘉猷。
荷生无以谢，
尽瘁竟何酬。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_234','奉和守岁应制','许敬宗','隋末唐初','玉琯移玄序，
金奏赏彤闱。
祥鸾歌里转，
春燕舞前归。
寿爵传三礼，
灯枝丽九微。
运广薰风积，
恩深湛露晞。
送寒终此夜，
延宴待晨晖。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_235','奉和行经破薛举战地应制','许敬宗','隋末唐初','混元分大象，
长策挫修鲸。
于斯建宸极，
由此创鸿名。
一戎乾宇泰，
千祀德流清。
垂衣凝庶绩，
端拱铸群生。
复整瑶池驾，
还临官渡营。
周游寻曩迹，
旷望动天情。
帷宫面丹浦，
帐殿瞩宛城。
虏场栖九穗，
前歌被六英。
战地甘泉涌，
阵处景云生。
普天沾凯泽，
相携欣颂平。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_236','奉和过旧宅应制','许敬宗','隋末唐初','飞云临紫极，
出震表青光。
自尔家寰海，
今兹返帝乡。
情深感代国，
乐甚宴谯方。
白水浮佳气，
黄星聚太常。
岐凤鸣层阁，
酆雀贺雕梁。
桂山犹总翠，
蘅薄尚流芳。
攀鳞有遗皓，
沐德抃称觞。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_237','奉和初春登楼即目应诏','许敬宗','隋末唐初','旭日临重壁，
天眷极中京。
春晖发芳甸，
佳气满层城。
去鸟随看没，
来云逐望生。
歌里非烟飏，
琴上凯风清。
文波浮镂槛，
摛景焕雕楹。
璇玑体宽政，
隆栋象端衡。
创规虽有作，
凝拱遂无营。
沐恩空改鬓，
将何谢夏成。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_238','奉和春日望海','许敬宗','隋末唐初','韩夷愆奉赆，
凭险乱天常。
乃神弘庙略，
横海剪吞航。
电野清玄菟，
腾笳振白狼。
连云飞巨舰，
编石架浮梁。
周游临大壑，
降望极遐荒。
桃门通山抃，
蓬渚降霓裳。
惊涛含蜃阙，
骇浪掩晨光。
青丘绚春组，
丹谷耀华桑。
长驱七萃卒，
成功百战场。
俄且旋戎路，
饮至肃岩廊。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_239','奉和秋日即目应制','许敬宗','隋末唐初','玉露交珠网，
金风度绮钱。
昆明秋景淡，
岐岫落霞然。
辞燕归寒海，
来鸿出远天。
叶动罗帷飏，
花映绣裳鲜。
规空升闇魄，
笼野散轻烟。
鹊度林光起，
凫没水文圆。
无机络秋纬，
如管奏寒蝉。
乃眷情何极，
宸襟豫有旃。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_240','奉和宴中山应制','许敬宗','隋末唐初','飞云旋碧海，
解网宥青丘。
养贤停八骏，
观风驻五牛。
张乐临尧野，
扬麾历舜州。
中山献仙酤，
赵媛发清讴。
塞门朱雁入，
郊薮紫麟游。
一举氛霓静，
千龄德化流。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_241','游清都观寻沈道士得清字','许敬宗','隋末唐初','幽人蹈箕颍，
方士访蓬瀛。
岂若逢真气，
齐契体无名。
既诠众妙理，
聊畅远游情。
纵心驰贝阙，
怡神想玉京。
或命馀杭酒，
时听洛滨笙。
风衢通阆苑，
星使下层城。
蕙帐晨飙动，
芝房夕露清。
方叶栖迟趣，
于此听钟声。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_242','七夕赋咏成篇','许敬宗','隋末唐初','一年抱怨嗟长别，
七夕含态始言归。
飘飘罗袜光天步，
灼灼新妆鉴月辉。
情催巧笑开星靥，
不惜呈露解云衣。
所叹却随更漏尽，
掩泣还弄昨宵机。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_243','奉和入潼关','许敬宗','隋末唐初','曦驭循黄道，
星陈引翠旗。
济潼纡万乘，
临河耀六师。
前旌弥陆海，
后骑发通伊。
势踰回地轴，
威盛转天机。
是节岁穷纪，
关树荡凉飔。
仙露含灵掌，
瑞鼎照川湄。
冲襟赏临睨，
高咏入京畿。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_244','奉和圣制送来济应制','许敬宗','隋末唐初','万乘腾镳警岐路，
百壶供帐饯离宫。
御沟分水声难绝，
广宴当歌曲易终。
兴言共伤千里道，
俯迹聊示五情同。
良哉既深留帝念，
沃化方有赞天聪。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_245','奉和执契静三边应诏','许敬宗','隋末唐初','玄塞隔阴戎，
朱光分昧谷。
地游穷北际，
云崖尽西陆。
星次绝轩台，
风衢乖禹服。
寰区无所外，
天覆今咸育。
窜苗犹有孽，
戮负自贻辜。
疏网妖鲵漏，
盘薮怪禽逋。
髯飞尚假息，
乳视暂稽诛。
乾灵振玉弩，
神略运璇枢。
日羽廓游气，
天阵清华野。
升晅光西夜，
驰恩溢东泻。
挥袂静昆炎，
开关纳流赭。
锦轺凌右地，
华缨羁大夏。
清台映罗叶，
玄沚控瑶池。
驼鹿输珍贶，
树羽飨来仪。
辍肴观化宇，
栖籞萃条支。
熏风交阆阙，
就日泛濛漪。
充庭延饮至，
绚简敷春藻。
迎姜已创图，
命力方论道。
昔托游河乘，
再备商山皓。
欣逢德化流，
思效登封草。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_246','奉和秋暮言志应制','许敬宗','隋末唐初','秋深桂初发，
寒窗菊馀菲。
波拥群凫至，
秋飘朔雁归。
月荚生还落，
云枝似复非。
凝宸阅栖亩，
观文伫少微。
圣敬韬前哲，
先天谅不违。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_247','奉和喜雪应制','许敬宗','隋末唐初','嵰州表奇贶，
閟竹应遐巡。
何如御京洛，
流霰下天津。
忽若琼林曙，
俄同李径春。
姑峰映仙质，
郢路杂歌尘。
伏槛观花瑞，
称觞庆冬积。
飘河共泻银，
委树还重璧。
连山分掩翠，
绵霄远韬碧。
千里遍浮空，
五轫咸沦迹。
机前辉裂素，
池上伴凌波。
腾华承玉宇，
凝照混金娥。
是日松筠性，
欣奉柏梁歌。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_248','奉和登陕州城楼应制','许敬宗','隋末唐初','挹河澄绿宇，
御沟映朱宫。
辰旂翻丽景，
星盖曳雕虹。
学嚬齐柳嫩，
妍笑发春丛。
锦鳞文碧浪，
绣羽绚青空。
眷念三阶静，
遥想二南风。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_249','阳春怨','许景先','盛唐','红树晓莺蹄，
春风暖翠闺。
雕笼熏绣被，
珠履踏金堤。
芍药花初吐，
菖蒲叶正齐。
藁砧当此日，
行役向辽西。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_250','奉和圣制送张尚书巡边','许景先','盛唐','文武承邦式，
风云感国祯。
王师亲赋政，
庙略久论兵。
汉主知三杰，
周官统六卿。
四方分阃受，
千里坐谋成。
介胄辞前殿，
壶觞宿左营。
赏延颁赐重，
宸赠出车荣。
龙武三军气，
鱼铃五校名。
郊云驻旌羽，
边吹引金钲。
训旅方称德，
安人更克贞。
伫看铭石罢，
同听凯歌声。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_251','折柳篇','许景先','盛唐','春色东来度渭桥，
青门垂柳百千条。
长杨西连建章路，
汉家林苑纷无数。
萦花始遍合欢枝，
游丝半罥相思树。
春楼初日照南隅，
柔条垂绿扫金铺。
宝钗新梳倭堕髻，
锦带交垂连理襦。
自怜柳塞淹戎幕，
银烛长啼愁梦著。
芳树朝催玉管新，
春风夜染罗衣薄。
城头杨柳已如丝，
今年花落去年时。
折芳远寄相思曲，
为惜容华难再持。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_252','奉和御制春台望','许景先','盛唐','睿德在青阳，
高居视中县。
秦城连凤阙，
汉寝疏龙殿。
文物照光辉，
郊畿郁葱茜。
千门望成锦，
八水明如练。
复道晓光披，
宸游出禁移。
瑞气朝浮五云阁，
祥光夜吐万年枝。
兰叶负龟初荐祉，
桐花集凤更来仪。
秦汉生人凋力役，
阿房甘泉构云碧。
汾祠雍畤望通天，
玉堂宣室坐长年。
鼓钟西接咸阳观，
苑囿南通鄠杜田。
明主卑宫诫前失，
辅德钦贤政惟一。
昆虫不夭在春蒐，
稼穑常艰重农术。
邦家已荷圣谟新，
犹闻俭陋惜中人。
豫奉北辰齐七政，
长歌东武抃千春。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_253','若耶春意','许景先','盛唐','越水正逶迤，
艳阳三月时。
中有婵娟子，
含怨望佳期。
鲜肤润玉泽，
微眄动蛾眉。
解佩遗中浦，
折芳怀所思。
彩色岂不重，
瑰艳难久滋。
一歌江南曲，
再使妾心悲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_254','徵君宅','许景先','盛唐','徵君昔嘉遁，
抗迹遗俗尘。
了心悟有物，
乘化游无垠。
道丧历千载，
复存颍阳真。
上虞佳山水，
晚岁耽隐沦。
内史既解绶，
支公亦相亲。
儒道匪远理，
意胜聊自欣。
洄沿南溪夕，
流浪东山春。
石壁践丹景，
金潭冒绿蘋。
探鍊备海峤，
赏心寓情人。
奈何灵仙骨，
锹翮瑶池津。
寥寥虚白宇，
夙创招提因。
家风缅多尚，
玄德谢无邻。
谬陪金门彦，
矫迹侍紫宸。
皇恩竟已矣，
遗烈庶不泯。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_255','下第东归留别郑侍郎','许棠','中唐','无才副至公，
岂是命难通。
分合吟诗老，
家宜逐浪空。
别心悬阙下，
归念极吴东。
唯畏重回日，
初情恐不同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_256','下黄耳盘','许棠','中唐','独下黄盘路，
多虞部落连。
云晴仍著地，
树古自参天。
乱鸟飞人上，
惊麋起马前。
行行无郡邑，
唯见虎狼烟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_257','中秋夜对月','许棠','中唐','月月势皆圆，
中秋朗最偏。
万方期一夕，
到晓是经年。
影蔽星芒尽，
光分物状全。
惟应苦吟者，
目断向遥天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_258','五原书事','许棠','中唐','西出黄云外，
东怀白浪遥。
星河愁立夜，
雷电独行朝。
碛迥人防寇，
天空雁避雕。
如何非战卒，
弓剑不离腰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_259','忆宛陵旧居','许棠','中唐','旧忆陵阳北，
林园近板桥。
江晴帆影满，
野迥鹤声遥。
鸟径通山市，
汀扉上海潮。
秦城归去梦，
夜夜到渔樵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_260','日暮江上','许棠','中唐','孤帆收广岸，
落照在遥峰。
南北渡人少，
高低归鸟重。
潮回沙出树，
雨过浦沉钟。
渔父虽相问，
那能话所从。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_261','长安书情','许棠','中唐','疏散过闲人，
同人不在秦。
近来惊白发，
方解惜青春。
僻寺居将遍，
权门到绝因。
行藏如此辈，
何以谓谋身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_262','长安寓居','许棠','中唐','贫寄帝城居，
交朋日自疏。
愁迎离碛雁，
梦逐出关书。
经雨蝉声尽，
兼风杵韵馀。
谁知江徼塞，
所忆在樵渔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_263','东归次采石江','许棠','中唐','东下经牛渚，
依然是故关。
客程临岸尽，
乡思入鸥闲。
雨涨巴来浪，
云增楚际山。
渔翁知未达，
相顾不开颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_264','东归留辞沈侍郎','许棠','中唐','一第久乖期，
深心已自疑。
沧江归恨远，
紫阁别愁迟。
稽古成何事，
龙钟负已知。
依门非近日，
不虑旧恩移。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_265','写怀','许棠','中唐','汨没与辛勤，
全钟在此身。
半生为下客，
终老托何人。
两鬓关中改，
千岩海上春。
青云知有路，
自是致无因。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_266','写怀','许棠','中唐','此生居此世，
堪笑复堪悲。
在处有岐路，
何人无别离。
长当多难日，
愁过少年时。
穷达都判了，
休闲镊白髭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_267','冬夜与友人会宿','许棠','中唐','君初离雁塞，
我久滞雕阴。
隔闰俱劳梦，
通宵各话心。
禁风吹漏出，
原树映星沉。
白昼常多事，
无妨到晓吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_268','冬夜怀真里友人会宿','许棠','中唐','静语与高吟，
搜神又爽心。
各来依帝里，
相对似山阴。
漏永星河没，
堂寒月彩深。
从容不易到，
莫惜曙钟侵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_269','冬杪归陵阳别业五首','许棠','中唐','无媒归别业，
所向自乖心。
闾里故人少，
田园荒草深。
浪翻全失岸，
竹迸别成林。
鸥鸟犹相识，
时来听苦吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_270','冬杪归陵阳别业五首','许棠','中唐','眠云终未遂，
策马暂休期。
上国劳魂梦，
中心甚别离。
冰封岩溜断，
雪压砌松欹。
骨肉嗟名晚，
看归却泪垂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_271','冬杪归陵阳别业五首','许棠','中唐','学剑虽无术，
吟诗似有魔。
已贫甘事晚，
临老爱闲多。
鸡犬唯随鹿，
儿童只衣蓑。
时因寻野叟，
狂醉复狂歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_272','冬杪归陵阳别业五首','许棠','中唐','乡国乱离后，
交亲半旅游。
远闻诚可念，
归见岂无愁。
败苇迷荒径，
寒蓑没坏舟。
衡门终不掩，
倚杖看波流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_273','冬杪归陵阳别业五首','许棠','中唐','游秦复滞燕，
不觉近衰年。
旅貌同柴毁，
行衣对骨穿。
篱寒多啄雀，
木落断浮烟。
楚夜闻鸣雁，
犹疑在塞天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_274','出塞门','许棠','中唐','步步经戎虏，
防兵不离身。
山多曾战处，
路断野行人。
暴雨声同瀑，
奔沙势异尘。
片时怀万虑，
白发数茎新。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_275','失题','许棠','中唐','独夜长城下，
孤吟近北辰。
半天初去雁，
穷碛远来人。
月黯氛埃积，
风膻帐幕邻。
惟闻防虏寇，
不语暗伤神。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_276','白菊','许棠','中唐','所尚雪霜姿，
非关落帽期。
香飘风外别，
影到月中疑。
发在林彫后，
繁当露冷时。
人间稀有此，
自古乃无诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_277','边城晚望','许棠','中唐','广漠杳无穷，
孤城四面空。
马行高碛上，
日堕迥沙中。
逼晓人移帐，
当川树列风。
迢迢河外路，
知直去崆峒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_278','成纪书事二首','许棠','中唐','东吴远别客西秦，
怀旧伤时暗洒巾。
满野多成无主冢，
防边半是异乡人。
山河再阔千馀里，
城市曾经一百春。
闲与将军议戎事，
伊兰犹未绝胡尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_279','成纪书事二首','许棠','中唐','蹉跎远入犬羊中，
荏苒将成白首翁。
三楚田园归未得，
五原岐路去无穷。
天垂大野雕盘草，
月落孤城角啸风。
难问开元向前事，
依稀犹认隗嚣宫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_280','早发洛中','许棠','中唐','半夜发清洛，
不知过石桥。
云增中岳大，
树隐上阳遥。
堑黑初沉月，
河明欲认潮。
孤村人尚梦，
无处暂停桡。',NULL,'[{"Book": "《瀛奎律髓》", "Section": null, "Content": "此一早发诗，“不知”二字便佳、盖曙中船过桥下也。“中岳”、“上阳”，以“云增”而“大”，以“树隐”而“遥”，极有味。第六句亦佳。末句则予尝夜航浙河，熟谙此况也。与许浑全不同。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓》"}, {"Book": "《唐诗归》", "Section": null, "Content": "“大”字痴得好。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}, {"Book": "《唐诗成法》", "Section": null, "Content": "“不知”承“半夜”。三前望，四回首，皆写半夜景，又切洛阳沉月、河明将晓之景。七八紧接五六，言此时村人尚梦，以形己之早发也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗成法》"}, {"Book": "《瀛奎律髓汇评》", "Section": null, "Content": "冯班：未见胜许。又云：“较之大历以前，家数便小。查慎行：第三、第六俱拙。纪昀：第三句意工而语拙，“大”字尤拙。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓汇评》"}, {"Book": "《重订中晚唐诗主客图》", "Section": null, "Content": "“不知”字妙，恍惚中得早发神理（“不知”句下）。“大”字好（“云增”句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《重订中晚唐诗主客图》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_281','曲江三月三日','许棠','中唐','满国赏芳辰，
飞蹄复走轮。
好花皆折尽，
明日恐无春。
鸟避连云幄，
鱼惊远浪尘。
如何当此节，
独自作愁人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_282','汝州郡楼望嵩山','许棠','中唐','不共众山同，
岧峣出迥空。
几层高鸟外，
万仞一楼中。
水落难归地，
云离便逐风。
唯应霄汉客，
绝顶路方通。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_283','江上行','许棠','中唐','片席随高鸟，
连天积浪间。
苇宽云不匝，
风广雨无闲。
戍影临孤浦，
潮痕在半山。
东原归未得，
荏苒滞江关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_284','江上遇友人','许棠','中唐','阙下分离日，
杏园花半开。
江边相值夜，
榆塞雁初来。
坐久河沉斗，
吟长月浸杯。
鲈鱼非不恋，
共有客程催。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_285','讲德陈情上淮南李仆射八首','许棠','中唐','天降贤人佐圣时，
自然声教满华夷。
英明不独中朝仰，
清重兼闻外国知。
凉夜酒醒多对月，
晓庭公退半吟诗。
梁城东下虽经战，
风俗犹传守旧规。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_286','讲德陈情上淮南李仆射八首','许棠','中唐','多朝轩冕冠乾坤，
四海皆推圣最尊。
楚玉已曾分卞玉，
膺门依旧是龙门。
筵开乐振高云动，
城掩鼙收落日昏。
尝念苍生如赤子，
九州无处不沾恩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_287','讲德陈情上淮南李仆射八首','许棠','中唐','未领春闱望早清，
况联戎阃控强兵。
风威遍布江山静，
教化高同日月明。
九郡竟歌兼煮海，
四方皆得共和羹。
东南自此全无事，
只为期年政已成。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_288','讲德陈情上淮南李仆射八首','许棠','中唐','帝念淮堧疫疹频，
牢笼山海委名臣。
古来比德由无侣，
当代同途岂有人。
夜宴独吟梁苑月，
朝游重见广陵春。
多年疲瘵全苏息，
须到讴谣日满秦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_289','讲德陈情上淮南李仆射八首','许棠','中唐','三纪吟诗望一名，
丹霄待得白头成。
已期到老还沾禄，
无复偷闲却养生。
当宴每垂听乐泪，
望云长起忆山情。
朱门旧是登龙客，
初脱鱼鳞胆尚惊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_290','讲德陈情上淮南李仆射八首','许棠','中唐','东来淮海拜旌旟，
不把公卿一字书。
曾侍晚斋吟对雪，
又容华馆食兼鱼。
孤微自省恩非次，
际会谁知分有馀。
唯耻旧桥题处在，
荣归无计似相如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_291','讲德陈情上淮南李仆射八首','许棠','中唐','平生南北逐蓬飘，
待得名成鬓已彫。
寒浦一从抛钓艇，
旧林无处认风飙。
程途虽喜关河尽，
时节犹惊骨肉遥。
愁策羸蹄更归去，
乱山流水满翻潮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_292','讲德陈情上淮南李仆射八首','许棠','中唐','丹霄空把桂枝归，
白首依前着布衣。
当路公卿谁见待，
故乡亲爱自疑非。
东风乍喜还沧海，
栖旅终愁出翠微。
应念无媒居选限，
二年须更守渔矶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_293','贞女祠','许棠','中唐','何穴藏贞骨，
荒祠见旧颜。
精灵应自在，
云雨不相关。
落石泉多咽，
无风树尽闲。
唯疑千古后，
为瑞向人间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_294','过中条山','许棠','中唐','徒为经异岳，
不得访灵踪。
日尽行难尽，
千重复万重。
云垂多作雨，
雷动半和钟。
孤竹人藏处，
无因认本峰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_295','过分水岭','许棠','中唐','陇山高共鸟行齐，
瞰险盘空甚蹑梯。
云势崩腾时向背，
水声呜咽若东西。
风兼雨气吹人面，
石带冰棱碍马蹄。
此去秦川无别路，
隔崖穷谷却难迷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_296','过洞庭湖','许棠','中唐','惊波常不定，
半日鬓堪斑。
四顾疑无地，
中流忽有山。
鸟高恒畏坠，
帆远却如闲。
渔父闲相引，
时歌浩渺间。',NULL,'[{"Book": "《北梦琐言》", "Section": null, "Content": "洞庭湖，凡阔数百里，而君山宛在水中。秋水归壑，此山复居于陆，唯一条湘川而已。海为桑田，于斯验也。前辈许棠《过洞庭诗》，最为首出，尔后无继斯作。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《北梦琐言》"}, {"Book": "《唐诗纪事》", "Section": null, "Content": "棠《洞庭》诗有“四顾疑无地，中流忽有山”之句，人以题扇。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗纪事》"}, {"Book": "《唐音癸签》", "Section": null, "Content": "许文化致语楚楚，《洞庭》一律，时人多取以题扇。“四顾疑无地，中流忽有山”，视老杜“乾坤日夜浮”愈切愈小。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐音癸签》"}, {"Book": "《唐诗选脉会通评林》", "Section": null, "Content": "周珽曰：极言湖之汪洋灏瀚险荡。三四妙在“疑无”、“忽有”四字；五六妙在“恒”、“却”二字，俱以虚字摹出洞庭形势来。半日不觉鬓斑，惊心所摄也。……浩然之后，此诗见称于世。许棠此诗形容湖为无地，窦叔向《檐石湖》诗并言无其无，语大是幻绝，因知文翰场中每多勍敌。若读第三联，窦不若许矣。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选脉会通评林》"}, {"Book": "《五朝诗善鸣集》", "Section": null, "Content": "第四句写君山神到。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《五朝诗善鸣集》"}, {"Book": "《初白庵诗评》", "Section": null, "Content": "句句是过湖景象，余尝身历其境，故知此诗之工。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《初白庵诗评》"}, {"Book": "《瀛奎律髓汇评》", "Section": null, "Content": "纪昀：刻意张皇，而根柢浅薄，转形竭蹶，五句尤为拙俚，观此乃知孟、杜二公不愧凌跨一代也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓汇评》"}, {"Book": "《网师园唐诗笺》", "Section": null, "Content": "无声画（“四顾”四句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《网师园唐诗笺》"}, {"Book": "《重订中晚唐诗主客图》", "Section": null, "Content": "力求新奇，乃力求写生，故妙。文化以此诗得名，然在集中尚非极诣。二句何必是洞庭，然确是洞庭，非身到者不知也（“四顾”联下）想头妙绝（“鸟飞”联下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《重订中晚唐诗主客图》"}, {"Book": "《养一斋诗话》", "Section": null, "Content": "许棠有《洞庭》诗，号为“许洞庭”。然“四顾疑无地，中流忽有山”语意平弱，“鸟飞应畏堕”尤涉痕迹，惟“帆远却如闲”五字佳，然亦不必是洞庭诗。少陵、襄阳后，何为动此笔耶！", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《养一斋诗话》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_297','过湍沟谷','许棠','中唐','西去穷胡处，
嵓崖境不常。
石形相对耸，
天势一条长。
栈底鸣流水，
林端敛夕阳。
虽随兵马至，
未免畏豺狼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_298','过穆陵关','许棠','中唐','荒关无守吏，
亦耻白衣过。
地广人耕绝，
天寒雁下多。
东西方自感，
雨雪更相和。
日暮聊摅思，
摇鞭一放歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_299','投徐端公','许棠','中唐','无谋寻旧友，
强喜亦如愁。
丹桂阻丹恳，
白衣成白头。
穷吴迷钓业，
大漠事贫游。
霄汉期提引，
龙钟未拟休。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_300','汴上暮秋','许棠','中唐','独立长堤上，
西风满客衣。
日临秋草广，
山接远天微。
岸叶随波尽，
沙云与鸟飞。
秦人宁有素，
去意自知归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_301','言怀','许棠','中唐','万事不关心，
终朝但苦吟。
久贫惭负债，
渐老爱山深。
日月销天外，
帆樯弃海阴。
荣枯应已定，
无复系浮沉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_302','陇上书事','许棠','中唐','城叠连云壑，
人家似隐居。
树飞鹦鹉众，
川下鹡鸰疏。
滴梦关山雨，
资餐陇水鱼。
谁知江徼客，
此景倍相于。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_303','陇州旅中书事寄李中丞','许棠','中唐','三伏客吟过，
长安未拟还。
蛩声秋不动，
燕别思仍闲。
乱叶随寒雨，
孤蟾起暮关。
经时高岭外，
来往旆旌间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_304','陈情献江西李常侍五首','许棠','中唐','二十二三年，
游秦复滞燕。
徒陪群彦后，
自苦此生前。
径折啼猿树，
岩荒喷月泉。
东堂曾受荐，
垂白志犹坚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_305','陈情献江西李常侍五首','许棠','中唐','淅淅复栖栖，
人间只自迷。
终年愁远道，
到老去何蹊。
始见红叶落，
又闻黄鸟啼。
不因趋大旆，
谁肯暂提携。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_306','陈情献江西李常侍五首','许棠','中唐','童蒙即苦辛，
未识杏园春。
谩倚无为日，
还成不偶人。
乡程长恨远，
旅梦亦愁贫。
天地虽云广，
殊难寄此身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_307','陈情献江西李常侍五首','许棠','中唐','春闱久已滞，
秋赋又逢停。
选士疑长阻，
伤时自不宁。
秦城还逐梦，
楚徼影随形。
此去吟虽苦，
何人更肯听。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_308','陈情献江西李常侍五首','许棠','中唐','孤立时全塞，
求名势转难。
身多离下国，
分合阻长安。
越鸟啼春早，
蛮花送雨寒。
丘门沾顾重，
未别欲阑干。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_309','和薛侍御题兴善寺松','许棠','中唐','何年斸到城，
满国响高名。
半寺阴常匝，
邻坊景亦清。
代多无朽势，
风定有馀声。
自得天然状，
非同涧底生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_310','奉天寒食书事','许棠','中唐','处处无烟火，
人家似暂空。
晓林花落雨，
寒谷鸟啼风。
故里芳洲外，
残春甸服中。
谁知独西去，
步步泣途穷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_311','泗上早发','许棠','中唐','独起无人见，
长河夜泛时。
平芜疑自动，
落月似相随。
楚外离空早，
关西去已迟。
渔歌闻不绝，
却轸洞庭思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_312','经八合坂','许棠','中唐','蹑险入高空，
初疑势不穷。
又缘千嶂尽，
还共七盘同。
下辨东流水，
平随北去鸿。
天然无此道，
应免患穷通。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_313','经故杨太尉旧居','许棠','中唐','在汉信垂功，
于唐道更隆。
一川留古迹，
多代仰高风。
树折巢堕鸟，
阶荒草覆虫。
行人过岂少，
独驻夕阳中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_314','青山晚望','许棠','中唐','昔人怀感处，
此地倍魂消。
四海经摇落，
三吴正寂寥。
风移残烧远，
帆带夕阳遥。
欲继前贤迹，
谁能似隐招。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_315','亲仁里双鹭','许棠','中唐','双去双来日已频，
只应知我是江人。
对欹雪顶思寻水，
更振霜翎恐染尘。
三楚几时初失侣，
五陵何树又栖身。
天然不与凡禽类，
傍砌听吟性自驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_316','客行','许棠','中唐','旅食唯草草，
此生谁我同。
故园魂梦外，
长路别离中。
人事萍随水，
年光鸟过空。
欲吟先落泪，
多是怨途穷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_317','宣城送进士郑徽赴举','许棠','中唐','长安去是归，
上马肯沾衣。
水国车通少，
秦人楚荐稀。
鸿方离北鄙，
叶下已西畿。
好整丹霄步，
知音在紫微。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_318','将归江南留别友人','许棠','中唐','连春不得意，
所业已疑非。
旧国乱离后，
新年惆怅归。
雪开还楚地，
花惹别秦衣。
江徼多留滞，
高秋会恐违。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_319','将过单于','许棠','中唐','荒碛连天堡戍稀，
日忧蕃寇却忘机。
江山不到处皆到，
陇雁已归时未归。
行李亦须携战器，
趋迎当便著戎衣。
并州去路殊迢遰，
风雨何当达近畿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_320','春日乌延道中','许棠','中唐','边穷厄未穷，
复此逐归鸿。
去路多相似，
行人半不同。
山川藏北狄，
草木背东风。
虚负男儿志，
无因立战功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_321','春日言怀','许棠','中唐','东风万物新，
独未到幽人。
赋命自多蹇，
阳和非不均。
五陵三月暮，
百越一家贫。
早误闲眠处，
无愁异此身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_322','春夜同厉文学先辈会宿','许棠','中唐','江汉久分路，
京关重聚吟。
更为他夜约，
方尽昔年心。
月隔明河远，
花藏宿鸟深。
无眠将及曙，
多是说山阴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_323','春暮途次华山下','许棠','中唐','他皆宴牡丹，
独又出长安。
远道行非易，
无图住自难。
离城风已暖，
近岳雨翻寒。
此去知谁顾，
闲吟祗自宽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_324','洞庭湖','张泌','五代至宋','空江浩荡景萧然，
尽日菰蒲泊钓船。
青草浪高三月渡，
绿杨花扑一溪烟。
情多莫举伤春目，
愁极兼无买酒钱。
犹有渔人数家住，
不成村落夕阳边。',NULL,'[{"Book": "《五朝诗善鸣集》", "Section": null, "Content": "洞庭大境也，阻风就其一小处而言，风景宛然。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《五朝诗善鸣集》"}, {"Book": "《唐诗绎》", "Section": null, "Content": "三四写阻风之景，声势俱出。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗绎》"}, {"Book": "《唐诗鼓吹笺注》", "Section": null, "Content": "此言洞庭浩荡，景物凄凉，终日钓船于菰蒲之畔。第四虚对实，即以风中之絮自比，起下“情多”、“愁极”句，回抱“萧然”。“住”字又正与絮飞无定相反也，摆脱变化，不可捉摸。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗鼓吹笺注》"}, {"Book": "《山满楼笺注唐诗七言律》", "Section": null, "Content": "一江中无船，二岸边有船，其我之船不得开，不必言而自明矣。此避实击虚之法也，妙，妙。“青草”、“绿杨”，借对甚奇，巧而不纤。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《山满楼笺注唐诗七言律》"}, {"Book": "《唐诗别裁》", "Section": null, "Content": "夜泊洞庭湖边港汊，故有“绿杨花扑一溪烟”句，否则风景全不合矣，玩末句自明。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗别裁》"}, {"Book": "《网师园唐诗笺》", "Section": null, "Content": "写景自然（“青草浪高”二句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《网师园唐诗笺》"}, {"Book": "《唐贤小三昧集续集》", "Section": null, "Content": "绝顶好句（“绿杨花扑”句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐贤小三昧集续集》"}, {"Book": "《养一斋诗话》", "Section": null, "Content": "《洞庭阻风》云：“青草浪高三月渡，绿杨花扑一溪烟。”岂似咏洞庭者？气局之琐可知。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《养一斋诗话》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_325','秋日归旧山','许棠','中唐','山云蝉满树，
欲住更何安。
上国回将晚，
孤峰别自难。
碛遥鸿未到，
江近夜先寒。
泉石虽堪恋，
行人不愿看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_326','秋日陪陆校书游玉泉','许棠','中唐','共爱泉源异，
频来不觉劳。
散光垂草细，
繁响出风高。
沫滞潭花片，
沙遗浴鸟毛。
尘间喧与闷，
须向此中逃。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_327','秋江霁望','许棠','中唐','高秋偏入望，
霁景倍关情。
落木满江水，
离人怀渭城。
山高孤戍断，
野极暮天平。
渔父时相问，
羞真道姓名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_328','送从弟归泉州','许棠','中唐','问省归南服，
悬帆任北风。
何山犹见雪，
半路已无鸿。
瘴杂春云重，
星垂夜海空。
往来如不住，
亦是一年中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_329','送从弟筹任告成尉','许棠','中唐','海上从戎罢，
嵩阳佐县初。
故人皆羡去，
吾祖旧曾居。
地古多生药，
溪灵不聚鱼。
唯应寻隐者，
闲寺讲仙书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_330','送元遂上人归吴中','许棠','中唐','落发在王畿，
承恩著紫衣。
印心谁受请，
讲疏自携归。
泛浦龙惊锡，
禅云虎绕扉。
吴中知久别，
庵树想成围。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_331','送友人北游','许棠','中唐','北出阴关去，
何人肯待君。
无青山拥晋，
半浊水通汾。
雁塞虽多雁，
云州却少云。
兹游殊不恶，
莫恨暂离群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_332','送友人游蜀','许棠','中唐','巴兴千万寻，
此去若为心。
蟋蟀既将定，
猕猴应正吟。
剑门秋断雁，
褒谷夜多砧。
自古西南路，
艰难直至今。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_333','送王侍御赴宣城','许棠','中唐','戴豸却驱鸡，
东南上句溪。
路过金谷口，
帆转石城西。
水树连天暗，
山禽绕郡啼。
江人谙旧化，
那复俟招携。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_334','送王侍御赴宣城','许棠','中唐','朝回离九陌，
岛外赏残春。
经宿留闲客，
看云作主人。
时清难议隐，
位重亦甘贫。
岩洞真仙境，
应休别卧邻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_335','送厉校书从事凤翔','许棠','中唐','赴辟依丞相，
超荣事岂同。
城池当陇右，
山水是关中。
日有来巴使，
秋高出塞鸿。
旬休随大旆，
应到九成宫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_336','送龙州樊使君','许棠','中唐','曾见邛人说，
龙州地未深。
碧溪飞白鸟，
红旆映青林。
土产唯宜药，
王租只贡金。
政成开宴日，
谁伴使君吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_337','送刘校书游东鲁','许棠','中唐','内阁劳雠校，
东邦忽纵游。
才编精二雅，
分合遇诸侯。
暗海龟蒙雨，
连空赵魏秋。
如经麟见处，
驻马瞰荒丘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_338','送防州邬员外','许棠','中唐','千溪与万嶂，
缭绕复峥嵘。
太守劳车马，
何从驻旆旌。
椒香近满郭，
漆货远通京。
唯涤双尘耳，
东南听政声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_339','送张员外西川从事','许棠','中唐','为郎不入朝，
自是赴嘉招。
豸角初离首，
金章已在腰。
剑横阴绿野，
栈响近丹霄。
迎驿应相续，
悬愁去路遥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_340','送李员外知扬子州留务','许棠','中唐','帝命分留务，
东南向楚天。
几程回送骑，
中路见迎船。
冶例开山铸，
民多酌海煎。
青云名素重，
此去岂经年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_341','送李频之南陵主簿','许棠','中唐','赴县是还乡，
途程岂觉长。
听莺离灞岸，
荡桨入陵阳。
野蕨生公署，
闲云拂印床。
晴天调膳外，
垂钓有池塘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_342','送杜仓曹往沧洲觐叔常侍','许棠','中唐','浮阳横巨浸，
南巷拥旌旃。
别带秦城雨，
行闻魏国蝉。
碛鸿来每后，
朝日见常先。
东鄙云霞广，
高林间水天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_343','送金吾侍御奉使日东','许棠','中唐','还乡兼作使，
到日倍荣亲。
向化虽多国，
如公有几人。
孤山无返照，
积水合苍旻。
膝下知难住，
金章已系身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_344','送前汝州李侍御罢归宣城','许棠','中唐','吟诗早得名，
戴豸又加荣。
下国闲归去，
他人少此情。
云移寒峤出，
烧夹夜江明。
重引池塘思，
还登谢朓城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_345','送省玄上人归江东','许棠','中唐','释律周儒礼，
严持用戒身。
安禅思剡石，
留偈别都人。
雨合吴江黑，
潮移海路新。
瓶盂自此去，
应不更还秦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_346','送裴拾遗宰下邽','许棠','中唐','受谪因延谏，
兹行不出关。
直庐辞玉陛，
上马向仙山。
地古桑麻广，
城偏仆御闲。
县斋高枕卧，
犹梦犯天颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_347','重归江南','许棠','中唐','无成归故里，
不似在他乡。
岁月逐流水，
山川空夕阳。
回潮迷古渡，
迸竹过邻墙。
耆旧休存省，
胡为止泪行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_348','哭宣城元徵君','许棠','中唐','高眠终不起，
远趣固难知。
琴剑今无主，
园林旧许谁。
苔封僧坐石，
苇涨鹤翘池。
后代传青史，
方钦道德垂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_349','夏州道中','许棠','中唐','茫茫沙漠广，
渐远赫连城。
堡迥烽相见，
河移浪旋生。
无蝉嘶折柳，
有寇似防兵。
不耐饥寒迫，
终谁至此行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_350','旅中送人归九华','许棠','中唐','分与仙山背，
多年负翠微。
无因随鹿去，
只是送人归。
顶木晴摩日，
根岚晓润衣。
会于猿鸟外，
相对掩高扉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_351','旅次滑台投献陆侍御','许棠','中唐','已是鸿来日，
堪惊却背秦。
天遥三楚树，
路远两河人。
旅梦难归隐，
吟魂不在身。
霜台欹冠豸，
赖许往来频。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_352','旅怀','许棠','中唐','终年唯旅舍，
只似已无家。
白发除还出，
丹霄去转赊。
夏游穷塞路，
春醉负秦花。
应是穹苍意，
空教老若耶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_353','留别从弟郴','许棠','中唐','同承太岳胤，
俱值太平时。
丹陛怀趋计，
沧洲负去期。
久贫成蹭蹬，
多病惜支离。
宗分兼交分，
吾知汝亦知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_354','秦中遇友人','许棠','中唐','半生南走复西驰，
愁过杨朱罢泣岐。
远梦亦羞归海徼，
贫游多是滞边陲。
胡云不聚风无定，
陇路难行栈更危。
旦暮唯闻语征战，
看看已欲废吟诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_355','陪友人夏夜对月','许棠','中唐','后伏中宵月，
高秋满魄齐。
轮移仙掌外，
影下玉绳西。
蝉雀飞多误，
星萤出自迷。
烦蒸惊顿绝，
吟玩畏闻鸡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_356','陪郢州张员外宴白雪楼','许棠','中唐','高情日日闲，
多宴雪楼间。
洒槛江干雨，
当筵天际山。
带帆分浪色，
驻乐话朝班。
岂料羁浮者，
樽前得解颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_357','宿华山','许棠','中唐','异境良难测，
非仙岂合游。
星辰方满岳，
风雨忽移舟。
喷月泉垂壁，
栖松鹤在楼。
因知休养处，
不必在嵩丘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_358','宿同州厉评事旧业寄华下','许棠','中唐','从戎依远地，
无日见家山。
地近风沙处，
城当甸服间。
阻河通渭水，
曲苑带秦关。
待月登楼夜，
何人相伴闲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_359','宿灵山兰若','许棠','中唐','江心天半寺，
一夕万缘空。
地出浮云上，
星摇积浪中。
滴沤垂阁雨，
吹桧送帆风。
旦夕闻清磬，
唯应是钓翁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_360','宿青山馆','许棠','中唐','下马青山下，
无言有所思。
云藏李白墓，
苔暗谢公诗。
烈烧飞荒野，
栖凫宿广陂。
东来与西去，
皆是不闲时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_361','寄华阴刘拾遗','许棠','中唐','坚心持谏诤，
自古亦艰难。
寄邑虽行化，
眠云似去官。
河分中野断，
岳入半天寒。
瀑布冰成日，
谁陪吟复看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_362','寄江上弟妹','许棠','中唐','无成归未得，
不是不谋归。
垂老登云路，
犹胜守钓矶。
大荒身去数，
穷海信来稀。
孤立皆难进，
非关命独违。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_363','寄庐山贾处士','许棠','中唐','时泰亦高眠，
人皆谓不然。
穷经休望辟，
饵朮止期仙。
彭蠡波涵月，
炉峰雪照天。
常闻风雨夜，
到晓在渔船。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_364','寄建州姚员外','许棠','中唐','诬谮遭遐谪，
明君即自知。
乡遥辞剑外，
身独向天涯。
岭堠蛮云积，
闽空瘴雨垂。
南来终不遂，
日探北归期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_365','寄赵能卿','许棠','中唐','我命同君命，
君诗似我诗。
俱无中道计，
各失半生期。
素业沧江远，
清时白发垂。
蹉跎一如此，
何处卜栖迟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_366','寄敬亭山清越上人','许棠','中唐','南朝山半寺，
谢朓故乡邻。
岭上非无主，
秋诗复有人。
高禅星月近，
野火虎狼驯。
旧许陪闲社，
终应待此身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_367','寄睦州陆郎中','许棠','中唐','下国多高趣，
终年半是吟。
海涛通越分，
部伍杂闽音。
晓郭云藏市，
春山鸟护林。
东浮虽未遂，
日日至中心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_368','寄黔南李校书','许棠','中唐','从戎巫峡外，
吟兴更应多。
郡响蛮江涨，
山昏蜀雨过。
公筵饶越味，
俗土尚巴歌。
中夜怀吴梦，
知经滟滪波。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_369','寄盩厔薛能少府','许棠','中唐','满县唯云水，
何曾似近畿。
晓庭猿集惯，
寒署吏衙稀。
冰色封深涧，
樵声出紫微。
时闻迎隐者，
依旧著山衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_370','野步','许棠','中唐','闲赏步易远，
野吟声自高。
路无人到迹，
林有鹤遗毛。
物外趣都别，
尘中心枉劳。
沿溪收堕果，
坐石唤饥猱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_371','银州北书事','许棠','中唐','南辞采石远，
北背乞银深。
碛路虽多险，
江人不废吟。
雕依孤堠立，
鸥向迥沙沈。
因共边人熟，
行行起战心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_372','隗嚣宫晚望','许棠','中唐','西顾伊兰近，
方惊滞极边。
水随空谷转，
山向夕阳偏。
碛鸟多依地，
胡云不满天。
秋风动衰草，
只觉犬羊膻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_373','渭上送人南归','许棠','中唐','远役与归愁，
同来渭水头。
南浮应到海，
北去阻无州。
楚雨天连地，
胡风夏甚秋。
江人如见问，
为话复贫游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_374','登山','许棠','中唐','信步上鸟道，
不知身忽高。
近空无世界，
当楚见波涛。
顶峭松多瘦，
崖悬石尽牢。
猕猴呼独散，
隔水向人号。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_375','登凌歊台','许棠','中唐','平芜望已极，
况复倚凌歊。
江截吴山断，
天临楚泽遥。
云帆高出树，
水市迥分桥。
立久斜阳尽，
无言似寂寥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_376','登渭南县楼','许棠','中唐','近甸名偏著，
登城景又宽。
半空分太华，
极目是长安。
雪助河流涨，
人耕烧色残。
闲来时甚少，
欲下重凭栏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_377','雁门关野望','许棠','中唐','高关闲独望，
望久转愁人。
紫塞唯多雪，
胡山不尽春。
河遥分断野，
树乱起飞尘。
时见东来骑，
心知近别秦。',NULL,'[{"Book": "《重订中晚唐诗主客图》", "Section": null, "Content": "实刻是贾。文化久游边塞，故诗中多得风沙寒阔之概。其于老杜诗无意学之，亦每有相近处，后略仿此。“不尽”二字著力（“胡山”句下）。写边景逼真（“河遥”一联下）。有馀味，耐思（末二句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《重订中晚唐诗主客图》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_378','塞下二首','许棠','中唐','胡虏偏狂悍，
边兵不敢闲。
防秋朝伏弩，
纵火夜搜山。
雁逆风鼙振，
沙飞猎骑还。
安西虽有路，
难更出阳关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_379','塞下二首','许棠','中唐','征役已不定，
又缘无定河。
塞深烽砦密，
山乱犬羊多。
汉卒闻笳泣，
胡儿击剑歌。
番情终未测，
今昔谩言和。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_380','塞外书事','许棠','中唐','征路出穷边，
孤吟傍戍烟。
河光深荡塞，
碛色迥连天。
残日沉雕外，
惊蓬到马前。
空怀钓鱼所，
未定卜归年。',NULL,'[{"Book": "《瀛奎律髓汇评》", "Section": null, "Content": "纪昀：五六雄阔，不类晚唐。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓汇评》"}, {"Book": "《重订中晚唐诗主客图》", "Section": null, "Content": "“深荡”二字匠妙（“河光”句下）。“迥连”二字匠妙（“碛色”句下）。此乃同右丞诗意，其摹写高迥逼真处，亦几不多让矣。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《重订中晚唐诗主客图》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_381','新年呈友','许棠','中唐','一月月相似，
一年年不同。
清晨窥古镜，
旅貌近衰翁。
处世闲难得，
关身事半空。
浮生能几许，
莫惜醉春风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_382','献独孤尚书','许棠','中唐','虚抛南楚滞西秦，
白首依前衣白身。
退鹢已经三十载，
登龙曾见一千人。
魂离为役诗篇苦，
泪竭缘嗟骨相贫。
今日鞠躬高旆下，
欲倾肝胆杳无因。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_383','遣怀','许棠','中唐','此生何处遂，
屑屑复悠悠。
旧国归无计，
他乡梦亦愁。
飞尘长满眼，
衰发暗添头。
章句非经济，
终难动五侯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_384','题开明里友人居','许棠','中唐','城中尘外住，
入望是田家。
井出深山水，
阑藏异国花。
风巢和鸟动，
雪竹向人斜。
来往唯君熟，
乡园共海涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_385','题张乔升平里居','许棠','中唐','下马似无人，
开门只一身。
心同孤鹤静，
行过老僧真。
乱水藏幽径，
高原隔远津。
匡庐曾共隐，
相见自相亲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_386','题李昌符丰乐幽居','许棠','中唐','诗家依阙下，
野景似山中。
兰菊俱含露，
杉梧为奏风。
破门韦曲对，
浅岸御沟通。
莫叹连年屈，
君须遇至公。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_387','题汧湖二首','许棠','中唐','偶得湖中趣，
都忘陇坻愁。
边声风下雁，
楚思浪移舟。
静极亭连寺，
凉多岛近楼。
吟游终不厌，
还似曲江头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_388','题汧湖二首','许棠','中唐','陇首时无事，
湖边日纵吟。
游鱼来复去，
浴鸟出还沈。
蜃气藏孤屿，
波光到远林。
无人见垂钓，
暗起洞庭心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_389','题郑拾遗南斋','许棠','中唐','明时无事谏，
岂事隐明君。
每值离丹陛，
多陪宴白云。
门连萧洞僻，
地与曲江分。
满院皆柽竹，
期栖鸾鹤群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_390','题青山馆','许棠','中唐','境概殊诸处，
依然是谢家。
遗文齐日月，
旧井照烟霞。
水隔平芜远，
山横度鸟斜。
无人能此隐，
来往谩兴嗟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_391','题闻琴馆','许棠','中唐','城非宓贱邑，
馆亦号闻琴。
乃是前贤意，
常留化俗心。
代公存绿绮，
谁更寄清音。
此迹应无改，
寥寥毕古今。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_392','题秦州城','许棠','中唐','圣泽滋遐徼，
河堤四向通。
大荒收虏帐，
遗土复秦风。
乱烧迷归路，
遥山似梦中。
此时怀感切，
极目思无穷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_393','题慈恩寺元遂上人院','许棠','中唐','竹槛匝回廊，
城中似外方。
月云开作片，
枝鸟立成行。
径接河源润，
庭容塔影凉。
天台频去说，
谁占最高房。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_394','赠天台僧','许棠','中唐','赤城霞外寺，
不忘旧登年。
石上吟分海，
楼中语近天。
重游空有梦，
再隐定无缘。
独夜休行道，
星辰静照禅。',NULL,'[{"Book": "《重订中晚唐诗主客图》", "Section": null, "Content": "“分”字奇（“石上”句下）。刻峭似贾（“重游”句下）。朴老似贾（末句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《重订中晚唐诗主客图》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_395','赠志空上人','许棠','中唐','了了在心中，
南宗与北宗。
行高无外染，
骨瘦是真容。
饭野盂埋雪，
禅云杖倚松。
常修不住性，
必拟老何峰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_396','赠栖白上人','许棠','中唐','闲身却不闲，
日日对天颜。
已住城中寺，
难归海上山。
诗传华夏外，
偈布市朝间。
欲问空门事，
空门岂有关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_397','雕阴道中作','许棠','中唐','五月绥州北，
途程少郁蒸。
马依膻草聚，
人抱浊河澄。
迹固长城垒，
冤深太子陵。
往来经此地，
悲苦有谁能。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_398','汴河十二韵','许棠','中唐','昔年开汴水，
元应别有由。
或兼通楚塞，
宁独为扬州。
直断平芜色，
横分积石流。
所思千里便，
岂计万方忧。
首甚资功济，
终难弭宴游。
空怀龙舸下，
不见锦帆收。
浪倒长汀柳，
风欹远岸楼。
奔逾怀许竭，
澄彻泗滨休。
路要多行客，
鱼稀少钓舟。
日开天际晚，
雁合碛西秋。
一派注沧海，
几人生白头。
常期身事毕，
于此泳东浮。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_399','闻蝉十二韵','许棠','中唐','造化生微物，
常能应候鸣。
初离何处树，
又发去年声。
未蜕唯愁动，
才飞似解惊。
闻来邻海徼，
恨起过边城。
骚屑随风远，
悠扬类雪轻。
报秋凉渐至，
嘶月思偏清。
互默疑相荅，
微摇似欲行。
繁音人已厌，
朽壳蚁犹争。
朝士严冠饰，
宫嫔逞鬓名。
乱依西日噪，
多引北归情。
筱露凝潜吸，
蛛丝忽迸萦。
此时吟立者，
不觉万愁生。',NULL,'[{"Book": "《唐诗归》", "Section": null, "Content": "潭云：替他想到此，只是心细（“初离”二句下）。谭云：“过”字妙（“恨起”句下）。钟云：“悠扬”声也，却“类雪轻”，妙！妙（“悠扬”句下）！谭云：深极，不意咏物中有此静想（“互默”句下）。钟云：咏物诗不难于精切，而难于高简；然高简易妙，而精切难妙。此诗精切而未尝不妙者也，高简又当别论。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}]','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_400','题甘露寺','许棠','中唐','丹槛拂丹霄，
人寰下瞰遥。
何年增造化，
万古出尘嚣。
地势盘三楚，
江声换几朝。
满栏皆异药，
到顶尽飞桥。
泽广方云梦，
山孤数沃焦。
中宵霞始散，
经腊木稀凋。
铎动天风度，
窗明海气消。
带鼙分迥堞，
当日辨翻潮。
鸟去沉葭菼，
帆来映泬㵳。
浮生自多事，
无计免回镳。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_401','题郑侍郎岩隐十韵','许棠','中唐','朝退常归隐，
真修大隐情。
园林应得趣，
岩谷自为名。
野步难寻寺，
闲吟少在城。
树藏幽洞黑，
花照远村明。
海石分湖路，
风泉遰雨声。
性高怜散逸，
官达厌公卿。
架引藤重长，
阶延笋迸生。
青门无到客，
紫阁有来莺。
物外身虽隐，
区中望本清。
终难依此境，
坐卧避钧衡。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_402','寻山','许棠','中唐','蹑履复支筇，
深山草木中。
隔溪遥避虎，
当坞忽闻钟。
落叶多相似，
幽禽半不同。
群猱呼却散，
如此异林翁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_403','过故洛城','许棠','中唐','七百数还穷，
城池一旦空。
夕阳唯照草，
危堞不胜风。
岸断河声别，
田荒野色同。
去来皆过客，
何处问遗宫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_404','送友人归江南','许棠','中唐','皇州五更鼓，
月落西南维。
此时有行客，
别我孤舟归。
上国身无主，
下第诚可悲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_405','送李左丞巡边','许棠','中唐','狂戎侵内地，
左辖去萧关。
走马冲边雪，
鸣鞞动塞山。
风收枯草定，
月满广沙闲。
西绕河兰匝，
应多隔岁还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_406','送徐侍御充南诏判官','许棠','中唐','西去安夷落，
乘轺从节行。
彤庭传圣旨，
异域化戎情。
瘴路穷巴徼，
蛮川过峤城。
地偏风自杂，
天漏月稀明。
危栈连空动，
长江到底清。
笑宜防狒狒，
言好听猩猩。
抚论如敦行，
归情自合盟。
回期佩印绶，
何更见新正。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_407','留别故人','许棠','中唐','殊立本不偶，
非唯今所难。
无门闲共老，
尽日泣相看。
鸟畏闻鶗鴂，
花惭背牡丹。
何人知此计，
复议出长安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_408','题金山寺','许棠','中唐','四面波涛匝，
中楼日月邻。
上穷如出世，
下瞷忽惊神。
刹碍长空鸟，
船通外国人。
房房皆叠石，
风扫永无尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_409','忆江南','许棠','中唐','南楚西秦远，
名迟别岁深。
欲归难遂去，
闲忆自成吟。
雷电闲倾雨，
猿猱斗堕林。
眠云机尚在，
未忍负初心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_410','句','许棠','中唐','晓嶂猿开户，
寒湫鹿舐冰。
当空吟待月，
到晚坐看山。
一年三领郡，
领郡管仙山。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_411','登岭望','许鼎','后梁','淼淼三江水，
悠悠五岭关。
雁飞犹不度，
人去若为还。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_412','崿岭四望','许鼎','后梁','汉家仙仗在咸阳，
洛水东流出建章。
野老至今犹望辛，
离宫秋树独苍苍。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_413','醉吟','许碏','唐','阆苑花前是醉乡，
踏翻王母九霞觞。
群仙拍手嫌轻薄，
谪向人间作酒狂。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_414','题南岳招仙观壁上','许碏','唐','洪炉烹锻人性命，
器用不同分皆定。
妖精鬼魅斗神通，
只自干邪不干正。
黄口小儿初学行，
唯知日月东西生。
还为万灵威圣力，
移月在南日在北。
玉为玉兮石是石，
蕴弃深泥终不易。
邓通饿死严陵贫，
帝王岂是无人力。
丈夫未达莫相侵，
攀龙附凤捐精神。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_415','题怀素上人草书','许瑶','唐','志在新奇无定则，
古瘦漓纚半无墨。
醉来信手两三行，
醒后却书书不得。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_416','闰月定四时','许稷','唐','玉律穷三纪，
推为积闰期。
月馀因妙算，
岁遍自成时。
乍觉年华改，
翻怜物候迟。
六旬知不惑，
四气本无欺。
月桂亏还正，
阶蓂落复滋。
从斯分历象，
共仰定毫釐。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_417','赋得风动万年枝','许稷','唐','琼树偏春早，
光飞处处宜。
晓浮三殿日，
暗度万年枝。
婀娜摇仙禁，
缤翻映玉池。
含芳烟乍和，
拂砌影初移。
为近韶阳煦，
皆先众卉垂。
成阴知可待，
不与众芳随。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_418','江南春','许稷','唐','江南正月春花早，
梅花柳花夹长道。
江南二月春光半，
杏白桃红香蕊散。
江南三月春光暮，
蝴蝶闲飞绕深圃。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_419','纪梦','许瀍','中唐','晚入瑶台露气清，
天风飞下步虚声。
尘心未尽俗缘在，
十里下山空月明。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_420','驻锡峰','邢允中','唐','高峰常驻锡，
灵异见当年。
卓立惊沙界，
光辉动梵天。
鹤飞青霭外，
龙护赤岚边。
丈室仍相对，
重来果夙缘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_421','洗钵潭','邢允中','唐','潭水澄初地，
长为洗钵供。
已能降虎豹，
不问揽鱼龙。
溅沫溪莎碧，
疏流石濑重。
此中清净理，
继迹有禅宗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_422','梦中美人歌','邢凤','唐','长安少女踏春阳，
何处春阳不断肠？
舞袖弓弯浑忘却，
罗衣空换九秋霜。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_423','游宣州琴溪同武平一作','邢巨','唐','灵溪非人迹，
仙意素所秉。
鳞岭森翠微，
澄潭照秋景。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_424','游春','邢巨','唐','海岳三峰古，
春皇二月寒。
绿潭渔子钓，
红树美人攀。
弱蔓环沙屿，
飞花点石关。
溪山游未厌，
琴酌弄晴湾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_425','古意','邢象玉','初唐','家中酒新熟，
园里叶初荣。
伫杯欲取醉，
悒然思友生。
忽闻有奇客，
何姓复何名。
嗜酒陶彭泽，
能琴阮步兵。
何须问寒暑，
径共坐山亭。
举袂祛啼鸟，
扬巾扫落英。
心神无俗累，
歌咏有新声。
新声是何曲，
沧浪之水清。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_426','郡中有怀寄上睦州员外杜十三兄','邢群','唐','城枕溪流更浅斜，
丽谯连带邑人家。
经冬野菜青青色，
未腊山梅处处花。
虽免嶂云生岭上，
永无音信到天涯。
如今岁晏从羁滞，
心喜弹冠事不赊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_427','送萧颖士赴东府得君字','邬载','唐','策名十二载，
独立先斯文。
迩来及门者，
半已升青云。
青云岂无姿，
黄鹄素不群。
一辞芸香吏，
几岁沧江濆。
散职既不羁，
天听亦昭闻。
虽承急贤诏，
未谒陶唐君。
薄俸还自急，
此言那足云。
和风媚东郊，
时物滋南薰。
蕙草正可摘，
豫章犹未分。
宗师忽千里，
使我心氛氲。',NULL,'','{"preface": "萧夫子赴东府，门人送者十二人。刘太真为之序云：「先师微言既绝者千有馀载，至夫子而后洵美无度，得夫天和。顷东倭之人，踰海来宾，举其国俗，愿师于夫子，弗敢私，请表闻于天子。夫子辞以疾而不之从也，退然贫居，述作万卷，去其浮辞，存乎正言。昔左氏失于烦，谷梁失于短，公羊失于俗，而夫子为其折衷。王公交辟，拒而不应。从官三年，始参谋于洛京，家兄与先鸣者六七人奉壶开筵，执弟子之礼于路左。太真以文求进，以无闻见举，而不吝为夫子羞。春云轻阴，草色新碧，皎皎匹马，出于青门。吾徒喟然，瞻望不及。赋诗仰饯者，自相里造、贾邕以下，凡十二人，皆及门之选也。」", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_428','谒赠何国子监司籍坚','阳城','中唐','久仰高明抱朴忠，
倏传马首向城东。
锦袍光射三千里，
汗史功高百二雄。
童稚候门烹雀舌，
黎老植杖盼菊松。
皇天应欲逸家辅，
故遣盘桓醉碧筒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_429','和张燕公湘中九日登高','阴行先','盛唐','重阳初启节，
无射正飞灰。
寂寞风蝉至，
连翩霜雁来。
山棠红叶下，
岸菊紫花开。
今日桓公座，
多愧孟嘉才。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_430','与节供奉大德游京口寺留题','齐己','唐末至五代','柳岸晴缘十里来，
水边精舍绝尘埃。
煮茶尝摘兴何极，
直至残阳未欲回。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_431','水边行','齐己','唐末至五代','身著袈裟手杖藤，
水边行止不妨僧。
禽栖日落犹孤立，
隔浪秋山千万层。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_432','片云','齐己','唐末至五代','水底分明天上云，
可怜形影似吾身。
何妨舒作从龙势，
一雨吹销万里尘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_433','对菊','齐己','唐末至五代','无艳无妖别有香，
栽多不为待重阳。
莫嫌醒眼相看过，
却是真心爱澹黄。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_434','扑满子','齐己','唐末至五代','祗爱满我腹，
争如满害身。
到头须扑破，
却散与他人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_435','观盆池白莲','齐己','唐末至五代','素萼金英喷露开，
倚风凝立独徘徊。
应思潋滟秋池底，
更有归天伴侣来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_436','观荷叶露珠','齐己','唐末至五代','霏微晓露成珠颗，
宛转田田未有风。
任器方圆性终在，
不妨翻覆落池中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_437','闭门','齐己','唐末至五代','正是闭门争合闭，
大家开处不须开。
还防朗月清风夜，
有个诗人相访来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_438','怀道林寺道友','齐己','唐末至五代','四绝堂前万木秋，
碧参差影压湘流。
闲思宋杜题诗板，
一日凭栏到夜休。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_439','戒小师','齐己','唐末至五代','不肯吟诗不听经，
禅宗异岳懒游行。
他年白首当人问，
将底言谈对后生。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_440','杂曲歌辞','齐己','唐末至五代','凤楼高映绿阴阴，
凝重多含雨露深。
莫谓一枝柔软力，
几曾牵破别离心。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_2_441','杂曲歌辞','齐己','唐末至五代','馆娃宫畔响廊前，
依托吴王养翠烟。
剑去国亡台殿毁，
却随红树噪秋蝉。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_2_442','杂曲歌辞','齐己','唐末至五代','秾低似中陶潜酒，
软极如伤宋玉风。
多谢将军绕营种，
翠中闲卓战旗红。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_2_443','杂曲歌辞','齐己','唐末至五代','高僧爱惜遮江寺，
游子伤残露野桥。
争似著行垂上苑，
碧桃红杏对摇摇。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_2_444','庚午岁十五夜对月','齐己','唐末至五代','海澄空碧正团圆，
吟想玄宗此夜寒。
玉兔有情应记得，
西边不见旧长安。',NULL,'[{"Book": "《四库全书总目》", "Section": null, "Content": "惓惓故君，尤非他释子所及。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《四库全书总目》"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_445','放鹭鸶','齐己','唐末至五代','洁白虽堪爱，
腥膻不那何。
到头从所欲，
还汝旧沧波。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_446','苦热怀玉泉寺寄仁上人','齐己','唐末至五代','火云如烧接苍梧，
原野烟连大泽枯。
谩费葛衫葵扇力，
争禁泉石润肌肤。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_447','勉吟僧','齐己','唐末至五代','千途万辙乱真源，
白昼劳形夜断魂。
忍著袈裟把名纸，
学他低折五侯门。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_448','勉送吴国三五新戒归','齐己','唐末至五代','法王遗制付仁王，
难得难持劫数长。
努力只须坚守护，
三千八万是垣墙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_449','幽斋偶作','齐己','唐末至五代','幽院才容个小庭，
疏篁低短不堪情。
春来犹赖邻僧树，
时引流莺送好声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_450','春风曲','齐己','唐末至五代','春风有何情，
旦暮来林园。
不问桃李主，
吹落红无言。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_451','看金陵图','齐己','唐末至五代','六朝图画战争多，
最是陈宫计数讹。
若爱苍生似歌舞，
隋皇自合耻干戈。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_452','荅长沙丁秀才书','齐己','唐末至五代','月月便车奔帝阙，
年年贡士过荆台。
如何三度槐花落，
未见故人携卷来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_453','贻九华上人','齐己','唐末至五代','一法传闻继老能，
九华闲卧最高层。
秋钟尽后残阳暝，
门掩松边雨夜灯。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_454','送人归华下','齐己','唐末至五代','莲花峰翠湿凝秋，
旧业园林在下头。
好束诗书且归去，
而今不爱事风流。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_455','送人往长沙','齐己','唐末至五代','荆门归路指湖南，
千里风帆兴可谙。
好听鹧鸪啼雨处，
木兰舟晚泊春潭。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_456','送胎发笔寄仁公','齐己','唐末至五代','内唯胎发外秋毫，
绿玉新栽管束牢。
老病手疼无那尔，
却资年少写风骚。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_457','送高丽二僧南游','齐己','唐末至五代','日边乡井别年深，
中国灵踪欲遍寻。
何处碧山逢长老，
分明认取祖师心。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_458','送惠空北游','齐己','唐末至五代','君向岘山游圣境，
我将何以记多才。
叮咛堕泪碑前过，
写取斯文寄我来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_459','送楚云上人往南岳刺血写法华经','齐己','唐末至五代','剥皮刺血诚何苦，
欲写灵山九会文。
十指沥乾终七轴，
后来求法更无君。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_460','送僧归日本','齐己','唐末至五代','日东来向日西游，
一钵闲寻遍九州。
却忆鸡林本师寺，
欲归还待海风秋。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_461','送僧游龙门香山寺','齐己','唐末至五代','君到香山寺，
探幽莫损神。
且寻风雅主，
细看乐天真。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_462','闻雁','齐己','唐末至五代','潇湘浦暖全迷鹤，
逻逤川寒只有雕。
谁向孤舟忆兄弟，
坐看连雁度横桥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_463','夏日城中作二首','齐己','唐末至五代','三面僧邻一面墙，
更无风路可吹凉。
他年舍此归何处，
青壁红霞裹石房。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_464','夏日城中作二首','齐己','唐末至五代','竹低莎浅雨濛濛，
水槛幽窗暑月中。
有境牵怀人不会，
东林门外翠横空。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_465','夏日寄清溪道者','齐己','唐末至五代','老病不能求药饵，
朝昏祗是但焚烧。
不知谁为收灰骨，
垒石栽松傍寺桥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_466','病中勉送小师往清凉山礼大圣','齐己','唐末至五代','丰衣足食处莫住，
圣迹灵踪好遍寻。
忽遇文殊开慧眼，
他年应记老师心。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_467','偶作寄王秘书','齐己','唐末至五代','七丝湘水秋深夜，
五字河桥日暮时。
借问秘书郎此意，
静弹高咏有谁知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_468','偶题','齐己','唐末至五代','时事懒言多忌讳，
野吟无主若纵横。
君看三百篇章首，
何处分明著姓名。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_469','寄山中叟','齐己','唐末至五代','青泉碧树夏风凉，
紫蕨红粳午爨香。
应笑晨持一盂苦，
腥膻市里叫家常。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_470','寄怀归州马判官','齐己','唐末至五代','三年为倅兴何长，
归计应多事少忙。
又见秋风霜裛树，
满山椒熟水云香。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_471','寄怀曾口寺文英大师','齐己','唐末至五代','著紫袈裟名已贵，
吟红菡萏价兼高。
秋风曾忆西游处，
门对平湖满白涛。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_472','寄郑谷郎中','齐己','唐末至五代','人间近遇风骚匠，
鸟外曾逢心印师。
除此二门无别妙，
水边松下独寻思。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_473','寄南岳泰禅师','齐己','唐末至五代','江头默想坐禅峰，
白石山前万丈空。
山下猎人应不到，
雪深花鹿在庵中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_474','寄清溪道者','齐己','唐末至五代','万重千叠红霞嶂，
夜烛朝香白石龛。
常寄溪窗凭危槛，
看经影落古龙潭。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_475','寄赓匡图兄弟','齐己','唐末至五代','僧外闲吟乐最清，
年登八十丧南荆。
风骚作者为商确，
道去碧云争几程。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_476','答文胜大师清柱书','齐己','唐末至五代','才把文章干圣主，
便承恩泽换禅衣。
应嫌六祖传空衲，
只向曹溪求息机。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_477','谢人惠纸','齐己','唐末至五代','烘焙几工成晓雪，
轻明百幅叠春冰。
何消才子题诗外，
分与能书贝叶僧。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_478','谢人惠拄杖','齐己','唐末至五代','何处云根采得来，
黑龙狂欲作风雷。
知师念我形骸老，
教把经行拄绿苔。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_479','谢西川昙域大师玉箸篆书','齐己','唐末至五代','玉箸真文久不兴，
李斯传到李阳冰。
正悲千载无来者，
果见僧中有个僧。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_480','谢阴符经勉送藏休上人二首','齐己','唐末至五代','事遂鼎湖遗剑履，
时来渭水掷鱼竿。
欲知贤圣存亡道，
自向心机反覆看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_481','谢阴符经勉送藏休上人二首','齐己','唐末至五代','一林霜雪未沾头，
争遣藏休肯便休。
学尽世间难学事，
始堪随处任虚舟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_482','谢荆幕孙郎中见示乐府歌集二十八字','齐己','唐末至五代','长吉才狂太白颠，
二公文阵势横前。
谁言后代无高手，
夺得秦皇鞭鬼鞭。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_483','谢猿皮','齐己','唐末至五代','贵向猎师家买得，
携来乞与坐禅床。
不知摘月秋潭畔，
曾对何人啼断肠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_484','辞主人绝句四首 放猿','齐己','唐末至五代','堪忆春云十二峰，
野桃山杏摘香红。
王孙可念愁金锁，
从放断肠明月中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_485','辞主人绝句四首 放鹤','齐己','唐末至五代','华亭来复去芝田，
丹顶霜毛性可怜。
纵与乘轩终误主，
不如还放却辽天。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_486','辞主人绝句四首 放鹦鹉','齐己','唐末至五代','陇西苍巘结巢高，
本为无人识翠毛。
今日笼中强言语，
乞归天外啄含桃。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_487','辞主人绝句四首 放鹭鸶','齐己','唐末至五代','白萍红蓼碧江涯，
日暖双双立睡时。
顾揭金笼放归去，
却随沙鹤斗轻丝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_488','酬光上人','齐己','唐末至五代','禅言难后到诗言，
坐石心同立月魂。
应记前秋会吟处，
五更犹在老松根。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_489','酬欧阳秀才卷','齐己','唐末至五代','三十篇多十九章，
□声风力撼疏篁。
不堪更有精搜处，
谁见萧萧雨夜堂。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_490','翡翠','齐己','唐末至五代','水边飞去青难辨，
竹里归来色一般。
磨吻鹰鹯莫相害，
白鸥鸿鹤满沙滩。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_491','题旧拄杖','齐己','唐末至五代','亲采匡庐瀑布西，
层崖悬壁更安梯。
携行三十年吟伴，
未有诗人□□□。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_492','赠念法华经僧','齐己','唐末至五代','万境心随一念平，
红芙蓉折爱河清。
持经功力能如是，
任驾白牛安稳行。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_493','赠琴客','齐己','唐末至五代','曾携五老峰前过，
几向双松石上弹。
此境此身谁更爱，
掀天羯鼓满长安。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_494','默坐','齐己','唐末至五代','灯引飞蛾拂焰迷，
露淋栖鹤压枝低。
冥心坐满蒲团稳，
梦到天台过剡溪。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_495','七十作','齐己','唐末至五代','七十去百岁，
都来三十春。
纵饶生得到，
终免死无因。
密理方通理，
栖真始见真。
沃洲匡阜客，
几劫不迷人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_496','九日逢虚中虚受','齐己','唐末至五代','楚后萍台下，
相逢九日时。
干戈人事地，
荒废菊花篱。
我已多衰病，
君犹尽黑髭。
皇天安罪得，
解语便吟诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_497','又寄彭泽昼公','齐己','唐末至五代','闻君彭泽住，
结搆近陶公。
种菊心相似，
尝茶味不同。
湖光秋枕上，
岳翠夏窗中。
八月东林去，
吟香菡萏风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_498','与张先辈话别','齐己','唐末至五代','为子同辈者，
各自话离心。
及第还全蜀，
游方归二林。
巴江经峡涨，
楚野入吴深。
他日传消息，
东西不易寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_499','与杨秀才话别','齐己','唐末至五代','庾信哀何极，
仲宣悲苦多。
因思学文赋，
不胜弄干戈。
自古有如此，
于今终若何。
到头重策蹇，
归去旧烟萝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_500','与崔校书静话言怀','齐己','唐末至五代','同年生在咸通里，
事佛为儒趣尽高。
我性已甘披祖衲，
君心犹待脱蓝袍。
霜髭晓几临铜镜，
雪鬓寒疏落剃刀。
出世朝天俱未得，
不妨还往有风骚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_501','乞樱桃','齐己','唐末至五代','去年曾赋此花诗，
几听南园烂熟时。
嚼破红香堪换骨，
摘残丹颗欲烧枝。
流莺偷啄心应醉，
行客潜窥眼亦痴。
闻说张筵就珠树，
任从攀折半离披。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_502','小松','齐己','唐末至五代','发地才过膝，
蟠根已有灵。
严霜百草白，
深院一林青。
后夜萧骚动，
空阶蟋蟀听。
谁于千岁外，
吟绕老龙形。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_503','山中春怀','齐己','唐末至五代','心魂役役不曾归，
万象相牵向极微。
所得或忧逢郢刃，
凡言皆欲夺天机。
游深晚谷香充鼻，
坐苦春松粉满衣。
何物不为狼籍境，
桃花和雨更霏霏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_504','山中荅人','齐己','唐末至五代','谩道诗名出，
何曾著苦吟。
忽来还有意，
已过即无心。
夏月山长往，
霜天寺独寻。
故人怜拙朴，
时复寄空林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_505','山中寄凝密大师兄弟','齐己','唐末至五代','一炉薪尽室空然，
万象何妨在眼前。
时有兴来还觅句，
已无心去即安禅。
山门影落秋风树，
水国光凝夕照天。
借问荀家兄弟内，
八龙头角让谁先。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_506','山中喜得友生书','齐己','唐末至五代','柴门关树石，
未省梦尘埃。
落日啼猿里，
同人有信来。
自成为拙隐，
难以谢多才。
见说相思处，
前峰对古台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_507','山寺喜道者至','齐己','唐末至五代','闰年春过后，
山寺始花开。
还有无心者，
闲寻此境来。
鸟幽声忽断，
茶好味重回。
知住南岩久，
冥心坐绿苔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_508','己卯岁值冻阻归有作','齐己','唐末至五代','河冰连地冻，
朔气压春寒。
开户思归远，
出门移步难。
湖云黏雁重，
庙树刮风乾。
坐看孤灯焰，
微微向晓残。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_509','不睡','齐己','唐末至五代','永夜不欲睡，
虚堂闭复开。
却离灯影去，
待得月光来。
落叶逢巢住，
飞萤值我回。
天明拂经案，
一炷白檀灰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_510','中春怆怀寄二三知己','齐己','唐末至五代','眼暗心还白，
逢春强凭栏。
因闻积雨夜，
却忆旧山寒。
竹撼烟丛滑，
花烧露朵乾。
故人相会处，
应话此衰残。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_511','中春林下偶作','齐己','唐末至五代','净境无人可共携，
闲眠未起日光低。
浮生莫把还丹续，
万事须将至理齐。
花在月明蝴蝶梦，
雨馀山绿杜鹃啼。
何能向外求攀折，
岩桂枝条拂石梯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_512','中春感兴','齐己','唐末至五代','春风日日雨时时，
寒力潜从暖势衰。
一气不言含有象，
万灵何处谢无私。
诗通物理行堪掇，
道合天机坐可窥。
应是正人持造化，
尽驱幽细入垆锤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_513','中秋十五夜寄人','齐己','唐末至五代','高河瑟瑟转金盘，
喷露吹光逆凭栏。
四海鱼龙精魄冷，
五山鸾鹤骨毛寒。
今宵尽向圆时望，
后夜谁当缺处看。
何事清光与蟾兔，
却教才小少留难。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_514','中秋十四日夜对月上南平主人','齐己','唐末至五代','今宵前夕皆堪玩，
何必圆时始竭才。
空说轮中有天子，
不知何处是楼台？
终忧明夜云遮却，
且埽闲居坐看来。
玉兔银蟾似多意，
乍临棠树影裴回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_515','中秋夕怆怀寄荆幕孙郎中','齐己','唐末至五代','白莲香散沼痕乾，
绿筱阴浓藓地寒。
年老寄居思隐切，
夜凉留客话时难。
行僧尽去云山远，
宾雁同来泽国宽。
时谢孔璋操檄外，
每将空病问衰残。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_516','中秋月','齐己','唐末至五代','空碧无云露湿衣，
群星光外涌清规。
东楼莫碍渐高势，
四海待看当午时。
还许分明吟皓魄，
肯教幽暗取丹枝。
可怜半夜婵娟影，
正对五侯残酒池。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_517','书古寺僧房','齐己','唐末至五代','绿树深深处，
长明焰焰灯。
春时游寺客，
花落闭门僧。
万法心中寂，
孤泉石上澄。
劳生莫相问，
喧默不相应。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_518','书匡山隐者壁','齐己','唐末至五代','红霞青壁底，
石室薜萝垂。
应有迷仙者，
曾逢采药时。
桃花饶两颊，
松叶浅长髭。
直是来城市，
何人识得伊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_519','友人寒夜所寄','齐己','唐末至五代','通宵亦孤坐，
但念旧峰云。
白日还如此，
清闲本共君。
二毛凋一半，
百岁去三分。
早晚寻流水，
同归麋鹿群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_520','忆东林因送二生归','齐己','唐末至五代','好向东林度此生，
半天山脚寺门平。
红霞嶂底潺潺色，
清夜房前瑟瑟声。
偶别十年成瞬息，
欲来千里阻刀兵。
可怜二子同归兴，
南国烟花路好行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_521','忆旧山','齐己','唐末至五代','谁请衰羸住北州，
七年魂梦旧山丘。
心清槛底潇湘月，
骨冷禅中太华秋。
高节未闻驯虎豹，
片言何以傲王侯。
应须脱洒孤峰去，
始是分明个剃头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_522','忆在匡庐日','齐己','唐末至五代','忆在匡庐日，
秋风八月时。
松声虎溪寺，
塔影雁门师。
步碧葳蕤径，
吟香菡萏池。
何当旧泉石，
归去洗心脾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_523','忆别匡山寄彭泽乾昼上人','齐己','唐末至五代','忆别匡山日，
无端是远游。
却回看五老，
翻悔上孤舟。
蹭蹬三千里，
蹉跎二十秋。
近来空寄梦，
时到虎溪头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_524','月下作','齐己','唐末至五代','良夜如清昼，
幽人在小庭。
满空垂列宿，
那个是文星。
世界归谁是，
心魂向自宁。
何当见尧舜，
重为造生灵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_525','水鹤','齐己','唐末至五代','鸳鸯与鸂鶒，
相狎岂惭君。
比雪还胜雪，
同群亦出群。
静巢孤岛月，
寒梦九皋云。
归路分明过，
飞鸣即可闻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_526','东林作寄金陵知己','齐己','唐末至五代','十八贤真在，
时来拂榻看。
已知前事远，
更结后人难。
泉滴胜清磬，
松香掩白檀。
凭君听朝贵，
谁欲厌簪冠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_527','东林雨后望香炉峰','齐己','唐末至五代','翠湿僧窗里，
寒堆鸟道边。
静思寻去路，
急绕落来泉。
暮雨开青壁，
朝阳照紫烟。
二林多长老，
谁忆上头禅。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_528','东林寄别修睦上人','齐己','唐末至五代','行心乞得见秋风，
双履难留去住踪。
红叶正多离社客，
白云无限向嵩峰。
囊中自欠诗千首，
身外谁知事几重。
此别不能为后约，
年华相似逼衰容。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_529','仙掌','齐己','唐末至五代','峭形寒倚夕阳天，
毛女莲花翠影连。
云外自为高出手，
人间谁合斗挥拳。
鹤抛青汉来岩桧，
僧隔黄河望顶烟。
晴露红霞长满掌，
只应栖托是神仙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_530','古寺老松','齐己','唐末至五代','百岁禅师说，
先师指此松。
小年行道绕，
早见偃枝重。
月槛移孤影，
秋亭卓一峰。
终当因夜电，
拿攫从云龙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_531','古松','齐己','唐末至五代','雷电不敢伐，
鳞皴势万端。
蠹依枯节死，
蛇入朽根盘。
影浸僧禅湿，
声吹鹤梦寒。
寻常风雨夜，
应有鬼神看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_532','对菊','齐己','唐末至五代','蝶醉风狂半折时，
冷烟清露压离披。
欲倾琥珀杯浮尔，
好把茱萸朵配伊。
孔雀毛衣应者是，
凤凰金翠更无之。
何因栽向僧园里，
门外重阳过不知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_533','对雪','齐己','唐末至五代','松门堆复积，
埋石亦埋莎。
为瑞还难得，
居贫莫厌多。
听怜终夜落，
吟惜一年过。
谁在江楼望，
漫漫堕绿波。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_534','归雁','齐己','唐末至五代','塞门春已暖，
连影起蘋风。
云梦千行去，
潇湘一夜空。
江人休举网，
虏将又虚弓。
莫失南来伴，
衡阳树即红。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_535','戊辰岁江南感怀','齐己','唐末至五代','忽忽动中私，
人间何所之。
老过离乱世，
生在太平时。
桃李春无主，
杉松寺有期。
曾吟子山赋，
何啻旧凌迟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_536','戊辰岁湘中寄郑谷郎中','齐己','唐末至五代','白发久慵簪，
常闻病亦吟。
瘦应成鹤骨，
闲想似禅心。
上国杨花乱，
沧洲荻笋深。
不堪思翠巘，
西望独沾襟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_537','永夜','齐己','唐末至五代','永日还欹枕，
良宵亦曲肱。
神闲无万虑，
壁冷有残灯。
香影浮龛象，
瓶声著井冰。
寻思到何处，
海上断崖僧。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_538','永夜感怀寄郑谷郎中','齐己','唐末至五代','展转复展转，
所思安可论。
夜凉难就枕，
月好重开门。
霜杀百草尽，
蛩归四壁根。
生来苦章句，
早遇至公言。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_539','白发','齐己','唐末至五代','莫染亦莫镊，
任从伊满头。
白虽无耐药，
黑也不禁秋。
静枕听蝉卧，
闲垂看水流。
浮生未达此，
多为尔为愁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_540','示诸侄','齐己','唐末至五代','莫问年将朽，
加餐已不多。
形容浑瘦削，
行止强牵拖。
死也何忧恼，
生而有咏歌。
侯门终谢去，
却埽旧松萝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_541','边上','齐己','唐末至五代','汉地从休马，
胡家自牧羊。
都来销帝道，
浑不用兵防。
草上孤城白，
沙翻大漠黄。
秋风起边雁，
一一向潇湘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_542','龙潭作','齐己','唐末至五代','乍临毛发竖，
双壁夹湍流。
白日鸟影过，
青苔龙气浮。
蔽空云出石，
应祷雨翻湫。
四面耕桑者，
先闻贺有秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_543','伤郑谷郎中','齐己','唐末至五代','钟陵千首作，
笔绝亦身终。
知落干戈里，
谁家煨烬中。
吟斋春长蕨，
钓渚夜鸣鸿。
惆怅秋江月，
曾招我看同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_544','伤秋','齐己','唐末至五代','旦暮馀生在，
肌肤十分无。
眠寒半榻朽，
立月一株枯。
梦已随双树，
诗犹却万夫。
名山未归得，
可惜死江湖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_545','再经蒋山与诸长老夜话','齐己','唐末至五代','远迹都如雁，
南行又北回。
老僧犹记得，
往岁已曾来。
话遍名山境，
烧残黑栎灰。
无因伴师往，
归思在天台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_546','再逢昼公','齐己','唐末至五代','竟陵西别后，
遍地起刀兵。
彼此无缘着，
云山有处行。
久吟难敌句，
终忍不求名。
年鬓俱如雪，
相看眼且明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_547','再游匡山','齐己','唐末至五代','紫霄兼二老，
相对倚空寒。
久别成衰病，
重来更上难。
径危云母滑，
崖旱瀑流乾。
目断岚烟际，
神仙有石坛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_548','匡山寓居栖公','齐己','唐末至五代','外物尽已外，
闲游且自由。
好山逢过夏，
无事住经秋。
树影残阳寺，
茶香古石楼。
何时定休讲，
归漱虎溪流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_549','吊双泉大师真塔','齐己','唐末至五代','塔耸层峰后，
碑镌巨石新。
不知将一句，
分付与何人。
静坐云生衲，
空山月照真。
后徒游礼者，
犹认指迷津。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_550','吊杜工部坟','齐己','唐末至五代','鹏翅蹋于斯，
明君知不知。
域中诗价大，
荒外土坟卑。
瘴雨无时滴，
蛮风有穴吹。
唯应李太白，
魂魄往来疲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_551','同光岁送人及第东归','齐己','唐末至五代','西笑道何光，
新朝旧桂堂。
春官如白傅，
内试似文皇。
变化龙三十，
升腾凤一行。
还家几多兴，
满袖月中香。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_552','因览支使孙中丞看可准大师诗序有寄','齐己','唐末至五代','一千篇里选，
三百首菁英。
玉尺新量出，
金刀旧剪成。
锦江增古翠，
仙掌减元精。
自此为风格，
留传诸后生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_553','孙支使来借诗集因有谢','齐己','唐末至五代','冥搜从少小，
随分得淳元。
闻说吟僧口，
多传过蜀门。
相寻江岛上，
共看夏云根。
坐落迟迟日，
新题互把论。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_554','寺居','齐己','唐末至五代','邻井双梧上，
一蝉鸣隔墙。
依稀旧林日，
撩乱绕山堂。
难嘿吟风口，
终清饮露肠。
老僧加护物，
应任噪残阳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_555','寻阳道中作','齐己','唐末至五代','秋声连岳树，
草色遍汀洲。
多事时为客，
无人处上楼。
云疏片雨歇，
野阔九江流。
欲向南朝去，
诗僧有惠休。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_556','岁暮江寺住','齐己','唐末至五代','山依枯槁容，
何处见年终？
风雪军城外，
蒹葭古寺中。
孤村谁认磬，
极浦夜鸣鸿。
坐忆匡庐隐，
泉声滴半空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_557','扫地','齐己','唐末至五代','日日扫复洒，
不容纤物侵。
敢望来客口，
道似主人心。
蚁过光中少，
苔依润处深。
门前亦如此，
一径入疏林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_558','早秋雨后晚望','齐己','唐末至五代','暑气时将薄，
虫声夜转稠。
江湖经一雨，
日月换新秋。
有景堪援笔，
何人未上楼。
欲承凉冷兴，
西向碧嵩游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_559','早秋寄友生','齐己','唐末至五代','雨多残暑歇，
蝉急暮风清。
谁有闲心去，
江边看水行。
河遥红蓼簇，
野阔白烟平。
试折秋莲叶，
题诗寄竺卿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_560','早莺','齐己','唐末至五代','何处经年閟好音，
暖风催出啭乔林。
羽毛新刷陶潜菊，
喉舌初调叔夜琴。
藏雨并栖红杏密，
避人双入绿杨深。
晓来枝上千般语，
应共桃花说旧心。',NULL,'[{"Book": "《唐诗快》", "Section": null, "Content": "“旧心”二字生，妙，从无人用。然有吴（融）侍郎《还俗尼》之“旧身”，自有己公“桃花”、“莺”之“旧心”。程伊川所谓“天下之理，无独必有对”，岂不信然？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗快》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_561','早梅','齐己','唐末至五代','万木冻欲折，
孤根暖独回。
前村深雪里，
昨夜一枝开。
风遰幽香去，
禽窥素艳来。
明年如应律，
先发映春台。',NULL,'[{"Book": "《五代史补》", "Section": null, "Content": "时郑谷在袁州，齐己因携所为诗往谒焉。有《早梅》诗曰：“前村深雪里，咋夜数枝开。”谷笑谓：“数枝非‘早’也，不如‘一枝’则佳。”齐己矍然，不觉兼三衣叩地膜拜。自是士林以谷为齐己“一字之师”。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《五代史补》"}, {"Book": "《瀛奎律髓》", "Section": null, "Content": "寻常只将前四句作绝读，其实二十字绝妙。五六亦幽致。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓》"}, {"Book": "《唐诗选脉会通评林》", "Section": null, "Content": "周珽曰：此与《听泉》篇可称咏物之矫矫者。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选脉会通评林》"}, {"Book": "《唐诗别裁》", "Section": null, "Content": "二四格胜，五六只是凡语。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗别裁》"}, {"Book": "《唐诗笺注》", "Section": null, "Content": "气格矫健，绝不似僧家寒俭光景，宜其为少陵所赏识也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗笺注》"}, {"Book": "《网师园唐诗笺》", "Section": null, "Content": "方外人乃有此领会（“前村”二句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《网师园唐诗笺》"}, {"Book": "《瀛奎律髓汇评》", "Section": null, "Content": "冯班：方君云“二十字绝妙”，然气格末完，住不得。又云：出色。查慎行：造意、造语俱佳。纪昀：起四句极有神力，五六亦可，七八则辞意并竭矣。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓汇评》"}, {"Book": "《历代诗法》", "Section": null, "Content": "幽洁，自为写照。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《历代诗法》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_562','次耒阳作','齐己','唐末至五代','绕岳复沿湘，
衡阳又耒阳。
不堪思北客，
从此入南荒。
旦夕多猿狖，
淹留少雪霜。
因经杜公墓，
惆怅学文章。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_563','次韵酬郑谷郎中','齐己','唐末至五代','林下高眠起，
相招得句时。
开门流水入，
静话鹭鸶知。
每许题成晚，
多嫌雪阻期。
西斋坐来久，
风竹撼疏篱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_564','江上值春雨','齐己','唐末至五代','江皋正月雨，
平陆亦波澜。
半是峨嵋雪，
重为泽国寒。
农田淹寖尽，
客棹往来难。
愁杀骚人路，
沧浪正渺漫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_565','江上夏日','齐己','唐末至五代','无处清阴似剡溪，
火云奇崛倚空齐。
千山冷叠湖光外，
一扇凉摇楚色西。
碧树影疏风易断，
绿芜平远日难低。
故园旧寺临湘水，
斑竹烟深越鸟啼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_566','江上望远山寄郑谷郎中','齐己','唐末至五代','危碧层层映水天，
半垂冈陇下民田。
王维爱甚难抛画，
支遁高多不惜钱。
巨石尽含金玉气，
乱峰闲锁栋梁烟。
秦争汉夺空劳力，
却是巢由得稳眠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_567','江令石','齐己','唐末至五代','思量江令意，
爱石甚悠悠。
贪向深宫去，
死同亡国休。
两株荒草里，
千古暮江头。
若似黄金贵，
隋军也不留。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_568','江寺春残寄幕中知己二首','齐己','唐末至五代','谁遣西来负岳云，
自由归去竟何因。
山龛薜荔应残雪，
江寺玫瑰又度春。
早岁便师无学士，
临年却作有为人。
何妨夜醮时相忆，
伴醉佯狂笑老身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_569','江寺春残寄幕中知己二首','齐己','唐末至五代','社莲惭与幕莲同，
岳寺萧条俭府雄。
冷淡独开香火里，
殷妍行列绮罗中。
秋加玉露何伤白，
夜醉金缸不那红。
闲忆遗民此心地，
一般无染喻真空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_570','江行早发','齐己','唐末至五代','舟子相呼起，
长江未五更。
几看星月在，
犹带梦魂行。
鸟乱村林迥，
人喧水栅横。
苍茫平野外，
渐认远峰名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_571','江居寄关中知己','齐己','唐末至五代','多病多慵汉水边，
流年不觉已皤然。
旧栽花地添黄竹，
新陷盆池换白莲。
雪月未忘招远客，
云山终待去安禅。
八行书札君休问，
不似风骚寄一篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_572','池上感兴','齐己','唐末至五代','所向似无端，
风前吟凭栏。
旁人应闷见，
片水自闲看。
碧底红鳞鬣，
澄边白羽翰。
南山众木叶，
飘著竹声乾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_573','灯','齐己','唐末至五代','幽光耿耿草堂空，
窗隔飞蛾恨不通。
红烬自凝清夜朵，
赤心长谢碧纱笼。
云藏水国城台里，
雨闭松门殿塔中。
金屋玉堂开照睡，
岂知萤雪有深功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_574','老将','齐己','唐末至五代','破虏与平戎，
曾居第一功。
明时不用武，
白首向秋风。
马病霜飞草，
弓闲雁过空。
儿孙已成立，
胆气亦英雄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_575','自勉','齐己','唐末至五代','试算平生事，
中年欠五年。
知非未落后，
读易尚加前。
分受诗魔役，
宁容俗态牵。
闲吟见秋水，
数只钓鱼船。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_576','自贻','齐己','唐末至五代','心中身外更何猜，
坐石看云养圣胎。
名在好诗谁逐去，
迹依闲处自归来。
时添瀑布新瓶水，
旋换旃檀旧印灰。
晴出寺门惊往事，
古松千尺半苍苔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_577','自湘中将入蜀留别诸友','齐己','唐末至五代','巾舄初随入蜀船，
风帆吼过洞庭烟。
七千里路到何处，
十二峰云更那边。
巫女暮归林淅沥，
巴猿吟断月婵娟。
来年五月峨嵋雪，
坐看消融满锦川。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_578','自遣','齐己','唐末至五代','了然知是梦，
既觉更何求。
死入孤峰去，
灰飞一烬休。
云无空碧在，
天静月华流。
免有诸徒弟，
时来吊石头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_579','自题','齐己','唐末至五代','禅外求诗妙，
年来鬓已秋。
未尝将一字，
容易谒诸侯。
挂梦山皆远，
题名石尽幽。
敢言梁太子，
傍采碧云流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_580','舟中江上望玉梁山怀李尊师','齐己','唐末至五代','残照玉梁巅，
峨峨远棹前。
古来传胜异，
人去学神仙。
白鹿老碧壑，
黄猿啼紫烟。
谁心共无事，
局上度流年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_581','舟中晚望祝融峰','齐己','唐末至五代','天际卓寒青，
舟中望晚晴。
十年关梦寐，
此日向峥嵘。
巨石凌空黑，
飞泉照夜明。
终当蹑孤顶，
坐看白云生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_582','行次宜春寄湘西诸友','齐己','唐末至五代','幸无名利路相迷，
双履寻山上柏梯。
衣钵祖辞梅岭外，
香灯社别橘洲西。
云中石壁青侵汉，
树下苔钱绿绕溪。
我爱远游君爱住，
此心他约与谁携。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_583','杂曲歌辞','齐己','唐末至五代','下浸与高盘，
不为行路难。
是非真险恶，
翻覆作峰峦。
漆愧同时黑，
朱惭巧处丹。
令人畏相识，
欲画白云看。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_584','西墅新居','齐己','唐末至五代','渐渐见苔青，
疏疏遍地生。
闲穿藤屐起，
乱踏石阶行。
野鸟啼幽树，
名僧笑此情。
残阳竹阴里，
老圃打门声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_585','观烧','齐己','唐末至五代','猎猎寒芜引，
承风势不还。
放来应有主，
焚去到何山。
焰入空濛里，
烟飞苍莽间。
石中有良玉，
惆怅但伤颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_586','访自牧上人不遇','齐己','唐末至五代','然诺竟如何，
诸侯见重多。
高房度江雨，
经月长寒莎。
道本同骚雅，
书曾到薜萝。
相寻未相见，
危阁望沧波。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_587','过西山施肩吾旧居','齐己','唐末至五代','大志终难起，
西峰卧翠堆。
床前倒秋壑，
枕上过春雷。
鹤见丹成去，
僧闻栗熟来。
荒斋松竹老，
鸾鹤自裴回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_588','过西塞山','齐己','唐末至五代','空江平野流，
风岛苇飕飕。
残日衔西塞，
孤帆向北洲。
边鸿渡汉口，
楚树出吴头。
终入高云里，
身依片石休。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_589','过陆鸿渐旧居','齐己','唐末至五代','楚客西来过旧居，
读碑寻传见终初。
佯狂未必轻儒业，
高尚何妨诵佛书。
种竹岸香连菡萏，
煮茶泉影落蟾蜍。
如今若更生来此，
知有何人赠白驴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_590','过陈陶处士旧居','齐己','唐末至五代','一室贮琴尊，
诗皆大雅言。
夜过秋竹寺，
醉打老僧门。
远烧来篱下，
寒蔬簇石根。
闲庭除鹤迹，
半是杖头痕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_591','过荆门','齐己','唐末至五代','路出荆门远，
行行日欲西。
草枯蛮冢乱，
山断汉江低。
野店丛蒿短，
烟村簇树齐。
翻思故林去，
在处有猿啼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_592','过商山','齐己','唐末至五代','叠叠叠岚寒，
红尘翠里盘。
前程有名利，
此路莫艰难。
云水侵天老，
轮蹄到月残。
何能寻四皓，
过尽见长安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_593','过鹿门作','齐己','唐末至五代','鹿门埋孟子，
岘首载羊公。
万古千秋里，
青山明月中。
政从襄沔绝，
诗过洞庭空。
尘路谁回眼，
松声两处风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_594','过湘江唐弘书斋','齐己','唐末至五代','四邻无俗迹，
终日大开门。
水晚来边雁，
林秋下楚猿。
一家随难在，
双眼向书昏。
沈近骚人庙，
吟应见古魂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_595','闭门','齐己','唐末至五代','外事休关念，
灰心独闭门。
无人来问我，
白日又黄昏。
灯集飞蛾影，
窗销迸雪痕。
中心自明了，
一句祖师言。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_596','严陵钓台','齐己','唐末至五代','夫子垂竿处，
空江照古台。
无人更如此，
白浪自成堆。
鹤静寻僧去，
鱼狂入海回。
登临秋值晚，
树石尽多苔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_597','乱中闻郑谷吴延保下世','齐己','唐末至五代','小谏才埋玉，
星郎亦逝川。
国由多聚盗，
天似不容贤。
兵火焚诗草，
江流涨墓田。
长安已涂炭，
追想更凄然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_598','乱后江西过孙鲂旧居因寄','齐己','唐末至五代','旧游重到倍悲凉，
吟忆同人倚寺墙。
何处暮蝉喧逆旅，
此中山鸟噪垂杨。
寰区有主权兵器，
风月无人掌桂香。
欲寄此心空北望，
塞鸿天末失归行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_599','乱后经西山寺','齐己','唐末至五代','松烧寺破是刀兵，
谷变陵迁事可惊。
云里乍逢新住主，
石边重认旧题名。
闲临菡萏荒池坐，
乱踏鸳鸯破瓦行。
欲伴高僧重结社，
此身无计舍前程。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_600','别东林后回寄修睦','齐己','唐末至五代','昨夜从香社，
辞君出薜萝。
晚来巾舄上，
已觉俗尘多。
远路萦芳草，
遥空共白波。
南朝在天末，
此去重经过。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_601','吟兴自述','齐己','唐末至五代','前习都由未尽空，
生知雅学妙难穷。
一千首出悲哀外，
五十年销雪月中。
兴去不妨归静虑，
情来何止发真风。
曾无一字干声利，
岂愧操心负至公。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_602','听李尊师弹琴','齐己','唐末至五代','仙子弄瑶琴，
仙山松月深。
此声含太古，
谁听到无心。
洒石霜千片，
喷崖泉万寻。
何人传指法，
携向海中岑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_603','听泉','齐己','唐末至五代','落石几万仞，
冷声飘远空。
高秋初雨后，
半夜乱山中。
只有照壁月，
更无吹叶风。
几曾庐岳听，
到晓与僧同。',NULL,'[{"Book": "《对床夜语》", "Section": null, "Content": "齐己云：“只有照壁月，更无吹叶风”、“湘水泻秋碧，古风吹太清”……亦足以见其清苦之致。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《对床夜语》"}, {"Book": "《唐诗归》", "Section": null, "Content": "钟云：二语妙在不是说月与风，却是说泉，孤深在目（“只有”二句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}, {"Book": "《唐诗选脉会通评林》", "Section": null, "Content": "唐汝询曰：起峻爽，结想头几穷。纵观唐人咏泉诗，多有入妙者，如储光羲、刘长卿、张籍、刘得仁、齐己等作，俱以静远幽厚，发为清响。若此诗五六，结思沉细，即刘得仁《听夜泉》“寒助空山月，复畏有风生”，皆借神风月有味，尤（犹）不及此二语，一片真气在内。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选脉会通评林》"}, {"Book": "《唐诗摘钞》", "Section": null, "Content": "首二语已将本题尽情说透，以后只从题外层出，此前紧后松法也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗摘钞》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_604','怀从弟','齐己','唐末至五代','孤窗烛影微，
何事阻吟思。
兄弟断消息，
山川长路岐。
日沈栖鹤坞，
霜著叫猿枝。
可想为怀抱，
多愁多难时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_605','怀天台华顶僧','齐己','唐末至五代','华顶危临海，
丹霞里石桥。
曾从国清寺，
上看月明潮。
好鸟亲香火，
狂泉喷泬寥。
欲归师智者，
头白路迢迢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_606','怀巴陵','齐己','唐末至五代','垂白堪思大乱前，
薄游曾驻洞庭边。
寻僧古寺沿沙岸，
倚杖残阳落水天。
兰蕊蔫烟骚客庙，
烟波晴阔钓师船。
此时欲买君山住，
懒就商人乞个钱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_607','怀巴陵旧游','齐己','唐末至五代','洞庭云梦秋，
空碧共悠悠。
孟子狂题后，
何人更倚楼。
日西来远棹，
风外见平流。
终欲重寻去，
僧窗古岸头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_608','怀东湖寺','齐己','唐末至五代','铁柱东湖岸，
寺高人亦闲。
往年曾每日，
来此看西山。
竹径青苔合，
茶轩白鸟还。
而今在天末，
欲去已衰颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_609','怀匡阜','齐己','唐末至五代','荆州连岁滞游方，
拄杖尘封六尺光。
洗面有香思石溜，
冥心无挠忆山床。
闲机但愧时机速，
静论须惭世论长。
昨夜分明梦归去，
薜萝幽径绕禅房。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_610','怀华顶道人','齐己','唐末至五代','华顶星边出，
真宜上士家。
无人触床榻，
满屋贮烟霞。
坐卧临天井，
晴明见海涯。
禅馀石桥去，
屐齿印松花。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_611','怀体休上人','齐己','唐末至五代','仲宣楼上望重湖，
君到潇湘得健无。
病遇何人分药饵，
诗逢谁子论功夫。
杉萝寺里寻秋早，
橘柚洲边度日晡。
许送自身归华岳，
待来朝暮拂瓶盂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_612','怀轩辕先生','齐己','唐末至五代','不得先生信，
空怀汗漫秋。
月华离鹤背，
日影上鳌头。
欲学孤云去，
其如重骨留。
槎程在何处，
人世屡荒丘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_613','怀武陵因寄幕中韩先辈何从事','齐己','唐末至五代','武陵嘉致迹多幽，
每见图经恨白头。
溪浪碧通何处去，
桃花红过郡前流。
常闻相幕鸳鸿兴，
日向神仙洞府游。
凿井耕田人在否，
如今天子正徵搜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_614','怀终南僧','齐己','唐末至五代','扰扰一京尘，
何门是了因。
万重千叠嶂，
一去不来人。
鸟道春残雪，
萝龛昼定身。
寥寥石窗外，
天籁动衣巾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_615','怀金陵李推官僧自牧','齐己','唐末至五代','秣陵长忆共吟游，
儒释风骚道上流。
莲幕少年轻谢朓，
雪山真子鄙汤休。
也应有作怀清苦，
莫谓无心过白头。
欲附别来千万意，
病身初起向残秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_616','怀金陵知旧','齐己','唐末至五代','海门相别住荆门，
六度秋光两鬓根。
万象倒心难盖口，
一生无事可伤魂。
石头城外青山叠，
北固窗前白浪翻。
尽是共游题版处，
有谁惆怅拂苔痕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_617','怀洞庭','齐己','唐末至五代','忆过巴陵岁，
无人问去留。
中宵满湖月，
独自在僧楼。
渔父真闲唱，
灵均是谩愁。
今来欲长往，
谁借木兰舟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_618','怀道林寺因寄仁用二上人','齐己','唐末至五代','名山知不远，
长忆寺门松。
昨晚登楼见，
前年过夏峰。
雨馀云脚树，
风外日西钟。
莫更来东岸，
红尘没马踪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_619','怀潇湘即事寄友人','齐己','唐末至五代','浸野淫空澹荡和，
十年邻住听渔歌。
城临远棹浮烟泊，
寺近闲人泛月过。
岸引绿芜春雨细，
汀连斑竹晚风多。
可怜千古怀沙处，
还有鱼龙弄白波。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_620','拟嵇康绝交寄湘中贯微','齐己','唐末至五代','何处同嵇懒，
吾徒道异诸。
本无文字学，
何有往来书。
岳寺逍遥梦，
侯门勉强居。
相知在玄契，
莫讶八行疏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_621','村居寄怀','齐己','唐末至五代','风雨如尧代，
何心欲退藏。
诸侯行教化，
下国自耕桑。
道挫时机尽，
禅留话路长。
前溪久不过，
忽觉早禾香。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_622','沙鸥','齐己','唐末至五代','暖傍渔船睡不惊，
可怜孤洁似华亭。
晚来湾浦冲平碧，
晴过汀洲拂浅青。
翡翠静中修羽翼，
鸳鸯闲处事仪形。
何如飞入汉宫里，
留与兴亡作典经。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_623','角','齐己','唐末至五代','闻说征人说，
呜呜何处边。
孤城沙塞地，
残月雪霜天。
会转胡风急，
吹长碛雁连。
应伤汉车骑，
名未勒燕然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_624','言诗','齐己','唐末至五代','毕竟将何状，
根元在正思。
达人皆一贯，
迷者自多岐。
触类风骚远，
怀贤肺腑衰。
河桥送别者，
二子好相知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_625','还族弟卷','齐己','唐末至五代','岂要私相许，
君诗自入神。
风骚何句出，
瀑布一联新。
□若长如此，
名须远逐身。
闲斋舒复卷，
留滞忽经旬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_626','远山','齐己','唐末至五代','天际云根破，
寒山列翠回。
幽人当立久，
白鸟背飞来。
瀑溅何州地，
僧寻几峤苔。
终须拂巾履，
独去谢尘埃。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_627','远思','齐己','唐末至五代','远思极何处，
南楼烟水长。
秋风过鸿雁，
游子在潇湘。
海面云生白，
天涯堕晚光。
徘徊古堤上，
曾此赠垂杨。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_628','依韵酬谢尊师见赠二首','齐己','唐末至五代','南国搜奇久，
偏伤杜甫坟。
重来经汉浦，
又去入嵩云。
旧别人稀见，
新朝事渐闻。
莫将高尚迹，
闲处傲明君。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_629','依韵酬谢尊师见赠二首','齐己','唐末至五代','岳顶休高卧，
荆门访掩扉。
新诗遗我别，
旧约与谁归。
贤路曾无滞，
良时肯自违。
明年窥日窟，
仙桂露霏微。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_630','卖松者','齐己','唐末至五代','未得凌云价，
何惭所买真。
自知桃李世，
有爱岁寒人。
瑟瑟初离涧，
青青未识尘。
宁同买花者，
贵逐片时春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_631','和孙支使惠示院中庭竹之什','齐己','唐末至五代','忆就江僧乞，
和烟得一茎。
剪黄憎旧本，
科绿惜新生。
护噪蝉身稳，
资吟客眼明。
星郎有佳咏，
雅合此君声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_632','和西蜀可准大师远寄之什','齐己','唐末至五代','莫知何路去追攀，
空想人间出世间。
杜口已同居士室，
传心休问祖师山。
禅中不住方为定，
说处无生始是闲。
珍重希音远相寄，
乱峰西望叠孱颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_633','和李书记','齐己','唐末至五代','繁极全分青帝功，
开时独占上春风。
吴姬舞雪非真艳，
汉后题诗是怨红。
远蝶恋香抛别苑，
野莺衔得出深宫。
君看万态当筵处，
羞杀蔷薇点碎丛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_634','和岷公送李评事往宜春','齐己','唐末至五代','兵火销邻境，
龙沙有去人。
江潭牵兴远，
风物入题新。
雪湛将残腊，
霞明向早春。
郡侯开宴处，
桃李照歌尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_635','和昙域上人寄赠之什','齐己','唐末至五代','百病煎衰朽，
栖迟战国中。
思量青壁寺，
行坐赤松风。
道寄虚无合，
书传往复空。
可怜禅月子，
香火国门东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_636','和郑谷郎中幽栖之什','齐己','唐末至五代','谁知闲退迹，
门径入寒汀。
静倚云僧杖，
孤看野烧星。
墨沾吟石黑，
苔染钓船青。
相对唯溪寺，
初宵闻念经。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_637','和郑谷郎中看棋','齐己','唐末至五代','个是仙家事，
何人合用心。
几时终一局，
万木老千岑。
有路如飞出，
无机似陆沈。
樵夫可能解，
也此废光阴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_638','和翁员外题马太傅宅贾相公井','齐己','唐末至五代','飞尘不敢下相干，
闇脉傍应润牡丹。
心任短长投玉绠，
底须三五映金盘。
神工旧制泓澄在，
天泽时加潋滟寒。
太傅欲旌前古事，
星郎属思久凭栏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_639','咏怀寄知己','齐己','唐末至五代','已得浮生到老闲，
且将新句拟玄关。
自知清兴来无尽，
谁道淳风去不还。
三百正声传世后，
五千真理在人间。
此心终待相逢说，
时复登楼看暮山。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_640','咏影','齐己','唐末至五代','万物患有象，
不能逃大明。
始随残魄灭，
又逐晓光生。
曲直宁相隐，
洪纤必自呈。
还如至公世，
洞鉴是非情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_641','夜次湘阴','齐己','唐末至五代','风涛出洞庭，
帆影入澄清。
何处惊鸿起，
孤舟趁月行。
时难多战地，
野阔绝春耕。
骨肉知存否，
林园近郡城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_642','夜坐','齐己','唐末至五代','百虫声里坐，
夜色共冥冥。
远忆诸峰顶，
曾栖此性灵。
月华澄有象，
诗思在无形。
彻曙都忘寝，
虚窗日照经。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_643','夜坐闻雪寄所知','齐己','唐末至五代','初宵飞霰急，
竹树洒乾轻。
不是知音者，
难教爱此声。
渐凌孤烛白，
偏激苦心清。
堪笑同文友，
忘眠坐到明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_644','宜阳道中作','齐己','唐末至五代','宜阳南面路，
下岳又经过。
枫叶红遮店，
芒花白满坡。
猿无山渐薄，
雁众水还多。
日落犹前去，
诸村牧竖歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_645','宜春江上寄仰山长老二首','齐己','唐末至五代','水隔孤城城隔山，
水边时望忆师闲。
清泉白日中峰上，
落日半空栖鸟还。
云影触衣分朵朵，
雨声吹磬散潺潺。
传心莫学罗浮去，
后辈思量待扣关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_646','宜春江上寄仰山长老二首','齐己','唐末至五代','雨晴天半碧光流，
影倒残阳湿郡楼。
绝顶有人经劫在，
浮生无客暂时游。
窗开万壑春泉乱，
塔锁孤灯万木稠。
欲为吾师拂衣去，
白云红叶又新秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_647','居道林寺书怀','齐己','唐末至五代','花落水喧喧，
端居信昼昏。
谁来看山寺，
自要埽松门。
是事皆能讳，
唯诗未懒言。
传闻好时世，
亦欲背啼猿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_648','岳中寄殷处士','齐己','唐末至五代','出岳与入岳，
前题继后题。
遍寻僧壁上，
多在雁峰西。
近说游江寺，
将谁话石梯。
相思立高巘，
山下草萋萋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_649','岳阳道中作','齐己','唐末至五代','客思寻常动，
未如今断魂。
路岐经乱后，
风雪少人村。
大泽鸣寒雁，
千峰啼昼猿。
争教此时白，
不上鬓须根。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_650','庚午岁九日作','齐己','唐末至五代','门底秋苔嫩似蓝，
此中消息兴何堪。
乱离偷过九月九，
头尾算来三十三。
云影半晴开梦泽，
菊花微暖傍江潭。
故人今日在不在，
胡雁背风飞向南。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_651','招乾昼上人宿话','齐己','唐末至五代','连夜因风雪，
相留在寂寥。
禅心谁指示，
诗卷自焚烧。
语默邻寒漏，
窗扉向早朝。
天台若长往，
还渡海门潮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_652','招湖上兄弟','齐己','唐末至五代','去岁得君消息在，
两凭人信过重湖。
忍贪风月当年少，
不寄音书慰老夫。
药鼎近闻传秘诀，
诗门曾说拥寒炉。
汉江江路西来便，
好傍扁舟访我无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_653','明月峰','齐己','唐末至五代','明月峰头石，
曾闻学月明。
别舒长夜彩，
高照一村耕。
颇乱无私理，
徒惊鄙俗情。
传云遭凿后，
顽白在峥嵘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_654','松化为石','齐己','唐末至五代','盘根几耸翠崖前，
却偃凌云化至坚。
乍结精华齐永劫，
不随凋变已千年。
逢贤必用镌辞立，
遇圣终将刻印传。
肯似荆山凿馀者，
藓封顽滞卧岚烟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_655','林下留别道友','齐己','唐末至五代','住亦无依去是闲，
何心终恋此林间。
片云孤鹤东西路，
四海九州多少山。
静坐趁凉移树影，
兴随题处著苔斑。
秋来洗浣行衣了，
还尔邻僧旧竹关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_656','经安公寺','齐己','唐末至五代','大圣威灵地，
安公宴坐踪。
未知长寂默，
不见久从容。
塔影高群木，
江声压暮钟。
此游幽胜后，
来梦亦应重。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_657','经吴平观','齐己','唐末至五代','中元斋醮后，
残烬满空坛。
老鹤心何待，
尊师鬓已乾。
幡灯古殿夜，
霜霰大椿寒。
谁见长生路，
人间事万端。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_658','经费徵君旧居','齐己','唐末至五代','高眠当圣代，
云鸟未为孤。
天子徵不起，
闲人亲得无。
猿猱狂欲坠，
水石怪难图。
寂寞荒斋外，
松杉相倚枯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_659','经贾岛旧居','齐己','唐末至五代','先生居处所，
野烧几为灰。
若有吟魂在，
应随夜魄回。
地宁销志气，
天忍罪清才。
古木霜风晚，
江禽共宿来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_660','苦热','齐己','唐末至五代','云势崄于峰，
金流断竹风。
万方应望雨，
片景欲焚空。
毒害芙蓉死，
烦蒸瀑布红。
恩多是团扇，
出入画屏中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_661','苦热中江上怀炉峰旧居','齐己','唐末至五代','旧寄炉峰下，
杉松绕石房。
年年五六月，
江上忆清凉。
久别应荒废，
终归隔渺茫。
何当便摇落，
披衲玩秋光。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_662','话道','齐己','唐末至五代','大道多大笑，
寂寥何以论。
霜枫翻落叶，
水鸟啄闲门。
服药还伤性，
求珠亦损魂。
无端凿混沌，
一死不还源。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_663','金山寺','齐己','唐末至五代','山带金名远，
楼台压翠层。
鱼龙光照像，
风浪影摇灯。
槛外扬州树，
船通建业僧。
尘埃何所到，
青石坐如冰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_664','金江寓居','齐己','唐末至五代','考槃应未永，
聊此养闲疏。
野趣今何似，
诗题旧不如。
春篁离箨尽，
陂藕折花初。
终要秋云是，
从风恣卷舒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_665','临行题友生壁','齐己','唐末至五代','山衲宜何处，
经行避暑深。
峰西多古寺，
日午乱松阴。
鹤默堪分静，
蝉凉解助吟。
慇勤题壁去，
秋早此相寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_666','剃发','齐己','唐末至五代','金刀闪冷光，
一剃一清凉。
未免随朝夕，
依前长雪霜。
夏林欹石腻，
春涧水泉香。
向老凋疏尽，
寒天不出房。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_667','剑客','齐己','唐末至五代','拔剑绕残樽，
歌终便出门。
西风满天雪，
何处报人恩。
勇死寻常事，
轻雠不足论。
翻嫌易水上，
细碎动离魂。',NULL,'[{"Book": "《唐诗归》", "Section": null, "Content": "钟云：写出一“爽”字，不爽不豪。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}, {"Book": "《五朝诗善鸣集》", "Section": null, "Content": "气魄在荆、聂之上，出自高僧之手，超脱。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《五朝诗善鸣集》"}, {"Book": "《唐诗归折衷》", "Section": null, "Content": "唐云：咏剑客不厌其粗豪。敬夫云：今僧家作禅寂语偏粗，此作豪爽语殊隽。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归折衷》"}, {"Book": "《载酒园诗话》", "Section": null, "Content": "黄白山评：余尝欲删齐己《剑客》诗、赵微明《古离别》二首后四语，作绝句乃佳……前诗写剑客行径风生，后诗写思妇痴情可掬，赘后四语，其妙顿减。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《载酒园诗话》"}, {"Book": "《围炉诗话》", "Section": null, "Content": "齐己《剑客》诗，杰作也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《围炉诗话》"}, {"Book": "《唐诗成法》", "Section": null, "Content": "前四传剑客侠气，勃勃欲生。不如作绝句妙。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗成法》"}, {"Book": "《唐诗别裁》", "Section": null, "Content": "豪爽，何尝是僧诗？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗别裁》"}, {"Book": "《近体秋阳》", "Section": null, "Content": "“翻嫌”一见，紧承颈联，“细碎”二字，足令庆卿心服。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《近体秋阳》"}, {"Book": "《瀛奎律髓汇评》", "Section": null, "Content": "许印芳：（齐己）亦有豪而近粗者。如《剑客》诗……三四及结句极佳，起句及五六则粗矣。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓汇评》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_668','勉诗僧','齐己','唐末至五代','莫把毛生刺，
低佪谒李膺。
须防知佛者，
解笑爱名僧。
道性宜如水，
诗情合似冰。
还同莲社客，
联唱绕香灯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_669','勉道林谦光鸿蕴二侄','齐己','唐末至五代','旧林诸侄在，
还住本师房。
共埽焚修地，
同闻水石香。
莫将闲世界，
拟敌好时光。
须看南山下，
无名冢满冈。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_670','南归舟中二首','齐己','唐末至五代','南归乘客棹，
道路免崎岖。
江上经时节，
船中听鹧鸪。
春容含众岫，
雨气泛平芜。
落日停舟望，
王维未有图。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_671','南归舟中二首','齐己','唐末至五代','长江春气寒，
客况棹声闲。
夜泊诸村雨，
程回数郡山。
桑根垂断岸，
浪沫聚空湾。
已去邻园近，
随缘是暂还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_672','叙怀寄高推官','齐己','唐末至五代','搜新编旧与谁评，
自向无声认有声。
已觉爱来多废道，
可堪传去更沽名。
风松韵里忘形坐，
霜月光中共影行。
还胜御沟寒夜水，
狂吟冲尹甚伤情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_673','城中示友人','齐己','唐末至五代','久与寒灰合，
人中亦觉闲。
重城不锁梦，
每夜自归山。
雨破冥鸿出，
桐枯井月还。
唯君道心在，
来往寂寥间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_674','城中晚夏思山','齐己','唐末至五代','葛衣沾汗功虽健，
纸扇摇风力甚卑。
苦热恨无行脚处，
微凉喜到立秋时。
竹轩静看蜘蛛挂，
莎径闲听蟋蟀移。
天外有山归即是，
岂同游子暮何之。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_675','将之匡岳过寻阳','齐己','唐末至五代','帆过寻阳晚霁开，
西风北雁似相催。
大都浪后青堆没，
五老云中翠叠来。
此路便堪归水石，
何门更合向尘埃。
远公林下莲池畔，
个个高人尽有才。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_676','将归旧山留别错公','齐己','唐末至五代','旧峰前昨下来时，
白石丛丛间紫薇。
章句不堪歌有道，
溪山只合退无机。
云含暧态晴犹在，
鹤养闲神昼不飞。
欲去更思过丈室，
二年频此揖清晖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_677','将游嵩华行次荆渚','齐己','唐末至五代','莲峰映敷水，
嵩岳压伊河。
两处思归久，
前贤隐去多。
闲身应绝迹，
在世幸无他。
会向红霞峤，
僧龛对薜萝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_678','尝茶','齐己','唐末至五代','石屋晚烟生，
松窗铁碾声。
因留来客试，
共说寄僧名。
味击诗魔乱，
香搜睡思轻。
春风霅川上，
忆傍绿丛行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_679','幽庭','齐己','唐末至五代','不放生纤草，
从教遍绿苔。
还防长者至，
未著牡丹栽。
蛱蝶空飞过，
鹡鸰时下来。
南邻折芳子，
到此寂寥回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_680','庭际晚菊上主人','齐己','唐末至五代','九月将欲尽，
幽丛始绽芳。
都缘含正气，
不是背重阳。
采去蜂声远，
寻来蝶路长。
王孙归未晚，
犹得泛金觞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_681','庭际新移松竹','齐己','唐末至五代','三茎瘦竹两株松，
瑟瑟翛翛韵且同。
抱节乍离新涧雪，
盘根远别旧林风。
岁寒相倚无尘地，
荫影分明有月中。
更待阳和信催促，
碧梢青杪看凌空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_682','思游峨嵋寄林下诸友','齐己','唐末至五代','刚有峨嵋念，
秋来锡欲飞。
会抛湘寺去，
便逐蜀帆归。
难世堪言善，
闲人合见机。
殷勤别诸友，
莫厌楚江薇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_683','春兴','齐己','唐末至五代','柳暖莺多语，
花明草尽长。
风流在诗句，
牵率绕池塘。
叫切禽名宇，
飞忙蝶姓庄。
时来真可惜，
自勉掇兰芳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_684','春居寄友生','齐己','唐末至五代','莎径荒芜甚，
君应共此情。
江村雷雨发，
竹屋梦魂惊。
社过多来燕，
花繁渐老莺。
相思意何切，
新作未曾评。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_685','春雨','齐己','唐末至五代','欲布如膏势，
先闻动地雷。
云龙相得起，
风电一时来。
霢霂农桑野，
冥濛杨柳台。
何人待晴暖，
庭有牡丹开。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_686','春草','齐己','唐末至五代','处处碧萋萋，
平原带日西。
堪随游子路，
远入鹧鸪啼。
金谷园应没，
夫差国已迷。
欲寻兰蕙径，
荒秽满汀畦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_687','春寄尚颜','齐己','唐末至五代','含桃花谢杏花开，
杜宇新啼燕子来。
好事可能无分得，
名山长似有人催。
檐声未断前旬雨，
电影还连后夜雷。
心迹共师争几许，
似人嫌处自迟回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_688','春雪初晴喜友生至','齐己','唐末至五代','数日不见日，
飘飘势忽开。
虽无忙事出，
还有故人来。
已尽南檐滴，
仍残北牖堆。
明朝望平远，
相约在春台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_689','春晴感兴','齐己','唐末至五代','连旬阴翳晓来晴，
水满圆塘照日明。
岸草短长边过客，
江花红白里啼莺。
野无征战时堪望，
山有楼台煖好行。
桑柘依依禾黍绿，
可怜归去是张衡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_690','残春','齐己','唐末至五代','三月看无也，
芳时此可嗟。
园林欲向夕，
风雨更吹花。
影乱冲人蝶，
声繁绕堑蛙。
那堪傍杨柳，
飞絮满邻家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_691','残春连雨中偶作怀故人','齐己','唐末至五代','南邻阻杖藜，
屐齿绕床泥。
漠漠门长掩，
迟迟日又西。
不知何兴味，
更有好诗题。
还忆东林否，
行苔傍虎溪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_692','残秋感怆','齐己','唐末至五代','日日加衰病，
心心趣寂寥。
残阳起闲望，
万木耸寒条。
楚寺新为客，
吴江旧看潮。
此怀何以寄，
风雨暮萧萧。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_693','独院偶作','齐己','唐末至五代','风篁清一院，
坐卧润肌肤。
此境终抛去，
邻房肯信无。
身非王者役，
门是祖师徒。
毕竟伊云鸟，
从来我友于。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_694','盆池','齐己','唐末至五代','盆沼陷花边，
孤明似玉泉。
涵虚心不浅，
待月底长圆。
平稳承天泽，
依微泛曙烟。
何须照菱镜，
即此鉴媸妍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_695','看云','齐己','唐末至五代','何峰触石湿苔钱，
便逐高风离瀑泉。
深处卧来真隐逸，
上头行去是神仙。
千寻有影沧江底，
万里无踪碧落边。
长忆旧山青壁里，
绕庵闲伴老僧禅。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_696','看水','齐己','唐末至五代','范蠡东浮阔，
灵均北泛长。
谁知远烟浪，
别有好思量。
故国门前急，
天涯照里忙。
难收上楼兴，
渺漫正斜阳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_697','秋夕书怀','齐己','唐末至五代','凉多夜永拥山袍，
片石闲欹不觉劳。
蟋蟀绕床无梦寐，
梧桐满地有萧骚。
平生乐道心常切，
五字逢人价合高。
破落西窗向残月，
露声如雨滴蓬蒿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_698','秋夕言怀寄所知','齐己','唐末至五代','休问蒙庄材不材，
孤灯影共傍寒灰。
忘筌话道心甘死，
候体论诗口懒开。
窗外风涛连建业，
梦中云水忆天台。
相疏却是相知分，
谁讶经年一度来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_699','秋夕寄诸侄','齐己','唐末至五代','每到秋残夜，
灯前忆故乡。
园林红橘柚，
窗户碧潇湘。
离别身垂老，
艰难路去长。
弟兄应健在，
兵火里耕桑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_700','秋日钱塘作','齐己','唐末至五代','秋光明水国，
游子倚长亭。
海浸全吴白，
山澄百越青。
英雄贵黎庶，
封土绝精灵。
句践魂如在，
应悬战血腥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_701','秋兴','齐己','唐末至五代','所见背时情，
闲行亦独行。
晚凉思水石，
危阁望峥嵘。
雨外残云片，
风中乱叶声。
旧山吟友在，
相忆梦应清。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_702','秋兴寄胤公','齐己','唐末至五代','风声吹竹健，
凉气著身轻。
谁有闲心去，
江边看水行。
村遥红树远，
野阔白烟平。
试裂芭蕉片，
题诗问竺卿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_703','秋江','齐己','唐末至五代','两岸山青映，
中流一棹声。
远无风浪动，
正向夕阳横。
岛屿蝉分宿，
沙洲客独行。
浩然心自合，
何必濯吾缨。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_704','秋夜听业上人弹琴','齐己','唐末至五代','万物都寂寂，
堪闻弹正声。
人心尽如此，
天下自和平。
湘水泻秋碧，
古风吹太清。
往年庐岳奏，
今夕更分明。',NULL,'[{"Book": "《唐诗归》", "Section": null, "Content": "钟云：深直在李颀、元结之间。谭云：胸中有一段渊渊浩浩，立于声诗之先，即用此作古诗、乐府，已高一层矣，况近体耶？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}, {"Book": "《唐诗快》", "Section": null, "Content": "友夏云：“胸中渊渊浩浩，即用此作古诗、乐府，已高一层，何况近体。”其赏此诗至矣。顾何以得此于晚季耶？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗快》"}, {"Book": "《五朝诗善鸣集》", "Section": null, "Content": "此诗能移我情。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《五朝诗善鸣集》"}, {"Book": "《唐诗别裁》", "Section": null, "Content": "太和元气，从来咏琴诗俱未写到（首二句下）。渊灏之气，应在李颀、常建之间。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗别裁》"}, {"Book": "《网师园唐诗笺》", "Section": null, "Content": "二语远胜昌黎作（“人心”二句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《网师园唐诗笺》"}, {"Book": "《律髓辑要》", "Section": null, "Content": "以气胜，不甚拘对偶，而有情思贯注其间，非若昼公徒标高格，全无意味也。又云：沈归愚谓三四语写出太和元气，“从来咏琴者俱未写到”。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《律髓辑要》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_705','秋空','齐己','唐末至五代','已觉秋空极，
更堪寥泬青。
只应容好月，
争合有妖星。
耿耿高河截，
翛翛一雁经。
曾于洞庭宿，
上下彻心灵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_706','秋苔','齐己','唐末至五代','独怜苍翠文，
长与寂寥存。
鹤静窥秋片，
僧闲踏冷痕。
月明疏竹径，
雨歇败莎根。
别有深宫里，
兼花锁断魂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_707','荅友生山居寄示','齐己','唐末至五代','嘉遁有新吟，
因僧寄竹林。
静思来鸟外，
闲味绕松阴。
兵寇凭凌甚，
溪山几许深。
休为反招隐，
携取一相寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_708','荅孔秀才','齐己','唐末至五代','早向文章里，
能降少壮心。
不愁人不爱，
闲处自闲吟。
水国云雷阔，
僧园竹树深。
无嫌我衰飒，
时此一相寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_709','荅无愿上人书','齐己','唐末至五代','郑生驱蹇岘山回，
传得安公好信来。
千里阻修俱老骨，
八行重叠慰寒灰。
春残桃李犹开户，
雪满松杉始上台。
必有南游山水兴，
汉江平稳好浮杯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_710','荅陈秀才','齐己','唐末至五代','万事皆可了，
有诗门最深。
古人难得志，
吾子苦留心。
野叠凉云朵，
苔重怪木阴。
他年立名字，
笑我老双林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_711','荅知己自阙下寄书','齐己','唐末至五代','故人劳札翰，
千里寄荆台。
知恋文明在，
来寻江汉来。
群机喧白昼，
陆海涨黄埃。
得路应相笑，
无成守死灰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_712','荅崔校书','齐己','唐末至五代','雪色衫衣绝点尘，
明知富贵是浮云。
不随喧滑迷真性，
何用潺湲洗污闻。
北阙会抛红駊騀，
东林社忆白氛氲。
清吟有兴频相示，
欲得多惭蠹蚀文。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_713','荆门勉怀寄道林寺诸友','齐己','唐末至五代','荣枯得失理昭然，
谁敩离骚更问天。
生下便知真梦幻，
老来何必叹流年。
清风不变诗应在，
明月无踪道可传。
珍重匡庐沃洲主，
拂衣抛却好林泉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_714','荆门秋日寄友人','齐己','唐末至五代','青溪知不远，
白首要难归。
空想烟云里，
春风鸾鹤飞。
谁论传法偈，
自补坐禅衣。
未谢侯门去，
寻常即掩扉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_715','荆门送人自峨嵋游南岳','齐己','唐末至五代','峨嵋来已远，
衡岳去犹赊。
南浦悬帆影，
西风乱荻花。
天涯遥梦泽，
山众近长沙。
有兴多新作，
携将大府誇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_716','荆门送兴禅师','齐己','唐末至五代','洒落南宗子，
游方迹似云。
青山寻处处，
赤叶路纷纷。
虎共松岩宿，
猿和石溜闻。
何峰一回首，
忆我在人群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_717','荆门送昼公归彭泽旧居','齐己','唐末至五代','彭泽旧居在，
匡庐翠叠前。
因思从楚寺，
便附入吴船。
岸绕春残树，
江浮晓霁天。
应过虎溪社，
伫立想诸贤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_718','荆门夏日寄洞山节公','齐己','唐末至五代','湖光摇翠木，
灵洞叠云深。
五月经行处，
千秋桧柏阴。
山形临北渚，
僧格继东林。
莫惜相招信，
余心是此心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_719','荆门疾中喜谢尊师自南岳来相里秀才自京至','齐己','唐末至五代','闲堂昼卧眼初开，
强起徐行绕砌苔。
鹤氅人从衡岳至，
鹑衣客自洛阳来。
坐闻邻树栖幽鸟，
吟觉江云发早雷。
西笑东游此相别，
两途消息待谁回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_720','荆门病中雨后书怀寄幕中知己','齐己','唐末至五代','病根翻作忆山劳，
一雨聊堪浣郁陶。
心白未能忘水月，
眼青独得见秋毫。
蝉声晚簇枝枝急，
云影晴分片片高。
还忆赤松兄弟否，
别来应见鹤衣毛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_721','荆门病中寄怀贯微上人','齐己','唐末至五代','我衰君亦老，
相忆更何言。
除泥安禅力，
难医必死根。
梅寒争雪彩，
日冷让冰痕。
早晚东归去，
同寻入石门。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_722','荆门寄怀章供奉兼呈幕中知己','齐己','唐末至五代','紫衣居贵上，
青衲老关中。
事佛门相似，
朝天路不同。
神凝无恶梦，
诗澹老真风。
闻道知音在，
官高信莫通。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_723','荆门寄沈彬','齐己','唐末至五代','罢趋明圣懒从知，
鹤氅缡褷遂性披。
道有静君堪托迹，
诗无贤子拟传谁。
松声白日边行止，
日影红霞里梦思。
珍重两篇千里达，
去年江上雪飞时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_724','荆门寄题禅月大师影堂','齐己','唐末至五代','泽国闻师泥日后，
蜀王全礼葬馀灰。
白莲塔向清泉锁，
禅月堂临锦水开。
西岳千篇传古律，
南宗一句印灵台。
不堪只履还西去，
葱岭如今无使回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_725','荆门暮冬与节公话别','齐己','唐末至五代','漳河湘岸柳关头，
离别相逢四十秋。
我忆黄梅梦南国，
君怀明主去东周。
几程霜雪经残腊，
何处封疆过旧游。
好及春风承帝泽，
莫忘衰朽卧林丘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_726','荆州贯休大师旧房','齐己','唐末至五代','疏篁抽笋柳垂阴，
旧是休公种境吟。
入贡文儒来请益，
出官卿相驻过寻。
右军书画神传髓，
康乐文章梦授心。
销得青城千嶂下，
白莲标塔帝恩深。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_727','荆州寄贯微上人','齐己','唐末至五代','旧斋休忆对松关，
各在王侯顾遇间。
命服已沾天渥泽，
衲衣犹拥祖斓斑。
相思莫救烧心火，
留滞难移压脑山。
得失两途俱不是，
笑他高卧碧孱颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_728','荆州新秋寺居写怀诗五首上南平王','齐己','唐末至五代','竹如翡翠侵帘影，
苔学琉璃布地纹。
高卧更无如此乐，
远游何必爱他云。
闲听谢朓吟为政，
静看萧何坐致君。
只恐老身衰朽速，
他年不得颂鸿勋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_729','荆州新秋寺居写怀诗五首上南平王','齐己','唐末至五代','井梧黄落暮蝉清，
久驻金台但暗惊。
事佛未怜诸弟子，
谈空争动上公卿。
合归鸟外藏幽迹，
敢向人前认好名。
满印白檀灯一盏，
可能酬谢得聪明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_730','荆州新秋寺居写怀诗五首上南平王','齐己','唐末至五代','金汤里面境何求，
宝殿东边院最幽。
栽种已添新竹影，
画图兼列远山秋。
形容岂合亲公子，
章句争堪狎士流。
虚负岷峨老僧约，
年年雪水下汀洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_731','荆州新秋寺居写怀诗五首上南平王','齐己','唐末至五代','汉江西岸蜀江东，
六稔安禅教化中。
托迹幸将王粲别，
归心宁与子山同。
尊罍岂识曹参酒，
宾客还亲宋玉风。
又见去年三五夕，
一轮寒魄破烟空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_732','荆州新秋寺居写怀诗五首上南平王','齐己','唐末至五代','石龛闲锁旧居峰，
何事膺门岁月重。
五七诗中叨见遇，
三千客外许疏慵。
迎凉蟋蟀喧闲思，
积雨莓苔没屐踪。
会待英雄启金口，
却教担锡入云松。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_733','荆州新秋病起杂题一十五首 病起见王化','齐己','唐末至五代','病起见王化，
融融古帝乡。
晓烟凝气紫，
晚色作云黄。
四野歌丰稔，
千门唱乐康。
老身仍未死，
犹咏好风光。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_734','荆州新秋病起杂题一十五首 病起见生涯','齐己','唐末至五代','病起见生涯，
资缘觉甚奢。
方袍嫌垢弊，
律服变光华。
颇愧同诸俗，
何尝异出家。
三衣如两翼，
珍重汝寒鸦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_735','荆州新秋病起杂题一十五首 病起见闲云','齐己','唐末至五代','病起见闲云，
空中聚又分。
滞留堪笑我，
舒卷不如君。
触石终无迹，
从风或有闻。
仙山足鸾凤，
归去自同群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_736','荆州新秋病起杂题一十五首 病起见图画','齐己','唐末至五代','病起见图画，
云门兴似饶。
衲衣棕笠重，
嵩岳华山遥。
命在斋犹赴，
刀閒发尽凋。
秋光渐轻健，
欲去倚江桥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_737','荆州新秋病起杂题一十五首 病起见苔钱','齐己','唐末至五代','病起见苔钱，
规模遍地圆。
儿童扫不破，
子母自相连。
润屋何曾有，
缘墙谩可怜。
虚教作铜臭，
空使外人传。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_738','荆州新秋病起杂题一十五首 病起见庭石','齐己','唐末至五代','病起见庭石，
岂知经夏眠。
不能资药价，
空自作苔钱。
翠忆蓝光底，
青思瀑影边。
岩僧应笑我，
细碎种阶前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_739','荆州新秋病起杂题一十五首 病起见庭竹','齐己','唐末至五代','病起见庭竹，
君应悲我情。
何妨甚消瘦，
却称苦修行。
每谢侵床影，
时回傍枕声。
秋来渐平复，
吟绕骨毛轻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_740','荆州新秋病起杂题一十五首 病起见庭柏','齐己','唐末至五代','病起见庭柏，
青青我不任。
力扶乾瘦骨，
勉对岁寒心。
韵谢疏篁合，
根容片石侵。
衰残想长寿，
时倚就闲吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_741','荆州新秋病起杂题一十五首 病起见庭莎','齐己','唐末至五代','病起见庭莎，
绿阶傍竹多。
绕行犹未得，
静听复如何。
蟋蟀幽中响，
蟪蛄深处歌。
不缘田地窄，
剩种任婆娑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_742','荆州新秋病起杂题一十五首 病起见庭莲','齐己','唐末至五代','病起见庭莲，
风荷已飒然。
开时闻馥郁，
枕上正缠绵。
本在沧江阔，
移来碧沼圆。
却思香社里，
叶叶漏声连。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_743','荆州新秋病起杂题一十五首 病起见庭菊','齐己','唐末至五代','病起见庭菊，
几劳栽种工。
可能经卧疾，
相倚自成丛。
翠萼低含露，
金英尽亚风。
那知予爱尔，
不在酒杯中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_744','荆州新秋病起杂题一十五首 病起见秋月','齐己','唐末至五代','病起见秋月，
正当三五时。
清光应鉴我，
幽思更同谁。
惜坐身犹倦，
牵吟气尚羸。
明年七十六，
约此健相期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_745','荆州新秋病起杂题一十五首 病起见秋扇','齐己','唐末至五代','病起见秋扇，
风前悟感伤。
念予当咽绝，
得尔致清凉。
沙鹭如摇影，
汀莲似绽香。
不同婕妤咏，
托意怨君王。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_746','荆州新秋病起杂题一十五首 病起见衰叶','齐己','唐末至五代','病起见衰叶，
飘然似我身。
偶乘风有韵，
初落地无尘。
纵得红沾露，
争如绿带春。
因伤此怀抱，
聊寄一篇新。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_747','荆诸偶作','齐己','唐末至五代','无味吟诗即把经，
竟将疏野访谁行。
身依江寺庭无树，
山绕天涯路有兵。
竹瓦雨声漂永日，
纸窗灯焰照残更。
从容一觉清凉梦，
归到龙潭扫石枰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_748','荆渚逢禅友','齐己','唐末至五代','泽国相逢话一宵，
云山偶别隔前朝。
社思匡岳无宗炳，
诗忆扬州有鲍昭。
晨野黍离春漠漠，
水天星粲夜遥遥。
闲吟莫忘传心祖，
曾立阶前雪到腰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_749','荆渚寄怀西蜀无染大师兄','齐己','唐末至五代','大沩心付白崖前，
宝月分辉照蜀天。
圣主降情延北内，
诸侯稽首问南禅。
清秋不动骊龙海，
红日无私罔象川。
欲听吾宗旧山说，
地边身老楚江边。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_750','荆渚感怀寄僧达禅弟三首','齐己','唐末至五代','电击流年七十三，
齿衰气沮竟何堪。
谁云有句传天下，
自愧无心寄岭南。
晓漱气嫌通市井，
晚烹香忆落云潭。
邻峰道者应弹指，
藓剥藤缠旧石龛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_751','荆渚感怀寄僧达禅弟三首','齐己','唐末至五代','十五年前会虎溪，
白莲斋后便来西。
干戈时变信虽绝，
吴楚路长魂不迷。
黄叶喻曾同我悟，
碧云情近与谁携。
春残相忆荆江岸，
一只杜鹃头上啼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_752','荆渚感怀寄僧达禅弟三首','齐己','唐末至五代','鹤岭僧来细话君，
依前高尚迹难群。
自抛南岳三生石，
长傍西山数片云。
丹访葛洪无旧灶，
诗寻灵观有遗文。
莫将离别为相隔，
心似虚空几处分。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_753','览延栖上人卷','齐己','唐末至五代','今体雕镂妙，
古风研考精。
何人忘律韵，
为子辨诗声。
贾岛苦兼此，
孟郊清独行。
荆门见编集，
愧我老无成。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_754','览清尚卷','齐己','唐末至五代','李洞僻相似，
得诗先示师。
鬼神迷去处，
风日背吟时。
格已搜清竭，
名还着紫卑。
从容味高作，
翻为古人疑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_755','贺孙支使郎中迁居','齐己','唐末至五代','别认公侯礼上才，
筑金何啻旧燕台。
地连东阁横头买，
门对西园正面开。
不隔红尘趋棨戟，
只拖珠履赴尊罍。
应逢明月清霜夜，
闲领笙歌宴此来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_756','贺行军太傅得白氏东林集','齐己','唐末至五代','乐天歌咏有遗编，
留在东林伴白莲。
百尺典坟随丧乱，
一家风雅独完全。
常闻荆渚通侯论，
果遂吴都使者传。
仰贺斯文归朗鉴，
永资声政入薰弦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_757','贺雪','齐己','唐末至五代','上清凝结下乾坤，
为瑞为祥表致君。
日月影从光外过，
山河形向静中分。
歌扬郢路谁同听，
声洒梁园客共闻。
堪想画堂帘卷次，
轻随舞袖正纷纷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_758','贻王秀才','齐己','唐末至五代','功到难搜处，
知难始是诗。
自能探虎子，
何虑屈男儿。
此道真清气，
前贤早白髭。
须教至公手，
不惜付丹枝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_759','贻庐岳陈沆秀才','齐己','唐末至五代','为儒老双鬓，
勤苦竟何如。
四海方磨剑，
空山自读书。
石围泉眼碧，
秋落洞门虚。
莫虑搜贤僻，
徵君旧此居。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_760','贻张生','齐己','唐末至五代','日日见入寺，
未曾含酒容。
闲听老僧语，
坐到夕阳钟。
竹里行多影，
花边偶过踪。
犹言谢生计，
随我去孤峰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_761','贻徐生','齐己','唐末至五代','可能东海子，
清苦在贫居。
扫地无闲客，
堆窗有古书。
少年犹若此，
向老合何如。
去岁频相访，
今来见亦疏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_762','贻惠暹上人','齐己','唐末至五代','经论功馀更业诗，
又于难里纵天机。
吴朝客见投文去，
楚国僧迎著紫归。
已得声名先振俗，
不妨风雪更探微。
金陵高忆恩门在，
终挂云帆重一飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_763','送二友生归宜阳','齐己','唐末至五代','二生俱我友，
清苦辈流稀。
旧国居相近，
孤帆秋共归。
残阳沙鸟乱，
疏雨岛枫飞。
几宿多山处，
猿啼烛影微。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_764','送人下第东归再谒旧主人','齐己','唐末至五代','一战偶不捷，
东归计未空。
还携故书剑，
去谒旧英雄。
楚雪连吴树，
西江正北风。
男儿艺若是，
会合值明公。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_765','送人归吴','齐己','唐末至五代','比说归耕钓，
迢迢向海涯。
春寒游子路，
村晚主人家。
野岸纷垂柳，
深山绿过茶。
重寻旧邻里，
菱藕正开花。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_766','送人自蜀回南游','齐己','唐末至五代','锦水东浮情尚郁，
湘波南泛思何长。
蜀魂巴狖悲残夜，
越鸟燕鸿叫夕阳。
烟月几般为客路，
林泉四绝是吾乡。
寻幽必有僧相指，
宋杜题诗近旧房。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_767','送人南游','齐己','唐末至五代','且听吟赠远，
君此去蒙州。
瘴国频闻说，
边鸿亦不游。
蛮花藏孔雀，
野石乱犀牛。
到彼谁相慰，
知音有郡侯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_768','送人赴官','齐己','唐末至五代','年少作初官，
还如行路难。
兵荒经邑里，
风俗久凋残。
照砚花光淡，
漂书柳絮乾。
聊应充侍膳，
薄俸继朝餐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_769','送人赴举','齐己','唐末至五代','分有争忘得，
时来须出山。
白云终许在，
清世莫空还。
驿树秋声健，
行衣雨点斑。
明年从月里，
满握度春关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_770','送人润州寻兄弟','齐己','唐末至五代','君话南徐去，
迢迢过建康。
弟兄新得信，
鸿雁久离行。
木落空林浪，
秋残渐雪霜。
闲游登北固，
东望海苍苍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_771','送人游玉泉寺','齐己','唐末至五代','西峰大雪开，
万叠向空堆。
客贵犹寻去，
僧高肯不来。
潭澄猿觑月，
窦冷鹿眠苔。
公子将才子，
联题兴未回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_772','送人游武陵湘中','齐己','唐末至五代','为子歌行乐，
西南入武陵。
风烟无战士，
宾榻有吟僧。
山绕军城叠，
江临寺阁层。
遍寻幽胜了，
湘水泛清澄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_773','送人游南','齐己','唐末至五代','南国多山水，
君游兴可知。
船中江上景，
晚泊早行时。
子美遗魂地，
藏真旧墨池。
经过几销日，
荒草里寻碑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_774','送人游湘湖','齐己','唐末至五代','君游南国去，
旅梦若为宁。
一路随鸿雁，
千峰绕洞庭。
林明枫尽落，
野黑烧初经。
有兴寻僧否，
湘西寺最灵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_775','送人游塞','齐己','唐末至五代','槐柳野桥边，
行尘暗马前。
秋风来汉地，
客路入胡天。
雁聚河流浊，
羊群碛草膻。
那堪陇头宿，
乡梦逐潺湲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_776','送人游雍京','齐己','唐末至五代','君来乞诗别，
聊与怆前程。
九野未无事，
少年何远行。
商云盘翠险，
秦甸下烟平。
应见周南化，
如今在雍京。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_777','送人游衡岳','齐己','唐末至五代','荆楚腊将残，
江湖苍莽间。
孤舟载高兴，
千里向名山。
雪浪来无定，
风帆去是闲。
石桥僧问我，
应寄岳茶还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_778','送友人游湘中','齐己','唐末至五代','怀才难自住，
此去亦如僧。
何处西风夜，
孤吟旅舍灯。
路沿湘树叠，
山入楚云层。
若有东来札，
归鸿亦可凭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_779','送王处士游蜀','齐己','唐末至五代','又挂寒帆向锦川，
木兰舟里过残年。
自修姹姹炉中物，
拟作飘飘水上仙。
三峡浪喧明月夜，
万州山到夕阳天。
来年的有荆南信，
回札应缄十色笺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_780','送王秀才往松滋夏课','齐己','唐末至五代','松滋闻古县，
明府是诗家。
静理馀无事，
攲眠尽落花。
江光摇夕照，
柳影带残霞。
君去应相与，
乘船泛月华。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_781','送东林寺睦公往吴国','齐己','唐末至五代','八月江行好，
风帆日夜飘。
烟霞经北固，
禾黍过南朝。
社客无宗炳，
诗家有鲍昭。
莫因贤相请，
不返旧山椒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_782','送卢说乱后投知己','齐己','唐末至五代','兵寇残江墅，
生涯尽荡除。
事堪煎桂玉，
时莫倚诗书。
暮狖啼空半，
春山列雨馀。
舟中有新作，
回寄示慵疏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_783','送司空学士赴京','齐己','唐末至五代','弘文初命下江边，
难恋沙鸥与钓船。
蓝绶乍称新学士，
白衫初脱旧神仙。
龙山送别风生路，
鸡树从容雪照筵。
重谒往年金榜主，
便将才术佐陶甄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_784','送玉泉道者回山寺','齐己','唐末至五代','却忆西峰顶，
经行绝爱憎。
别来心念念，
归去雪层层。
石坞寻春笋，
苔龛续夜灯。
应悲尘土里，
追逐利名僧。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_785','送白处士游峨嵋','齐己','唐末至五代','闲身谁道是羁游，
西指峨嵋碧顶头。
琴鹤几程随客棹，
风霜何处宿龙湫。
寻僧石磴临天井，
斸药秋崖倒瀑流。
莫为寰瀛多事在，
客星相逐不回休。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_786','送节大德归阙','齐己','唐末至五代','西京曾入内，
东洛又朝天。
圣上方虚席，
僧中正乏贤。
晨光金殿里，
紫气玉帘前。
知祝唐尧化，
新恩异往年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_787','送休师归长沙宁觐','齐己','唐末至五代','吾子此归宁，
风烟是旧经。
无穷芳草色，
何处故山青？
偶泊鸣蝉岛，
难眠好月汀。
殷勤问安外，
湘岸采诗灵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_788','送休师归长沙宁觐','齐己','唐末至五代','高堂亲老本师存，
多难长悬两处魂。
已说战尘消汉口，
便随征棹别荆门。
晴吟野阔无耕地，
晚宿湾深有钓村。
他日更思衰老否，
七年相伴琢诗言。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_789','送冰禅再往湖中','齐己','唐末至五代','行心宁肯住，
南去与谁群。
碧落高空处，
清秋一片云。
穿林瓶影灭，
背雨锡声分。
应笑游方久，
龙钟楚水濆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_790','送刘秀才归桑水宁觐','齐己','唐末至五代','归和初喜戢戈矛，
乍捧乡书感去留。
雁序分飞离汉口，
鸰原骞翥在鳌头。
家邻紫塞仍千里，
路过黄河更几州。
应到高堂问安后，
却携文入帝京游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_791','送刘秀才往东洛','齐己','唐末至五代','羡子去东周，
行行非旅游。
烟霄有兄弟，
事业尽曹刘。
洛水清奔夏，
嵩云白入秋。
来年遂鹏化，
一举上瀛洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_792','送韩蜕秀才赴举','齐己','唐末至五代','百发百中技，
长杨献赋年。
丹枝如计分，
一箭的无偏。
文物兵销国，
关河雪霁天。
都人看春榜，
韩字在谁前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_793','送孙凤秀才赴举','齐己','唐末至五代','九重方侧席，
四海仰文明。
好把孤吟去，
便随公道行。
梁园浮雪气，
汴水涨春声。
此日登仙众，
君应最后生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_794','送孙逸人归庐山','齐己','唐末至五代','独自担琴鹤，
还归瀑布东。
逍遥非俗趣，
杨柳谩春风。
草绕村程绿，
花盘石磴红。
他时许相觅，
五老乱云中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_795','送朱秀才归闽','齐己','唐末至五代','荆门来几日，
欲往又囊空。
远客归南越，
单衣背北风。
近乡微有雪，
到海渐无鸿。
努力成诗业，
无谋谒至公。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_796','送朱侍御自洛阳归阆州宁觐','齐己','唐末至五代','寻常西望故园时，
几处魂随落照飞。
客路旧萦秦甸出，
乡程今绕汉阳归。
已过巫峡沈青霭，
忽认峨嵋在翠微。
从此倚门休望断，
交亲喜换老莱衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_797','送迁客','齐己','唐末至五代','天涯即爱州，
谪去莫多愁。
若似承恩好，
何如傍主休。
瘴昏铜柱黑，
草赤火山秋。
应想尧阴下，
当时獬豸头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_798','送吴先辈赴京','齐己','唐末至五代','烟霄已遂明经第，
江汉重来问苦吟。
托兴偶凭风月远，
忘机终在寂寥深。
千篇未听常徒口，
一字须防作者心。
此日与君聊话别，
老身难约更相寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_799','送吴守明先辈游蜀','齐己','唐末至五代','凭君游蜀去，
细为话幽奇。
丧乱嘉陵驿，
尘埃贾岛诗。
未应过锦府，
且合上峨嵋。
既逐高科后，
东西任所之。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_800','送李秀才归湘中','齐己','唐末至五代','词客携文访病夫，
因吟送别忆湘湖。
寒消浦溆催鸿雁，
暖入溪山养鹧鸪。
僧向月中寻岳麓，
云从城上去苍梧。
君归为问峰前寺，
旧住僧房锁在无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_801','送李评事往宜春','齐己','唐末至五代','兰舟西去是通津，
名郡贤侯下礼频。
山遍寺楼看仰岫，
台连城阁上宜春。
鸿心夜过乡心乱，
雪韵朝飞句韵新。
别有官荣身外趣，
月江松径访禅人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_802','送灵𧦬上人游五台','齐己','唐末至五代','此去清凉顶，
期瞻大圣容。
便应过洛水，
即未上嵩峰。
残照催行影，
幽林惜驻踪。
想登金阁望，
东北极兵锋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_803','送陈霸归闽','齐己','唐末至五代','凉风动行兴，
含笑话临途。
已得身名了，
全忘客道孤。
乡程过百越，
帆影绕重湖。
家在飞鸿外，
音书可寄无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_804','送周秀游峡','齐己','唐末至五代','又向夔城去，
知难动旅魂。
自非亡国客，
何虑断肠猿。
滟滪分高仞，
瞿塘露浅痕。
明年期此约，
平稳到荆门。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_805','送林上人归永嘉旧居','齐己','唐末至五代','东越常悬思，
山门在永嘉。
秋光浮楚水，
帆影背长沙。
城黑天台雨，
村明海峤霞。
时寻谢公迹，
春草有瑶花。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_806','送欧阳秀才赴举','齐己','唐末至五代','莫疑空手去，
无援取高科。
直是文章好，
争如德行多。
烟霄心一寸，
霜雪路千坡。
称意东归后，
交亲那喜何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_807','送幽禅师','齐己','唐末至五代','霜繁野叶飞，
长老卷行衣。
浮世不知处，
白云相待归。
磬和天籁响，
禅动岳神威。
莫便言长往，
劳生待发机。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_808','送相里秀才自京至却回','齐己','唐末至五代','夷门诗客至，
楚寺闭萧骚。
老病语言涩，
少年风韵高。
难于寻阆岛，
险甚涉云涛。
珍重西归去，
无忘役思劳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_809','送相里秀才赴举','齐己','唐末至五代','两上东堂不见春，
文明重去有谁亲。
曾逢少海尊前客，
旧是神仙会里人。
已遂风云催化羽，
却将雷电助烧鳞。
明年自此登龙后，
回首荆门一路尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_810','送胤公归阙','齐己','唐末至五代','西朝归去见高情，
应恋香灯近圣明。
关令莫疑非马辩，
道安还跨赤驴行。
充斋野店蔬无味，
洒笠平原雪有声。
忍惜文章便闲得，
看他趋竞取时名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_811','送赵长史归闽川','齐己','唐末至五代','荆门与闽越，
关戍隔三千。
风雪扬帆去，
台隍指海边。
客情消旅火，
王化似尧年。
莫失春回约，
江城谷雨前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_812','送唐禀正字归萍川','齐己','唐末至五代','霜须芸阁吏，
久掩白云扉。
来谒元戎后，
还骑病马归。
烟村蔬饮淡，
江驿雪泥肥。
知到中林日，
春风长涧薇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_813','送徐秀才之吴','齐己','唐末至五代','吴都霸道昌，
才子去观光。
望阙云天近，
朝宗水路长。
海门收片雨，
建业泊残阳。
欲问淮王信，
仙都即帝乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_814','送徐秀才游吴国','齐己','唐末至五代','西江东注急，
孤棹若流星。
风浪相随白，
云中独过青。
他时谁共说，
此路我曾经。
好向吴朝看，
衣冠尽汉庭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_815','送泰禅师归南岳','齐己','唐末至五代','石龛闲锁白猿边，
归去程途半在船。
林簇晓霜离水寺，
路穿新烧入山泉。
已寻岚壁临空尽，
却看星辰向地悬。
有兴寄题红叶上，
不妨收拾别为编。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_816','送益公归旧居','齐己','唐末至五代','旧隐终牵梦，
春残结束归。
溪山无伴过，
风雨有花飞。
片石留题字，
孤潭照浣衣。
邻僧喜相接，
埽径与开扉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_817','送秘上人','齐己','唐末至五代','谁喜老闲身，
春山起送君。
欲凭莲社信，
转入洞庭云。
道路长无阻，
干戈渐不闻。
秋来向何处，
相忆雁成群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_818','送乾康禅师入山过夏','齐己','唐末至五代','由来喧滑境，
难驻寂寥踪。
逼夏摇孤锡，
离城入乱峰。
云门应近寺，
石路或穿松。
知在栖禅外，
题诗寄北宗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_819','送崔判官赴归倅','齐己','唐末至五代','白首从颜巷，
青袍去佐官。
只应微俸禄，
聊补旧饥寒。
地说丘墟甚，
民闻旱歉残。
春风吹绮席，
宾主醉相欢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_820','送彬座主赴龙安请讲','齐己','唐末至五代','两论久研精，
龙安受请行。
春城雨雪霁，
古寺殿堂明。
白发老僧听，
金毛师子声。
同流有谁共，
别著国风清。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_821','送略禅者归南岳','齐己','唐末至五代','林下钟残又拂衣，
锡声还独向南飞。
千峰冷截冥鸿处，
一径险通禅客归。
青石上行苔片片，
古杉边宿雨霏霏。
劳生有愿应回首，
忍著无心与物违。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_822','送隆公上人','齐己','唐末至五代','独携谭柄去，
千里指人寰。
未断生徒望，
难教白日闲。
空江横落照，
大府向西山。
好骋陈那孔，
谁云劫石顽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_823','送惠空上人归','齐己','唐末至五代','尘中名利热，
鸟外水云闲。
吾子多高趣，
秋风独自还。
空囊随客棹，
几宿泊湖山。
应有吟僧在，
邻居树影间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_824','送游山道者','齐己','唐末至五代','我亦游山者，
常经旧所经。
雪消天外碧，
春晓海中青。
可见乱离世，
况临衰病形。
怜君此行兴，
独入白云屏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_825','送谢尊师自南岳出入京','齐己','唐末至五代','曾听鹿鸣逢世乱，
因披羽服隐衡阳。
几多事隔丹霄兴，
三十年成两鬓霜。
芝朮未甘销勇气，
风骚无那激刚肠。
中朝旧有知音在，
可是悠悠入帝乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_826','送韩蜕秀才赴举','齐己','唐末至五代','槐花馆驿暮尘昏，
此去分明吏部孙。
才器合居科第首，
风流幸是缙绅门。
春和洛水清无浪，
雪洗高峰碧断根。
堪想都人齐指点，
列仙相次上昆崙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_827','送错公栖公南游','齐己','唐末至五代','洪偃汤休道不殊，
高帆共载兴何俱。
北京丧乱离丹凤，
南国烟花入鹧鸪。
明月团圆临桂水，
白云重叠起苍梧。
威仪本是朝天士，
暂向辽荒住得无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_828','送僧','齐己','唐末至五代','老忆游方日，
天涯锡独摇。
凌晨从北固，
冲雪向南朝。
鬓发泉边剃，
香灯树下烧。
双峰诸道友，
夏满有书招。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_829','送僧归南岳','齐己','唐末至五代','浊世住终难，
孤峰念永安。
逆风眉磔磔，
冲雪锡珊珊。
石室关霞嫩，
松枝拂藓乾。
岩猿应认得，
连臂下句栏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_830','送僧归洛中','齐己','唐末至五代','赤日彤霞照晚坡，
东州道路兴如何。
蝉离楚柳鸣犹少，
叶到嵩云落渐多。
海内自为闲去住，
关头谁问旧经过。
叮咛与访春山寺，
白乐天真在也么。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_831','送谭三藏入京','齐己','唐末至五代','阿阇梨与佛身同，
灌顶难施利济功。
持咒力须资运祚，
度人心要似虚空。
东周路踏红尘里，
北极门瞻紫气中。
好进焚文沾帝泽，
却归天策继真风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_832','重宿旧房与愚上人静话','齐己','唐末至五代','曾此栖心过十冬，
今来潇洒属生公。
檀栾旧植青添翠，
菡萏新栽白换红。
北面城临灯影合，
西邻壁近讲声通。
不知门下趋筵士，
何似当时石解空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_833','闻王员外新恩有寄','齐己','唐末至五代','欲退无因贵逼来，
少仪官美右丞才。
青袍早许淹花幕，
霜简方闻谢柏台。
金诺静宜资讲诵，
玉山寒称奉尊罍。
西峰有客思相贺，
门隔潇湘雪未开。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_834','闻西蟾从弟卜岩居岳西有寄','齐己','唐末至五代','瀑布见高低，
岩开岩壁西。
碧云多旧作，
红叶几新题。
滴沥中疏磬，
嵌空半倚梯。
仍闻樵子径，
□不到前溪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_835','闻沈彬赴吴都请辟','齐己','唐末至五代','长讶高眠得稳无，
果随徵辟起江湖。
鸳鸯已列樽罍贵，
鸥鹤休怀钓渚孤。
白日不妨扶汉祚，
清才何让赋吴都。
可能更忆相寻夜，
雪满诸峰火一炉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_836','闻尚颜上人创居有寄','齐己','唐末至五代','麓山南面橘洲西，
别搆新斋与竹齐。
野客已闻将鹤赠，
江僧未说有诗题。
窗临杳霭寒千嶂，
枕遍潺湲月一溪。
可想乍移禅榻处，
松阴冷湿壁新泥。',NULL,'[{"Book": "《贯华堂选批唐才子诗》", "Section": null, "Content": "一句分明是写“创”，三四分明是写“新”，只有二句之“与竹齐”三字，却是写景。甚矣，律诗之不肯写景也（首四句下）。前解写新居之新，此解写新居之受用也，易解。末句只写得“壁泥新”三字耳。上四字只如一人问云：松阴何故冷湿？因答之云：非冷湿也，乃壁新泥耳（末四句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《贯华堂选批唐才子诗》"}, {"Book": "《小清华园诗谈》", "Section": null, "Content": "何谓超然？……僧齐己之“麓山南面橘洲西，闻道新斋与竹齐……”等作是也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《小清华园诗谈》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_837','闻尚颜下世','齐己','唐末至五代','岳僧传的信，
闻在麓山亡。
郡有为诗客，
谁来一影堂。
梦休寻灞浐，
迹已绝潇湘。
远忆同吟石，
新秋桧柏凉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_838','闻贯休下世','齐己','唐末至五代','吾师诗匠者，
真个碧云流。
争得梁太子，
重为文选楼。
锦江新冢树，
婺女旧山秋。
欲去焚香礼，
啼猿峡阻修。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_839','闻落叶','齐己','唐末至五代','楚树雪晴后，
萧萧落晚风。
因思故国夜，
临水几株空。
煮茗烧乾脆，
行苔踏烂红。
来年未离此，
还见碧丛丛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_840','闻道林诸友尝茶因有寄','齐己','唐末至五代','枪旗冉冉绿丛园，
谷雨初晴叫杜鹃。
摘带岳华蒸晓露，
碾和松粉煮春泉。
高人梦惜藏岩里，
白硾封题寄火前。
应念苦吟耽睡起，
不堪无过夕阳天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_841','闻雁','齐己','唐末至五代','何处人惊起，
飞来过草堂。
丹心劳避弋，
万里念随阳。
影断风天月，
声孤荻岸霜。
明年趁春去，
江上别鸳鸯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_842','除夜','齐己','唐末至五代','夜久谁同坐，
炉寒鼎亦澄。
乱松飘雨雪，
一室掩香灯。
白发添新岁，
清吟减旧朋。
明朝待晴旭，
池上看春冰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_843','倦客','齐己','唐末至五代','闭眼即开门，
人间事倦闻。
如何迎好客，
不似看闲云。
少欲资三要，
多言让十分。
疏慵本吾性，
任笑早离群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_844','原上晚望','齐己','唐末至五代','倚杖聊摅望，
寒原远近分。
夜来何处火，
烧出古人坟。
野势盘空泽，
江流合暮云。
残阳催百鸟，
各自著栖群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_845','哭郑谷郎中','齐己','唐末至五代','朝衣闲典尽，
酒病觉难医。
下世无遗恨，
传家有大诗。
新坟青嶂叠，
寒食白云垂。
长忆招吟夜，
前年风雪时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_846','夏日江寺寄无上人','齐己','唐末至五代','讲终斋磬罢，
何处称真心。
古寺高杉下，
炎天独院深。
燕和江鸟语，
墙夺暮花阴。
大府多才子，
闲过在竹林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_847','夏日西霞寺书怀寄张逸人','齐己','唐末至五代','人中林下现，
名自有闲忙。
建业红尘热，
栖霞白石凉。
倚身柽几稳，
洒面瀑流香。
不似高斋里，
花连竹影长。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_848','夏日作','齐己','唐末至五代','燕雀语相和，
风池满芰荷。
可惊成事晚，
殊喜得闲多。
竹众凉欺水，
苔繁绿胜莎。
无惭孤圣代，
赋咏有诗歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_849','夏日言怀','齐己','唐末至五代','苦被流年迫，
衰羸老病情。
得归青嶂死，
便共白云生。
树蘖烧炉响，
崖棱蹑屐声。
此心人信否，
魂梦自分明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_850','夏日林下作','齐己','唐末至五代','烦暑莫相煎，
森森在眼前。
暂来还尽日，
独坐只闻蝉。
草媚终难死，
花飞卒未蔫。
秋风舍此去，
满箧贮新篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_851','夏日雨中寄幕中知己','齐己','唐末至五代','北风吹夏雨，
和竹亚南轩。
豆枕欹凉冷，
莲峰入梦魂。
窗多斜迸湿，
庭遍瀑流痕。
清兴知无限，
晴来示一言。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_852','夏日草堂作','齐己','唐末至五代','沙泉带草堂，
纸帐卷空床。
静是真消息，
吟非俗肺肠。
园林坐清影，
梅杏嚼红香。
谁住原西寺，
钟声送夕阳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_853','夏日原西避暑寄吟友','齐己','唐末至五代','热烟疏竹古原西，
日日乘凉此杖藜。
闲处雨声随霹雳，
旱田人望隔虹霓。
蝉依独树乾吟苦，
鸟忆平川渴过齐。
别有相招好泉石，
瑞花瑶草尽堪携。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_854','夏日梅雨中寄睦公','齐己','唐末至五代','梅月来林寺，
冥冥各闭门。
已应双履迹，
全没乱云根。
琢句心无味，
看经眼亦昏。
何时见清霁，
招我凭岩轩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_855','夏日寓居寄友人','齐己','唐末至五代','北游兵阻复南还，
因寄荆州病掩关。
日月坐销江上寺，
清凉魂断剡中山。
披缁影迹堪藏拙，
出世身心合向闲。
多谢扶风大君子，
相思时到寂寥间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_856','夏满日偶作寄孙支使','齐己','唐末至五代','一百二十日，
煎熬几不胜。
忆归沧海寺，
冷倚翠崖棱。
旧扇犹操执，
新秋更郁蒸。
何当见凉月，
拥衲访诗朋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_857','桃花','齐己','唐末至五代','千株含露态，
何处照人红？
风暖仙源里，
春和水国中。
流莺应见落，
舞蝶未知空。
拟欲求图画，
枝枝带竹丛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_858','浙江晚渡','齐己','唐末至五代','去年曾到此，
久立滞前程。
岐路时难处，
风涛晚未平。
汀蝉含老韵，
岸荻簇枯声。
莫泥关河险，
多游自远行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_859','浣口泊舟晓望天柱峰','齐己','唐末至五代','根盘潜岳半，
顶逼日轮边。
冷碧无云点，
危棱有瀑悬。
秀轻毛女下，
名与鼎湖偏。
谁见扶持力，
峨峨出后天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_860','海棠花','齐己','唐末至五代','繁于桃李盛于梅，
寒食旬前社后开。
半月暄和留艳态，
两时风雨免伤摧。
人怜格异诗重赋，
蝶恋香多夜更来。
犹得残红向春暮，
牡丹相继发池台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_861','爱吟','齐己','唐末至五代','正堪凝思掩禅扃，
又被诗魔恼竺卿。
偶凭窗扉从落照，
不眠风雪到残更。
皎然未必迷前习，
支遁宁非悟后生。
传写会逢精鉴者，
也应知是咏闲情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_862','留题仰山大师塔院','齐己','唐末至五代','岚光叠杳冥，
晓翠湿窗明。
欲起游方去，
重来绕塔行。
乱云开鸟道，
群木发秋声。
曾约诸徒弟，
香灯尽此生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_863','病起二首','齐己','唐末至五代','一卧四十日，
起来秋气深。
已甘长逝魄，
还见旧交心。
撑拄筇犹重，
枝梧力未任。
终将此形陋，
归死故丘林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_864','病起二首','齐己','唐末至五代','秋风已伤骨，
更带竹声吹。
抱疾关门久，
扶羸傍砌时。
无生即不可，
有死必相随。
除却归真觉，
何由拟免之。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_865','读阴符经','齐己','唐末至五代','绕窗风竹骨轻安，
闲借阴符仰卧看。
绝利一源真有谓，
空劳万卷是无端。
清虚可保升云易，
嗜欲终知入圣难。
三要洞开何用闭，
高台时去凭栏干。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_866','读岘山碑','齐己','唐末至五代','三载羊公政，
千年岘首碑。
何人更堕泪，
此道亦殊时。
兵火烧文缺，
江云触藓滋。
那堪望黎庶，
匝地是疮痍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_867','读参同契','齐己','唐末至五代','堪笑修仙侣，
烧金觅大还。
不知消息火，
只在寂寥关。
鬓白炉中术，
魂飞海上山。
悲哉五千字，
无用在人间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_868','读贾岛集','齐己','唐末至五代','遗篇三百首，
首首是遗冤。
知到千年外，
更逢何者论。
离秦空得罪，
入蜀但听猿。
还似长沙祖，
唯馀赋鵩言。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_869','逢乡友','齐己','唐末至五代','无况来江岛，
逢君话滞留。
生缘同一国，
相识共他州。
竹影斜青藓，
茶香在白瓯。
犹怜心道合，
多事亦冥搜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_870','逢进士沈彬','齐己','唐末至五代','欲话趋时首重骚，
因君倍惜剃头刀。
千般贵在能过达，
一片心闲不那高。
山叠好云藏玉鸟，
海翻狂浪隔金鳌。
时应记得长安事，
曾向文场属思劳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_871','逢诗僧','齐己','唐末至五代','禅玄无可并，
诗妙有何评。
五七字中苦，
百千年后清。
难求方至理，
不朽始为名。
珍重重相见，
忘机话此情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_872','宿江寺','齐己','唐末至五代','岛僧留宿慰衰颜，
旧住何妨老未还。
身共锡声离鸟外，
迹同云影过人间。
曾无梦入朝天路，
忆有诗题隔海山。
珍重来晨渡江去，
九华青里扣松关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_873','宿沈彬进士书院','齐己','唐末至五代','相期只为话篇章，
踏雪曾来宿此房。
喧滑尽消城漏滴，
窗扉初掩岳茶香。
旧山春暖生薇蕨，
大国尘昏惧杀伤。
应有太平时节在，
寒宵未卧共思量。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_874','宿舒湖希上人房','齐己','唐末至五代','入寺先来此，
经窗半在湖。
秋风新菡萏，
暮雨老菰蒲。
任听浮生速，
能消默坐无。
语来灯焰短，
嘒唳发高梧。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_875','宿简寂观','齐己','唐末至五代','万壑云霞影，
千年松桧声。
如何教下士，
容易信长生。
月共虚无白，
香和沆𤅈清。
闲寻古廊画，
记得列仙名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_876','寄三觉山从益上人','齐己','唐末至五代','山下人来说，
多时不下山。
是应终未是，
闲得且须闲。
海面云归窦，
猿边月上关。
寻思乱峰顶，
空送衲僧还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_877','寄上荆渚因梦庐岳乃图壁赋诗','齐己','唐末至五代','梦绕嵯峨里，
神疏骨亦寒。
觉来谁共说，
壁上自图看。
古翠松藏寺，
春红杏湿坛。
归心几时遂，
日向渐衰残。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_878','寄山中诸友','齐己','唐末至五代','自归城里寺，
长忆宿山门。
终夜冥心客，
诸峰叫月猿。
岚光生眼力，
泉滴爽吟魂。
只待游方遍，
还来埽树根。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_879','寄云盖山先禅师','齐己','唐末至五代','曾寻湘水东，
古翠积秋浓。
长老禅栖处，
半天云盖峰。
闲床饶得石，
杂树少于松。
近有谁堪语，
浏阳妙指踪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_880','寄友生','齐己','唐末至五代','风骚情味近如何，
门底寒流屋里莎。
曾摘园蔬留我宿，
共吟江月看鸿过。
时危苦恨无收拾，
道妙深誇有琢磨。
凉夜欹眠应得梦，
平生心肺似君多。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_881','寄双泉大师师兄','齐己','唐末至五代','清泉流眼底，
白道倚岩棱。
后夜禅初入，
前溪树折冰。
南凉来的的，
北魏去腾腾。
敢把吾师意，
密传门外僧。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_882','寄文秀大师','齐己','唐末至五代','皎然灵一时，
还有屈于诗。
世岂无英主，
天何惜大师。
道终归正始，
心莫问多岐。
览卷堪惊立，
贞风喜未衰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_883','寄文浩百法','齐己','唐末至五代','当时六祖在黄梅，
五百人中眼独开。
入室偈闻传绝唱，
升堂客谩恃多才。
铁牛无用成真角，
石女能生是圣胎。
闻说欲抛经论去，
莫教惆怅却空回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_884','寄无愿上人','齐己','唐末至五代','六十八去七十岁，
与师年鬓不争多。
谁言生死无消处，
还有修行那得何。
开士安能穷好恶，
故人堪忆旧经过。
会归原上焚身后，
一阵灰飞也任他。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_885','寄王振拾遗','齐己','唐末至五代','折槛意何如，
平安信不虚。
近来焚谏草，
深去觅山居。
志定荣枯外，
身全宠辱馀。
分明知在处，
难寄乱离书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_886','寄东林言之禅子','齐己','唐末至五代','闻思相送后，
幽院闭苔钱。
使我吟还废，
闻君病未痊。
听秋唯困坐，
怕客但佯眠。
可惜东窗月，
无寥过一年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_887','寄归州马判官','齐己','唐末至五代','郡带女𡡓名，
民康境亦宁。
晏梳秋鬓白，
闲坐暮山青。
赠客椒初熟，
寻僧酒半醒。
应怀旧居处，
歌管隔墙听。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_888','寄旧居邻友','齐己','唐末至五代','别后知何趣，
搜奇少客同。
几层山影下，
万树雪声中。
晚鼎烹茶绿，
晨厨爨粟红。
何时携卷出，
世代有名公。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_889','寄玉泉实仁上人','齐己','唐末至五代','往岁曾寻圣迹时，
树边三绕礼吾师。
敢望护法将军记，
且喜焚香弟子知。
后会未期心的的，
前峰欲下步迟迟。
今来老劣难行甚，
空寂无缘但寄诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_890','寄仰山光味长者','齐己','唐末至五代','大仰禅栖处，
杉松到顶阴。
下来虽有路，
归去每无心。
鸟道峰形直，
龙湫石影深。
径行谁得见，
半夜老猿吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_891','寄匡阜诸公二首','齐己','唐末至五代','松头柏顶碧森森，
虚槛寒吹夏景深。
静社可追长往迹，
白莲难问久修心。
山围四面才容寺，
月到中宵始满林。
争学忘言住幽胜，
吾师遗集尽清吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_892','寄匡阜诸公二首','齐己','唐末至五代','峰前林下东西寺，
地角天涯来往僧。
泉月净流闲世界，
杉松深锁尽香灯。
争无大士重修社，
合有诸贤更服膺。
曾寄邻房挂瓶锡，
雨闻岩溜解春冰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_893','寄华山司空图','齐己','唐末至五代','天下艰难际，
全家入华山。
几劳丹诏问，
空见使臣还。
瀑布寒吹梦，
莲峰翠湿关。
兵戈阻相访，
身老瘴云间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_894','寄孙鲂秀才','齐己','唐末至五代','郡楼东面寺墙西，
颜子生涯竹屋低。
书案飞飏风落絮，
地苔狼藉燕衔泥。
吟窗晚凭春篁密，
行径斜穿夏菜齐。
别后相思频梦到，
二年同此赋闲题。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_895','寄孙辟呈郑谷郎中','齐己','唐末至五代','衡岳去都忘，
清吟恋省郎。
淹留才半月，
詶唱颇盈箱。
雪长松柽格，
茶添语话香。
因论乐安子，
年少老篇章。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_896','寄寻萍公','齐己','唐末至五代','闻在湓城多寄住，
随时谈笑浑尘埃。
孤峰恐忆便归去，
浮世要看还下来。
万顷野烟春雨断，
九条寒浪晚窗开。
虎溪桥上龙潭寺，
曾此相寻踏雪回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_897','寄当阳张明府','齐己','唐末至五代','玉泉神运寺，
寒磬彻琴堂。
有境灵如此，
为官兴亦长。
吏愁清白甚，
民乐赋输忘。
闻说巴山县，
今来尚忆张。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_898','寄江西幕中孙鲂员外','齐己','唐末至五代','簪履为官兴，
芙蓉结社缘。
应思陶令醉，
时访远公禅。
茶影中残月，
松声里落泉。
此门曾共说，
知未遂终焉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_899','寄江居耿处士','齐己','唐末至五代','野癖虽相似，
生涯即不同。
红霞禅石上，
明月钓船中。
醉倒芦花白，
吟缘蓼岸红。
相思何以寄，
吾道本空空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_900','寄江夏仁公','齐己','唐末至五代','寺阁高连黄鹤楼，
檐前槛底大江流。
几因秋霁澄空外，
独为诗情到上头。
白日有馀闲送客，
紫衣何啻贵封侯。
别来多少新吟也，
不寄南宗老比丘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_901','寄自牧上人','齐己','唐末至五代','五老回无计，
三峰去不成。
何言谢云鸟，
此地识公卿。
梦愧将僧说，
心嫌触类生。
南朝古山寺，
曾忆共寻行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_902','寄西山郑谷神','齐己','唐末至五代','西望郑先生，
焚修在杳冥。
几番松骨朽，
未换鬓根青。
石阙凉调瑟，
秋坛夜拜星。
俗人应抚掌，
闲处诵黄庭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_903','寄西川惠光大师昙域','齐己','唐末至五代','禅月有名子，
相知面未曾。
笔精垂壁溜，
诗涩滴杉冰。
蜀国从栖泊，
芜城几废兴。
忆归应寄梦，
东北过金陵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_904','寄许州清古','齐己','唐末至五代','北来儒士说，
许下有吟僧。
白日身长倚，
清秋塔上层。
言虽依景得，
理要入无徵。
敢望多相示，
孱微老不胜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_905','寄阳岐西峰僧','齐己','唐末至五代','西峰残照东，
瀑布洒冥鸿。
闲忆高窗外，
秋晴万里空。
藤阴藏石磴，
衣毳落杉风。
日有谁来觅，
层层鸟道中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_906','寄体休','齐己','唐末至五代','南州君去为寻医，
病色应除似旧时。
久别莫忘庐阜约，
却来须有洞庭诗。
金陵往岁同窥井，
岘首前秋共读碑。
两处山河见兴废，
相思更切卧云期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_907','寄何崇丘员外','齐己','唐末至五代','门底桃源水，
涵空复映山。
高吟烟雨霁，
残日郡楼间。
变俗真无事，
分题是不闲。
寻思章岸见，
全未有年颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_908','寄吴国西供奉','齐己','唐末至五代','别来相忆梦多迷，
君住东朝我楚西。
瑶阙合陪龙象位，
春山休记鹧鸪啼。
承恩位与千官别，
应制才将十子齐。
几笑远公慵送客，
慇勤只到寺前溪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_909','寄吴国知旧','齐己','唐末至五代','淮甸当年忆旅游，
衲衣棕笠外何求。
城中古巷寻诗客，
桥上残阳背酒楼。
晴色水云天合影，
晚声名利市争头。
可怜王化融融里，
惆怅无僧似惠休。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_910','寄吴拾遗','齐己','唐末至五代','新竹将谁搉重轻，
皎然评里见权衡。
非无苦到难搜处，
合有清垂不朽名。
疏雨晚冲莲叶响，
乱蝉凉抱桧梢鸣。
野桥闲背残阳立，
翻忆苏卿送子卿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_911','寄吴都沈员外彬','齐己','唐末至五代','归休兴若何，
朱绂尽还他。
自有园林阔，
谁争山水多。
村烟晴莽苍，
僧磬晚嵯峨。
野醉题招隐，
相思可寄么。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_912','寄岘山道人','齐己','唐末至五代','凤门高对鹿门青，
往岁经过恨未平。
辩鼎上人方话道，
卧龙丞相忽追兵。
炉峰已负重回计，
华岳终悬未去情。
闻说东周天子圣，
会摇金锡却西行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_913','寄岘山愿公三首','齐己','唐末至五代','形影更谁亲，
应怀漆道人。
片言酬凿齿，
半偈伏姚秦。
榛莽池经烧，
蒿莱寺过春。
心期重西去，
一共吊遗尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_914','寄岘山愿公三首','齐己','唐末至五代','相思恨相远，
至理那时何。
道笑忘言甚，
诗嫌背俗多。
青苔闲阁闭，
白日断人过。
独上西楼望，
荆门千万坡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_915','寄岘山愿公三首','齐己','唐末至五代','彼此无消息，
所思江汉遥。
转闻多患难，
甚说远相招。
老至何悲叹，
生知便寂寥。
终期踏松影，
携手虎溪桥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_916','寄庐岳僧','齐己','唐末至五代','一闻飞锡别区中，
深入西南瀑布峰。
天际雪埋千片石，
洞门冰折几株松。
烟霞明媚栖心地，
苔藓萦纡出世踪。
莫问江边旧居寺，
火烧兵劫断秋钟。',NULL,'[{"Book": "《贯华堂选批唐才子诗》", "Section": null, "Content": "一声锡响，去得恁疾，雪埋冰折，入得恁深。一解诗分明便是“一自泥牛斗入海，直至于今无消息”句也（首四句下）。此僧不知何人，辱己公写到如许。真大死后重更活人，诸佛不奈之何者也。写心地不用寂寞字，偏说“烟霞明媚”；写行履不用孤峭字，偏说“藤竹萦纡”。此是“肯埋”、“冰折”后自然无碍境界，非他人所得滥叨也。若夫世间未经冰雪之士，即有如士人所云矣（末四句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《贯华堂选批唐才子诗》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_917','寄怀东林寺匡白监寺','齐己','唐末至五代','南岳别来无约后，
东林归住有前缘。
闲搜好句题红叶，
静敛霜眉对白莲。
雁塔影分疏桧月，
虎溪声合几峰泉。
修心若似伊耶舍，
传记须添十九贤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_918','寄怀江西栖公','齐己','唐末至五代','龙沙为别日，
庐阜得书年。
不见来香社，
相思绕白莲。
江僧归海寺，
楚路接吴烟。
老病何堪说，
扶羸寄此篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_919','寄怀江西僧达禅翁','齐己','唐末至五代','长忆旧山日，
与君同聚沙。
未能精贝叶，
便学咏杨花。
苦甚伤心骨，
清还切齿牙。
何妨继馀习，
前世是诗家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_920','寄怀江西徵岷二律师','齐己','唐末至五代','乱后江边寺，
堪怀二律师。
几番新弟子，
一样旧威仪。
院影连春竹，
窗声接雨池。
共缘山水癖，
久别共题诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_921','寄怀西蟾师弟','齐己','唐末至五代','万里八九月，
一身西北风。
自从相示后，
长记在吟中。
见说南游远，
堪怀我姓同。
江边忽得信，
回到岳门东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_922','寄怀钟陵旧游因寄知己','齐己','唐末至五代','洗井僧来说旧游，
西江东岸是城楼。
昔年淹迹因王化，
长日凭栏看水流。
真观上人栖树石，
陈陶处士在林丘。
终拖老病重寻去，
得到匡庐死便休。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_923','寄李洞秀才','齐己','唐末至五代','到处听时论，
知君屈最深。
秋风几西笑，
抱玉但伤心。
野水翻红藕，
沧江老白禽。
相思未相识，
闻在蜀中吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_924','寄谷山长老','齐己','唐末至五代','游遍名山祖遍寻，
却来尘世浑光阴。
肯将的的吾师意，
拟付茫茫弟子心。
岂有虚空遮道眼，
不妨文字问知音。
沧浪万顷三更月，
天上何如水底深。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_925','寄还阙下高辇先辈卷','齐己','唐末至五代','去岁逢京使，
因还所寄诗。
难留天上作，
曾换月中枝。
趣极僧迷旨，
功深鬼不知。
仍闻得名后，
特地更忘疲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_926','寄尚颜','齐己','唐末至五代','莫向孤峰道息机，
有人偷眼羡吾师。
满身光化年前宠，
几轴开平岁里诗。
北阙故人随丧乱，
南山旧寺在参差。
清吟但忆徐方政，
应恨当时不见时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_927','寄居道林寺作','齐己','唐末至五代','岚湿南朝殿塔寒，
此中因得谢尘寰。
已同庭树千株老，
未负溪云一片闲。
石镜旧游临皎洁，
岳莲曾上彻孱颜。
如今衰飒成多病，
黄叶风前昼掩关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_928','寄明月山僧','齐己','唐末至五代','山称明月好，
月出遍山明。
要上诸峰去，
无妨半夜行。
白猿真雪色，
幽鸟古琴声。
吾子居来久，
应忘我在城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_929','寄松江陆龟蒙处士','齐己','唐末至五代','万卷功何用，
徒称处士休。
闲欹太湖石，
醉听洞庭秋。
道在谁开口，
诗成自点头。
中间欲相访，
寻便阻戈矛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_930','寄欧阳侍郎','齐己','唐末至五代','又闻繁总在嘉州，
职重身闲倚寺楼。
大象影和山面落，
两江声合郡前流。
棋轻国手知难敌，
诗是天才肯易酬。
毕竟男儿自高达，
从来心不是悠悠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_931','寄武陵贯微上人二首','齐己','唐末至五代','知泛沧浪棹未还，
西峰房锁夜潺潺。
春陪相府游仙洞，
雪共宾寮对玉山。
诗里几添新菡萏，
衲痕应换旧斓斑。
莫忘一句曹溪妙，
堪塞孙孙骋度关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_932','寄武陵贯微上人二首','齐己','唐末至五代','吴头东面楚西边，
云接苍梧水浸天。
两地别离身已老，
一言相合道休传。
风骚妙欲凌春草，
踪迹闲思绕岳莲。
不是傲他名利世，
吾师本在雪山巅。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_933','寄武陵道友','齐己','唐末至五代','阮肇迷仙处，
禅门接紫霞。
不知寻鹤路，
几里入桃花。
晚树阴摇藓，
春潭影弄砂。
何当见招我，
乞与片生涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_934','寄武陵微上人','齐己','唐末至五代','善卷台边寺，
松筠绕祖堂。
秋声度风雨，
晓色遍沧浪。
白石同谁坐，
清吟过我狂。
近闻为古律，
雅道更重光。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_935','寄诗友','齐己','唐末至五代','天地有万物，
尽应输苦心。
他人虽欲解，
此道奈何深。
返朴遗时态，
关门度岁阴。
相思去秋夕，
共对冷灯吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_936','寄贯休','齐己','唐末至五代','子美曾吟处，
吾师复去吟。
是何多胜地，
销得二公心。
锦水流春阔，
峨嵋叠雪深。
时逢蜀僧说，
或道近游黔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_937','寄郑谷郎中','齐己','唐末至五代','上国谁传消息过，
醉眠醒坐对嵯峨。
身离道士衣裳少，
笔荅禅师句偈多。
南岸郡钟凉度枕，
西斋竹露冷沾莎。
还应笑我降心外，
惹得诗魔助佛魔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_938','寄郑谷郎中','齐己','唐末至五代','高名喧省闼，
雅颂出吾唐。
叠巘供秋望，
无云到夕阳。
自封修药院，
别埽著僧床。
几梦中朝事，
依依鹓鹭行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_939','寄郑谷郎中','齐己','唐末至五代','诗心何以传，
所證自同禅。
觅句如探虎，
逢知似得仙。
神清太古在，
字好雅风全。
曾沐星郎许，
终惭是斐然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_940','寄金陵幕中李郎中','齐己','唐末至五代','龙门支派富才能，
年少飞翔便大鹏。
久待尊罍临铁瓮，
又从幢节镇金陵。
精神一只秋空鹤，
骚雅千寻夏井冰。
长忆相招宿华馆，
数宵忘寝尽寒灯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_941','寄南岳诸道友','齐己','唐末至五代','南望衡阳积瘴开，
去年曾踏雪游回。
谩为楚客蹉跎过，
却是边鸿的当来。
乳窦孤明含海日，
石桥危滑长春苔。
终寻十八高人去，
共坐苍崖养圣胎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_942','寄南徐刘员外二首','齐己','唐末至五代','竟陵兵革际，
归复旧园林。
早岁为官苦，
常闻说此心。
海边山夜上，
城外寺秋寻。
应讶嵩峰约，
蹉跎直到今。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_943','寄南徐刘员外二首','齐己','唐末至五代','昼公评众制，
姚监选诸文。
风雅谁收我，
编联独有君。
馀生终此道，
万事尽浮云。
争得重携手，
探幽楚水濆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_944','寄南雅上人','齐己','唐末至五代','曾得音书慰暮年，
相思多故信难传。
清吟何处题红叶，
旧社空怀堕白莲。
山水本同真趣向，
侯门刚有薄因缘。
他时不得君招隐，
会逐南归楚客船。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_945','寄洛下王彝训先辈二首','齐己','唐末至五代','贾岛存正始，
王维留格言。
千篇千古在，
一咏一惊魂。
离别无他寄，
相思共此门。
阳春堪永恨，
郢路转尘昏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_946','寄洛下王彝训先辈二首','齐己','唐末至五代','北极新英主，
高科旧少年。
风流传贵达，
谈笑取荣迁。
洛水秋空底，
嵩峰晓翠巅。
寻常谁并马，
桥上戏成篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_947','寄荅武陵幕中何支使二首','齐己','唐末至五代','十万雄军幕，
三千上客才。
何当谈笑外，
远慰寂寥来。
骚雅锵金掷，
风流醉玉颓。
争知江雪寺，
老病向寒灰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_948','寄荅武陵幕中何支使二首','齐己','唐末至五代','南州无百战，
北地有长征。
闲杀何从事，
伤哉苏子卿。
江楼联雪句，
野寺看春耕。
门外沧浪水，
风波杂雨声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_949','寄荆幕孙郎中','齐己','唐末至五代','珠履风流忆富春，
三千鹓鹭让精神。
诗工凿破清求妙，
道论研通白见真。
四座共推操檄健，
一家谁信买书贫。
别来乡国魂应断，
剑阁东西尽战尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_950','寄倪署郎中','齐己','唐末至五代','风雨冥冥春闇移，
红残绿满海棠枝。
帝乡久别江乡住，
椿笋何如樱笋时。
海内擅名君作赋，
林间外学我为诗。
近闻南国升南省，
应笑无机老病师。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_951','寄哭西川坛长广济大师','齐己','唐末至五代','千万僧中宝，
三朝帝宠身。
还源未化火，
举国葬全真。
文集编金在，
碑铭刻玉新。
有谁于异代，
弹指礼遗尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_952','寄唐洙处士','齐己','唐末至五代','行僧去湘水，
归雁度荆门。
彼此亡家国，
东西役梦魂。
多慵如长傲，
久住不生根。
曾问兴亡事，
丁宁寄勿言。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_953','寄唐禀正字','齐己','唐末至五代','疏野还如旧，
何曾称在城。
水边无伴立，
天际有山横。
落日云霞赤，
高窗笔砚明。
鲍昭多所得，
时忆寄汤生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_954','寄朗陵二禅友','齐己','唐末至五代','潇湘曾宿话诗评，
荆楚连秋阻野情。
金锡罢游双鬓白，
铁盂终守一斋清。
篇章老欲齐高手，
风月闲思到极精。
南望山门石何处，
沧浪云梦浸天横。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_955','寄栖白上人','齐己','唐末至五代','万国争名地，
吾师独此闲。
题诗招上相，
看雪下南山。
内殿承恩久，
中条进表还。
常因秋贡客，
少得掩禅关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_956','寄益上人','齐己','唐末至五代','长想寻君道路遥，
乱山霜后火新烧。
近闻移住邻衡岳，
几度题诗上石桥。
古木传声连峭壁，
一灯悬影过中宵。
风骚味薄谁相爱，
攲枕常多梦鲍昭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_957','寄监利司空学士','齐己','唐末至五代','诗家为政别，
清苦日闻新。
乱后无荒地，
归来尽远人。
宽容民赋税，
憔悴吏精神。
何必河阳县，
空传桃李春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_958','寄钱塘罗给事','齐己','唐末至五代','愤愤呕谗书，
无人诵子虚。
伤心天祐末，
搔首懿宗初。
海树青丛短，
湖山翠点疏。
秋涛看足否，
罗刹石边居。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_959','寄顾处士','齐己','唐末至五代','半年离别梦，
来往即湖边。
两幅关山雪，
寻常在眼前。
项容藏古翠，
张藻卷寒烟。
蓝淀图花鸟，
时人不惜钱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_960','寄顾蟾处士','齐己','唐末至五代','久闻为客过苍梧，
休说携家归镜湖。
山水颠狂应尽在，
鬓毛凋落免贫无。
和僧抢入云中峭，
带鹤驱成涧底孤。
春醉醒来有馀兴，
因人乞与武陵图。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_961','寄曹松','齐己','唐末至五代','旧制新题削复刊，
工夫过甚琢琅玕。
药中求见黄芽易，
诗里思闻白雪难。
扣寂颇同心在定，
凿空何止发冲冠。
夜来月苦怀高论，
数树霜边独傍栏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_962','寄梁先辈','齐己','唐末至五代','慈恩塔下曲江边，
别后多应梦到仙。
时去与谁论此事，
乱来何处觅同年？
陈琳笔砚甘前席，
甪里烟霞待共眠。
爱惜麻衣好颜色，
未教朱紫污天然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_963','寄清溪道友','齐己','唐末至五代','山门摇落空，
霜霰满杉松。
明月行禅处，
青苔绕石重。
泉声喧万壑，
钟韵遍千峰。
终去焚香老，
同师大士踪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_964','寄萍乡唐禀正字','齐己','唐末至五代','新书声价满皇都，
高卧林中更起无。
春兴酒香薰肺腑，
夜吟云气湿髭须。
同登水阁僧皆别，
共上渔船鹤亦孤。
长忆前年送行处，
洞门残日照菖蒲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_965','寄黄晖处士','齐己','唐末至五代','蒙氏艺传黄氏子，
独闻相继得名高。
锋铓妙夺金鸡距，
纤利精分玉兔毫。
濡染只应亲赋咏，
风流不称近方刀。
何妨寄我临池兴，
忍使江淹役梦劳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_966','寄敬亭清越','齐己','唐末至五代','敬亭山色古，
庙与寺松连。
住此修行过，
春风四十年。
鼎尝天柱茗，
诗硾剡溪笺。
冥目应思著，
终南北阙前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_967','寄普明大师可准','齐己','唐末至五代','莲岳三徵者，
论诗旧与君。
相留曾几岁，
酬唱有新文。
翠窦容闲憩，
岚峰许共分。
当年若同访，
合得伴吟云。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_968','寄湘中诸友','齐己','唐末至五代','碧云诸友尽黄眸，
石点花飞更说无。
岚翠湿衣松接院，
芙蓉薰面寺临湖。
沃洲高卧心何僻，
匡社长禅兴亦孤。
争似楚王文物国，
金镳紫绶让前途。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_969','寄湘幕王重书记','齐己','唐末至五代','抛掷浟江旧钓矶，
日参筹画废吟诗。
可能有事关心后，
得似无人识面时。
官好近闻加茜服，
药灵曾说换霜髭。
高才直气平生志，
除却徒知即不知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_970','寄谢高先辈见寄二首','齐己','唐末至五代','穿凿堪伤骨，
风骚久痛心。
永言无绝唱，
忽此惠希音。
杨柳江湖晚，
芙蓉岛屿深。
何因会仙手，
临水一披襟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_971','寄谢高先辈见寄二首','齐己','唐末至五代','诗在混茫前，
难搜到极玄。
有时还积思，
度岁未终篇。
片月双松际，
高楼阔水边。
前贤多此得，
风味若为传。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_972','寄道林寺诸友','齐己','唐末至五代','吟兴终依异境长，
旧游时入静思量。
江声里过东西寺，
树影中行上下方。
春色湿僧巾屦腻，
松花沾鹤骨毛香。
老来何计重归去，
千里重湖浪渺茫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_973','寄韩蜕秀才','齐己','唐末至五代','松门高不似侯门，
藓径鞋踪触处分。
远事即为无害鸟，
多闲便是有情云。
那忧宠辱来惊我，
且寄风骚去敌君。
知伴李膺琴酒外，
绛纱闲卷共论文。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_974','寄楚萍上人','齐己','唐末至五代','北面香炉秀，
南边瀑布寒。
自来还独去，
夏满又秋残。
日影松杉乱，
云容洞壑宽。
何峰是邻侧，
片石许相安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_975','寄蜀国广济大师','齐己','唐末至五代','冰压霜坛律格清，
三千传授尽门生。
禅心尽入空无迹，
诗句闲搜寂有声。
满国繁华徒自乐，
两朝更变未曾惊。
终思相约岷峨去，
不得携筇一路行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_976','寄酬秦府高推官辇','齐己','唐末至五代','天台衡岳旧曾寻，
闲忆留题白石林。
岁月已残衰飒鬓，
风骚犹壮寂寥心。
缑山碧树遮藏密，
丹穴红霞掩映深。
争得相逢一携手，
拂衣同去听玄音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_977','寄酬高辇推官','齐己','唐末至五代','道自闲机长，
诗从静境生。
不知春艳尽，
但觉雅风清。
竹腻题幽碧，
蕉乾裂脆声。
何当九霄客，
重叠记无名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_978','寄澧阳吴使君','齐己','唐末至五代','南客西来话使君，
涔阳风雨变行春。
四邻耕钓趋仁政，
千里烟花压路尘。
去兽未胜除狡吏，
还珠争似复逋民。
红兰浦暖携才子，
烂醉连题赋白蘋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_979','寄赠集滩二公','齐己','唐末至五代','闻有难名境，
因君住更名。
轩窗中夜色，
风月绕滩声。
客好过无厌，
禽幽画不成。
终期一寻去，
聊且寄吟情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_980','寄镜湖方干处士','齐己','唐末至五代','贺监旧山川，
空来近百年。
闻君与琴鹤，
终日在渔船。
岛露深秋石，
湖澄半夜天。
云门几回去，
题遍好林泉。',NULL,'[{"Book": "《唐诗归》", "Section": null, "Content": "钟云：合作三事说，便奇（“闻君”句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}, {"Book": "《唐诗矩》", "Section": null, "Content": "全篇直叙格。起法浑峭而响，在晚唐亦不多得。只将贺监抬出，在山川七长价，方处士之人品不言而自见，笔意高人十倍。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗矩》"}, {"Book": "《唐诗别裁》", "Section": null, "Content": "方处上呼之欲出（“闻君”句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗别裁》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_981','崔秀才宿话','齐己','唐末至五代','事转闻多事，
心休话苦心。
相留明月寺，
共忆白云岑。
藓壁残虫韵，
霜轩倒竹阴。
开门又言别，
谁竟慰尘襟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_982','得李推官近寄怀','齐己','唐末至五代','荆门前岁使乎回，
求得星郎近制来。
连日借吟终不已，
一灯忘寝又重开。
秋风漫作牵情赋，
春草真为入梦才。
堪笑陈宫诸狎客，
当时空有个追陪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_983','惊秋','齐己','唐末至五代','褰帘听秋信，
晚傍竹声归。
多故堪伤骨，
孤峰好拂衣。
梧桐凋绿尽，
菡萏堕红稀。
却恐吾形影，
嫌心与口违。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_984','惊秋','齐己','唐末至五代','晓窗惊觉向秋风，
万里心凝淡荡中。
池影碎翻红菡萏，
井声乾落绿梧桐。
破除闲事浑归道，
销耗劳生旋逐空。
妖杀九原狐兔意，
岂知丘陇是英雄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_985','晚夏金江寓居答友生','齐己','唐末至五代','日日冲残热，
相寻入乱蒿。
闲中滋味远，
诗里是非高。
碧耸新生竹，
红垂半熟桃。
时难未可出，
且欲淬豪曹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_986','梓栗杖送人','齐己','唐末至五代','禅家何物赠分襟，
只有天台杖一寻。
拄去客归青洛远，
采来僧入白云深。
游山曾把探龙穴，
出世期将指佛心。
此日江边赠君后，
却携筇杖向东林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_987','欲游龙山鹿苑有作','齐己','唐末至五代','龙山门不远，
鹿苑路非遥。
合逐闲身去，
何须待客招。
年华残两鬓，
筋骨倦长宵。
闻说峰前寺，
新修白石桥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_988','清夜作','齐己','唐末至五代','不惜白日短，
乍容清夜长。
坐闻风露滴，
吟觉骨毛凉。
兴寝无诸病，
空闲有一床。
天明振衣起，
苔砌落花香。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_989','渚宫江亭寓目','齐己','唐末至五代','津亭虽极望，
未称本心闲。
白有三江水，
青无一点山。
新鸿喧夕浦，
远棹聚空湾。
终遂归匡社，
孤帆即此还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_990','渚宫自勉二首','齐己','唐末至五代','晨午殊丰足，
伊何挠肺肠。
形容侵老病，
山水忆韬藏。
必谢金台去，
还携铁锡将。
东林露坛畔，
旧对白莲房。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_991','渚宫自勉二首','齐己','唐末至五代','毕竟拟何求，
随缘去住休。
天涯游胜境，
海上宿仙洲。
梦好寻无迹，
诗成旋不留。
从他笑轻事，
独自忆庄周。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_992','渚宫西城池上居','齐己','唐末至五代','城东移锡住城西，
绿绕春波引杖藜。
翡翠满身衣有异，
鹭鸶通体格非低。
风摇柳眼开烟小，
暖逼兰芽出土齐。
犹有幽深不相似，
剡溪乘棹入耶溪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_993','渚宫春日因怀有作','齐己','唐末至五代','旧业树连湘树远，
家山云与岳云平。
僧来已说无耕钓，
雁去那知有弟兄。
客思莫牵蝴蝶梦，
乡心自忆鹧鸪声。
沙头南望堪肠断，
谁把归舟载我行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_994','渚宫莫问诗一十五首','齐己','唐末至五代','莫问疏人事，
王侯已任伊。
不妨随野性，
还似在山时。
静入无声乐，
狂抛正律诗。
自为仍自爱，
清净里寻思。',NULL,'','{"preface": "予以辛巳岁蒙主人命居龙安寺，察其疏鄙，免以趋奉，爰降手翰，曰盖知心不在常礼也。予不觉欣然而作，顾谓形影曰：尔本青山一衲，白日孤禅。今王侯搆室安之，给俸食之，使之乐然。万事都外，游息自得，则云泉猿鸟，不必为狎，其放纵若是，夫何系乎？自是龙门墙仞，历稔不复瞻觊。况他家哉，因创莫问之题，凡一十五篇，皆以莫问为首焉。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_995','渚宫莫问诗一十五首','齐己','唐末至五代','莫问伊嵇懒，
流年已付他。
话通时事少，
诗着野题多。
梦外春桃李，
心中旧薜萝。
浮生此不悟，
剃发竟如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_996','渚宫莫问诗一十五首','齐己','唐末至五代','莫问休行脚，
南方已遍寻。
了应须自了，
心不是他心。
赤水珠何觅，
寒山偈莫吟。
谁同论此理，
杜口少知音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_997','渚宫莫问诗一十五首','齐己','唐末至五代','莫问孱愚格，
天应只与闲。
合居长树下，
那称众人间。
迹绝为真隐，
机忘是大还。
终当学支遁，
买取个青山。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_998','渚宫莫问诗一十五首','齐己','唐末至五代','莫问无求意，
浮云喻可知。
满盈如不戒，
倚伏更何疑。
乐矣贤颜子，
穷乎圣仲尼。
已过知命岁，
休把运行推。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_999','渚宫莫问诗一十五首','齐己','唐末至五代','莫问闲行趣，
春风野水涯。
千门无谢女，
两岸有杨花。
好鹤曾为客，
真龙或作蛇。
踌蹰自回首，
日脚背楼斜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1000','渚宫莫问诗一十五首','齐己','唐末至五代','莫问真消息，
中心只自知。
清风含笑咏，
明月混希夷。
坏衲凉天拥，
玄文静夜披。
善哉温伯子，
言望至公知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1001','渚宫莫问诗一十五首','齐己','唐末至五代','莫问休持钵，
从贫乞已疏。
侯门叨月俸，
斋食剩年储。
簪履三千外，
形骸六十馀。
旧峰呵练若，
松径接匡庐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1002','渚宫莫问诗一十五首','齐己','唐末至五代','莫问依刘迹，
金台又度秋。
威仪非上客，
谭笑愧诸侯。
礼许无拘检，
诗推异辈流。
东林未归得，
摇落楚江头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1003','渚宫莫问诗一十五首','齐己','唐末至五代','莫问无机性，
甘名百钝人。
一床铺冷落，
长日卧精神。
分已疏知旧，
诗还得意新。
多才碧云客，
时或此相亲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1004','渚宫莫问诗一十五首','齐己','唐末至五代','莫问关门意，
从来寡往还。
道应归淡泊，
身合在空闲。
四面苔围绿，
孤窗雨洒斑。
梦寻何处去，
秋色水边山。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1005','渚宫莫问诗一十五首','齐己','唐末至五代','莫问休贪恋，
浮云逐性情。
人间高此道，
禅外剩他名。
夏雨松边坐，
秋光水畔行。
更无时忌讳，
容易得题成。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1006','渚宫莫问诗一十五首','齐己','唐末至五代','莫问多山兴，
晴楼独凭时。
六年沧海寺，
一别白莲池。
句早逢名匠，
禅曾见祖师。
冥搜与真性，
清外认扬眉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1007','渚宫莫问诗一十五首','齐己','唐末至五代','莫问衰残质，
流光速可悲。
寸心修未了，
长命欲何为。
坐卧身多倦，
经行骨渐疲。
分明说此苦，
珍重竺乾师。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1008','渚宫莫问诗一十五首','齐己','唐末至五代','莫问野腾腾，
劳形已不能。
慇勤无上士，
珍重有名僧。
坐觉心心默，
行思步步冰。
终归石房里，
一点夜深灯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1009','渚宫谢杨秀才自嵩山相访','齐己','唐末至五代','嵩峰有客远相寻，
尘满麻衣袖苦吟。
花尽草长方闭户，
道孤身老正伤心。
红堆落日云千仞，
碧撼凉风竹一林。
惆怅雅声消歇去，
喜君聊此暂披襟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1010','移竹','齐己','唐末至五代','旧溪千万竿，
风雨夜珊珊。
白首来江国，
黄金买岁寒。
乍移伤粉节，
终绕著朱栏。
会得承春力，
新抽锦箨看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1011','移居','齐己','唐末至五代','上台言任养疏愚，
乞与西城水满湖。
吹榻好风终日有，
趁凉闲客片时无。
檀栾翠拥清蝉在，
菡萏红残白鸟孤。
欲问存思搜抉妙，
几联诗许敌三都。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1012','移居西湖作二首','齐己','唐末至五代','火云阳焰欲烧空，
小槛幽窗想旧峰。
白汗此时流枕簟，
清风何处动杉松。
残更正好眠凉月，
远寺俄闻报晓钟。
只待秋声涤心地，
衲衣新洗健形容。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1013','移居西湖作二首','齐己','唐末至五代','官园树影昼阴阴，
咫尺清凉莫浣心。
桃李别教人主掌，
烟花不称我追寻。
蜩螗晚噪风枝稳，
翡翠闲眠宿处深。
争似出尘地行止，
东林苔径入西林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1014','竟陵遇昼公','齐己','唐末至五代','高迹何来此，
游方渐老身。
欲投莲岳夏，
初过竟陵春。
锡影离云远，
衣痕拂藓新。
无言即相别，
此处不迷津。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1015','船窗','齐己','唐末至五代','孤舸凭幽窗，
清波逼面凉。
举头还有碍，
低眼即无妨。
瞥过沙禽翠，
斜分夕照光。
何时到山寺，
上阁看江乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1016','萤','齐己','唐末至五代','透窗穿竹住还移，
万类俱闲始见伊。
难把寸光藏暗室，
自持孤影助明时。
空庭散逐金风起，
乱叶争投玉露垂。
后代儒生懒收拾，
夜深飞过读书帷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1017','野步','齐己','唐末至五代','城里无闲处，
却寻城外行。
田园经雨水，
乡国忆桑耕。
傍涧蕨薇老，
隔村冈陇横。
何穷此心兴，
时复鹧鸪声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1018','野鸭','齐己','唐末至五代','野鸭殊家鸭，
离群忽远飞。
长生缘甚瘦，
近死为伤肥。
江海游空阔，
池塘啄细微。
红兰白蘋渚，
春暖刷毛衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1019','喜表公往楚王城','齐己','唐末至五代','已闻人舍地，
结构旧基平。
一面湖光白，
邻家竹影清。
应难寻辇道，
空说是王城。
谁信兴亡迹，
今来有磬声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1020','喜夏雨','齐己','唐末至五代','四郊云影合，
千里雨声来。
尽洗红埃去，
并将清气回。
潺湲浮楚甸，
萧散露荆台。
欲赋随车瑞，
濡毫渴謏才。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1021','喜乾昼上人远相访','齐己','唐末至五代','彼此垂七十，
相逢意若何。
圣明殊未至，
离乱更应多。
澹泊门难到，
从容日易过。
馀生消息外，
只合听诗魔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1022','喜彬上人见访','齐己','唐末至五代','高吟欲继沃州师，
千里相寻问课虚。
残腊江山行尽处，
满衣风雪到闲居。
携来律韵清何甚，
趣入幽微旨不疏。
莫惜天机细搥琢，
他时终可拟芙蕖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1023','喜得自牧上人书','齐己','唐末至五代','吴都使者泛惊涛，
灵一传书慰毳袍。
别兴偶随云水远，
知音本自国风高。
身依闲淡中销日，
发向清凉处落刀。
闻著括囊新集了，
拟教谁与序离骚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1024','喜𧦬公自武陵至','齐己','唐末至五代','已尽沧浪兴，
还思相楚行。
鬓全无旧黑，
诗别有新清。
暂憩临寒水，
时来扣静荆。
囊中有灵药，
终不献公卿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1025','喻吟','齐己','唐末至五代','日用是何专，
吟疲即坐禅。
此生还可喜，
馀事不相便。
头白无邪里，
魂清有象先。
江花与芳草，
莫染我情田。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1026','寒节日寄乡友','齐己','唐末至五代','岁岁逢寒食，
寥寥古寺家。
踏青思故里，
垂白看杨花。
原野稀疏雨，
江天冷澹霞。
沧浪与湘水，
归恨共无涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1027','寒食日怀寄友人','齐己','唐末至五代','万井追寒食，
闲扉独不开。
梨花应折尽，
柳絮自飞来。
梦觉怀仙岛，
吟行绕砌苔。
浮生已悟了，
时节任相催。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1028','寓言','齐己','唐末至五代','造化安能保，
山川凿欲翻。
精华销地底，
珠玉聚侯门。
始作骄奢本，
终为祸乱根。
亡家与亡国，
云此更何言。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1029','寓居岳麓谢进士沈彬再访','齐己','唐末至五代','去岁来寻我，
留题在藓痕。
又因风雪夜，
重宿古松门。
玉有疑休泣，
诗无主且言。
明朝此相送，
披褐入桃源。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1030','期友人','齐己','唐末至五代','早晚逐兹来，
闲门日为开。
乱蛩鸣白草，
残菊藉苍苔。
困卧谁惊起，
闲行自欲回。
何时此携手，
吾子本多才。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1031','游三觉山','齐己','唐末至五代','白石路重重，
萦纡势忽穷。
孤峰擎像阁，
万木蔽星空。
世论随时变，
禅怀历劫同。
良宵正冥目，
海日上窗红。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1032','游谷山寺','齐己','唐末至五代','城里寻常见碧棱，
水边朝暮送归僧。
数峰云脚垂平地，
一径松声彻上层。
寒涧不生浮世物，
阴崖犹积去年冰。
此身有底难抛事，
时复携筇信步登。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1033','游道林寺四绝亭观宋杜诗版','齐己','唐末至五代','宋杜诗题在，
风骚到此真。
独来终日看，
一为拂秋尘。
古石生寒仞，
春松脱老鳞。
高僧眼根静，
应见客吟神。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1034','游橘洲','齐己','唐末至五代','春日上芳洲，
经春兰杜幽。
此时寻橘岸，
昨日在城楼。
鹭立青枫杪，
沙沈白浪头。
渔家好生计，
檐底系扁舟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1035','湖上逸人','齐己','唐末至五代','澹荡光中翡翠飞，
田田初出柳丝丝。
吟沿绿岛时逢鹤，
醉泛清波或见龟。
七泽钓师应识我，
中原逐鹿不知谁。
秋风水寺僧相近，
一径芦花到竹篱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1036','湖西逸人','齐己','唐末至五代','老隐洞庭西，
渔樵共一溪。
琴前孤鹤影，
石上远僧题。
橘柚园林熟，
蒹葭径路迷。
君能许邻并，
分药斸春畦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1037','湘中春兴','齐己','唐末至五代','雨歇江明苑树乾，
物妍时泰恣游盘。
更无轻翠胜杨柳，
尽觉浓华在牡丹。
终日去还抛寂寞，
绕池回却凭栏干。
红芳片片由青帝，
忍向西园看落残。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1038','湘中送翁员外归闽','齐己','唐末至五代','船满琴书与酒杯，
清湘影里片帆开。
人归南国乡园去，
雁逐西风日夜来。
天势渐低分海树，
山程欲尽见城台。
此身未别江边寺，
犹看星郎奉诏回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1039','湘中寓居春日感怀','齐己','唐末至五代','江禽野兽两堪伤，
避射惊弹各自忙。
头角任多无獬豸，
羽毛虽众让鸳鸯。
落苔红小樱桃熟，
侵井青纤燕麦长。
吟把离骚忆前事，
汨罗春浪撼残阳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1040','湘中感怀','齐己','唐末至五代','渔翁那会我，
傲兀苇边行。
乱世难逸迹，
乘流拟濯缨。
江花红细碎，
沙鸟白分明。
向夕题诗处，
春风斑竹声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1041','湘江送客','齐己','唐末至五代','湘江秋色湛如冰，
楚客离怀暮不胜。
千里碧云闻塞雁，
几程青草见巴陵。
寒涛响叠晨征橹，
岸苇丛明夜泊灯。
鹦鹉洲边若回首，
为思前事一扪膺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1042','湘江渔父','齐己','唐末至五代','湘潭春水满，
岸远草青青。
有客钓烟月，
无人论醉醒。
门前蛟蜃气，
蓑上蕙兰馨。
曾受蒙庄子，
逍遥一卷经。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1043','湘西道林寺陶太尉井','齐己','唐末至五代','太尉遗孤井，
寒澄七百年。
未闻陵谷变，
终与姓名传。
影浸无风树，
光含有月天。
林僧晓来此，
满汲洒金田。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1044','登大林寺观白太傅题版','齐己','唐末至五代','九叠苍崖里，
禅家凿翠开。
清时谁梦到，
白傅独寻来。
怪石和僧定，
闲云共鹤回。
任兹休去者，
心是不然灰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1045','登金山寺','齐己','唐末至五代','四面白波声，
中流翠峤横。
望来堪目断，
上彻始心平。
鸟向天涯去，
云连水国生。
重来与谁约，
题罢自吟行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1046','登祝融峰','齐己','唐末至五代','猿鸟共不到，
我来身欲浮。
四边空碧落，
绝顶正清秋。
宇宙知何极，
华夷见细流。
坛西独立久，
白日转神州。',NULL,'[{"Book": "《唐诗评选》", "Section": null, "Content": "近情语自远。南岳诸作，此空其群。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗评选》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1047','答禅者','齐己','唐末至五代','五老峰前相遇时，
两无言语只扬眉。
南宗北祖皆如此，
天上人间更问谁。
山衲静披云片片，
铁刀凉削鬓丝丝。
闲吟莫学汤从事，
抛却袈裟负本师。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1048','答献上人卷','齐己','唐末至五代','衲衣禅客袖篇章，
江上相寻共感伤。
秦甸乱来栖白没，
杼山空后皎然亡。
清留岛月秋凝露，
苦寄巴猿夜叫霜。
珍重南宗好才子，
灰心冥目外无妨。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1049','落日','齐己','唐末至五代','晚照背高台，
残钟残角催。
能销几度落，
已是半生来。
吹叶阴风发，
漫空暝色回。
因思古人事，
更变尽尘埃。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1050','落叶','齐己','唐末至五代','落多秋亦晚，
窗外见诸邻。
世上谁惊尽，
林间独扫频。
萧骚微月夜，
重叠早霜晨。
昨日繁阴在，
莺声树树春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1051','落花','齐己','唐末至五代','朝开暮亦衰，
雨打复风吹。
古屋无人处，
残阳满地时。
静依青藓片，
闲缀绿莎枝。
繁艳根枝在，
明年向此期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1052','谢丁秀才见示赋卷','齐己','唐末至五代','五首新裁剪，
搜罗尽指归。
谁曾师古律，
君自负天机。
圣后求贤久，
明公得隽稀。
乘秋好携去，
直望九霄飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1053','谢人自钟陵寄纸笔','齐己','唐末至五代','故人犹忆苦吟劳，
所惠何殊金错刀。
霜雪剪栽新剡硾，
锋铓管束本宣毫。
知君倒箧情何厚，
借我临池价斗高。
词客分张看欲尽，
不堪来处隔秋涛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1054','谢人寄南榴卓子','齐己','唐末至五代','幸附全材长，
良工斸器殊。
千林文柏有，
一尺锦榴无。
品格宜仙果，
精光称玉壶。
怜君远相寄，
多愧野蔬粗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1055','谢人寄新诗集','齐己','唐末至五代','所闻新事即戈矛，
欲去终疑是暗投。
远客寄言还有在，
此门将谓总无休。
千篇著述诚难得，
一字知音不易求。
时入思量向何处，
月圆孤凭水边楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1056','谢人惠十才子图','齐己','唐末至五代','丹青妙写十才人，
玉峭冰棱姑射神。
醉舞离披真鸑鷟，
狂吟崩倒瑞麒麟。
翻腾造化山曾竭，
采掇珠玑海几贫。
犹得知音与图画，
草堂闲挂似相亲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1057','谢人惠丹药','齐己','唐末至五代','别后闻餐饵，
相逢讶道情。
肌肤红色透，
髭发黑光生。
仙洞谁传与，
松房自鍊成。
常蒙远分惠，
亦觉骨毛轻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1058','谢人惠竹蝇拂','齐己','唐末至五代','妙刮筠篁制，
纤柔玉柄同。
拂蝇声满室，
指月影摇空。
敢舍经行外，
常将宴坐中。
挥谈一无取，
千万愧生公。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1059','谢人惠拄杖','齐己','唐末至五代','邛州灵境产修篁，
九节材应表九阳。
造化已能分尺度，
保持争合与寻常。
幽林剪破清秋影，
高手携来绿玉光。
深谢鲁儒怜潦倒，
欲教撑拄绕禅床。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1060','谢人惠药','齐己','唐末至五代','五金元造化，
九鍊更精新。
敢谓长生客，
将遗必死人。
久餐应换骨，
一服已通神。
终逐淮王去，
永抛浮世尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1061','谢人惠扇子及茶','齐己','唐末至五代','鎗旗封蜀茗，
圆洁制鲛绡。
好客分烹煮，
青蝇避动摇。
陆生誇妙法，
班女恨凉飙。
多谢崔居士，
相思寄寂寥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1062','谢人惠紫栗拄杖','齐己','唐末至五代','仙掌峰前得，
何当此见遗。
百年衰朽骨，
六尺岁寒姿。
雪外兼松凭，
泉边待月欹。
他时出山去，
犹谢见相随。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1063','谢人惠端溪砚','齐己','唐末至五代','端人凿断碧溪浔，
善价争教惜万金。
砻琢已曾经敏手，
研磨终见透坚心。
安排得主难移动，
含贮随时任浅深。
保重更求装钿匣，
闲将濡染寄知音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1064','谢人墨','齐己','唐末至五代','珍重岁寒烟，
携来路几千。
只应真典诰，
消得苦磨研。
正色浮端砚，
精光动蜀笺。
因君强濡染，
舍此即忘筌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1065','谢中上人寄茶','齐己','唐末至五代','春山谷雨前，
并手摘芳烟。
绿嫩难盈笼，
清和易晚天。
且招邻院客，
试煮落花泉。
地远劳相寄，
无来又隔年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1066','谢元愿上人远寄檀溪集','齐己','唐末至五代','白首萧条居汉浦，
清吟编集号檀溪。
有人收拾应如玉，
无主知音只似泥。
入理半同黄叶句，
遣怀多拟碧云题。
犹能为我相思在，
千里封来梦泽西。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1067','谢王先辈昆弟游湘中回各见示新诗','齐己','唐末至五代','潇湘多胜异，
宗社久裴回。
兄弟同游去，
幽奇尽采来。
只应求妙唱，
何以示寒灰。
上国携归后，
唯呈不世才。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1068','谢王先辈寄毡','齐己','唐末至五代','深谢高科客，
名毡寄惠重。
静思生朔漠，
和雪长蒙茸。
摺坐资禅悦，
铺眠减病容。
他年从破碎，
担去卧孤峰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1069','谢王先辈湘中回惠示卷轴','齐己','唐末至五代','少小即怀风雅情，
独能遗象琢淳精。
不教霜雪侵玄鬓，
便向云霄换好名。
携去湘江闻鼓瑟，
袖来缑岭伴吹笙。
多君百首贻衰飒，
留把吟行访竺卿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1070','谢王秀才见示诗卷','齐己','唐末至五代','谁见少年心，
低摧向苦吟。
后须离影响，
得必洞精深。
道院春苔径，
僧楼夏竹林。
天如爱才子，
何虑未知音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1071','谢王拾遗见访兼寄篇什','齐己','唐末至五代','竹里安禅处，
生涯一印灰。
经年乞食过，
昨日谏臣来。
愧把黄梅偈，
曾酬白雪才。
因令识鸟迹，
重叠在苍苔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1072','谢王詹事垂访','齐己','唐末至五代','鸟外孤峰未得归，
人间触类是无机。
方悲鹿轸栖江寺，
忽讶轺车降竹扉。
王泽乍闻谭涣汗，
国风那得话玄微。
应惊老病炎天里，
枯骨肩横一衲衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1073','谢主人石笋','齐己','唐末至五代','西园罢宴游，
东阁念林丘。
特减花边峭，
来添竹里幽。
忆过阳朔见，
曾记大湖求。
从此频吟绕，
归山意亦休。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1074','谢兴公上人寄山水簇子','齐己','唐末至五代','半幅古潺颜，
看来心意闲。
何须寻鸟道，
即此出人间。
巘暮疑啼狖，
松深认掩关。
知君远相惠，
免我忆归山。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1075','谢孙郎中寄示','齐己','唐末至五代','一念禅馀味国风，
早因持论偶名公。
久伤琴丧人亡后，
忽有云和雪唱同。
绳琢静闻罤象外，
是非闲见寂寥中。
时来日往缘真趣，
不觉秋江度塞鸿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1076','谢西川可准上人远寄诗集','齐己','唐末至五代','匡社经行外，
沃洲禅宴馀。
吾师还继此，
后辈复何如。
江上传风雅，
静中时卷舒。
堪随乐天集，
共伴白芙蕖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1077','谢武陵徐巡官远寄五七字诗集','齐己','唐末至五代','五字才将七字争，
为君聊敢试悬衡。
鼎湖菡萏摇金影，
蓬岛鸾皇舞翠声。
还是灵龟巢得稳，
要须仙子驾方行。
两边珍重遥相惠，
何夕灯前尽此情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1078','谢贯微上人寄示古风今体四轴','齐己','唐末至五代','四轴骚词书八行，
捧吟肌骨遍清凉。
谩求龙树能医眼，
休问图澄学洗肠。
今体尽搜初剖判，
古风淳凿未玄黄。
不知谁肯降文阵，
闇点旌旗敌子房。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1079','谢南平王赐山鸡','齐己','唐末至五代','五色文章类彩鸾，
楚人罗得半摧残。
金笼莫恨伤冠帻，
玉粒颁惭剪羽翰。
孤立影危丹槛里，
双栖伴在白云端。
上台爱育通幽细，
却放溪山去不难。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1080','谢炭','齐己','唐末至五代','正拥寒灰次，
何当惠寂寥。
且留连夜向，
未敢满炉烧。
必恐吞难尽，
唯愁拨易消。
豪家捏为兽，
红迸锦茵焦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1081','谢重缘旧山水障子','齐己','唐末至五代','敢望重缘饰，
微茫洞壑春。
坐看终未是，
归卧始应真。
已觉心中朽，
犹怜四面新。
不因公子鉴，
零落几成尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1082','谢秦府推官寄丹台集','齐己','唐末至五代','秦王手笔序丹台，
不错褒扬最上才。
凤阙几传为匠硕，
龙门曾用振风雷。
钱郎未竭精华去，
元白终存作者来。
两轴蚌胎骊颔耀，
枉临禅室伴寒灰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1083','谢高辇先辈寄新唱和集','齐己','唐末至五代','敢谓神仙手，
多怀老比丘。
编联来鹿野，
酬唱在龙楼。
洛浦精灵慑，
邙山鬼魅愁。
二南风雅道，
从此化东周。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1084','谢虚中上人寄示题天策阁诗','齐己','唐末至五代','天策二首作，
境幽搜亦玄。
阁横三楚上，
题挂九霄边。
寺额因标胜，
诗人合遇贤。
他时谁倚槛，
吟此岂忘筌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1085','谢虚中上人晚秋见寄','齐己','唐末至五代','楚外同文在，
荆门得信时。
几重相别意，
一首晚秋诗。
日暮山沈雨，
莲残水满池。
登楼试南望，
为子动归思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1086','谢虚中寄新诗','齐己','唐末至五代','旧友一千里，
新诗五十篇。
此文经大匠，
不见已多年。
趣极同无迹，
精深合自然。
相思把行坐，
南望隔尘烟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1087','谢道友拄杖','齐己','唐末至五代','剪自南岩瀑布边，
寒光七尺乳珠连。
持来未入尘埃路，
乞与应怜老病年。
欹影夜归青石涧，
卓痕秋过绿苔钱。
他时携上嵩峰顶，
把倚长松看洛川。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1088','谢橘洲人寄橘','齐己','唐末至五代','洞庭栽种似潇湘，
绿绕人家带夕阳。
霜裛露蒸千树熟，
浪围风撼一洲香。
洪崖遣后名何远，
陆绩怀来事更长。
藏贮待供宾客好，
石榴宜称映舟光。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1089','谢灉湖茶','齐己','唐末至五代','灉湖唯上贡，
何以惠寻常。
还是诗心苦，
堪消蜡面香。
碾声通一室，
烹色带残阳。
若有新春者，
西来信勿忘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1090','遇元上人','齐己','唐末至五代','七泽过名山，
相逢黄落残。
杉松开寺晚，
泉月话心寒。
祖遍诸方礼，
经曾几处看。
应怀出家院，
紫阁近长安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1091','道林寺居寄岳麓禅师二首','齐己','唐末至五代','门前石路彻中峰，
树影泉声在半空。
寻去未应劳上下，
往来殊已倦西东。
髭根尽白孤云并，
心迹全忘片月同。
长忆高窗夏天里，
古松青桧午时风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1092','道林寺居寄岳麓禅师二首','齐己','唐末至五代','山袍不称下红尘，
各是闲居岛外身。
两处烟霞门寂寂，
一般苔藓石磷磷。
禅关悟后宁疑物，
诗格玄来不傍人。
月照经行更谁见，
露华松粉点衣巾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1093','道林寓居','齐己','唐末至五代','秋泉一片树千株，
暮汲寒烧外有馀。
青嶂这边来已熟，
红尘那畔去应疏。
风骚未肯忘雕琢，
潇洒无妨更剃除。
即问沃州开士僻，
爱禽怜骏意何如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1094','塘上闲作','齐己','唐末至五代','闲行闲坐藉莎烟，
此兴堪思二古贤。
陶靖节居彭泽畔，
贺知章在镜池边。
鸳鸯著对能飞绣，
菡萏成群不语仙。
形影腾腾夕阳里，
数峰危翠滴渔船。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1095','感时','齐己','唐末至五代','忽忽枕前蝴蝶梦，
悠悠觉后利名尘。
无穷今日明朝事，
有限生来死去人。
终与狐狸为窟穴，
谩师龟鹤养精神。
可怜颜子能消息，
虚室坐忘心最真。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1096','新秋','齐己','唐末至五代','始惊三伏尽，
又遇立秋时。
露彩朝还冷，
云峰晚更奇。
垄香禾半熟，
原迥草微衰。
幸好清光里，
安仁谩起悲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1097','新秋雨后','齐己','唐末至五代','夜雨洗河汉，
诗怀觉有灵。
篱声新蟋蟀，
草影老蜻蜓。
静引闲机发，
凉吹远思醒。
逍遥向谁说，
时注漆园经。',NULL,'[{"Book": "《瀛奎律髓》", "Section": null, "Content": "此诗起句自然，第六句尤好。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓》"}, {"Book": "《瀛奎律髓汇评》", "Section": null, "Content": "纪昀：三四新脆，“觉有灵”三字不佳。许印芳：此诗次句即老杜“诗成觉有神”意，语虽不依，却无疵颣。三四佳在“新”宇”、“老”字”、若用“闻”、“见”等字，便是小儿语。五六亦颇细致，六句暗藏“风”字，措语亦较五句有味，故虚谷以为尤好。尾联……上句太空，下句太滞，故为易之：“逍遥吾向得，不假漆园经。”", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓汇评》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1098','新秋病中枕上闻蝉','齐己','唐末至五代','枕上稍醒醒，
忽闻蝉一声。
此时知不死，
昨日即前生。
更欲临窗听，
犹难策杖行。
寻应同蜕壳，
重饮露华清。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1099','新秋霁后晚眺怀先公','齐己','唐末至五代','雨霁湘楚晚，
水凉天亦澄。
山中应解夏，
渡口有行僧。
鸟列沧洲队，
云排碧落层。
孤峰磬声绝，
一点石龛灯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1100','新栽松','齐己','唐末至五代','野僧教种法，
苒苒出蓬蒿。
百岁催人老，
千年待尔高。
静宜兼竹石，
幽合近猿猱。
他日成阴后，
秋风吹海涛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1101','新笋','齐己','唐末至五代','乱迸苔钱破，
参差出小栏。
层层离锦箨，
节节露琅玕。
直上心终劲，
四垂烟渐宽。
欲知含古律，
试剪凤箫看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1102','新燕','齐己','唐末至五代','燕燕知何事，
年年应候来。
却缘华屋在，
长得好时催。
花外衔泥去，
空中接食回。
不同黄雀意，
迷逐网罗媒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1103','新燕','齐己','唐末至五代','栖托近佳人，
应怜巧语新。
风光华屋暖，
弦管牡丹晨。
远采江泥腻，
双飞麦雨匀。
差池自有便，
敢触杏梁尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1104','楚寺寒夜作','齐己','唐末至五代','寒炉局促坐成劳，
暗淡灯光照二毛。
水寺闲来僧寂寂，
雪风吹去雁嗷嗷。
江山积叠归程远，
魂梦穿沿过处高。
毕竟忘言是吾道，
袈裟不称揖萧曹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1105','溪居寓言','齐己','唐末至五代','秋蔬数垄傍潺湲，
颇觉生涯异俗缘。
诗兴难穷花草外，
野情何限水云边。
虫声绕屋无人语，
月影当松有鹤眠。
寄向东溪老樵道，
莫催丹桂博青钱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1106','溪斋二首','齐己','唐末至五代','岂敢言招隐，
归休喜自安。
一溪云卧稳，
四海路行难。
瑞兽藏头角，
幽禽惜羽翰。
子猷何处在，
老尽碧琅玕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1107','溪斋二首','齐己','唐末至五代','杉竹映溪关，
修修共岁寒。
幽人眠日晏，
花雨落春残。
道妙言何强，
诗玄论甚难。
闲居有亲赋，
搔首忆潘安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1108','詶王秀才','齐己','唐末至五代','离乱几时休，
儒生厄远游。
亡家非汉代，
何处觅荆州？
旅梦寒灯屋，
乡怀昼雨楼。
相逢话相杀，
谁复念风流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1109','遣怀','齐己','唐末至五代','病肠休洗老休医，
七十能饶百岁期。
不死任还蓬岛客，
无生自有雪山师。
浮云聚散俱关虑，
明月相逢好展眉。
既兆未萌闲酌度，
不如中抱是寻思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1110','遣怀','齐己','唐末至五代','诗病相兼老病深，
世医徒更费千金。
馀生岂必虚抛掷，
未死何妨乐咏吟。
流水不回休叹息，
白云无迹莫追寻。
闲身自有闲消处，
黄叶清风蝉一林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1111','酬九经者','齐己','唐末至五代','九经三史学，
穷妙又穷微。
长白山初出，
青云路欲飞。
江僧酬雪句，
沙鹤识麻衣。
家在黄河北，
南来偶未归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1112','酬元员外','齐己','唐末至五代','清洛碧嵩根，
寒流白照门。
园林经难别，
桃李几株存。
衰老江南日，
凄凉海上村。
闲来晒朱绂，
泪滴旧朝恩。',NULL,'[{"Book": "《唐诗归》", "Section": null, "Content": "钟云：极悲、极厚（末二句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}, {"Book": "《唐诗矩》", "Section": null, "Content": "尾联见意格。嵩洛大山水，写得如此轻细，另是一种笔法。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗矩》"}, {"Book": "《唐诗选脉会通评林》", "Section": null, "Content": "周敬曰：起似岑嘉州。起联即元所居言，所谓“海上村”也。园林既经离乱后，物类伤残，交游凋谢，自多衰老凄凉之感。重得闲晒朱绂，宁忘国恩之渥乎？泫然泪滴，所必至也。悲调怆情，为元员外写衷，亦曲以尽矣。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选脉会通评林》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1113','酬元员外见寄','齐己','唐末至五代','僻巷谁相访，
风篱翠蔓牵。
易中通性命，
贫里过流年。
且有吟情挠，
都无俗事煎。
时闻得新意，
多是此忘缘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1114','酬王秀才','齐己','唐末至五代','相于分倍亲，
静论到吟真。
王泽曾无外，
风骚甚少人。
鸿随秋过尽，
雪向腊飞频。
何处多幽胜，
期君作近邻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1115','酬孙鲂','齐己','唐末至五代','幽人还爱云，
才子已从军。
可信鸳鸿侣，
更思麋鹿群。
新题虽有寄，
旧论竟难闻。
知己今如此，
编联悉欲焚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1116','酬西川楚峦上人卷','齐己','唐末至五代','玉垒峨嵋秀，
岷江锦水清。
古人搜不尽，
吾子得何精。
可信由前习，
堪闻正后生。
东西五千里，
多谢寄无成。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1117','酬西蜀广济大师见寄','齐己','唐末至五代','犹得吾师继颂声，
百篇相爱寄南荆。
卷开锦水霞光烂，
吟入峨嵋雪气清。
楚外已甘推绝唱，
蜀中谁敢共悬衡。
应怜无可同无本，
终向风骚作弟兄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1118','酬庐山张处士','齐己','唐末至五代','发枯身老任浮沉，
懒泥秋风更役吟。
新事向人堪结舌，
旧诗开卷但伤心。
苔床卧忆泉声绕，
麻履行思树影深。
终谢柴桑与彭泽，
醉游闲访入东林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1119','酬尚颜','齐己','唐末至五代','取尽风骚妙，
名高身倍闲。
久离王者阙，
欲向祖师山。
幕府秋招去，
溪邻日望还。
伊余岂酬敌，
来往踏苔斑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1120','酬尚颜上人','齐己','唐末至五代','紫绶苍髭百岁侵，
绿苔芳草绕阶深。
不妨好鸟喧高卧，
切忌闲人聒正吟。
鲁鼎寂寥休辨口，
劫灰销变莫宣心。
还怜我有冥搜癖，
时把新诗过竹寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1121','酬洞庭陈秀才','齐己','唐末至五代','何必要识面，
见诗惊苦心。
此门从自古，
难学至如今。
青草湖云阔，
黄陵庙木深。
精搜当好景，
得即动知音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1122','酬荅退上人','齐己','唐末至五代','须鬓三分白二分，
一生踪迹出人群。
嵩丘梦忆诸峰雪，
衡岳禅依五寺云。
青衲几临高瀑濯，
苦吟曾许断猿闻。
荒村残腊相逢夜，
月满鸿多楚水濆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1123','酬章水知己','齐己','唐末至五代','新吟忽有寄，
千里到荆门。
落日云初碧，
残年眼正昏。
已为难敌手，
谁更入深论。
后信多相寄，
吾生重此言。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1124','酬湘幕徐员外见寄','齐己','唐末至五代','东海儒宗事业全，
冰棱孤峭类神仙。
诗同李贺精通鬼，
文拟刘轲妙入禅。
珠履早曾从相府，
玳簪今又别官筵。
篇章几谢传西楚，
空想雄风度十年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1125','酬微上人','齐己','唐末至五代','古律皆深妙，
新吟复造微。
搜难穷月窟，
琢苦尽天机。
晚桧清蝉咽，
寒江白鸟飞。
他年旧山去，
为子远携归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1126','酬蜀国欧阳学士','齐己','唐末至五代','因缘刘表驻经行，
又听西风堕叶声。
鹤发不堪言此世，
峨嵋空约在他生。
已从禅祖参真性，
敢向诗家认好名。
深愧故人怜潦倒，
每传仙语下南荆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1127','雉','齐己','唐末至五代','角角类关关，
春晴锦羽乾。
文呈五色异，
瑞入九苞难。
暮宿红兰暖，
朝飞绿野寒。
山梁从行者，
错解仲尼叹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1128','暮冬送璘上人归华容','齐己','唐末至五代','故园虽不远，
那免怆行思。
莽苍平湖路，
霏微过雪时。
全无山阻隔，
或有客相随。
得见交亲后，
春风动柳丝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1129','暮春久雨作','齐己','唐末至五代','积雨向春阴，
冥冥独院深。
已无花落地，
空有竹藏禽。
檐溜声何暴，
邻僧影亦沈。
谁知力耕者，
桑麦最关心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1130','暮游岳麓寺','齐己','唐末至五代','寺楼高出碧崖棱，
城里谁知在上层。
初雪洒来乔木暝，
远禽飞过大江澄。
闲消不睡怜长夜，
静照无言谢一灯。
回首何边是空地，
四村桑麦遍丘陵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1131','潇湘','齐己','唐末至五代','寒清健碧远相含，
珠媚根源在极南。
流古遰今空作岛，
逗山冲壁自为潭。
迁来贾谊愁无限，
谪过灵均恨不堪。
毕竟输他老渔叟，
绿蓑青竹钓浓蓝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1132','蔷薇','齐己','唐末至五代','根本似玫瑰，
繁英刺外开。
香高丛有架，
红落地多苔。
去住闲人看，
晴明远蝶来。
牡丹先几日，
销歇向尘埃。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1133','静坐','齐己','唐末至五代','日日只腾腾，
心机何以兴。
诗魔苦不利，
禅寂颇相应。
砚满尘埃点，
衣多坐卧棱。
如斯自消息，
合是个闲僧。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1134','静坐','齐己','唐末至五代','绳床欹坐任崩颓，
双眼醒醒闭复开。
日月更无闲里过，
风骚时有静中来。
天真自得生难舍，
世幻谁惊死不回。
何处堪投此踪迹，
水边晴去上高台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1135','静坐','齐己','唐末至五代','坐卧与行住，
入禅还出吟。
也应长日月，
消得个身心。
默论相如少，
黄梅付嘱深。
门前古松径，
时起步清阴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1136','静院','齐己','唐末至五代','花院相重点破苔，
谁心肯此话心灰。
好风时傍疏篁起，
幽鸟晚从何处来？
笔砚兴狂师沈谢，
香灯魂断忆宗雷。
浮生已问空王了，
箭急光阴一任催。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1137','韶阳微公','齐己','唐末至五代','曲江晴影石千株，
吾子思归梦断初。
有信北来山叠叠，
无言南去雨疏疏。
祖师门接园林路，
丞相家同井邑居。
闲野老身留得否，
相招多是秀才书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1138','题中上人院','齐己','唐末至五代','高房占境幽，
讲退即冥搜。
欠鹤同支遁，
多诗似惠休。
瓶澄孤井浪，
案白小窗秋。
莫道归山字，
朝贤日献酬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1139','题无余处士书斋','齐己','唐末至五代','闲地从莎藓，
谁人爱此心。
琴棋怀客远，
风雪闭门深。
枕外江滩响，
窗西树石阴。
他年衡岳寺，
为我一相寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1140','题东林十八贤真堂','齐己','唐末至五代','白藕花前旧影堂，
刘雷风骨画龙章。
共轻天子诸侯贵，
同爱吾师一法长。
陶令醉多招不得，
谢公心乱入无方。
何人到此思高躅，
岚点苔痕满粉墙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1141','题东林白莲','齐己','唐末至五代','大士生兜率，
空池满白莲。
秋风明月下，
斋日影堂前。
色后群芳拆，
香殊百和燃。
谁知不染性，
一片好心田。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1142','题玉泉寺','齐己','唐末至五代','高韵双悬张曲江，
联题兼是孟襄阳。
后人才地谁称短，
前辈经天尽负长。
胜景饱于闲采拾，
灵踪销得正思量。
时移两板成尘迹，
犹挂吾师旧影堂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1143','题玉泉寺大师影堂','齐己','唐末至五代','大化终华顶，
灵踪示玉泉。
由来负高尚，
合向好山川。
洞壑藏诸怪，
杉松列瘦烟。
千秋空树影，
犹似覆长禅。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1144','题张氏池亭','齐己','唐末至五代','树石丛丛别，
诗家趣向幽。
有时闲客散，
始觉细泉流。
蝶到琴棋畔，
花过岛屿头。
月明红藕上，
应见白龟游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1145','题明公房','齐己','唐末至五代','寺北闻湘浪，
窗南见岳云。
自然高日用，
何要出人群。
瓦滴残松雨，
香炉匝印文。
近年精易道，
疑者晓纷纷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1146','题画鹭鸶兼简孙郎中','齐己','唐末至五代','曾向沧江看不真，
却因图画见精神。
何妨金粉资高格，
不用丹青点此身。
蒲叶岸长堪映带，
荻花丛晚好相亲。
思量画得胜笼得，
野性由来不恋人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1147','题终南山隐者室','齐己','唐末至五代','终南山北面，
直下是长安。
自埽青苔室，
闲攲白石看。
风吹窗树老，
日晒窦云乾。
时向圭峰宿，
僧房瀑布寒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1148','题南平后园牡丹','齐己','唐末至五代','暖披烟艳照西园，
翠幄朱栏护列仙。
玉帐笙歌留尽日，
瑶台伴侣待归天。
香多觉受风光剩，
红重知含雨露偏。
上客分明记开处，
明年开更胜今年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1149','题南岳般若寺','齐己','唐末至五代','诸峰翠少中峰翠，
五寺名高此寺名。
石路险盘岚霭滑，
僧窗高倚泬寥明。
凌空殿阁由天设，
遍地杉松是自生。
更有上方难上处，
紫苔红藓绕峥嵘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1150','题真州精舍','齐己','唐末至五代','波心精舍好，
那岸是繁华。
碍目无高树，
当门即远沙。
晨斋来海客，
夜磬到渔家。
石鼎秋涛静，
禅回有岳茶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1151','题梁贤巽公房','齐己','唐末至五代','吴王庙侧有高房，
帘影南轩日正长。
吹苑野风桃叶碧，
压畦春露菜花黄。
悬灯向后惟冥默，
凭案前头即渺茫。
知有虎溪归梦切，
寺门松折社僧亡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1152','题赠湘西龙安寺利禅师','齐己','唐末至五代','头白已无行脚念，
自开荒寺住烟萝。
门前路到潇湘尽，
石上云归岳麓多。
南祖衣盂曾礼谒，
东林泉月旧经过。
闲来松外看城郭，
一片红尘隔逝波。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1153','赠无本上人','齐己','唐末至五代','往年吟月社，
因乱散扬州。
未免无端事，
何妨出世流。
洞庭禅过腊，
衡岳坐经秋。
终说将衣钵，
天台老去休。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1154','赠卢明府闲居','齐己','唐末至五代','鬓霜垂七十，
江国久辞官。
满箧新风雅，
何人旧岁寒。
闲居当野水，
幽鸟宿渔竿。
终欲相寻去，
兵戈时转难。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1155','赠白处士','齐己','唐末至五代','莘野居何定，
浮生知是谁。
衣衫同野叟，
指趣似禅师。
白发应无也，
丹砂久服之。
仍闻创行计，
春暖向峨嵋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1156','赠仰上人','齐己','唐末至五代','避地依真境，
安閒似旧溪。
干戈百里外，
泉石乱峰西。
草瑞香难歇，
松灵盖尽低。
寻应报休马，
瓶锡向南携。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1157','赠刘五经','齐己','唐末至五代','往年长白山，
发愤忍饥寒。
埽叶雪霜湿，
读书唇齿乾。
群经通讲解，
八十尚轻安。
今日江南寺，
相逢话世难。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1158','赠孙生','齐己','唐末至五代','见君诗自别，
君是继诗人。
道出千途外，
功争一字新。
寂寥中影迹，
霜雪里精神。
待折东堂桂，
归来更苦辛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1159','赠李明府','齐己','唐末至五代','名家宰名邑，
将谓屈锋铓。
直是难苏俗，
能消不下堂。
冰痕生砚水，
柳影透琴床。
何必称潇洒，
独为诗酒狂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1160','赠浙西李推官','齐己','唐末至五代','他皆恃勋贵，
君独爱诗玄。
终日秋光里，
无人竹影边。
东楼生倚月，
北固积吟烟。
闻说鸳行里，
多才复少年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1161','赠曹松先辈','齐己','唐末至五代','今岁赴春闱，
达如夫子稀。
山中把卷去，
榜下注官归。
楚月吟前落，
江禽酒外飞。
闲游向诸寺，
却看白麻衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1162','赠智满三藏','齐己','唐末至五代','灌顶清凉一滴通，
大毗卢藏遍虚空。
欲飞薝卜花无尽，
须待陀罗尼有功。
金杵力摧魔界黑，
水精光透夜灯红。
可堪东献明天子，
命服新酬赞国风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1163','赠樊处士','齐己','唐末至五代','小子声名天下知，
满簪霜雪白麻衣。
谁将一著争先后，
共向长安定是非。
有路未曾迷日用，
无贪终不乱天机。
闲寻道士过仙观，
赌得黄庭两卷归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1164','蟋蟀','齐己','唐末至五代','声异蟪蛄声，
听须是正听。
无风来竹院，
有月在莎庭。
虽不妨调瑟，
多堪伴诵经。
谁人向秋夕，
为尔欲忘形。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1165','鹭鸶二首','齐己','唐末至五代','日日沧江去，
时时得意归。
自能终洁白，
何处误翻飞。
晚立银塘阔，
秋栖玉露微。
残阳苇花畔，
双下钓鱼矶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1166','鹭鸶二首','齐己','唐末至五代','雪里曾迷我，
笼中旧养君。
忽从红蓼岸，
飞出白鸥群。
影照翘滩浪，
翎濡宿岛云。
鸳鸿解相忆，
天上列纷纷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1167','竹里作六韵','齐己','唐末至五代','我来深处坐，
剩觉有吟思。
忽似潇湘岸，
欲生风雨时。
冷烟濛古屋，
乾箨堕秋墀。
径熟因频入，
身闲得遍欹。
踏多鞭节损，
题乱粉痕隳。
犹见前山叠，
微茫隔短篱。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1168','杨花','齐己','唐末至五代','暖景照悠悠，
遮空势渐稠。
乍如飞雪远，
未似落花休。
万带都门外，
千株渭水头。
纷纭知近夏，
销歇恐成秋。
软著朝簪去，
狂随别骑游。
旆冲离馆驿，
莺扑绕宫楼。
江国晴愁对，
池塘晚见浮。
虚窗萦笔雅，
深院藉苔幽。
静堕王孙酒，
繁黏客子裘。
咏吟何洁白，
根本属风流。
向日还轻举，
因风更自由。
不堪思汴岸，
千里到扬州。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1169','赴郑谷郎中招游龙兴观读题诗板谒七真仪像因有十八韵','齐己','唐末至五代','何处陪游胜，
龙兴古观时。
诗悬大雅作，
殿礼七真仪。
远继周南美，
弥旌拱北思。
雄方垂朴略，
后辈仰箴规。
对坐茵花暖，
偕行藓阵隳。
僧绦初学结，
朝服久慵披。
到处琴棋傍，
登楼笔砚随。
论禅忘视听，
谭老极希夷。
照日江光远，
遮轩桧影欹。
触鞋松子响，
窥立鹤雏痴。
始贵茶巡爽，
终怜酒散迟。
放怀还把杖，
憩石或支颐。
眺远凝清眄，
吟高动白髭。
风鹏心不小，
蒿雀志徒卑。
顾我专无作，
于身忘有为。
叨因五字解，
每忝重言期。
舍此应休也，
何人更赏之。
淹留仙境晚，
回骑雪风吹。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1170','夏雨','齐己','唐末至五代','霮䨴蔽穹苍，
冥濛自一方。
当时消酷毒，
随处有清凉。
著物声虽暴，
滋农润即长。
乍红萦急电，
微白露残阳。
应祷尤难得，
经旬甚不妨。
吟听喧竹树，
立见涨池塘。
众类声休出，
群峰色尽藏。
颓沱来洞壑，
汗漫入潇湘。
下叶黎氓望，
高祛旱暵光。
幽斋飘卧簟，
极浦洒归樯。
藓在阶从湿，
花衰苑任伤。
闲思济时力，
歌咏发哀肠。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1171','假山','齐己','唐末至五代','匡庐久别离，
积翠杳天涯。
静室曾图峭，
幽亭复创奇。
典衣酬土价，
择日运工时。
信手成重叠，
随心作蔽亏。
根盘惊院窄，
顶耸讶檐卑。
镇地那言重，
当轩未厌危。
巨灵何忍擘，
秦政肯轻移。
晚觉莎烟触，
寒闻竹籁吹。
蓝灰澄古色，
泥水合凝滋。
引看僧来数，
牵吟客散迟。
九华浑髣髴，
五老颇参差。
蛛网藤萝挂，
春霖瀑布垂。
加添双石笋，
映带小莲池。
旧说雷居士，
曾闻远大师。
红霞中结社，
白壁上题诗。
顾此诚徒尔，
劳心是妄为。
经营惭培塿，
赏玩愧童儿。
会入千峰去，
闲踪任属谁。',NULL,'','{"preface": "假山者，盖怀匡庐有作也。往岁尝居东郭，因梦觉，遂图于壁。迄于十秋，而攒青叠碧于寤寐间，宛若扪萝挽树而升彼绝顶，今所作仿像一面（令所作仿像一面），故不尽万壑千岩神仙鬼怪之宅。聊得解怀，既而功就，乃激幽抱，而作是诗，终于一百八十言尔。", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1172','禅庭芦竹十二韵呈郑谷郎中','齐己','唐末至五代','错错在禅庭，
高宜与竹名。
健添秋雨响，
乾助夜风清。
雀静如枯折，
僧闲见笋生。
对吟殊洒落，
负气甚孤贞。
密谢编栏固，
齐由灌溉平。
松姿真可敌，
柳态薄难并。
映带兼苔石，
参差近画楹。
雪霜消后色，
虫鸟默时声。
远忆沧洲岸，
寒连暮角城。
幽根狂乱迸，
劲叶动相撑。
避暑须临坐，
逃眠必绕行。
未逢仙手咏，
俗眼见犹轻。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1173','酬元员外见寄八韵','齐己','唐末至五代','旧隐梦牵仍，
归心只似蒸。
远青怜岛峭，
轻白爱云腾。
艳冶丛翻蝶，
腥膻地聚蝇。
雨声连洒竹，
诗兴继填膺。
访戴情弥切，
依刘力不胜。
众人忘苦苦，
独自愧兢兢。
处世无他望，
流年有病僧。
时惭大雅客，
遗韵许相承。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1174','潇湘二十韵','齐己','唐末至五代','二水远难论，
从离向坎奔。
冷穿千嶂脉，
清过几州门。
阔去都凝白，
傍来尽带浑。
经游闻舜禹，
表里见乾坤。
浦静鱼闲钓，
湾凉雁自屯。
月来分夜底，
云度见秋痕。
暮气藏邻寺，
寒涛聒近村。
离骚传永恨，
鼓瑟奏遗魂。
雾拥鱼龙窟，
槎欹岛屿根。
秋风帆上下，
落日树沈昏。
柳少沙洲缺，
苔多古岸存。
禽巢依橘柚，
獭径入兰荪。
色自江南绝，
名闻海内尊。
吴头雄莫遏，
汉口壮堪吞。
寥泬晴方映，
冯夷信忽翻。
渡遥峰翠叠，
汀小荻花繁。
势接湖烟涨，
声和瘴雨喷。
急摇吟客舫，
狂溅野人樽。
疏凿谁穷本，
澄鲜自有源。
对兹伤九曲，
含浊出昆崙。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1175','蝉八韵','齐己','唐末至五代','咽咽复啾啾，
多来自早秋。
园林凉正好，
风雨思相收。
在处声无别，
何人泪欲流。
冷怜天露滴，
伤共野禽游。
静息深依竹，
惊移瞥过楼。
分明晴渡口，
凄切暮关头。
时节推应定，
飞鸣即未休。
年年闻尔苦，
远忆所居幽。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1176','蝴蝶','齐己','唐末至五代','何处背繁红，
迷芳到槛重。
分飞还独出，
成队偶相逢。
远害终防雀，
争先不避蜂。
桃蹊牵往复，
兰径引相从。
翠裛丹心冷，
香凝粉翅浓。
可寻穿树影，
难觅宿花踪。
日晚来仍急，
春残舞未慵。
西风旧池馆，
犹得采芙蓉。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1177','题鹤鸣泉八韵','齐己','唐末至五代','嘹唳遗踪去，
澄明物掩难。
喷开山面碧，
飞落寺门寒。
汲引随瓶满，
分流逐处安。
幽虫乘叶过，
渴狖拥条看。
上有危峰叠，
旁宜怪石盘。
冷吞双树影，
甘润百毛端。
异早闻镌玉，
灵终别建坛。
潇湘在何处，
终日自波澜。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1178','与聂尊师话道','齐己','唐末至五代','伯阳遗妙旨，
杳杳与冥冥。
说即非难说，
行还不易行。
药中迷九转，
心外觅长生。
毕竟荒原上，
一盘蒿陇平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1179','书李秀才壁','齐己','唐末至五代','干戈阻上日，
南国寄贫居。
旧里荒应尽，
新年病未除。
窗风连岛树，
门径接邻蔬。
我有闲来约，
相看雪满株。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1180','日日曲','齐己','唐末至五代','日日日东上，
日日日西没。
任是神仙容，
也须成朽骨。
浮云灭复生，
芳草死还出。
不知千古万古人，
葬向青山为底物。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1181','风琴引','齐己','唐末至五代','挼吴丝，
雕楚竹，
高托天风拂为曲。
一一宫商在素空，
鸾鸣凤语翘梧桐。
夜深天碧松风多，
孤窗寒梦惊流波。
愁魂傍枕不肯去，
翻疑住处邻湘娥。
金风声尽熏风发，
冷泛虚堂韵难歇。
常恐听多耳渐烦，
清音不绝知音绝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1182','丙寅岁寄潘归仁','齐己','唐末至五代','九土尽荒墟，
干戈杀害馀。
更须忧去国，
未可守贫居。
康泰终来在，
编联莫破除。
他年遇知己，
无耻报襜褕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1183','古剑歌','齐己','唐末至五代','古人手中铸神物，
百鍊百淬始提出。
今人不要强硎磨，
莲锷星文未曾没。
一弹一抚闻铮铮，
老龙影夺秋灯明。
何时得遇英雄主，
用尔平治天下去。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1184','对雪寄荆幕知己','齐己','唐末至五代','猛势微开万里清，
月中看似日中明。
此时鸥鹭无人见，
何处关山有客行。
郢唱转高谁敢和，
巴歌相顾自销声。
江斋卷箔含毫久，
应想梁王礼不经。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1185','石竹花','齐己','唐末至五代','石竹花开照庭石，
红藓自禀离宫色。
一枝两枝初笑风，
猩猩血泼低低丛。
常嗟世眼无真鉴，
却被丹青苦相陷。
谁为根寻造化功，
为君吐出淳元胆。
白日当午方盛开，
彤霞灼灼临池台。
繁香浓艳如未已，
粉蝶游蜂狂欲死。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1186','吊汨罗','齐己','唐末至五代','落日倚阑干，
徘徊汨罗曲。
冤魂如可吊，
烟浪声似哭。
我欲考鼋鼍之心，
烹鱼龙之腹。
尔既啖大夫之血，
食大夫之肉。
千载之后，
犹斯暗伏。
将谓唐尧之尊，
还如荒悴之君。
更有逐臣，
于焉葬魂。
得以纵其噬，
恣其吞。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1187','回雁峰','齐己','唐末至五代','瘴雨过孱颜，
危边有径盘。
壮堪扶寿岳，
灵合置仙坛。
影北鸿声乱，
青南客道难。
他年思隐遁，
何处凭阑干。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1188','红蔷薇花','齐己','唐末至五代','晴日当楼晓香歇，
锦带盘空欲成结。
莺声渐老柳飞时，
狂风吹落猩猩血。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1189','杂曲歌辞','齐己','唐末至五代','行路难，
君好看。
惊波不在黤黮间，
小人心里藏崩湍。
七盘九折寒崷崒，
翻车倒盖犹堪出。
未似是非唇舌危，
闇中潜毁平人骨。
君不见楚灵均，
千古沉冤湘水滨。
又不见李太白，
一朝却作江南客。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1190','西山叟','齐己','唐末至五代','西山中，
多狼虎，
去岁伤儿复伤妇。
官家不问孤老身，
还在前山山下住。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1191','观李琼处士画海涛','齐己','唐末至五代','巨鳌转侧长䲡翻，
狂涛颠浪高漫漫。
李琼夺得造化本，
都卢缩在秋毫端。
一挥一画皆筋骨，
滉漾崩腾大鲸臬。
叶扑仙槎摆欲沉，
下头应是骊龙窟。
昔年曾要涉蓬瀛，
唯闻撼动珊瑚声。
今来正叹陆沉久，
见君此画思前程。
千寻万派功难测，
海门山小涛头白。
令人错认钱塘城，
罗刹石底奔雷霆。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1192','君子行','齐己','唐末至五代','圣人不生，
麟龙何瑞？
梧桐不高，
凤凰何止？
吾闻古之有君子，
行藏以时，
进退求己。
荣必为天下荣，
耻必为天下耻。
苟进不如此，
退不如此。
亦何必用虚伪之文章，
取荣名而自美。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1193','巫山高','齐己','唐末至五代','巫山高，
巫女妖。
雨为暮兮云为朝，
楚王憔悴魂欲销。
秋猿嗥嗥日将夕，
红霞紫烟凝老壁。
千岩万壑花皆坼，
但恐芳菲无正色。
不知今古行人行，
几人经此无秋情。
云深庙远不可觅，
十二峰头插天碧。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1194','灵松歌','齐己','唐末至五代','灵松灵松，
是何根株。
盘擗枝干，
与群木殊。
世眼争知苍翠容，
薜萝遮体深朦胧。
先秋瑟瑟生谷风，
青阴倒卓寒潭中。
八月天威行肃杀，
万木凋零向霜雪。
唯有此松高下枝，
一枝枝在无摧折。
痴冻顽冰如铁坚，
重重锁到槎牙颠。
老鳞枯节相把捉，
踉跄立在青崖前。
有时深洞兴雷雹，
飞电绕身光闪烁。
乍似苍龙惊起时，
攫雾穿云欲腾跃。
夜深山月照高枝，
疏影细落莓苔矶。
千年朽蘖魍魉出，
一株寒韵锵琉璃。
安得良工妙图雘，
写将偃蹇悬烟阁。
飞瀑声中战岁寒，
红霞影里擎萧索。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1195','还人卷','齐己','唐末至五代','李白李贺遗机杼，
散在人间不知处。
闻君收在芙蓉江，
日斗鲛人织秋浦。
金梭劄劄文离离，
吴姬越女羞上机。
鸳鸯浴烟鸾凤飞，
澄江晓映馀霞辉。
仙人手持玉刀尺，
寸寸酬君珠与璧。
裁作霞裳何处披，
紫皇殿里深难觅。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1196','还黄平素秀才卷','齐己','唐末至五代','求己甚忘筌，
得之经浑然。
僻能离诡差，
清不尚妖妍。
冷澹闻姚监，
精奇见浪仙。
如君好风格，
自可继前贤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1197','闲居','齐己','唐末至五代','渐觉春光媚，
尘销作土膏。
微寒放杨柳，
纤草入风骚。
睡少全无病，
身轻乍去袍。
前溪泛红片，
何处落金桃。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1198','刳肠龟','齐己','唐末至五代','尔既能于灵，
应久存其生。
尔既能于瑞，
胡得迷其死。
刳肠徒自屠，
曳尾复何累。
可怜濮水流，
一叶泛庄子。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1199','咏茶十二韵','齐己','唐末至五代','百草让为灵，
功先百草成。
甘传天下口，
贵占火前名。
出处春无雁，
收时谷有莺。
封题从泽国，
贡献入秦京。
嗅觉精新极，
尝知骨自轻。
研通天柱响，
摘绕蜀山明。
赋客秋吟起，
禅师昼卧惊。
角开香满室，
炉动绿凝铛。
晚忆凉泉对，
闲思异果平。
松黄乾旋泛，
云母滑随倾。
颇贵高人寄，
尤宜别匮盛。
曾寻修事法，
妙尽陆先生。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1200','祈真坛','齐己','唐末至五代','玉瓮瑶坛二三级，
学仙弟子参差入。
霓旌队仗下不下，
松桧森森天露湿。
殿前寒气束香云，
朝祈暮祷玄元君。
茫茫俗骨醉更昏，
楼台十二遥昆崙。
昆崙纵广一万二千里，
中有五色云霞五色水。
何当断欲便飞去，
不要九转神丹换精髓。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1201','杂曲歌辞 苦热行','齐己','唐末至五代','离宫划开赤帝怒，
喝出六龙奔日驭。
下土熬熬若煎煮，
苍生惶惶无处处。
火云峥嵘焚泬寥，
东皋老农肠欲焦。
何当一雨苏我苗，
为君击壤歌帝尧。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1202','赠梅君','李梦唐','当代','梅萼生时酒未倾，
低眉向盏看浮萍。
满庭明月共谁语，
听裂冰弦第一声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1203','采莲曲','齐己','唐末至五代','越溪女，
越江莲。
齐菡萏，
双婵娟。
嬉游向何处，
采摘且同船。
浩唱发容与，
清波生漪连。
时逢岛屿泊，
几共鸳鸯眠。
襟袖既盈溢，
馨香亦相传。
薄暮归去来，
苧萝生碧烟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1204','城中怀山友','齐己','唐末至五代','春城来往桃李碧，
煖艳红香断消息。
吾徒自有山中邻，
白昼冥心坐岚壁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1205','春日西湖作','齐己','唐末至五代','一水绕孤岛，
闲门掩春草。
曾无长者辙，
枉此问衰老。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1206','荆门病中寄怀乡人欧阳侍郎彬','齐己','唐末至五代','谁会荆州一老夫，
梦劳神役忆匡庐。
碧云雁影纷纷去，
黄叶蟾声渐渐无。
口淡莫分餐气味，
身羸但觉病肌肤。
可怜馔玉烧兰者，
肯慰寒偎雪夜炉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1207','荆州新秋病起杂题一十五首 病起见苔色','齐己','唐末至五代','病起见苔色，
凝然阵未枯。
浅深围柱础，
诘曲绕廊庑。
碧翠文相间，
青黄势自铺。
为钱虚玷染，
毕竟不如无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1208','荆渚病中因思匡庐遂成三百字寄梁先辈','齐己','唐末至五代','生老病死者，
早闻天竺书。
相随几汨没，
不了堪欷歔。
自理自可适，
他人谁与袪。
应当入寂灭，
乃得长销除。
前月已骨立，
今朝还貌舒。
披衣试步履，
倚策聊踌躇。
江月青眸冷，
秋风白发疏。
新题忆剡硾，
旧约怀匡庐。
张野久绝迹，
乐天曾卜居。
空龛掩薜荔，
瀑布喷蟾蜍。
古桧鸣玄鹤，
凉泉跃锦鱼。
狂吟树荫映，
纵踏花蔫烟。
唇舌既已闲，
心脾亦散摅。
松窗有偃息，
石径无趑趄。
梦冷通仙阙，
神融合太虚。
千峰杳霭际，
万壑明清初。
长往期非晚，
半生闲有馀。
依刘未是咏，
访戴宁忘诸。
稽古堪求己，
观时好笑渠。
埋头逐小利，
没脚拖长裾。
道种将闲养，
情田把药锄。
幽香发兰蕙，
秽莽摧丘墟。
敢谓囊盈物，
那言庾满储。
微烟动晨爨，
细雨滋园蔬。
藓乱珍禽羽，
门稀长者车。
冥机坐兀兀，
著履行徐徐。
每许亲朱履，
多怜奉隼旟。
簪嫌红玳瑁，
社念金芙蕖。
海内竞铁马，
箧中藏纸驴。
常言谢时去，
此意将何如。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1209','杂曲歌辞 轻薄行','齐己','唐末至五代','玉鞭金镫骅骝蹄，
横眉吐气如虹霓。
五陵春暖芳草齐，
笙歌到处花成泥。
日沉月上且斗鸡，
醉来莫问天高低。
伯阳道德何唾咦，
仲尼礼乐徒卑栖。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1210','送人入蜀','齐己','唐末至五代','何必闲吟蜀道难，
知君心出崄巇间。
寻常秋泛江陵去，
容易春浮锦水还。
两面碧悬神女峡，
几重青出丈人山。
文君酒市逢初雪，
满贳新沽洗旅颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1211','送中观进公归巴陵','齐己','唐末至五代','一论破双空，
持行大国中。
不知从此去，
何处挫邪宗。
昼雨悬帆黑，
残阳泊岛红。
应游到灉岸，
相忆绕茶丛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1212','送刘秀才南游','齐己','唐末至五代','南去谒诸侯，
名山亦得游。
便应寻瀑布，
乘兴上岣嵝。
高鸟随云起，
寒星向地流。
相思应北望，
天晚石桥头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1213','送禅者游南岳','齐己','唐末至五代','忽随南棹去衡阳，
谁住江边树下房。
尘梦是非都觉了，
野云心地更何妨。
渐临瀑布听猿思，
却背岣嵝有雁行。
想到中峰上层寺，
石窗秋霁见潇湘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1214','夏云曲','齐己','唐末至五代','红嵯峨，
烁晚波，
乖龙慵卧旱鬼多。
爞爞万里压天堑，
飏雷电光空闪闪。
好雨不雨风不风，
徒倚穹苍作岩险。
男巫女觋更走魂，
焚香祝天天不闻。
天若闻，
必能使尔为润泽，
洗埃氛，
而又变之成五色。
捧日轮，
将以表唐尧虞舜之明君。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1215','夏日荆渚书怀','齐己','唐末至五代','嵩岳去值乱，
匡庐回阻兵。
中途息瓶锡，
十载依公卿。
不那猿鸟性，
但怀林泉声。
何时遂情兴，
吟绕杉松行。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1216','浮云行','齐己','唐末至五代','大野有贤人，
大朝有圣君。
如何彼浮云，
掩蔽白日轮。
安得东南风，
吹散八表外。
使之天下人，
共见尧眉彩。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1217','耕叟','齐己','唐末至五代','春风吹蓑衣，
暮雨滴箬笠。
夫妇耕共劳，
儿孙饥对泣。
田园高且瘦，
赋税重复急。
官仓鼠雀群，
共待新租入。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1218','读李白集','齐己','唐末至五代','竭云涛，
刳巨鳌，
搜括造化空牢牢。
冥心入海海神怖，
骊龙不敢为珠主。
人间物象不供取，
饱饮游神向悬圃。
锵金铿玉千馀篇，
脍吞炙嚼人口传。
须知一一丈夫气，
不是绮罗儿女言。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1219','读李贺歌集','齐己','唐末至五代','赤水无精华，
荆山亦枯槁。
玄珠与虹玉，
璨璨李贺抱。
清晨醉起临春台，
吴绫蜀锦胸襟开。
狂多两手掀蓬莱，
珊瑚掇尽空土堆。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1220','寄朱拾遗','齐己','唐末至五代','一闻归阙下，
几番熟金桃。
沧海期仍晚，
清资路渐高。
研冰濡谏笔，
赋雪拥朝袍。
岂念空林下，
冥心坐石劳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1221','寄勉二三子','齐己','唐末至五代','不见二三子，
悠然吴楚间。
尽应生白发，
几个在青山。
暇日还宜爱，
馀生莫放闲。
君闻国风否，
千载咏关关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1222','寄南岳白莲道士能于长啸','齐己','唐末至五代','猿猱休啼月皎皎，
蟋蟀不吟山悄悄。
大耳仙人满颔须，
醉倚长松一声啸。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1223','渔父','齐己','唐末至五代','夜钓洞庭月，
朝醉巴陵市。
却归君山下，
鱼龙窟边睡。
生涯在何处，
白浪千万里。
曾笑楚臣迷，
苍黄汨罗水。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1224','猛虎行','齐己','唐末至五代','磨尔牙，
错尔爪，
狐莫威，
兔莫狡，
饥来吞噬取肠饱。
横行不怕日月明，
皇天产尔为生狞。
前村半夜闻吼声，
何人按剑灯荧荧。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1225','黄雀行','齐己','唐末至五代','双双野田雀，
上下同饮啄。
暖去栖蓬蒿，
寒归傍篱落。
殷勤避罗网，
乍可遇雕鹗。
雕鹗虽不仁，
分明在寥廓。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1226','善哉行','齐己','唐末至五代','大鹏刷翮谢溟渤，
青云万层高突出。
下视秋涛空渺㳽，
旧处鱼龙皆细物。
人生在世何容易，
眼浊心昏信生死。
愿除嗜欲待身轻，
携手同寻列仙事。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1227','湘妃庙','齐己','唐末至五代','湘烟濛濛湘水急，
汀露凝红裛莲湿。
苍梧云叠九嶷深，
二女魂飞江上立。
相携泣，
凤盖龙舆追不及。
庙荒松朽啼飞猩，
笋鞭迸出阶基倾。
黄昏一岸阴风起，
新月如眉生阔水。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1228','短歌寄鼓山长老','齐己','唐末至五代','雪峰雪峰高且雄，
峨峨堆积青冥中。
六月赤日烧不镕，
飞禽瞥见人难通。
常闻中有白象王，
五百象子皆威光。
行围坐绕同一色，
森森影动旃檀香。
于中一子最雄猛，
称尊独踞鼓山顶。
百千眷属阴□影，
身照曜，
吞秋景。
我闻岷国民归依，
前王后王皆师资。
宁同梁武遇达磨，
过后弹指空伤悲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1229','谢人惠十色花笺并棋子','齐己','唐末至五代','陵州棋子浣花笺，
深愧携来自锦川。
海蚌琢成星落落，
吴绫隐出雁翩翩。
留防桂苑题诗客，
惜寄桃源敌手仙。
捧受不堪思出处，
七千馀里剑门前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1230','谢欧阳侍郎寄示新集','齐己','唐末至五代','宫锦三十段，
金梭新织来。
殷勤谢君子，
迢递寄寒灰。
鸑鷟对鼓舞，
神仙双裴回。
谁当巧裁制，
披去升瑶台。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1231','谢徽上人见惠二龙障子以短歌酬之','齐己','唐末至五代','我见苏州昆山金城中，
金城柱上有二龙。
老僧相传道是僧繇手，
寻常入海共龙斗。
又闻蜀国玉局观有孙遇迹，
盘屈身长八十尺。
游人争看不敢近，
头觑寒泉万丈碧。
近有五羊徽上人，
闲工小笔得意新。
画龙不誇头角及须鳞，
只求筋骨与精神。
徽上人，
真艺者。
惠我双龙不言价，
等闲不敢将悬挂。
恐是叶公好假龙，
及见真龙却惊怕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1232','煌煌京洛行','齐己','唐末至五代','圣君垂衣裳，
荡荡若朝旭。
大观无遗物，
四夷来率服。
清晨回北极，
紫气盖黄屋。
双阙耸双鳌，
九门如川渎。
梯山航海至，
昼夜车相续。
我恐红尘深，
变为黄河曲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1233','酬岳阳李主簿卷','齐己','唐末至五代','把卷思高兴，
潇湘阔浸门。
无云生翠浪，
有月动清魂。
倚槛应穷底，
凝情合到源。
为君吟所寄，
难甚至忘筌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1234','赠岩居僧','齐己','唐末至五代','石如骐驎岩作室，
秋苔漫坛净于漆。
袈裟盖头心在无，
黄猿白猿啼日日。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1235','赠念法华经僧','齐己','唐末至五代','念念念兮入恶易，
念念念兮入善难。
念经念佛能一般，
爱河竭处生波澜。
言公少年真法器，
白昼不出夜不睡。
心心缘经口缘字，
一室寥寥灯照地。
沈檀卷轴宝函盛，
薝卜香熏水精记。
空山木落古寺闲，
松枝鹤眠霜霰乾。
牙根舌根水滴寒，
珊瑚搥打红琅玕。
但恐莲花七朵一时折，
朵朵似君心地白。
又恐天风吹天花，
缤纷如雨飘袈裟。
况闻此经甚微妙，
百千诸佛真秘要。
灵山说后始传来，
闻者虽多持者少。
更堪诵入陀罗尼，
唐音梵音相杂时。
舜弦和雅熏风吹，
文王武王弦更悲。
如此争不遣碧空中有龙来听，
有鬼来听，
亦使人间闻者敬。
见者敬，
自然心虚空，
性清净。
此经真体即毗卢，
雪岭白牛君识无。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1236','赠询公上人','齐己','唐末至五代','威仪何贵重，
一室贮冰清。
终日松杉径，
自多虫蚁行。
像前孤立影，
钟外数珠声。
知悟修来事，
今为第几生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1237','赠持法华经僧','齐己','唐末至五代','众人有口，
不说是，
即说非。
吾师有口何所为，
莲经七轴六万九千字。
日日夜夜终复始。
乍吟乍讽何悠扬，
风篁古松含秋霜。
但恐天龙夜叉乾闼众，
副塞虚空耳皆耸。
我闻念经功德缘，
舌根可算金刚坚。
他时劫火洞燃后，
神光璨璨如红莲。
受持身心苟精洁，
尚能使烦恼大海水枯竭。
魔王轮幢自摧折，
何况更如理行如理说。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1238','啄木','齐己','唐末至五代','啄木啄啄，
鸣林响壑。
贪心既缘，
利嘴斯凿。
有朽百尺，
微虫斯宅。
以啄去害，
啄更弥剧。
层崖豫章，
耸干苍苍。
无纵尔啄，
摧我栋梁。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_2_1239','蠹','齐己','唐末至五代','蠹不自蠹，
而蠹于木。
蠹极木心，
以丰尔腹。
偶或成之，
胡为勖人。
人而不真，
繇尔乱神。
蠹兮蠹兮，
何全其生。
无托尔形，
霜松雪柽。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_2_1240','句','齐己','唐末至五代','春晴游寺客，
花落闭门僧。
香传天下口。
□贵火前名，
角开香满室，
炉动绿凝铛。
园林将向夕，
风雨更吹花。
相思坐溪石，
□□□山风。
夕照背高台，
残钟残角催。
五老峰前相见时，
两无言语各扬眉。
高人爱惜藏岩里，
白甀封题寄火前。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1241','送贺秘监归会稽诗','齐光乂','唐','晚岁朝真隐，
皇情谅不违。
辞家五十载，
今日复东归。
祖帐临青道，
天章降紫微。
顾嗟轩冕者，
谁与比光辉？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1242','偈','齐安和尚','中唐','猛炽燄中人有路，
旋风顶上屹然栖。
镇常历劫谁差互，
杲日无言运照齐。',NULL,'','{"preface": "", "note": ""}','偈颂','hefengbao/jingmo-data3'),
('rd3_2_1243','长门怨','刘皂','唐','宫殿沈沈月欲分，
昭阳更漏不堪闻。
珊瑚枕上千行泪，
不是思君是恨君。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1244','送贺秘监归会稽诗','齐浣','唐','君家在四明，
崇道复遗荣。
霓服辞丹禁，
天文诏玉京。
义方延永锡，
真箓受长生。
举手都门外，
白云江上行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1245','登石伞峰','齐推','唐','能以郡中暇，
不遗尘外踪。
啸俦得鸳鸯，
探策入云松。
缘径历空际，
望崖来剑峰。
况当会天人，
复此陈歌钟。
贱子固多癖，
偶兹安一峰。
步林欣有适，
筑室幸可容。
宁期樵牧处，
忽与轩盖逢。
仰荷高兴属，
俯惭危磴重。
攀幽破岩霭，
践滑触苔封。
秋景山光动，
寒丛菊艳浓。
赏心惬觞酌，
逸韵陶襟胸。
仍叨勒名字，
永纪今所从。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1246','句','唐镐','南唐','莲中花更好，
云里月常新。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1247','题汉州西湖','严公贶','唐','凤沼才难尽，
馀思凿西湖。
珍木罗修岸，
冰光映坐隅。
琴台今寂寞，
竹岛尚萦纡。
犹蕴济川志，
芳名终不渝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1248','题汉州西湖','严公弼','唐','西湖创置自房公，
心匠纵横造化同。
见说凤池推独步，
高名何事滞川中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1249','建中四年十月感事','严巨川','唐','烟尘忽起犯中原，
自古临危道贵存。
手持礼器空垂泪，
心忆明君不敢言。
落日胡笳吟上苑，
通宵虏将醉西园。
传烽万里无师至，
累代何人受汉恩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1250','太清宫闻滴漏','严巨川','唐','玉漏移中禁，
齐车入太清。
渐知催辨色，
复听续馀声。
乍逐微风转，
时因杂佩轻。
青楼人罢梦，
紫陌骑将行。
残魄栖初尽，
馀寒滴更生。
惭非朝谒客，
空有振衣情。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1251','颂鲜于叔明','严氏子','唐','三院四人簪白笔，
一门三镇拥朱幡。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1252','唐昌观玉蕊花折有仙人游怅然成二绝','严休复','中唐','终日斋心祷玉宸，
魂销目断未逢真。
不如满树琼瑶蕊，
笑对藏花洞里人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1253','唐昌观玉蕊花折有仙人游怅然成二绝','严休复','中唐','羽车潜下玉龟山，
尘世何由睹蕣颜。
唯有多情枝上雪，
好风吹缀绿云鬟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1254','与于驸马','严休复','中唐','莫惜歌喉一串珠。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1255','送贺秘监归会稽诗','严向','唐','孤云去住本无机，
却指苍梧下翠微。
锡鼎为传仙族在，
泛槎还入海烟归。
客星一夜淩光武，
华表千年送令威。
闻道葛洪丹灶畔，
至今霜果有金衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1256','相和歌辞 班倢伃','严识玄','唐','贱妾如桃李，
君王若岁时。
秋风一已劲，
摇落不胜悲。
寂寂苍苔满，
沈沈绿草滋。
荣华非此日，
指辇竞何辞。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1257','巴岭荅杜二见忆','严武','唐','卧向巴山落月时，
两乡千里梦相思。
可但步兵偏爱酒，
也知光禄最能诗。
江头赤叶枫愁客，
篱外黄花菊对谁。
跂马望君非一度，
冷猿秋雁不胜悲。',NULL,'[{"Book": "《唐诗归》", "Section": null, "Content": "钟云：此老七言律反似胜诸名家，以淹贯中有生骨也。谭云：诗文带英雄气，自然不得烂熟。钟云：“枫愁客”、“菊对谁”，顿挫有腕力（“江头赤叶”二句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}, {"Book": "《唐诗选脉会通评林》", "Section": null, "Content": "陈继儒曰：盛唐佳调，王、李未能无逊。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选脉会通评林》"}, {"Book": "《唐诗归折衷》", "Section": null, "Content": "有此等诗，才是子美石交，复不作闾丘晓，二公俱有天幸。圣叹云：读先生此诗，始悟工部昔日相依，直是二人才力、学力自应分投至深，岂为草草交游而已哉！", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归折衷》"}, {"Book": "《唐体馀编》", "Section": null, "Content": "此正系思之事，暗承无迹（“也知光禄”句下）。景有馀景，情有馀情（末句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐体馀编》"}, {"Book": "《唐诗成法》", "Section": null, "Content": "沉着雄浑，有英雄气。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗成法》"}, {"Book": "《闻鹤轩初盛唐近体读本》", "Section": null, "Content": "章长玉曰：起最波倩，五、六“枫”，“菊”二字是倒着句法，最生。落句因歧马便及猿雁，是绾合之法。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《闻鹤轩初盛唐近体读本》"}, {"Book": "《唐诗近体》", "Section": null, "Content": "罢脱顿挫，风骨胜人。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗近体》"}, {"Book": "《唐七律隽》", "Section": null, "Content": "直抒胸臆，绝木投色，自有一种真致。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐七律隽》"}, {"Book": "《山满楼笺注唐诗七言律》", "Section": null, "Content": "人既不来，而“冷猿秋雁”顾乃苦叫哀啼之不绝，其能以无悲耶？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《山满楼笺注唐诗七言律》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1258','寄题杜拾遗锦江野亭','严武','唐','漫向江头把钓竿，
懒眠沙草爱风湍。
莫倚善题鹦鹉赋，
何须不著鵔鸃冠。
腹中书籍幽时晒，
肘后医方静处看。
兴发会能驰骏马，
应须直到使君滩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1259','酬别杜二','严武','唐','独逢尧典日，
再睹汉官时。
未效风霜劲，
空惭雨露私。
夜钟清万户，
曙漏拂千旗。
并向殊庭谒，
俱承别馆追。
斗城怜旧路，
涡水惜归期。
峰树还相伴，
江云更对垂。
试回沧海棹，
莫妒敬亭诗。
秪是书应寄，
无忘酒共持。
但令心事在，
未肯鬓毛衰。
最怅巴山里，
清猿醒梦思。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1260','军城早秋','严武','唐','昨夜秋风入汉关，
朔云边月满西山。
更催飞将追骄虏，
莫遣沙场匹马还。',NULL,'[{"Book": "《批点唐诗正声》", "Section": null, "Content": "桂天祥曰：风格矫然，唐人塞下诸作为第一。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《批点唐诗正声》"}, {"Book": "《唐诗广选》", "Section": null, "Content": "田子艺曰：气概雄壮，武将本色。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗广选》"}, {"Book": "《载酒园诗话又编》", "Section": null, "Content": "《军城早秋》自写英雄本色耳。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《载酒园诗话又编》"}, {"Book": "《唐诗别裁》", "Section": null, "Content": "英爽与少陵作鲁、卫。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗别裁》"}, {"Book": "《诗法易简录》", "Section": null, "Content": "前二句写早秋，即切定军城；三四句就军城生意，又不能脱早秋。盖秋高马肥，正骄虏入寇时也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《诗法易简录》"}, {"Book": "《唐诗笺要》", "Section": null, "Content": "绝类高达夫，结更气概雄伟，不掩大将本色。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗笺要》"}, {"Book": "《唐人万首绝句选评》", "Section": null, "Content": "此等诗不必有深思佳论，只须字字饱绽，气格并胜。阮亭于此种多取之，而凡有意而气不完者，不入选。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐人万首绝句选评》"}, {"Book": "《岘佣说诗》", "Section": null, "Content": "意尽句中矣，而雄健可喜。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《岘佣说诗》"}, {"Book": "《诗境浅说续编》", "Section": null, "Content": "上二句气势雄阔，后二句有誓扫匈奴之概。如王昌龄云：“不破楼兰终不还”，少陵《和郑公》之“更夺蓬婆雪外城”，虽皆作豪语，而非手握军符。此作出自郑公，弥见儒将英风。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《诗境浅说续编》"}, {"Book": "《唐人绝句精华》", "Section": null, "Content": "首二句写军城秋景，三四句杀敌雄心。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐人绝句精华》"}, {"Book": "唐诗鉴赏辞典", "Section": null, "Content": "安史之乱以后，唐王朝国力削弱，吐蕃趁虚而入，曾一度攻入长安，后来又向西南地区进犯。严武两次任剑南节度使，广德二年（764）秋天，他率兵西征，击败吐蕃七万多人，失地收复，安定了蜀地。《军城早秋》，一方面使我们看到诗人作为镇守一方的主将的才略和武功，另一方面也表现了这位统兵主将的词章文采，能文善武，无怪杜甫称其为“出群”之才。诗的第一句“昨夜秋风入汉关”，看上去是写景，其实是颇有寓意的。我国西北和北部的少数民族的统治武装，常于秋高马肥的季节向内地进犯。“秋风入汉关”就意味着边境上的紧张时刻又来临了。“昨夜”二字，紧扣诗题“早秋”，如此及时地了解“秋风”，正反映了严武作为边关主将对时局的密切关注，对敌情的熟悉。第二句接着写诗人听到秋风的反映，这个反映是很有个性的，他立即注视西山（即今四川西部大雪山），表现了主将的警觉、敏感，也暗示了他对时局所关注的具体内容。西山怎样呢？寒云低压，月色清冷，再加上一个“满”字，就把那阴沉肃穆的气氛写得更为浓重，这气氛正似风云突变的前兆，大战前的沉默。“眼中形势胸中策”（宗泽《早发》），这是一切将领用兵作战的基本规律。所以诗的前两句既然写出了战云密布的“眼中形势”，那胸中之策就自不待言了，诗中略去这一部分内容，正表现了严武是用兵的行家。<br /><br />“更催飞将追骄虏，莫遣沙场匹马还”。“更催”二字暗示战事已按主将部署胜利展开。两句一气而下，笔意酣畅，字字千钧，既显示出战场上势如破竹的气势，也表现了主将刚毅果断的气魄和胜利在握的神情，而整个战斗的结果也自然寓于其中了。这就是古人所说的“墨气所射，四表无穷，无字处皆其意也”（王夫之《董斋诗话》）。我们如果把一、二句和三、四句的内容放在一起来看，就会发现中间有着很大的跳跃。了解战争的人都知道，一个闭目塞听、对敌情一无所知的主将，是断然不会打胜仗的，战争的胜负往往取决于战前主将对敌情的敏感和了解的程度。诗的一、二句景中有情，显示出主将准确地掌握了时机和敌情，这就意味着已经居于主动地位，取得了主动权，取得了克敌制胜的先决条件，这一切正预示着战争的顺利，因而，胜利也就成了人们意料中的结果，所以读到三、四句非但没有突兀、生硬之感，反而有一种水到渠成、果然如此的满足。这首诗写得开阖跳跃，气概雄壮，干净利落，表现出地道的统帅本色。<br /><br />诗的思想感情、语言风格，也都富有作者本人的个性特征。这不是一般诗人所能写得出的。<br /><br />（赵其钧）", "IsComment": false, "ReferrenceUrls": null, "FullPath": "唐诗鉴赏辞典"}]','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1261','题巴州光福寺楠木','严武','唐','楚江长流对楚寺，
楠木幽生赤崖背。
临溪插石盘老根，
苔色青苍山雨痕。
高枝闹叶鸟不度，
半掩白云朝与暮。
香殿萧条转密阴，
花龛滴沥垂清露。
闻道偏多越水头，
烟生霁敛使人愁。
月明忽忆湘川夜，
猿叫还思鄂渚秋。
看君幽霭几千丈，
寂寞穷山今遇赏。
亦知钟梵报黄昏，
犹卧禅床恋奇响。',NULL,'[{"Book": "《唐诗归》", "Section": null, "Content": "此诗奇郁有异采，人偏不取，却专取其《军城早秋》一首。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}, {"Book": "《唐诗选脉会通评林》", "Section": null, "Content": "周珽曰：说得楠木根本枝叶古异幽奇。……唐仲言则云：沉细而奇，信非常调。但《军城早秋》亦七绝响调，钟今何违众而去之？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选脉会通评林》"}, {"Book": "《载酒园诗话又编》", "Section": null, "Content": "《题巴州光福寺楠木》曰：“看君幽霭几千丈，寂寞穷山今遇赏。亦知钟梵报黄昏，犹卧禅床恋奇响。”兴趣不俗，骨气亦尽高。武诗如此，宜其知少陵也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《载酒园诗话又编》"}]','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1262','落花','严恽','唐','春光冉冉归何处，
更向花前把一杯。
尽日问花花不语，
为谁零落为谁开。',NULL,'[{"Book": "皮日休《伤进士严子重诗序》", "Section": null, "Content": "（恽诗）佳者曰：“春光冉冉归何处……”余美之，讽而未尝怠。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "皮日休《伤进士严子重诗序》"}, {"Book": "《优古堂诗话》", "Section": null, "Content": "东坡《吉祥赏花寄陈述古》诗云：“仙花不用剪刀裁，国色初酣卯酒来。太守问花花不语，为谁零落为谁开？”《南部新书》记严恽诗：“……尽日问花花不语，为谁零落为谁开？”东坡全用此两句也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《优古堂诗话》"}, {"Book": "《容斋随笔》", "Section": null, "Content": "《温公诗话》云：唐之中叶，文章特盛，其姓名湮没不传于世者甚众……有严恽《惜花》一绝云：“春光冉冉归何处……”前人多不知谁作，乃见于《皮陆唱和集》中。大率康人多工诗，虽小说、戏剧、鬼物假托，莫不宛转有思致，不必颛门名家而后可称也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《容斋随笔》"}, {"Book": "《唐诗选脉会通评林》", "Section": null, "Content": "何新之为奇隽体。徐充曰：深切尤情之感。夫春自去来，花自开谢，问虽不语，实来尝不示人以荣瘁之故，人自不知惜耳。能自惜，便不为春所抛掷，花所含笑矣……《雅言杂载》：曹相镇浙西日，会湖州郡判官王枢，举恽此诗，一座称赏。彼岂皆悟“花开花落”之为谁耶？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选脉会通评林》"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1263','丹阳送韦参军','严维','中唐','丹阳郭里送行舟，
一别心知两地秋。
日晚江南望江北，
寒鸦飞尽水悠悠。',NULL,'[{"Book": "《唐诗正声》", "Section": null, "Content": "吴逸一评：离情缥渺。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗正声》"}, {"Book": "《批点唐诗正声》", "Section": null, "Content": "作诗妙处，正不在多道，如“日晚”二句，多少相思，都在此隐括内。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《批点唐诗正声》"}, {"Book": "《唐诗选胜直解》", "Section": null, "Content": "首一句完题面，后三句递生出一江之隔，故曰“两地”，曰“南”“北”。“悠悠”则实写江水，送别之意渐探渐远，有味。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选胜直解》"}, {"Book": "《唐人万首绝句选评》", "Section": null, "Content": "只一“望”字见意，末句转入空际，却自佳。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐人万首绝句选评》"}, {"Book": "《诗境浅说续编》", "Section": null, "Content": "临水寄怀，不落边际，自有渺渺予怀之感。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《诗境浅说续编》"}, {"Book": "唐诗鉴赏辞典", "Section": null, "Content": "这首七绝是作者抒写他给韦参军送行以及送走之后的情景，表现了他们之间的真挚情谊。<br /><br />诗的前两句是写送行。首句“丹阳郭里”交待了送行地点在丹阳的外城边。“行舟”表明友人将从水路离去。此时，千种离情，万般愁绪，一齐涌上诗人心头。“一别心知两地秋”，“秋”字，表面上写时令，实际上却是表达人的情绪。萧瑟的秋景增添了离情别绪。作者还巧妙地运用拆字法，以“心”上有“秋”说明“愁”。所以“两地秋”是双关语。<br /><br />诗的后两句写送走之后对韦参军的深切思念。“日晚江南望江北”这一句转接自然，不露痕迹地把前句抽象的离愁具体形象地表现出来。“江南”、“江北”，对比照应，突出了江水的阻隔。丹阳在江之南，“江南”──“江北”，既是友人行舟的路线，也是作者目送方向。“望”字传出思念之神态，忧思绵绵，“日晚”暗示思念时间之久，见出友情之深。由“望”自然而然地带出末一句“寒鸦飞尽水悠悠”。这一句写望中所见。通过环境气氛的渲染，表达作者的悠悠情思。由于思念，站在江边长时间的遥望着，秋日黄昏，江面上寒鸦点点，给人增添愁思。可是，就连这使人感伤的寒鸦此时此刻也“飞尽”了，只剩下悠悠江水流向远方。这一切给人以孤独、寂静、空虚的感触。“水悠悠”包含着无限思念的深情。<br /><br />这首小诗妙语连珠，情景交融，真切自然，既能把诚朴真挚的感情渗透在景物的描写中，又能在抒情中展现画图，做到辞有尽而意不尽。<br /><br />（宛新彬）", "IsComment": false, "ReferrenceUrls": null, "FullPath": "唐诗鉴赏辞典"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1264','岁初喜皇甫侍御至','严维','中唐','湖上新正逢故人，
情深应不笑家贫。
明朝别后门还掩，
修竹千竿一老身。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1265','状江南 季春','严维','中唐','江南季春天，
莼叶细如弦。
池边草作径，
湖上叶如船。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1266','相里使君宅听澄上人吹小管','严维','中唐','秦僧吹竹闭秋城，
早在梨园称主情。
今夕襄阳山太守，
座中流泪听商声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1267','送人入金华','严维','中唐','明月双溪水，
清风八咏楼。
昔年为客处，
今日送君游。',NULL,'[{"Book": "《唐诗摘钞》", "Section": null, "Content": "气局完密，绝无一字虚致，几欲与“白日依山尽”作争衡；所逊者，兴象微不逮耳。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗摘钞》"}, {"Book": "《唐人万首绝句选评》", "Section": null, "Content": "绝句妙境多在转句生意，此诗转句入妙，觉上二句都有情。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐人万首绝句选评》"}, {"Book": "《诗境浅说续编》", "Section": null, "Content": "凡人昔年屐齿所经，积久渐忘，忽逢故友，重履前尘，遂使钩游陈迹，一一潮上心头。……人情恋旧，大抵相同。作者回首当年，双溪打桨，八咏登楼，宜有桑下浮屠之感也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《诗境浅说续编》"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1268','七里滩重送','刘长卿','中唐','秋江渺渺水空波，
越客孤舟欲榜歌。
手折衰杨悲老大，
故人零落已无多。',NULL,'[{"Book": "《唐诗笺要》", "Section": null, "Content": "“故人零落”从“衰杨”生出，送客意已宛转砍尽。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗笺要》"}, {"Book": "《诗式》", "Section": null, "Content": "首句写景，二句写客之欲行者，三句转到送行，四句落到客去后情境。首句起，二句承，三句转，四句合。[品]凄婉。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《诗式》"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1269','宿天竺寺','严维','中唐','方外主人名道林，
怕将水月净身心。
居然对我说无我，
寂历山深将夜深。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1270','答刘长卿七里濑重送','严维','中唐','新安非欲枉帆过，
海内如君有几何。
醉里别时秋水色，
老人南望一狂歌。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1271','一公新泉','严维','中唐','山下新泉出，
泠泠北去源。
落池才有响，
喷石未成痕。
独映孤松色，
殊分众鸟喧。
唯当清夜月，
观此启禅门。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1272','九日陪崔郎中北山宴','严维','中唐','上客南台至，
重阳此会文。
菊芳寒露洗，
杯翠夕阳曛。
务简人同醉，
溪闲鸟自群。
府中官最小，
唯有孟参军。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1273','九日登高','严维','中唐','诗家九日怜芳菊，
迟客高斋瞰浙江。
汉浦浪花摇素壁，
西陵树色入秋窗。
木奴向熟悬金实，
桑落新开泻玉缸。
四子醉时争讲德，
笑论黄霸屈为邦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1274','九月十日即事','严维','中唐','家贫惟种竹，
时幸故人看。
菊度重阳少，
林经闰月寒。
宿酲犹落帽，
华发强扶冠。
美景良难得，
今朝更尽欢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1275','书情献相公','严维','中唐','年来白发欲星星，
误却生涯是一经。
魏阙望中何日见，
商歌奏罢复谁听。
孤根独弃惭山木，
弱质无成状水萍。
今日更须询哲匠，
不应休去老岩扃。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1276','示外生','严维','中唐','牵役非吾好，
宽情尔在傍。
经过悲井邑，
起坐倦舟航。
相宅生应贵，
逢时学可强。
无轻吾未用，
世事有行藏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1277','同韩员外宿云门寺','严维','中唐','小岭路难近，
仙郎此夕过。
潭空观月定，
涧静见云多。
竹翠烟深锁，
松声雨点和。
万缘俱不有，
对境自垂萝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1278','自云阳归晚泊陆澧宅','严维','中唐','天阴行易晚，
前路故人居。
孤棹所思久，
寒林相见初。
闲灯忘夜水，
清漏任更疏。
明发还须去，
离家几岁除。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1279','馀姚祗役奉简鲍参军','严维','中唐','童年献赋在皇州，
方寸思量君与侯。
万事无成新白首，
两春虚掷对沧流。
歌诗盛赋文星动，
箫管新亭晦日游。
知己欲依何水部，
乡人今正贱东丘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1280','咏孩子','严维','中唐','嘉客会初筵，
宜时魄再圆。
众皆含笑戏，
谁不点颐怜。
绣被花堪摘，
罗绷色欲妍。
将雏有旧曲，
还入武城弦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1281','奉和皇甫大夫夏日游花严寺','严维','中唐','初第华严会，
王家少长行。
到宫龙节驻，
礼塔雁行成。
莲界千峰静，
梅天一雨清。
禅庭未可恋，
圣主寄苍生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1282','秋日与诸公文会天寺','严维','中唐','相访从吾道，
因缘会尔时。
龙盘馀帝宅，
花界古人祠。
明月虚空色，
青林大小枝。
还将经济学，
来问道安师。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1283','秋夜船行','严维','中唐','扁舟时属暝，
月上有馀辉。
海燕秋还去，
渔人夜不归。
中流何寂寂，
孤棹也依依。
一点前村火，
谁家未掩扉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1284','荆溪馆呈丘义兴','严维','中唐','失路荆溪上，
依人忽暝投。
长桥今夜月，
阳羡古时州。
野烧明山郭，
寒更出县楼。
先生能馆我，
无事五湖游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1285','送少微上人东南游','严维','中唐','旧游多不见，
师在翟公门。
瘴海空山热，
雷州白日昏。
片心应为法，
万里独无言。
人尽酬恩去，
平生未感恩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1286','送李秘书往儋州','严维','中唐','魑魅曾为伍，
蓬莱近拜郎。
臣心瞻北阙，
家事在南荒。
莎草山城小，
毛洲海驿长。
玄成知必大，
宁是泛沧浪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1287','送房元直赴北京','严维','中唐','犹道楼兰十万师，
书生匹马去何之。
临歧未断归家目，
望月空吟出塞诗。
常欲激昂论上策，
不应憔悴老明时。
遥知到日逢寒食，
彩笔长裾会晋祠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1288','送舍弟','严维','中唐','疏懒吾成性，
才华尔自彊。
早称眉最白，
何事绶仍黄。
时暑嗟于迈，
家贫念聚粮。
秪应宵梦里，
诗兴属池塘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1289','送桃岩成上人归本寺','严维','中唐','长老归缘起，
桃花忆旧岩。
清晨云抱石，
深夜月笼杉。
道具门人捧，
斋粮谷鸟衔。
馀生愿依止，
文字欲三缄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1290','送崔峒使往睦州兼寄薛司户','严维','中唐','如今相府用英髦，
独往南州肯告劳。
冰水近开渔浦出，
雪云初卷定山高。
木奴花映桐庐县，
青雀舟随白露涛。
使者应须访廉吏，
府中惟有范功曹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1291','送薛尚书入蜀','严维','中唐','卑情不敢论，
拜首入辕门。
列郡诸侯长，
登朝八座尊。
凝笳临水发，
行旆向风翻。
几许遗黎泣，
同怀父母恩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1292','送薛居士和州读书','严维','中唐','孤云独鹤共悠悠，
万卷经书一叶舟。
楚地巢城民舍少，
烟村社树鹭湖秋。
蒿莱织妾晨炊黍，
隅落耕童夕放牛。
年少不应辞苦节，
诸生若遇亦封侯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1293','夏日纳凉','严维','中唐','山阴过野客，
镜里接仙郎。
盥漱临寒水，
褰闱入夏堂。
杉松交日影，
枕簟上湖光。
衮衮承嘉话，
清风纳晚凉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1294','留别邹绍刘长卿','严维','中唐','中年从一尉，
自笑此身非。
道在甘微禄，
时难耻息机。
晨趋本郡府，
书掩故山扉。
待见干戈毕，
何妨更采薇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1295','陪皇甫大夫谒禹庙','严维','中唐','竹使羞殷荐，
松龛拜夏祠。
为鱼歌德后，
舞羽降神时。
文卫瞻如在，
精灵信有期。
夕阳陪醉止，
塘上鸟咸迟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1296','宿法华寺','严维','中唐','一夕雨沈沈，
哀猿万木阴。
天龙来护法，
长老密看心。
鱼梵空山静，
纱灯古殿深。
无生久已学，
白发浪相侵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1297','晦日宴游','严维','中唐','晦日湔裾俗，
春楼致酒时。
出山还已醉，
谢客旧能诗。
溪柳薰晴浅，
岩花待闰迟。
为邦久无事，
比屋自熙熙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1298','游荆溪','严维','中唐','铜官之山溪水南，
周处庙前多夕岚。
看捲云帆歌白苧，
劝尝春酒破黄柑。
长林独往谁能觅，
幽事相关性所耽。
若欲避喧那畏虎，
尚从地主结松龛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1299','酬王侍御西陵渡见寄','严维','中唐','前年万里别，
昨日一封书。
郢曲西陵渡，
秦官使者车。
柳塘薰昼日，
花水溢春渠。
若不嫌鸡黍，
先令扫弊庐。',NULL,'[{"Book": "《近体秋阳》", "Section": null, "Content": "结束紧跟颈联，轻逸风致，妙。“令”字骤读之，殊觉意思不出，熟味之煞有韵致，不冷淡、不逢迎，使二句望友临况之情婉转逼露。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《近体秋阳》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1300','酬刘员外见寄','严维','中唐','苏耽佐郡时，
近出白云司。
药补清羸疾，
窗吟绝妙词。
柳塘春水慢，
花坞夕阳迟。
欲识怀君意，
明朝访楫师。',NULL,'[{"Book": "《六一诗话》", "Section": null, "Content": "若严维“柳塘春水漫，花坞夕阳迟”，则天容时态，融和骀荡，岂不如在目前乎？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《六一诗话》"}, {"Book": "《中山诗话》", "Section": null, "Content": "人多取佳句为句图，特小巧美丽可喜，皆指咏风景，影似万物者尔，不得见雄材远思之人也。梅圣俞爱严维诗曰：“柳塘春水漫，花坞夕阳迟。”固善矣，细较之，“夕阳迟”则系花，“春水漫”何须柳也？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《中山诗话》"}, {"Book": "《观林诗话》", "Section": null, "Content": "颜鲁公云“夕照明村树”，僧清塞云“夕照显重山”，顾非熊云“斜日晒林桑”，杜牧云“落口羡楼台”，半山云“返照媚林塘”，皆不若严维“花坞夕阳迟”也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《观林诗话》"}, {"Book": "《瀛奎律髓》", "Section": null, "Content": "五、六全于“漫”字上、“迟”字上用工。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓》"}, {"Book": "《唐诗摘钞》", "Section": null, "Content": "三、四不但写其才调，并文房丰神都为绘出。五、六作二景语，见己之对景相怀也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗摘钞》"}, {"Book": "《瀛奎律髓汇评》", "Section": null, "Content": "纪昀：“漫”乃春融而水涨之貌。俗本讹为“慢”字，非惟合掌，亦令全句少味。然宋人诗话已作“慢”字，则其讹久矣。查慎行：五、六全于第五字用意。何义门：测水痕，候日影，五、六正含落句，不徒为体日景物语，故韵味深。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《瀛奎律髓汇评》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1301','酬耿拾遗题赠','严维','中唐','掩扉常自静，
驿吏忽传呼。
水巷惊驯鸟，
藜床起病躯。
顾身悲欲老，
戒子力为儒。
明日公西去，
烟霞复作徒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1302','酬诸公宿镜水宅','严维','中唐','幸免低头向府中，
贵将藜藿与君同。
阳雁叫霜来枕上，
寒山映月在湖中。
诗书何德名夫子，
草木推年长数公。
闻道汉家偏尚少，
此身那此访芝翁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1303','酬普选二上人期相会见寄','严维','中唐','本意宿东林，
因听子贱琴。
遥知大小朗，
已断去来心。
夜静溪声近，
庭寒月色深。
宁知尘外意，
定后便成吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1304','酬谢侍御喜王宇及第见贺不遇之作','严维','中唐','寂寞柴门掩，
经过柱史荣。
老夫宁有力，
半子自成名。
柳映三桥发，
花连上道明。
缄书到别墅，
郢曲果先成。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1305','僧房避暑','严维','中唐','支公好闲寂，
庭宇爱林篁。
幽旷无烦暑，
恬和不可量。
蕙风清水殿，
荷气杂天香。
明月谈空坐，
怡然道术忘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1306','赠万经','严维','中唐','万公长慢世，
昨日又隳官。
纵酒真彭泽，
论诗得建安。
家山伯禹穴，
别墅小长干。
辄有时人至，
窗前白眼看。',NULL,'[{"Book": "《近体秋阳》", "Section": null, "Content": "一起一结，写尽万钟人品。有此起结，于中随意写描，无不凌虚造极。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《近体秋阳》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1307','赠别至弘上人','严维','中唐','最称弘偃少，
早岁草茆居。
年老从僧律，
生知解佛书。
衲衣求坏帛，
野饭拾春蔬。
章句无求断，
时中学有馀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1308','赠送朱放','严维','中唐','昔年居汉水，
日醉习家池。
道胜迹常在，
名高身不知。
欲依天目住，
新自始宁移。
生事曾无长，
惟将白接䍦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1309','赠送崔子向','严维','中唐','旅食来江上，
求名赴洛阳。
新诗踪谢守，
内学似支郎。
行怯秦为客，
心依越是乡。
何人作知己，
送尔泪浪浪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1310','中元日鲍端公宅遇吴天师联句','严维','中唐','道流为柱史，
教戒下真仙。
共契中元会，
初修内景篇。
游方依地僻，
卜室喜墙连。
宝笥开金箓，
华池漱玉泉。
怪龙随羽翼，
青节降云烟。
昔去遗丹灶，
今来变海田。
养形奔二景，
鍊骨度千年。
骑竹投陂里，
携壶挂牖边。
洞中尝入静，
河上旧谈玄。
伊洛笙歌远，
蓬壶日月偏。
青骡蓟训引，
白犬伯阳牵。
法受相君后，
心存象帝先。
道成能缩地，
功满欲升天。
何意迷孤性，
含情恋数贤。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1311','奉和刘祭酒伤白马','严维','中唐','沛艾如龙马，
来从上苑中。
棣华恩见赐，
伯舅礼仍崇。
镜点黄金眼，
花开白雪騣。
性柔君子德，
足逸大王风。
色照鸣珂静，
声连喷玉雄。
食场恩未尽，
过隙命旋终。
练影依云没，
银鞍向月空。
仍闻乐府唱，
犹念代劳功。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1312','奉和独孤中丞游云门寺','严维','中唐','绝壑开花界，
耶溪极上源。
光辉三独坐，
登陟五云门。
深木鸣驺驭，
晴山曜武贲。
乱泉观坐卧，
疏磬发朝昏。
苍翠新秋色，
莓苔积雨痕。
上方看度鸟，
后夜听吟猿。
异迹焚香对，
新诗酌茗论。
归来还抚俗，
诸老莫攀辕。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1313','奉和皇甫大夫祈雨应时雨降','严维','中唐','致和知必感，
岁旱未书灾。
伯禹明灵降，
元戎祷请来。
九成陈夏乐，
三献奉殷罍。
掣曳旗交电，
铿锵鼓应雷。
行云依盖转，
飞雨逐车回。
欲识皇天意，
为霖贶在哉。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1314','奉试水精环','严维','中唐','王室符长庆，
环中得水精。
任圆循不极，
见素质仍贞。
信是天然瑞，
非因朴斲成。
无瑕胜玉美，
至洁过冰清。
未肯齐珉价，
宁同杂佩声。
能衔任黄雀，
亦欲应时明。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1315','剡中赠张卿侍御','严维','中唐','辟疆年正少，
公子贵初还。
早列月卿位，
新参柱史班。
千夫驰驿道，
驷马入家山。
深巷乌衣盛，
高门画戟闲。
逶迤天乐下，
照耀剡溪间。
自贱游章句，
空为衰草颜。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1316','哭灵一上人','严维','中唐','一公何不住，
空有远公名。
共说岑山路，
今时不可行。
旧房松更老，
新塔草初生。
经论传缁侣，
文章遍墨卿。
禅林枝干折，
法宇栋梁倾。
谁复修僧史，
应知传已成。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1317','题鲍行军小阁','严维','中唐','宇下无留事，
经营意独新。
文房已得地，
相阁是推轮。
席上招贤急，
山阴对雪频。
虚明先旦暮，
启闭异冬春。
谈笑兵家法，
逢迎幕府宾。
还将负暄处，
时借在阴人。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1318','赠别刘长卿时赴河南严中丞幕府','严维','中唐','早见登郎署，
同时迹下僚。
几年江路永，
今去国门遥。
文变骚人体，
官移汉帝朝。
望山吟度日，
接枕话通宵。
万里趋公府，
孤帆恨信潮。
匡时知已老，
圣代耻逃尧。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1319','一字至九字诗联句','严维','中唐','东，
西。
步月，
寻溪。
鸟已宿，
猿又啼。
狂流碍石，
迸笋穿溪。
望望人烟远，
行行萝径迷。
探题只应尽墨，
持赠更欲封泥。
松下流时何岁月，
云中幽处屡攀跻。
乘兴不知山路远近，
缘情莫问日过高低。
静听林下潺潺足湍濑，
厌问城中喧喧多鼓鼙。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1320','入唐溪','严维','中唐','啸终万籁起，
吹去当溪云。
环屿或明昧，
远峰尚氛氲。
雨新翠叶发，
夜早玄象分。
金涧流不尽，
入山深更闻。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1321','书情上李苏州','严维','中唐','东土苗人尚有残，
皇皇亚相出朝端。
手持国宪群僚畏，
口喻天慈百姓安。
礼数自怜今日绝，
风流空计往年欢。
误著青袍将十载，
忍令渔浦却垂竿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1322','忆长安 五月','严维','中唐','忆长安，
五月时，
君王避暑华池。
进膳甘瓜朱李，
续命芳兰䌽丝。
竞处高明台榭，
槐阴柳色通逵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1323','酒语联句各分一字','严维','中唐','山简酣歌倒接䍦，
看朱成碧无所知。
耳鸣目眩驷马驰，
口称童羖腹鸱夷。
兀然落帽灌酒卮，
太常吏部相对时。
藉糟枕曲浮酒池，
瓮间篱下卧不移。
叫呼不应无事悲，
千日一醒知是谁。
左倾右倒人避之。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1324','游灞陵山','严维','中唐','入山未尽意，
胜迹聊独寻。
方士去在昔，
药堂留至今。
四隅白云闲，
一路清溪深。
芳秀惬春目，
高闲宜远心。
潭分化丹水，
路绕升仙林。
此道人不悟，
坐鸣松下琴。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1325','荅刘长卿蛇浦桥月下重送','严维','中唐','月色今宵最明，
庭闲夜久天清。
寂寞多年老宦，
殷勤远别深情。
溪临修竹烟色，
风落高梧雨声。
耿耿相看不寐，
遥闻晓柝山城。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_2_1326','句','严维','中唐','观身岸额离根草，
论命江头不系舟。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1327','句','严维','中唐','五色惊䌽凤，
千里象骢威。
三伏轩车动，
尧心急谏官。
名通内籍贵，
立近御床寒。
波从少海息，
云自大风开。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1328','剑诗','严维','中唐','舞挥秦日月，
为整汉山河。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1329','赠王叔雅兄弟','严维','中唐','万里天连水，
孤舟弟与兄。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1330','望夫石','严郾','唐','何代提戈去不还，
独留形影白云间。
肌肤销尽雪霜色，
罗绮点成苔藓斑。
江燕不能传远信，
野花空解妒愁颜。
近来岂少征人妇，
笑采蘼芜上北山。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1331','赋百舌鸟','严郾','唐','此禽轻巧少同伦，
我听长疑舌满身。
星未没河先报晓，
柳犹黏雪便迎春。
频嫌海燕巢难定，
却讶林莺语不真。
莫倚春风便多事，
玉楼还有晏眠人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1332','闻鹿鸣互谑','严震','唐','釜戴山中鹿又鸣，
此际多应到表兄。
表兄不是严家子，
合是三兄与四兄。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1333','别宋侍御','严嶷','唐','水国南连楚，
沙场北近胡。
春风万里别，
明月两乡孤。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1334','送贺秘监归会稽诗','何千里','唐','锡鼎升天几万春，
裔孙今复出嚣尘。
姓名当系上清箓，
齿发不知何代人？
暂应客星过世主，
旋归吴市作遗民。
辽东鹤驾忽飞去，
挥手无言辞紫宸。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1335','看花','何玄','唐','莫怪出门先骤马，
暮年常怨看花迟。
可怜尽日春山下，
似雪如云一万枝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1336','句','何玄','唐','一望白云千万断，
筝声日暮出花林。
门外夕阳寒映竹，
洞中秋水暗连山。
钟声半夜香山雨，
散入前林枫叶秋。
寺临飞鸟青山远，
径转幽萝白日长。
黄昏人到钟声里，
云起龙池不见山。
客来惆怅僧禅后，
月出松门满地霜。
朔风寒日笳声急，
万里辽城一段云。
满山月色连溪下，
林叶萧萧一夜霜。
秦客访花惊出洞，
庾公看月误登楼。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1337','所居寺院凉夜书情呈上吕和叔温郎中','何元上','唐','庾公念病宜清暑，
遣向僧家占上方。
月光似水衣裳湿，
松气如秋枕簟凉。
幸以薄才当客次，
无因弱羽逐鸾翔。
何由一示云霄路，
肠断星星两鬓霜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1338','李皋试诗','何仲举','五代','似玉来投狱，
抛家去就枷。
可怜两片木，
夹却一枝花。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1339','句','何仲举','五代','碧云章句才离手，
紫府神仙尽点头。
树迎高鸟归深野，
云傍斜阳过远山。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1340','七夕赋咏成篇','何仲宣','唐','日日思归勤理鬓，
朝朝伫望懒调梭。
凌风宝扇遥临月，
映水仙车远渡河。
历历珠星疑拖佩，
冉冉云衣似曳罗。
通宵道意终无尽，
向晓离愁已复多。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1341','赠兄','何兆','唐','洛阳纸价因兄贵，
蜀地红笺为弟贫。
南北东西九千里，
除兄与弟更无人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1342','句','何兆','唐','芙蓉十二池心漏，
薝卜三千灌顶香。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1343','次韵答阳刺史城','何坚','唐','素履衡门秉直忠，
挂冠金阙回江东。
戢羽应知非健翮，
守雌或可谓知雄。
午夜鸣琴餐玄露，
深山弄月友赤松。
多感君侯欢导引，
临流遣兴醉碧筒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1344','除授太学国子监司籍之职因赋','何坚','唐','九重天子重英豪，
御殿传恩赐绿袍。
乐道直欲学商尹，
致君恒切佐唐尧。
琼林日照宫花灿，
金榜风摇姓字高。
幸荷召颁入太学，
相期联步觐天朝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1345','一枝花','何希尧','唐','几树晴葩映水开，
乱红狼籍点苍苔。
东风留得残枝在，
为惜馀芳独看来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1346','柳枝词','何希尧','唐','大堤杨柳雨沈沈，
万缕千条惹恨深。
飞絮满天人去远，
东风无力系春心。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_2_1347','海棠','何希尧','唐','著雨胭脂点点消，
半开时节最妖娆。
谁家更有黄金屋，
深锁东风贮阿娇。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1348','操莲曲','何希尧','唐','锦莲浮处水粼粼，
风外香生袜底尘。
荷叶荷裙相映色，
闻歌不见采莲人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1349','寄旧同年','何扶','唐','金榜题名墨尚新，
今年依旧去年春。
花间每被红妆问，
何事重来只一人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1350','送阆州妓人归老','何扶','唐','竹翠婵娟草径幽，
佳人归老傍汀洲。
玉蟾露冷梁尘暗，
金凤花开云鬓秋。
十亩稻香新绿野，
一声歌断旧青楼。
芭蕉半卷西池雨，
日暮门前双白鸥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1351','戏为举子对句','何承裕','后晋','晓来犬吠张三妇，
日暮猿啼吕四妻。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1352','题杨克俭池馆','何昌龄','南唐','经旬因雨不重来，
门有蛛丝径有苔。
再向白莲亭上望，
不知花木为谁开。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1353','句','何涓','唐','雁影数行秋半逢，
渔歌一声夜深发。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1354','赋得骨','李梦唐','当代','生时强项死随尘，
谁识千年冢内人。
莫笑书生能曲笔，
须从曲笔见嶙峋。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1355','郊庙歌辞 祭汾阴乐章 舒和','何鸾','唐','乐奏云阕，
礼章载虔。
禋宗于地，
昭假于天。
惟馨荐矣，
既醉歆焉。
神之降福，
永永万年。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_2_1356','题吉州龙溪','何敬','唐','龙溪之山秀而峙，
龙溪之水清无底。
狂风激烈翻春涛，
薄雾冥濛溢清泚。
奔流百折银河通，
落花滚滚浮霞红。
四时佳境不可穷，
彷佛直与桃源通。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1357','墙阴残雪','何频瑜','唐','积雪还因地，
墙阴久尚残。
影添斜月白，
光借夕阳寒。
皎洁开帘近，
清荧步履看。
状花飞著树，
如玉不成盘。
冰薄方宁及，
霜浓比亦难。
谁怜高卧处，
岁暮叹袁安。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1358','亚父碎玉斗','何儒亮','唐','嬴女昔解网，
楚王有遗躅。
破关既定秦，
碎首闻献玉。
贞姿应刃散，
清响因风续。
匪徇切泥功，
将明怀璧辱。
莫量汉祖德，
空受项君勖。
事去见前心，
千秋渭水绿。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1359','书事','何赞','唐末至五代','果决生涯向路中，
西投知己话从容。
云遮剑阁三千里，
水隔瞿塘十二峰。
阔步文翁坊里月，
闲寻杜老宅边松。
到头须卜林泉隐，
自愧无能继卧龙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1360','奉赠叶□郎新湖诗','余鼎','唐','赏眺新湖趣，
澄漪写物华。
采蘋经绿溆，
垂钓倚枯槎。
水动鱼惊鸟，
风摇蝶□花。
宛然登兴处，
宁羡武陵家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1361','越溪怨','冷朝光','唐','越王宫里如花人，
越水溪头采白蘋。
白蘋未尽人先尽，
谁见江南春复春。',NULL,'[{"Book": "《升庵诗话》", "Section": null, "Content": "朝光诗仅此一首，亦奇作也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《升庵诗话》"}, {"Book": "《唐诗镜》", "Section": null, "Content": "绝快，绝隽。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗镜》"}, {"Book": "《唐诗归》", "Section": null, "Content": "钟云：说得废然，读不得（末二句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1362','送红线','冷朝阳','唐','采菱歌怨木兰舟，
送客魂销百尺楼。
还似洛妃乘雾去，
碧天无际水空流。',NULL,'[{"Book": "《甘泽谣》", "Section": null, "Content": "（红线本潞州节度使薛嵩青衣，后为薛嵩解难后，欲飘然远去。）嵩知不可驻，乃广为饯别，悉集宾客，夜宴中堂。嵩以歌送红线，请座客冷朝阳为词曰：“采菱歌怨木兰舟，送客魂销百尺楼。还似洛妃乘雾去，碧天无际水空流。”歌毕，嵩不胜悲。红线拜且泣，因伪醉离席，遂亡其所在。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《甘泽谣》"}, {"Book": "《升庵诗话》", "Section": null, "Content": "红线，薛嵩之青衣也。有剑术，夜飞入横海军解围，嵩留之不得，会幕下诗人送之，冷朝阳此诗为冠。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《升庵诗话》"}, {"Book": "《唐诗选脉会通评林》", "Section": null, "Content": "杨慎列为神品。周珽曰：语意天然，有响遏行云之态。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选脉会通评林》"}, {"Book": "《大历诗略》", "Section": null, "Content": "词调极佳、渔洋诸绝句所本。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《大历诗略》"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1363','中秋与空上人同宿华严寺','冷朝阳','唐','埽榻相逢宿，
论诗旧梵宫。
磬声迎鼓尽，
月色过山穷。
庭簇安禅草，
窗飞带火虫。
一宵何惜别，
回首隔秋风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1364','冬日逢冯法曹话怀','冷朝阳','唐','分襟二年内，
多少事相干。
礼乐风全变，
尘埃路渐难。
秋林新叶落，
霜月满庭寒。
虽喜逢知己，
他乡岁又阑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1365','同张深秀才游华严寺','冷朝阳','唐','同游云外寺，
渡水入禅关。
立埽窗前石，
坐看池上山。
有僧飞锡到，
留客话松间。
不是缘名利，
好来长伴闲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1366','别郎上人','冷朝阳','唐','过云寻释子，
话别更依依。
静室开来久，
游人到自稀。
触风香气尽，
隔水磬声微。
独傍孤松立，
尘中多是非。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1367','送远上人归京','冷朝阳','唐','夏腊岁方深，
思归彻曙吟。
未离销雪院，
已有过云心。
寒磬清函谷，
孤钟宿华阴。
别京游旧寺，
月色似双林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1368','送唐六赴举','冷朝阳','唐','秋色生边思，
送君西入关。
草衰空大野，
叶落露青山。
故国烟霞外，
新安道路间。
碧霄知己在，
香桂月中攀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1369','宿柏岩寺','冷朝阳','唐','幽寺在岩中，
行唯一径通。
客吟孤峤月，
蝉噪数枝风。
秋色生苔砌，
泉声入梵宫。
吾师修道处，
不与世间同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1370','瀑布泉','冷朝阳','唐','潺湲半空里，
霖落石房边。
风激珠光碎，
山欹练影偏。
急流难起浪，
迸沫祗如烟。
自古惟今日，
凄凉一片泉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1371','立春','冷朝阳','唐','玉律传佳节，
青阳应此辰。
土牛呈岁稔，
䌽燕表年春。
腊尽星回次，
寒馀月建寅。
风光行处好，
云物望中新。
流水初销冻，
潜鱼欲振鳞。
梅花将柳色，
偏思越乡人。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1372','讥韦玎吟以韦字为韵','利涉','唐','我之佛法是无为，
何故今朝得有为。
无韦始得三数载，
不知此复是何韦。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1373','咏痴','吴人','唐','榆儿复榆妇，
造屋兼造车。
十七八九夜，
还书复借书。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1374','饮后献时相','吴士矩','唐','一夕心期一种欢，
那知疏散负杯盘。
尊前数片朝云在，
不许冯公子细看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1375','独酌谣','吴士矩','唐','愚夫子不招。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1376','赠元微之','吴士矩','唐','永惭沾药犬，
多谢出囊锥。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1377','捣衣','吴大江','唐','沙塞秋应晚，
金闺恨已空。
那堪裂纨素，
时许出房栊。
杵影弄寒月，
砧声调夜风。
裁缝双泪尽，
万里寄云中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1378','留观中诗二首','吴子来','唐','此生此物当生涯，
白石青松便是家。
对月卧云如野鹿，
时时买酒醉烟霞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1379','留观中诗二首','吴子来','唐','终日草堂间，
清风常往还。
耳无尘事扰，
心有玩云闲。
对酒惟思月，
餐松不厌山。
时时吟内景，
自合驻童颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1380','赋得玉水记方流','吴丹','中唐','玉泉何处记，
四折水纹浮。
润下宁踰矩，
居方在上流。
映空虚漾漾，
涵白净悠悠。
影碎疑冲斗，
光清耐触舟。
圭璋分辨状，
沙砾共怀柔。
愿赴朝宗日，
萦回入御沟。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1381','凤仙花','吴仁璧','五代','香红嫩绿正开时，
冷蝶饥蜂两不知。
此际最宜何处看，
朝阳初上碧梧枝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1382','金钱花','吴仁璧','五代','浅绛浓香几朵匀，
日镕金铸万家新。
堪疑刘宠遗芳在，
不许山阴父老贫。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1383','南徐题友人郊居','吴仁璧','五代','门前樵径连江寺，
岸下渔矶系海槎。
待到秋深好时节，
与君长醉隐侯家。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1384','客路','吴仁璧','五代','人寰急景如波委，
客路浮云似盖轻。
回首故山天外碧，
十年无计却归耕。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1385','春雪','吴仁璧','五代','雪霁凝光入坐寒，
天明犹自卧袁安。
貂裘穿后鹤氅敝，
自此风流不足看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1386','秋日听僧弹琴','吴仁璧','五代','金徽玉轸韵泠然，
言下浮生指下泉。
恰称秋风西北起，
一时吹入碧湘烟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1387','衰柳','吴仁璧','五代','金风渐利露珠团，
广陌长堤黛色残。
水殿狂游隋炀帝，
一千馀里可堪看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1388','读度人经寄郑仁表','吴仁璧','五代','身虽一旦尘中老，
名拟三清会里题。
二午九斋馀日在，
请君相伴醉如泥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1389','贾谊','吴仁璧','五代','扶持一疏满遗编，
汉陛前头正少年。
谁道恃才轻绛灌，
却将惆怅吊湘川。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1390','钱塘鹤','吴仁璧','五代','人间路霭青天半，
鳌岫云生碧海涯。
虽抱雕笼密扃钥，
可能长在叔伦家。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1391','投谢钱武肃','吴仁璧','五代','东门上相好知音，
数尽台前郭隗金。
累重虽然容食椹，
力微无计报焚林。
弊貂不称芙蓉幕，
衰朽仍惭玳瑁簪。
十里溪光一山月，
可堪从此负归心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1392','句','吴仁璧','五代','为惜苔钱妨换砌，
因怜山色旋开尊。
高阁烟霞禅客睡，
满城尘土世人忙。
五龙金角向星斗，
三洞玉音愁鬼神。
蒲草薄裁连蒂白，
胭脂浓染半葩红。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1393','绝句','吴公','唐末','去国投兹土，
编茅隐旧踪。
年年秋水上，
独对数株松。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1394','古意','吴少微','初唐','洛阳芳树向春开，
洛阳女儿平旦来。
流车走马纷相催，
折芳瑶华向曲台。
曲台自有千万行，
重花累叶间垂杨。
北林朝日境明光，
南国微风苏合香。
可怜窈窕女，
不作邯郸娼。
妙舞轻回拂长袖，
高歌浩唱发清商。
歌终舞罢欢无极，
乐往悲来长叹息。
阳春白日不少留，
红荣碧树无颜色。
碧树风花先春度，
珠帘粉泽无人顾。
如何年少忽迟暮，
坐见明月与白露。
明月白露夜已寒，
香衣锦带空珊珊。
今日阳春一妙曲，
凤皇楼上与君弹。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1395','和崔侍御日用游开化寺阁','吴少微','初唐','左宪多才雄，
故人尤鸷鹗。
护赠单于使，
休轺太原郭。
馆次厌烦歊，
清怀寻寂寞。
西缘十里馀，
北上开化阁。
初入云树间，
冥蒙未昭廓。
渐出栏榥外，
万里秋景焯。
岁晏风落山，
天寒水归壑。
览物颂幽景，
三乘动玄钥。
但敷利解言，
永用忘昏著。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1396','满城中山靖王墓','李梦唐','当代','美穴佳陵信有之，
西来岳色不堪持。
黄泉犹爱黄金缕，
世上应多卖履儿。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1397','相和歌辞 长门怨','吴少微','初唐','月出映曾城，
孤圜上太清。
君王春爱歇，
枕席凉风生。
怨咽不能寝，
踟蹰步前楹。
空阶白露色，
百草寒虫鸣。
念昔金房里，
犹嫌玉座轻。
如何娇所误，
长夜泣恩情。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1398','相和歌辞 怨歌行','吴少微','初唐','城南有怨妇，
含怨倚兰丛。
自谓二八时，
歌舞入汉宫。
皇恩弄幸玉堂中。
绿陌黄花催夜酒，
锦衣罗袂逐春风。
建章西宫焕若神，
燕赵美女二千人。
君王厌德不忘新，
况群艳冶纷来陈。
是时别君不再见，
三十三春长信殿。
长信重门昼掩关，
清房晓帐幽且闲。
绮窗虫网氛尘色，
文轩莺对桃李颜。
天王贵宫不贮老，
浩然泪陨今来还。
自怜转晚暮，
试逐佳游芳草路。
小腰丽女夺人奇，
金鞍少年曾不顾。
归来谁为夫。
请谢西家妇，
莫辞先醉解罗襦。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1399','哭富嘉谟','吴少微','初唐','吾友适不死，
于戏社稷臣。
直禄非造利，
长怀大庇人。
乃通承明籍，
遘此敦牂春。
药厉其可畏，
皇穹故匪仁。
畴昔与夫子，
孰云异天伦。
同病一相失，
茫茫不重陈。
子之文章在，
其殆尼父新。
鼓兴斡河岳，
贞词毒鬼神。
可悲不可朽，
车輤没荒榛。
圣主贤为宝，
吁兹大国贫。',NULL,'','{"preface": "维三月癸丑，河南富嘉谟卒。予时寝疾于洛阳北里，闻之，投枕而起，泪沾乎衽席。匍匐于寝门之外，病不能哭，仰天而呼曰：「天乎天乎！俾予曷所朋，曷有律，曷可得而见？抑斯文也以存乎哀。太常少卿徐公、鄜州刺史尹公、中书徐元二舍人、兵部张郎中，未尝值我不叹于朝。夫情悼之赋诗，以宠亡也。」其词曰。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1400','咏史','李梦唐','当代','高阁垂裳调鼎时，
可怜天下有微词。
覆舟水是苍生泪，
不到横流君不知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1401','白云溪','吴巩','唐','山径入修篁，
深林蔽日光。
夏云生嶂远，
瀑水引溪长。
秀迹逢皆胜，
清芬坐转凉。
回看玉樽夕，
归路赏前忘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1402','言行相顾','吴叔达','唐','圣人垂政教，
万古请常传。
立志言为本，
修身行乃先。
相须宁得阙，
相顾在无偏。
荣辱当于己，
忠贞必动天。
大名如副宝，
至道亦通玄。
千里犹能应，
何云迩者焉。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1403','题路左佛堂','吴武陵','中唐','雀儿来逐飏风高，
下视鹰鹯意气豪。
自谓能生千里翼，
黄昏依旧委蓬蒿。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1404','贡院楼北新栽小松','吴武陵','中唐','拂槛爱贞容，
移根自远峰。
已曾经草没，
终不任苔封。
叶少初陵雪，
鳞生欲化龙。
乘春濯雨露，
得地近垣墉。
逐吹香微动，
含烟色渐浓。
时回日月照，
为谢小山松。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1405','答李曜','吴圆','唐','曳履优容日日欢，
须言达德倍汍澜。
韶光今已输先手，
领得蠙珠掌上看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1406','鱼上冰','吴晃','唐','春水潜鳞发，
寒潭旧藻疏。
扬鬐顺气后，
振鬣上冰初。
戏广怜空洁，
浮清媚景虚。
戒贪还避饵，
思达每怀书。
湿映流澌薄，
狂游触浪馀。
终希泮涣泽，
为化北溟鱼。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1407','相和歌辞 铜雀妓','吴烛','唐','秋色西陵满绿芜，
繁弦急管彊欢娱。
长舒罗袖不成舞，
却向风前承泪珠。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1408','风光草际浮','吴秘','唐','草色春沙里，
风光晓正幽。
轻明摇不散，
郁昱丽仍浮。
吹缓苗难转，
晖闲叶本柔。
碧凝烟彩入，
红是日华流。
耐可披襟对，
谁应满掬收。
恭闻掇芳客，
为此尚淹留。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_2_1409','水楼感事','吴商浩','唐','高柳螀啼雨后秋，
年光空感泪如流。
满湖菱荇东归晚，
闲倚南轩尽日愁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1410','泊舟','吴商浩','唐','身逐烟波魂自惊，
木兰舟上一帆轻。
云中有寺在何处，
山底宿时闻磬声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1411','秋塘晓望','吴商浩','唐','钟尽疏桐散曙鸦，
故山烟树隔天涯。
西风一夜秋塘晓，
零落几多红藕花。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1412','湘云','吴商浩','唐','□满湘江云莹空，
纷纷长对水溶溶。
日西遥望自归处，
尽挂九疑千万峰。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1413','长安春赠友人','吴商浩','唐','繁华堪泣帝城春，
粉堞青楼势碍云。
花对玉钩帘外发，
歌飘尘土路边闻。
几多远客魂空断，
何处王孙酒自醺。
各有归程千万里，
东风时节恨离群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1414','北邙山','吴商浩','唐','北邙山草又青青，
今日销魂事可明。
绿酒醉来春未歇，
白杨风起柳初晴。
冈原旋葬松新长，
年代无人阙半平。
堪取金炉九还药，
不能随梦向浮生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1415','巫峡听猿','吴商浩','唐','巴江猿啸苦，
响入客舟中。
孤枕破残梦，
三声随晓风。
连云波澹澹，
和雾雨濛濛。
巫峡去家远，
不堪魂断空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1416','宿山驿','吴商浩','唐','文战何堪功未图，
又驱羸马指天衢。
露华凝夜渚莲尽，
月彩满轮山驿孤。
岐路辛勤终日有，
乡关音信隔年无。
好同范蠡扁舟兴，
高挂一帆归五湖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1417','塞上即事','吴商浩','唐','身似星流迹似蓬，
玉关孤望杳溟濛。
寒沙万里平铺月，
晓角一声高捲风。
战士殁边魂尚哭，
单于猎处火犹红。
分明更想残宵梦，
故国依然在甬东。',NULL,'[{"Book": "《近体秋阳》", "Section": null, "Content": "此诗浩绽壮往，里有符句之累，而不损体气。收结虚怆缭绕，好。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《近体秋阳》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1418','歌','吴彩鸾','唐','若能相伴陟仙坛，
应得文箫驾䌽鸾。
自有绣襦并甲帐，
瑶台不怕雪霜寒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1419','上升歌','吴涵虚','唐末至五代','玉皇有诏登仙职，
龙吐云兮凤著力。
眼前蓦地见楼台，
异草奇花不可识。
我向大罗观世界，
世界即如指掌大。
当时不为上升忙，
一时提向瀛洲卖。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1420','仙诗五首','吴清妻','唐','道启真心觉渐清，
天教绝粒应精诚。
云外仙歌笙管合，
花间风引步虚声。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1421','仙诗五首','吴清妻','唐','□□□□□□□，
□君隐处当一星。
□□莲花山头饭，
黄精仙人掌上经。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1422','仙诗五首','吴清妻','唐','飞鸟莫到人莫攀，
一隐十年不下山。
袖中短书谁为达，
华山道士卖药还。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1423','仙诗五首','吴清妻','唐','日落焚香坐醮坛，
庭花露湿渐更阑。
净水仙童调玉液，
春宵羽客化金丹。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1424','仙诗五首','吴清妻','唐','摄念精思引彩霞，
焚香虚室对烟花。
道合云霄游紫府，
湛然真境瑞皇家。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1425','少年行','吴豸之','唐','承恩借猎小平津，
使气常游中贵人。
一掷千金浑是胆，
家无四壁不知贫。',NULL,'[{"Book": "《唐诗直解》", "Section": null, "Content": "妙在“浑是”两字。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗直解》"}, {"Book": "《唐诗广选》", "Section": null, "Content": "当与杜“马上谁家白面郎”并看。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗广选》"}, {"Book": "《唐诗选脉会通评林》", "Section": null, "Content": "周敬曰：极尽侠少行径，亦此题绝唱。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选脉会通评林》"}]','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1426','阳春歌','吴豸之','唐','帘低晓露湿，
帘捲莺声急。
欲起把箜篌，
如凝䌽弦涩。
孤眠愁不转，
点泪声相及。
净扫阶上花，
风来更吹入。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1427','巡衣锦军制还乡歌','钱镠','吴越','三节还乡兮挂锦衣，
碧天朗朗兮爱日晖。
功成道上兮列旌旗，
父老远来兮相追随。
家山乡眷兮会时稀，
今朝设宴兮觥散飞。
斗牛无孛兮民无欺，
吴越一王兮驷马归。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1428','没了期歌','钱镠','吴越','没了期，
没了期，
营基才了又仓基。
没了期，
没了期，
春衣才了又冬衣。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1429','句','钱镠','吴越','须将一片地，
付与有心人。
传语龙王并水府，
钱塘借与筑钱城。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1430','吊邓丽君墓三首','李梦唐','当代','筠园孤冢小沧桑，
旧日声名敌国倡。
海内今多歌舞地，
花前犹唱夜来香。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1431','吊邓丽君墓三首','李梦唐','当代','攻心战起用韩娥，
万户争传子夜歌。
绝似春莺来海上，
一声光复旧山河。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1432','吊邓丽君墓三首','李梦唐','当代','洗尽风尘曲更新，
偏安旧事等浮云。
我来一默焚香祷，
不吊英雄只吊君。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1433','游梅花山偶遇汪精卫墓两首','李梦唐','当代','孙陵在迩孝陵遐，
闻道斯人驻一嗟。
富士山边宜葬尔，
移棺何忍近梅花。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1434','游梅花山偶遇汪精卫墓两首','李梦唐','当代','作囚书诏两堪豪，
此后生涯似续貂。
假使当初燕市死，
声名应是压荆高。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1435','谒蓝毗尼佛祖诞生地','李梦唐','当代','浴佛池边一柱斜，
菩提静覆断垣花。
三千劫后灵何在，
只佑苍生不佑家。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1436','别章叟','吴筠','中唐','平昔同邑里，
经年不相思。
今日成远别，
相对心悽其。',NULL,'[{"Book": "《升庵诗话》", "Section": null, "Content": "余又记羽士吴筠《别章叟》一首……能道人情，亦前人未说破也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《升庵诗话》"}]','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1437','题华山人所居','吴筠','中唐','故人住南郭，
邀我对芳樽。
欢畅日云暮，
不知城市喧。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1438','题缙云岭永望馆','吴筠','中唐','人惊此路险，
我爱山前深。
犹恐佳趣尽，
欲行且沈吟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1439','舟中遇柳伯存归潜山因有此赠','吴筠','中唐','浇风久成俗，
真隐不可求。
何悟非所冀，
得君在扁舟。
目击道已存，
一笑遂忘言。
况观绝交书，
兼睹箴隐文。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1440','舟中遇柳伯存归潜山因有此赠','吴筠','中唐','见君浩然心，
视世如浮空。
君归潜山曲，
我复庐山中。
形间心不隔，
谁能嗟异同。
他日或相访，
无辞驭冷风。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1441','胡无人行','吴筠','中唐','剑头利如芒，
恒持照眼光。
铁骑追骁虏，
金羁讨黠羌。
高秋八九月，
胡地早风霜。
男儿不惜死，
破胆与君尝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1442','高士咏','吴筠','中唐','子真岩石下，
仲蔚蓬蒿居。
礼聘终不屈，
清贫长晏如。
心情在耕艺，
养寿资玄虚。
至乐非外物，
道冥欢有馀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1443','高士咏','吴筠','中唐','荷蓧隐耕艺，
晨门潜抱关。
道尊名可贱，
理惬心弥闲。
混迹是非域，
纵怀天地间。
同讥孔宣父，
匿景杳不还。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1444','高士咏','吴筠','中唐','高哉彼颜歜，
逸气陵齐宣。
道尊义不屈，
士重王来前。
荣禄安可诱，
保和从自然。
放情任所尚，
长揖归山泉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1445','同刘主簿承介建昌江泛舟作','吴筠','中唐','吾友从吏隐，
和光心杳然。
鸣琴正多暇，
啸侣浮清川。
风霁远澄映，
昭昭涵洞天。
坐惊众峰转，
乃觉孤舟迁。
崖屿非一状，
差池过目前。
徘徊白日暮，
月色江中鲜。
真兴殊未已，
滔滔且溯沿。
时歌沧浪曲，
或诵逍遥篇。
酣畅迷夜久，
迟迟方告旋。
此时无相与，
其旨在忘筌。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1446','元日言怀因以自励诒诸同志','吴筠','中唐','驰光无时憩，
加我五十年。
知非慕伯玉，
读易宗文宣。
经世匪吾事，
庶几唯道全。
谁言帝乡远，
自古多真仙。
馀滓永可涤，
秉心方杳然。
孰能无相与，
灭迹俱忘筌。
安用感时变，
当期升九天。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1447','舟中夜行','吴筠','中唐','榜人识江路，
挂席从宵征。
莫辨洲渚状，
但闻风波惊。
阴云正飘飖，
落月无光晶。
岂不畏艰险，
所凭在忠诚。
何时达遥夜，
伫见初日明。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1448','过天门山怀友','吴筠','中唐','举帆遇风劲，
逸势如飞奔。
缥缈凌烟波，
崩腾走川原。
两山夹沧江，
豁尔开天门。
须臾轻舟远，
想象孤屿存。
归路日已近，
怡然慰心魂。
所经多奇趣，
待与吾友论。
一日如三秋，
相思意弥敦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1449','听尹鍊师弹琴','吴筠','中唐','至乐本太一，
幽琴和乾坤。
郑声久乱雅，
此道稀能尊。
吾见尹仙翁，
伯牙今复存。
众人乘其流，
夫子达其源。
在山峻峰峙，
在水洪涛奔。
都忘迩城阙，
但觉清心魂。
代乏识微者，
幽音谁与论。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1450','步虚词十首','吴筠','中唐','众仙仰灵范，
肃驾朝神宗。
金景相照曜，
逶迤升太空。
七玄已高飞，
火鍊生珠宫。
馀庆逮天壤，
平和王道融。
八威清游气，
十绝舞祥风。
使我跻阳源，
其来自阴功。
逍遥太霞上，
真鉴靡不通。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1451','步虚词十首','吴筠','中唐','逸辔登紫清，
乘光迈奔电。
阆风隔三天，
俯视犹可见。
玉闼摽敞朗，
琼林郁葱茜。
自非挺金骨，
焉得谐夙愿。
真朋何森森，
合景恣游宴。
良会忘淹留，
千龄才一眄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1452','步虚词十首','吴筠','中唐','三宫发明景，
朗照同郁仪。
纷然驰飙歘，
上采空清蕤。
令我洞金色，
后天耀琼姿。
心协太虚静，
寥寥竟何思。
玄中有至乐，
淡泊终无为。
但与正真友，
飘飖散遨嬉。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1453','步虚词十首','吴筠','中唐','禀化凝正气，
鍊形为真仙。
忘心符元宗，
返本协自然。
帝一集绛宫，
流光出丹玄。
元英与桃君，
朗咏长生篇。
六府焕明霞，
百关罗紫烟。
飙车涉寥廓，
靡靡乘景迁。
不觉云路远，
斯须游万天。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1454','步虚词十首','吴筠','中唐','扶桑诞初景，
羽盖凌晨霞。
倏歘造西域，
嬉游金母家。
碧津湛洪源，
灼烁敷荷花。
煌煌青琳宫，
粲粲列玉华。
真气溢绛府，
自然思无邪。
俯矜区中士，
夭浊良可嗟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1455','步虚词十首','吴筠','中唐','琼台劫万仞，
孤映大罗表。
常有三素云，
凝光自飞绕。
羽幢泛明霞，
升降何缥缈。
鸾凤吹雅音，
栖翔绛林标。
玉虚无昼夜，
灵景何皎皎。
一睹太上京，
方知众天小。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1456','步虚词十首','吴筠','中唐','灼灼青华林，
灵风振琼柯。
三光无冬春，
一气清且和。
回首迩结灵，
倾眸亲曜罗。
豁落制六天，
流铃威百魔。
绵绵庆不极，
谁谓椿龄多。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1457','步虚词十首','吴筠','中唐','高情无侈靡，
遇物生华光。
至乐无箫歌，
金玉音琅琅。
或登明真台，
宴此羽景堂。
杳霭结宝云，
霏微散灵香。
天人诚遐旷，
欢泰不可量。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1458','步虚词十首','吴筠','中唐','爰从太微上，
肆觐虚皇尊。
腾我八景舆，
威迟入天门。
既登玉宸庭，
肃肃仰紫轩。
敢问龙汉末，
如何辟乾坤。
怡然辍云璈，
告我希夷言。
幸闻至精理，
方见造化源。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1459','步虚词十首','吴筠','中唐','二气播万有，
化机无停轮。
而我操其端，
乃能出陶钧。
寥寥大漠上，
所遇皆清真。
澄莹含元和，
气同自相亲。
绛树结丹实，
紫霞流碧津。
以兹保童婴，
永用超形神。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1460','建业怀古','吴筠','中唐','炎精既失御，
宇内为三分。
吴王霸荆越，
建都长江滨。
爰资股肱力，
以静淮海民。
魏后欲济师，
临流遽旋军。
岂惟限天堑，
所忌在有人。
惜哉归命侯，
淫虐败前勋。
衔璧入洛阳，
委躬为晋臣。
无何覆宗社，
为尔含悲辛。
俄及永嘉末，
中原塞胡尘。
五马浮渡江，
一龙跃天津。
此时成大业，
实赖贤缙绅。
辟土虽未远，
规模亦振振。
谢公佐王室，
仗节扫伪秦。
谁为吴兵孱，
用之在有伦。
荏苒宋齐末，
斯须变梁陈。
绵历已六代，
兴亡互纷纶。
在德不在险，
成败良有因。
高堞复于隍，
广殿摧于榛。
王风久泯灭，
胜气犹氤氲。
皇家一区域，
玄化通无垠。
常言宇宙泰，
忽遘云雷屯。
极目梁宋郊，
茫茫晦妖氛。
安得倚天剑，
斩兹横海鳞。
徘徊江山暮，
感激为谁申。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1461','经羊角哀墓作','吴筠','中唐','祇召出江国，
路傍旌古坟。
伯桃葬角哀，
墓近荆将军。
神道不相得，
称兵解其纷。
幽明信难知，
胜负理莫分。
长呼遂刎颈，
此节古未闻。
两贤结情爱，
骨肉何足云。
感子初并粮，
我心正氛氲。
迟回驻征骑，
不觉空林醺。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1462','苦春霖作寄友','吴筠','中唐','应龙迁南方，
霪雨备江干。
俯望失平陆，
仰瞻隐崇峦。
阴风敛暄气，
残月凄已寒。
时鸟戢好音，
众芳亦微残。
万流注江湖，
日夜增波澜。
数君旷不接，
悄然无与欢。
对酒聊自娱，
援琴为谁弹。
弹为愁霖引，
曲罢仍永叹。
此叹因感物，
谁能识其端。
写怀寄同心，
词极意未殚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1463','秋日望倚帝山','吴筠','中唐','楚服多奇山，
灵表先倚帝。
孤秀白云里，
青冥何崇丽。
秋天已晴朗，
晚日更澄霁。
远峰列在目，
杳与神襟契。
倏忽遗世间，
宛如再登诣。
伊予抱斯志，
代处人烟闭。
何事牵俗网，
悠然负芝桂。
朅来从隐沦，
式保羡门计。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1464','秋日彭蠡湖中观庐山','吴筠','中唐','泛舟太湖上，
回瞰兹山隈。
万顷沧波中，
千峰郁崔嵬。
凉烟发炉峤，
秋日明帝台。
绝巅凌大漠，
悬流泻昭回。
穹崇石梁引，
岈豁天门开。
飞鸟屡隐见，
白云时往来。
超然契清赏，
目醉心悠哉。
董氏出六合，
王君升九垓。
谁言旷遐祀，
庶可相追陪。
从此永栖托，
拂衣谢浮埃。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1465','览古十四首','吴筠','中唐','圣人重周济，
明道欲救时。
孔席不暇暖，
墨突何尝缁。
兴言振颓纲，
将以有所维。
君臣恣淫惑，
风俗日凋衰。
三代业遽陨，
七雄遂交驰。
庶物坠涂炭，
区中若棼丝。
秦皇燎儒术，
方册靡孑遗。
大汉历五叶，
斯文复崇推。
乃验经籍道，
与世同屯夷。
弛张固天意，
设教安能持。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1466','览古十四首','吴筠','中唐','兴亡道之运，
否泰理所全。
奈何淳古风，
既往不复旋。
三皇已散朴，
五帝初尚贤。
王业与霸功，
浮伪日以宣。
忠诚及狙诈，
殽混安可甄。
馀智入九霄，
守愚沦重泉。
永怀巢居时，
感涕徒泫然。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1467','览古十四首','吴筠','中唐','栋宇代巢穴，
其来自三皇。
迹生固为累，
经始增百王。
瑶台既灭夏，
琼室复陨汤。
覆车世不悟，
秦氏兴阿房。
继踵迷反正，
汉家崇建章。
力役弊万人，
瑰奇殚八方。
徇志仍未极，
促龄已云亡。
侈靡竟何在，
荆榛生庙堂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1468','览古十四首','吴筠','中唐','闲居览前载，
恻彼商与秦。
所残必忠良，
所宝皆凶嚚。
昵谀方自圣，
不悟祸灭身。
箕子作周辅，
孙通为汉臣。
洪范及礼仪，
后王用经纶。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1469','览古十四首','吴筠','中唐','吾观采苓什，
复感青蝇诗。
谗佞乱忠孝，
古今同所悲。
奸邪起狡猾，
骨肉相残夷。
汉储殒江充，
晋嗣灭骊姬。
天性犹可间，
君臣固其宜。
子胥烹吴鼎，
文种断越铍。
屈原沈湘流，
厥戚咸自贻。
何不若范蠡，
扁舟无还期。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1470','览古十四首','吴筠','中唐','尝稽真仙道，
清寂祛众烦。
秦皇及汉武，
焉得游其藩。
情扰万机屑，
位骄四海尊。
既欲先宇宙，
仍规后乾坤。
崇高与久远，
物莫能两存。
矧乃恣所欲，
荒淫伐灵根。
金膏恃延期，
玉色复动魂。
征战穷外域，
杀伤被中原。
天鉴谅难诬，
神理不可谖。
安期返蓬莱，
王母还昆崙。
异术终莫告，
悲哉竟何言。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1471','览古十四首','吴筠','中唐','鲁侯祈政术，
尼父从弃捐。
汉主思英才，
贾生被排迁。
始皇重韩子，
及睹乃不全。
武帝爱相如，
既徵复忘贤。
贵远世咸尔，
贱今理共然。
方知古来主，
难以效当年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1472','览古十四首','吴筠','中唐','食其昔未偶，
落魄为狂生。
一朝君臣契，
雄辩何纵横。
运筹康汉业，
凭轼下齐城。
既以智所达，
还为智所烹。
岂若终贫贱，
酣歌本无营。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1473','览古十四首','吴筠','中唐','晁错抱远策，
为君纳良规。
削彼诸侯权，
永用得所宜。
奸臣负旧隙，
乘衅谋相危。
世主竟不辨，
身戮宗且夷。
汉景称钦明，
滥罚犹如斯。
比干与龙逢，
残害何足悲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1474','览古十四首','吴筠','中唐','绛侯成大绩，
赏厚位仍尊。
一朝对狱吏，
荣辱安可论。
苏生佩六印，
奕奕为殃源。
主父食五鼎，
昭昭成祸根。
李斯佐二辟，
巨衅钟其门。
霍孟翼三后，
伊戚及后昆。
天人忌盈满，
兹理固永存。
方知得意者，
何必乘朱轮。
灭景栖远壑，
弦歌对清樽。
二疏返海滨，
蒋诩归林园。
萧洒去物累，
此谋诚足敦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1475','览古十四首','吴筠','中唐','至人顺通塞，
委命固无疵。
吾观太史公，
可谓识道规。
留滞焉足愤，
感怀殄生涯。
吾叹龚夫子，
秉义确不移。
晦迹一何晚，
天年夭当时。
薰膏自销铄，
楚老空馀悲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1476','览古十四首','吴筠','中唐','达者贵量力，
至人尚知几。
京房洞幽赞，
神奥咸发挥。
如何嫉元恶，
不悟祸所归。
谋物闇谋己，
谁言尔精微。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1477','览古十四首','吴筠','中唐','玄元明知止，
大雅尚保躬。
茂先洽闻者，
幽赜咸该通。
弱年赋鹪鹩，
可谓达养蒙。
晚节希鸾鹄，
长飞戾曾穹。
知进不知退，
遂令其道穷。
伊昔辨福初，
胡为迷祸终。
方验嘉遁客，
永贞天壤同。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1478','览古十四首','吴筠','中唐','圣人垂大训，
奥义不苟设。
天道殃顽凶，
神明祐懿哲。
斯言犹影响，
安得复回穴。
鲧瞍诞英睿，
唐虞育昏孽。
盗蹠何延期，
颜生乃短折。
鲁隐全克让，
祸机遂潜结。
楚穆肆巨逆，
福柄奚赫烈。
田常弑其主，
祚国久罔缺。
管仲存霸功，
世祖成诡说。
汉氏方版荡，
群阉恣邪谲。
謇謇陈蕃徒，
孜孜抗忠节。
誓期区宇静，
爰使凶丑绝。
谋协事靡从，
俄而反诛灭。
古来若兹类，
纷扰难尽列。
道遐理微茫，
谁为我昭晰。
吾将询上帝，
寥廓讵跻彻。
已矣勿用言，
忘怀庶自悦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1479','高士咏','吴筠','中唐','皎皎于陵子，
己贤妻亦明。
安兹道德重，
顾彼浮华轻。
琴书不为务，
禄位不可荣。
逃迹终灌园，
谁能达世情。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1480','高士咏','吴筠','中唐','广成卧云岫，
缅邈逾千龄。
轩辕来顺风，
问道修神形。
至言发玄理，
告以从杳冥。
三光入无穷，
寂默返太宁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1481','高士咏','吴筠','中唐','太伯全至让，
远投蛮夷间。
延陵嗣高风，
去国不复还。
尊荣比蝉翼，
道义侔崇山。
元规与峻节，
历世无能攀。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1482','高士咏','吴筠','中唐','文始通道源，
含光隐关吏。
遥欣紫气浮，
果验真人至。
玄诰已云锡，
世荣何足累。
高步三清境，
超登九仙位。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1483','高士咏','吴筠','中唐','贤哉彼沮溺，
避世全其真。
孔父栖栖者，
征途方问津。
行藏既异迹，
语默岂同伦。
耦耕长林下，
甘与鸟雀群。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1484','高士咏','吴筠','中唐','东方禀易象，
玩世隐廊庙。
栖心抱清微，
混迹秘光耀。
玄览寄数术，
纳规在谈笑。
卖药五湖中，
还从九仙妙。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1485','高士咏','吴筠','中唐','吾嘉台孝威，
乐道隐岩穴。
吾尚管幼安，
栖真养高节。
采药聊自给，
观书任所悦。
风尘不可混，
真素比松雪。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1486','高士咏','吴筠','中唐','季主超常伦，
沈迹寄卜筮。
宋贾二大夫，
停车试观艺。
高谈哂朝列，
洪辩不可际。
终秉鸾凤心，
翛然已遐逝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1487','高士咏','吴筠','中唐','野哉汉阴叟，
好古遂忘机。
抱瓮诚亦勤，
守朴全道微。
子贡初不达，
听言识其非。
已为风波人，
恍惘失所依。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1488','高士咏','吴筠','中唐','士安逾弱冠，
落魄未修饰。
一朝因感激，
志学忘寝食。
著书穷天人，
辞聘守玄默。
薄葬信昭俭，
可为将来则。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1489','高士咏','吴筠','中唐','冲虚冥至理，
体道自玄通。
不受子阳禄，
但饮壶丘宗。
泠然竟何依，
挠挑游大空。
未知风乘我，
为是我乘风。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1490','高士咏','吴筠','中唐','子平好真隐，
清净玩老易。
探玄乐无为，
观象验损益。
常抱方外心，
且纡人间迹。
一朝毕婚娶，
五岳遂长适。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1491','高士咏','吴筠','中唐','孙登好淳古，
卉服从穴居。
弹琴合天和，
读易见象初。
终日无愠色，
恬然在玄虚。
贻言诫叔夜，
超迹安所如。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1492','高士咏','吴筠','中唐','圣人贵素朴，
礼义非玄同。
师金告颜生，
可谓达化宗。
夫子饰刍狗，
自然道斯穷。
应物方矫行，
俯仰靡不通。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1493','高士咏','吴筠','中唐','莱氏道已远，
懿妻德弥清。
一遁嚣烦趣，
永契云壑情。
禄位非所重，
拂衣遂遐征。
杳然从我愿，
岂为物所撄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1494','高士咏','吴筠','中唐','大名贤所尚，
宝位圣所珍。
皎皎许仲武，
遗之若纤尘。
弃瓢箕山下，
洗耳颍水滨。
物外两寂寞，
独与玄冥均。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1495','高士咏','吴筠','中唐','汉皇敦故友，
物色访严生。
三聘迨深泽，
一来遇帝庭。
紫宸同御寝，
玄象验客星。
禄位终不屈，
云山乐躬耕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1496','高士咏','吴筠','中唐','汉皇举遗逸，
多士咸已宁。
至德不可拔，
严君独湛冥。
卜筮训流俗，
指归畅玄经。
闭关动元象，
何必游紫庭。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1497','高士咏','吴筠','中唐','夷齐互崇让，
弃国从所钦。
聿来及宗周，
乃复非其心。
世浊不可处，
冰清首阳岑。
采薇咏羲农，
高义越古今。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1498','高士咏','吴筠','中唐','周丰贵隐耀，
静默尊无名。
鲁侯询政体，
喻以治道精。
莅人在忠悫，
疑叛由会盟。
一言达至义，
千载良为程。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1499','高士咏','吴筠','中唐','庞公栖鹿门，
绝迹远城市。
超然风尘外，
自得丘壑美。
耕凿勤厥躬，
耘锄课妻子。
保兹永无患，
轩冕何足纪。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1500','高士咏','吴筠','中唐','邈邈河上叟，
无名契虚冲。
灵关畅玄旨，
万乘趋道风。
宠辱不可累，
飘然在云空。
独与造化友，
谁能测无穷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1501','高士咏','吴筠','中唐','卓哉弦高子，
商隐独摽奇。
效谋全郑国，
矫命犒秦师。
赏神义不受，
存公灭其私。
虚心贵无名，
远迹居九夷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1502','高士咏','吴筠','中唐','南华源道宗，
玄远故不测。
动与造化游，
静合太和息。
放旷生死外，
逍遥神明域。
况乃资九丹，
轻举归太极。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1503','高士咏','吴筠','中唐','子綦方隐几，
冥寂久灰心。
悟来应颜游，
清义杳何深。
含响尽天籁，
有言同鷇音。
是非不足辩，
安用劳神襟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1504','高士咏','吴筠','中唐','大禹受禅让，
子高辞诸侯。
退躬适外野，
放浪夫何求。
万乘造中亩，
一言良见酬。
俋俋耕不顾，
斯情邈难俦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1505','高士咏','吴筠','中唐','展禽抱纯粹，
灭迹和光尘。
高情遗轩冕，
降志救世人。
百行既无点，
三黜道弥真。
信谓德超古，
岂惟言中伦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1506','高士咏','吴筠','中唐','干木布衣者，
守道杜衡门。
德光义且富，
肯易王侯尊。
魏主钦其贤，
轼庐情亦敦。
秦兵遂不举，
高卧为国藩。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1507','高士咏','吴筠','中唐','亢仓致虚极，
潜迹依远岫。
智去愚独留，
日亏岁方就。
乡人谋尸祝，
不欲闻俎豆。
尚贤非至理，
尧舜固为陋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1508','高士咏','吴筠','中唐','荣期信知止，
带索无所求。
外物非我尚，
琴歌自优游。
三乐通至道，
一言醉孔丘。
居常以待终，
啸傲夫何忧。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1509','高士咏','吴筠','中唐','太项冥虚极，
微远不可究。
禀量合太初，
返形寄童幼。
孔父惭至理，
颜生赖真授。
泛然同万流，
无迹世莫觏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1510','高士咏','吴筠','中唐','原生何淡漠，
观妙自怡性。
蓬户常晏如，
弦歌乐天命。
无财方是贫，
有道固非病。
木赐钦高风，
退惭车马盛。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1511','高士咏','吴筠','中唐','壶丘道为量，
玄虚固难知。
季咸曜浅术，
禦寇初深疑。
至人忘祸福，
感变靡定期。
太冲杳无朕，
元化谁能知。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1512','高士咏','吴筠','中唐','通玄贵阴德，
利物非市朝。
悠然大江上，
散发挥轻桡。
已陈缁帷说，
复表沧浪谣。
灭迹竟何往，
遗文独昭昭。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1513','高士咏','吴筠','中唐','郭生在童稚，
已得方外心。
绝迹遗世务，
栖真入长林。
元和感异类，
猛兽怀德音。
不忆固无情，
斯言微且深。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1514','高士咏','吴筠','中唐','吾重陶渊明，
达生知止足。
怡情在樽酒，
此外无所欲。
彭泽非我荣，
折腰信为辱。
归来北窗下，
复采东篱菊。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1515','高士咏','吴筠','中唐','吾观时人趣，
矫迹务驰声。
独有高文通，
讼田求翳名。
公车徒见累，
爵禄非所荣。
隐身乐鱼钓，
世网不可撄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1516','高士咏','吴筠','中唐','万方厌秦德，
战伐何纷纷。
四皓同无为，
丘中卧白云。
自汉成帝业，
一来翼储君。
知几道可尚，
隐括成元勋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1517','高士咏','吴筠','中唐','玄元九仙主，
道冠三气初。
应物方佐命，
栖真亦归居。
贻篇训终古，
驾景还太虚。
孔父叹犹龙，
谁能知所如。',NULL,'','{"preface": "《易》称：「君子之道，或出、或处、或默、或语。」盖出而语者，所以佐时致理；处而默者，所以居静镇躁。故虽无言，亦几于利物，岂独善其身而已哉。夫子曰：「隐居以求其志，行义以达其道。」所谓百虑一致，殊途同归者也。夫好同恶异，人之常情。予自弱年，窃尚真隐，远览先达，实怡我心，虽不见古人，而馀风可仰，是则是效，其唯嘉遁之士乎。故企慕之不足，则师友之；师友之不足，则咏歌之，聊乐我员，于是乎在。昔玄晏先生皇甫谧因其所美而著〈高士传〉；梁伯鸾有〈高士颂〉；愚今有〈高士咏〉，亦各一时之志耳。太初渺邈，难得而详，洪崖之流，无迹可纪。故始于混元皇帝，终于陶徵君。举其绝伦，明其标的，为五十首，以昤讽其德音焉。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1518','高士咏','吴筠','中唐','董京依白社，
散发咏玄风。
心出区宇外，
迹参城市中。
嚣尘不能杂，
名位安可笼。
匿影留雅什，
精微信难穷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1519','高士咏','吴筠','中唐','伯休抱遐心，
隐括自为美。
卖药不二价，
有名反深耻。
安能受玄纁，
秉愿终素履。
逃遁从所尚，
萧萧绝尘轨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1520','高士咏','吴筠','中唐','仲连秉奇节，
释难含道情。
一言却秦围，
片札降聊城。
辞金义何远，
让禄心益清。
处世功已立，
拂衣蹈沧溟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1521','高士咏','吴筠','中唐','接舆耽冲玄，
伉俪亦真逸。
傲然辞徵聘，
耕绩代禄秩。
凤歌诫文宣，
龙德遂隐密。
一游峨嵋上，
千载保灵术。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1522','高士咏','吴筠','中唐','臧叟隐中壑，
垂纶心浩然。
文王感昔梦，
授政道斯全。
一遵无为术，
三载淳化宣。
功成遂不处，
遁迹符冲玄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1523','高士咏','吴筠','中唐','巢父志何远，
潜精人莫知。
耻闻让王事，
饮犊方见移。
不欲散大朴，
焉能为尧师。
鍊真自轻举，
浮世何足遗。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1524','高士咏','吴筠','中唐','世情矜宠誉，
效节徼当时。
颜阖遵无名，
饭牛聊自怡。
逃聘鄙束帛，
凿坏欣茅茨。
托聘嚣尘表，
放浪世莫知。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1525','高士咏','吴筠','中唐','黔娄蕴雅操，
守约遗代华。
淡然常有怡，
与物固无瑕。
哲妻配明德，
既没辩正邪。
辞禄乃馀贵，
表谥良可嘉。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1526','晚到湖口见庐山作呈诸故人','吴筠','中唐','夜舟达湖口，
渐近庐山侧。
高高标横天，
隐隐何峻极。
石镜启晨晖，
垆烟凝寒色。
旅泊将休暇，
归心已隮陟。
虚名久为累，
使我辞逸域。
良愿道不违，
幽襟果兹得。
故人在云峤，
乃复同晏息。
鸿飞入青冥，
虞氏罢缯弋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1527','游仙二十四首','吴筠','中唐','启册观往载，
摇怀考今情。
终古已寂寂，
举世何营营。
悟彼众仙妙，
超然含至精。
凝神契冲玄，
化服凌太清。
心同宇宙广，
体合云霞轻。
翔风吹羽盖，
庆霄拂霓旌。
龙驾朝紫微，
后天保令名。
岂如寰中士，
轩冕矜暂荣。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1528','游仙二十四首','吴筠','中唐','鸾凤栖瑶林，
雕鹗集平楚。
饮啄本殊好，
翱翔终异所。
吾方遗諠嚣，
立节慕高举。
解兹区中恋，
结彼霄外侣。
谁谓天路遐，
感通自无阻。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1529','游仙二十四首','吴筠','中唐','悯俗从迁谢，
寻仙去沦没。
三元有真人，
与我生道骨。
凌晨吸丹景，
入夜饮黄月。
百关弥调畅，
方寸益清越。
栖神合虚无，
洞览周恍惚。
不觉随玉皇，
焚香诣金阙。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1530','游仙二十四首','吴筠','中唐','西龟初定箓，
东华已校名。
三官无遗谴，
七祖升云軿。
体妙尘累隔，
心微玄化并。
一朝出天地，
亿载犹童婴。
使我齐浩劫，
萧萧宴玉清。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1531','游仙二十四首','吴筠','中唐','怡神在灵府，
皎皎含清澄。
仙经不吾欺，
轻举信有徵。
畴昔希道念，
而今果天矜。
岂非阴功著，
乃致白日升。
焉用过洞府，
吾其越朱陵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1532','游仙二十四首','吴筠','中唐','高真诚寥邈，
道合不我遗。
孰谓姑射远，
神人可同嬉。
结驾从之游，
飘飘出天垂。
不理人自化，
神凝物无疵。
因知至精感，
足以和四时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1533','游仙二十四首','吴筠','中唐','碧海广无际，
三山高不极。
金台罗中天，
羽客恣游息。
霞液朝可饮，
虹芝晚堪食。
啸歌自忘心，
腾举宁假翼。
保寿同三光，
安能纪千亿。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1534','游仙二十四首','吴筠','中唐','将过太帝宫，
暂诣扶桑处。
真童已相迓，
为我清宿雾。
海若宁洪涛，
羲和止奔驭。
五云结层阁，
八景动飞舆。
青霞正可挹，
丹椹时一遇。
留我宴玉堂，
归轩不令遽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1535','游仙二十四首','吴筠','中唐','欲超洞阳界，
试鉴丹极表。
赤帝跃火龙，
炎官控朱鸟。
导我升绛府，
长躯出天杪。
阳灵赫重晖，
四达何皎皎。
为尔流飘风，
群生遂无夭。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1536','游仙二十四首','吴筠','中唐','予因诣金母，
飞盖超西极。
遂入素中天，
停轮太濛侧。
若华拂流影，
不使白日匿。
倾曦复亭午，
六合无暝色。
道化随感迁，
此理谁能测。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1537','游仙二十四首','吴筠','中唐','九龙何蜿蜿，
载我升云纲。
临睨怀旧国，
风尘混苍茫。
依依远人寰，
去去迩帝乡。
上超星辰纪，
下视日月光。
倏已过太微，
天居焕煌煌。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1538','游仙二十四首','吴筠','中唐','停骖太仪侧，
整服金阙前。
肃肃承上帝，
锵锵会群仙。
鸿炉发灵香，
广庑张钧天。
玉醴洽中座，
霞膏充四筵。
良期无终极，
俛仰移亿年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1539','游仙二十四首','吴筠','中唐','峻朗妙门辟，
澄微真鉴通。
琼林九霞上，
金阁三天中。
飞虬跃庆云，
翔鹤抟灵风。
郁彼玉京会，
仙期六合同。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1540','游仙二十四首','吴筠','中唐','予升至阳元，
欲憩明霞馆。
飘飘琼轮举，
晔晔金景散。
结虚成万有，
高妙咸可玩。
玉山郁嵯峨，
琅海杳无岸。
暂赏过千椿，
遐龄谁复算。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1541','游仙二十四首','吴筠','中唐','招携紫阳友，
合宴玉清台。
排景羽衣振，
浮空云驾来。
灵幡七曜动，
琼障九光开。
凤舞龙璈奏，
虬轩殊未回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1542','游仙二十四首','吴筠','中唐','高升紫极上，
宴此玄都岑。
玉藻散奇香，
琼柯流雅音。
灵风生太漠，
习习吹人襟。
体混希微广，
神凝空洞深。
萧然宇宙外，
自得乾坤心。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1543','游仙二十四首','吴筠','中唐','晨登千仞岭，
俯瞰四人居。
原野间城邑，
山河分里闾。
眇彼埃尘中，
争奔声利途。
百龄宠辱尽，
万事皆为虚。
自昔无成功，
安能与尔俱。
将期驾云景，
超迹升天衢。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1544','游仙二十四首','吴筠','中唐','骨鍊体弥清，
鉴明尘已绝。
恬夷宇宙泰，
焕朗天光彻。
羽服参烟霄，
童颜皎冰雪。
隐符千魔骇，
鸣玉万帝悦。
遂使区宇中，
祅气永沦灭。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1545','游仙二十四首','吴筠','中唐','朝逾弱水北，
夕憩钟山顶。
颛顼清玄宫，
禺强扫幽境。
烛龙发神曜，
阴野弥焕炳。
导达三气和，
驱除六天静。
玉楼互相晖，
烟客何秀颖。
一举流霞津，
千年在俄倾。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1546','游仙二十四首','吴筠','中唐','扬盖造辰极，
乘烟游阆风。
上元降玉闼，
王母开琳宫。
天人何济济，
高会碧堂中。
列侍奏云歌，
真音满太空。
千年紫柰熟，
四劫灵瓜丰。
斯乐异荒宴，
陶陶殊未终。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1547','游仙二十四首','吴筠','中唐','整驾辞五岳，
排烟凌九霄。
纷然太虚中，
羽旆更相招。
且盼蓬壶近，
谁言昆阆遥。
悠悠竟安适，
仰赴三天朝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1548','游仙二十四首','吴筠','中唐','予招三清友，
迥出九天上。
挠挑绝漠中，
差池遥相望。
大空含常明，
八外无隐障。
鸾凤有逸翮，
泠然恣飘飏。
寥寥唯玄虚，
至乐在神王。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1549','游仙二十四首','吴筠','中唐','纵身太霞上，
眇眇虚中浮。
八威先启行，
五老同我游。
灵景何灼灼，
祥风正寥寥。
啸歌振长空，
逸响清且柔。
遨嬉无迹赏，
顾眄皆真俦。
不疾而自速，
万天俄已周。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1550','游仙二十四首','吴筠','中唐','返视太初先，
与道冥至一。
空洞凝真精，
乃为虚中实。
变通有常性，
合散无定质。
不行迅飞电，
隐曜光白日。
玄栖忘玄深，
无得固无失。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1551','游庐山五老峰','吴筠','中唐','彭蠡隐深翠，
沧波照芙蓉。
日初金光满，
景落黛色浓。
云外听猿鸟，
烟中见杉松。
自然符幽情，
潇洒惬所从。
整策务探讨，
嬉游任从容。
玉膏正滴沥，
瑶草多䒠茸。
羽人栖层崖，
道合乃一逢。
挥手欲轻举，
为余扣琼钟。
空香清人心，
正气信有宗。
永用谢物累，
吾将乘鸾龙。',NULL,'[{"Book": "《唐诗归》", "Section": null, "Content": "钟云：奇丽（“日初”句下）。钟云：（任从容）三字深于游理，对忙人说不得（“嬉游”句下）。谭云：妙语真事（“羽人”二句下）。谭云：与“心清闻妙香”同幻。“妙”字、“空”字”，可以尽“香”之理，“香”岂易言（“空香”句下）！", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}]','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1552','游倚帝山二首','吴筠','中唐','山间非吾心，
物表翼所托。
振衣超烦滓，
策杖追岑壑。
绝地穷㟏岈，
造天究磐礴。
迩临烟霞积，
逖睇宇宙廓。
俯惊白云涌，
仰骇飞泉落。
苔浓鲜翠屏，
松古丽丹崿。
目冀睹乔羡，
心希驭龙鹤。
乃知巢由情，
岂伊猿鸟乐。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1553','游倚帝山二首','吴筠','中唐','兹山何独秀，
万仞倚昊苍。
晨跻烟霞趾，
夕憩灵仙场。
俯观海上月，
坐弄浮云翔。
松风振雅音，
桂露含晴光。
不出六合外，
超然万累忘。
信彼古来士，
岩栖道弥彰。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1554','登北固山望海','吴筠','中唐','此山镇京口，
迥出沧海湄。
跻览何所见，
茫茫潮汐驰。
云生蓬莱岛，
日出扶桑枝。
万里混一色，
焉能分两仪。
愿言策烟驾，
缥缈寻安期。
挥手谢人境，
吾将从此辞。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1555','登庐山东峰观九江合彭蠡湖','吴筠','中唐','百川灌彭蠡，
秋水方浩浩。
九派混东流，
朝宗合天沼。
写心陟云峰，
纵目还缥缈。
宛转众浦分，
差池群山绕。
江妃弄明霞，
彷佛呈窈窕。
而我临长风，
飘然欲腾矫。
昔怀沧洲兴，
斯志果已绍。
焉得忘机人，
相从洽鱼鸟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1556','缑山庙','吴筠','中唐','朝吾自嵩山，
驱驾遵洛汭。
逶迟轘辕侧，
仰望缑山际。
王子谢时人，
笙歌此宾帝。
仙材夙所禀，
宝位焉足系。
为迫丹霄期，
阙流苍生惠。
高踪邈千载，
遗庙今一诣。
肃肃生风云，
森森列松桂。
大君弘至道，
层构何壮丽。
稽首环金坛，
焚香陟瑶砌。
伊余超浮俗，
尘虑久已闭。
况复清夙心，
萧然叶真契。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1557','酬叶县刘明府避地庐山言怀诒郑录事昆季苟尊师兼见赠之','吴筠','中唐','明哲良罕遇，
遇君辄思齐。
挺生著天爵，
自可析人圭。
河洛初沸腾，
方期扫虹霓。
时命竟未合，
安能亲鼓鼙。
从此罢飞凫，
投簪辞割鸡。
驱车适南土，
忠孝两不暌。
庐岳镇江介，
于焉惬林栖。
入门披䌽服，
出谷杖红藜。
隐令旧闾里，
而今复成跻。
郑公解簪绂，
华萼曜松溪。
贤哉苟徵君，
灭迹为圃畦。
顾已成非薄，
忝兹忘筌蹄。
相观对绿樽，
逸思凌丹梯。
道泰我长往，
时清君勿迷。
王孙且无归，
芳草正萋萋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1558','题龚山人草堂','吴筠','中唐','世人负一美，
未肯甘陆沉。
独抱匡济器，
能怀真隐心。
结庐迩城郭，
及到云木深。
灭迹慕颍阳，
忘机同汉阴。
启户面白水，
凭轩对苍岑。
但歌考槃诗，
不学梁父吟。
兹道我所适，
感君齐素襟。
勖哉龚夫子，
勿使嚣尘侵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1559','翰林院望终南山','吴筠','中唐','窃慕隐沦道，
所欢岩穴居。
谁言忝休命，
遂入承明庐。
物情不可易，
幽中未尝摅。
幸见终南山，
岧峣凌太虚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_2_1560','翰林院望终南山','吴筠','中唐','青霭长不灭，
白云闲卷舒。
悠然相探讨，
延望空踌蹰。
迹系心无极，
神超兴有馀。
何当解维絷，
永托逍遥墟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1561','句','吴筠','中唐','家住青山下，
时向青山上。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1562','句','吴筠','中唐','垂花临碧涧，
清翠依丹巘。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1563','永泰公主挽歌二首','吴兢','唐','秾华从妇道，
釐降适诸侯。
河汉天孙合，
潇湘帝子游。
关睢方作训，
鸣凤自相求。
可叹凌波迹，
东川遂不流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1564','永泰公主挽歌二首','吴兢','唐','舜华徂北渚，
宸思结南阳。
盩绶哀荣备，
游轩宠悼彰。
三川谋远日，
八水宅连冈。
无复秦楼上，
吹箫下凤皇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_2_1565','拟采桑曲','吴兢','唐','罗敷十五六，
采桑城南道。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_2_1566','上巳日','吴融','唐末','本学多情刘武威，
寻花傍水看春晖。
无端遇著伤心事，
赢得凄凉索漠归。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1567','山居即事','吴融','唐末','小亭前面接青崖，
白石交加衬绿苔。
日暮松声满阶砌，
不关风雨鹤归来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1568','山居即事四首','吴融','唐末','桂树秋来风满枝，
碧岩归日免乖期。
故人尽向蟾宫折，
独我攀条欲寄谁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1569','山居即事四首','吴融','唐末','不傲南窗且采樵，
乾松每带湿云烧。
庖厨却得长兼味，
三秀芝根五朮苗。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1570','山居即事四首','吴融','唐末','万事翛然只有棋，
小轩高净簟凉时。
阑珊半局和微醉，
花落中庭树影移。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1571','山居即事四首','吴融','唐末','无邻无里不成村，
水曲云重掩石门。
何用深求避秦客，
吾家便是武陵源。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1572','山居喜友人相访','吴融','唐末','秋雨空山夜，
非君不此来。
高于剡溪雪，
一棹到门回。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1573','云','吴融','唐末','南北东西似客身，
远峰高鸟自为邻。
清歌一曲犹能住，
莫道无心胜得人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1574','忆事','吴融','唐末','去年花下把金卮，
曾赋杨花数句诗。
回首朱门闭荒草，
如今愁到牡丹时。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1575','忆街西所居','吴融','唐末','衡门一别梦难稀，
人欲归时不得归。
长忆去年寒食夜，
杏花零落雨霏霏。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1576','水鸟','吴融','唐末','烟为行止水为家，
两两三三睡暖沙。
为谢离鸾兼别鹄，
如何禁得向天涯。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1577','王母庙','吴融','唐末','鸾龙一夜降昆丘，
遗庙千年枕碧流。
赚得武皇心力尽，
忍看烟草茂陵秋。',NULL,'[{"Book": "《唐诗归》", "Section": null, "Content": "钟云：分明笑汉武之呆，却似追咎王母，意绝不在此，探得立言之妙。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1578','买带花樱桃','吴融','唐末','粉红轻浅靓妆新，
和露和烟别近邻。
万一有情应有恨，
一年荣落两家春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1579','华清宫二首','吴融','唐末','四郊飞雪暗云端，
唯此宫中落旋乾。
绿树碧檐相掩映，
无人知道外边寒。',NULL,'[{"Book": "《注解选唐诗》", "Section": null, "Content": "知华清宫之暖，不知外边之寒，士怨、民怨、军怨皆不暇问矣，如之何不亡！此诗意在言外，非诗人不知其巧。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《注解选唐诗》"}, {"Book": "《唐诗绝句类选》", "Section": null, "Content": "尝爱谢叠山《蚕妇吟》：“子规啼彻四更时，起视蚕稠怕叶稀。不信柳头杨柳月，玉人歌舞未曾归。”合而观之，深宫之暖，不知外边之寒；玉人之乐，不知蚕妇之苦，词不迫切而意独至，深得风人之体。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗绝句类选》"}, {"Book": "《唐诗选脉会通评林》", "Section": null, "Content": "吴子《华清宫》三诗俱讥明皇恣欲宴游，俾全盛世业召祸一朝而莫悟。如此篇言独乐而不恤其民，以致怨恨之意见于言外也。……此篇非但意好，亦法度森严，第三句与第二句相应、树、檐掩映，所以“落便干”也。第四句与第一句相应，四郊飞雪，所以“外边寒”也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗选脉会通评林》"}, {"Book": "《唐诗快》", "Section": null, "Content": "本晏子对齐景语来，而更加隽婉之致（末句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗快》"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1580','华清宫二首','吴融','唐末','长生秘殿倚青苍，
拟敌金庭不死乡。
无奈逝川东去急，
秦陵松柏满残阳。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1581','华清宫四首','吴融','唐末','中原无鹿海无波，
凤辇鸾旗出幸多。
今日故宫归寂寞，
太平功业在山河。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1582','华清宫四首','吴融','唐末','渔阳烽火照函关，
玉辇匆匆下此山。
一曲羽衣听不尽，
至今遗恨水潺潺。',NULL,'[{"Book": "《注解选唐诗》", "Section": null, "Content": "白乐天云：“渔阳鼙鼓动地来，惊破霓裳羽衣曲”，与此诗意同。此诗云“一曲霓裳听不尽，至今遗恨水潺潺”，意味深远，尤胜乐大。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《注解选唐诗》"}, {"Book": "《唐诗绝句类选》", "Section": null, "Content": "绝句全在第三句转换有力，则气慨精神，首尾照应。如此诗提拟霓裳一曲，可见禄山之乱、剑阁之行，皆原于此。而明皇曾无悔过之意，良可哀也。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗绝句类选》"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1583','华清宫四首','吴融','唐末','上皇銮辂重巡游，
雨泪无言独倚楼。
惆怅眼前多少事，
落花明月满宫秋。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1584','华清宫四首','吴融','唐末','别殿和云锁翠微，
太真遗像梦依依。
玉皇掩泪频惆怅，
应叹僧繇彩笔飞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1585','杂曲歌辞 水调','吴融','唐末','凿河千里走黄沙，
浮殿西来动日华。
可道新声是亡国，
且贪惆怅后庭花。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_2_1586','江行','吴融','唐末','霞低水远碧翻红，
一棹无边落照中。
说示北人应不爱，
锦遮泥健马追风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1587','江树','吴融','唐末','终日冲奔浪，
何年坠乱风。
谢公堪入咏，
目极在云中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_2_1588','自讽','吴融','唐末','本是沧洲把钓人，
无端三署接清尘。
从来不解长流涕，
